def _url_request_atual():
    qs = (request.query_string or b"").decode("utf-8", errors="ignore").strip()
    if qs:
        return f"{request.path}?{qs}"
    return request.path





def _id_usuario_logado_para_sessao_paineis() -> str:
    """
    Eu monto um identificador estável do usuário logado para isolar
    a URL filtrada da lista de painéis dentro da sessão.

    Isso evita que, no mesmo navegador, um usuário B herde o filtro
    que o usuário A deixou salvo antes de sair do sistema.
    """
    try:
        if current_user and current_user.is_authenticated:
            id_dim = getattr(current_user, "IDDimUsuarios", None)
            if id_dim is not None:
                return f"usuario:{int(id_dim)}"

            get_id = getattr(current_user, "get_id", None)
            if callable(get_id):
                valor = get_id()
                if valor:
                    return f"usuario:{valor}"
    except Exception:
        pass

    return "usuario:anonimo"


def _chave_sessao_lista_paineis_return_to() -> str:
    """Eu separo a URL filtrada da lista de painéis por usuário logado."""
    return f"paineis_lista_return_to:{_id_usuario_logado_para_sessao_paineis()}"


def _valor_query_paineis_preenchido(chave: str, valor) -> bool:
    """
    Eu trato valores vazios ou padrões para decidir se a URL da lista
    realmente representa um filtro escolhido pelo usuário.
    """
    texto = str(valor or "").strip()
    if not texto:
        return False

    texto_lower = texto.lower()
    if texto_lower in {"none", "null", "undefined"}:
        return False

    chave_lower = str(chave or "").strip().lower()

    if chave_lower == "status" and texto_lower == "todos":
        return False

    if chave_lower == "ponto_ativo" and texto_lower == "1":
        return False

    if chave_lower == "mes_atual" and texto_lower == "1":
        return False

    return True


def _url_lista_paineis_segura(url: str) -> bool:
    """
    Eu aceito somente URLs internas da própria lista de painéis.

    Isso impede redirect aberto e também evita salvar retorno para outra tela.
    """
    texto = str(url or "").strip()
    if not texto:
        return False

    if texto.startswith("//"):
        return False

    try:
        partes = urlsplit(texto)
    except Exception:
        return False

    if partes.scheme or partes.netloc:
        return False

    caminho = (partes.path or "").rstrip("/")

    try:
        caminho_lista = url_for("Paineis.lista_paineis").rstrip("/")
    except Exception:
        caminho_lista = "/paineis"

    return caminho == caminho_lista


def _url_paineis_tem_filtro_real(url: str) -> bool:
    """
    Eu verifico se a URL da lista de painéis tem filtro real.

    Não considero page, per_page e parâmetros técnicos como filtro, mas
    preservo a URL inteira quando existe pelo menos um filtro de verdade.
    """
    try:
        partes = urlsplit(str(url or "").strip())
        parametros = parse_qs(partes.query, keep_blank_values=False)
    except Exception:
        return False

    chaves_filtro = (
        "q",
        "tipo",
        "exibidora",
        "cidade_exibicao",
        "tipo_documento",
        "vendedor",
        "marca_exibida",
        "status",
        "formato",
        "altxlarg",
        "iluminado",
        "area_min",
        "area_max",
        "ponto_ativo",
        "dt_ini",
        "dt_fim",
        "periodo",
        "ano",
        "anomes",
        "mes",
        "dia",
        "trimestre",
        "semana_iso",
        "dia_semana_iso",
        "quinzena",
        "bi_semana",
        "bisemana",
        "fim_de_semana",
        "tudo",
        "selected_codface",
        "selected_codponto",
    )

    for chave in chaves_filtro:
        valores = parametros.get(chave) or []
        if any(_valor_query_paineis_preenchido(chave, valor) for valor in valores):
            return True

    return False


def _registrar_lista_paineis_return_to_na_sessao() -> str:
    """
    Eu salvo a URL atual da lista somente quando ela possui filtro real.

    Regra crítica:
    - /paineis/ limpo NÃO pode ser salvo na sessão como return_to, porque
      depois a própria rota /paineis/ pode tentar redirecionar para /paineis/
      de novo e gerar ERR_TOO_MANY_REDIRECTS.
    - URL filtrada pode ser salva, pois melhora a navegação ao voltar da grade.
    """
    url_atual = _url_request_atual()
    chave = _chave_sessao_lista_paineis_return_to()

    if _url_lista_paineis_segura(url_atual) and _url_paineis_tem_filtro_real(url_atual):
        session[chave] = url_atual
        return url_atual

    url_salva = session.get(chave)
    if url_salva and _url_lista_paineis_segura(url_salva) and _url_paineis_tem_filtro_real(url_salva):
        return url_salva

    session.pop(chave, None)
    return url_atual


def _resolver_return_to_paineis() -> str:
    """
    Eu resolvo para onde a grade deve voltar.

    Regra crítica:
    - Posso retornar /paineis/ limpo como destino de volta.
    - Mas só salvo na sessão quando existe filtro real.
    - Isso evita loop: /paineis/ -> redirect para /paineis/ -> redirect para /paineis/.
    """
    chave = _chave_sessao_lista_paineis_return_to()

    candidatos = [
        request.args.get("return_to"),
        request.form.get("return_to"),
        session.get(chave),
    ]

    for candidato in candidatos:
        url = str(candidato or "").strip()
        if not url:
            continue

        if _url_lista_paineis_segura(url):
            if _url_paineis_tem_filtro_real(url):
                session[chave] = url
            elif session.get(chave) == url:
                session.pop(chave, None)

            return url

    return url_for("Paineis.lista_paineis")


def _valor_query_contratos_preenchido(valor):
    """
    Eu trato valores vazios gerados por url_for/Jinja para não considerar
    q=, id_contrato=None ou contrato_ativo= como filtro real.
    """
    texto = str(valor or "").strip()
    if not texto:
        return False

    return texto.lower() not in {"none", "null", "undefined"}


def _url_contratos_tem_filtro_real(url):
    """
    Eu verifico se uma URL da lista de contratos possui filtro real.

    Não considero page, per_page e calcular_total como filtros, porque esses
    parâmetros são paginação/controle visual. O objetivo é preservar somente
    busca, status, cidade, segmento, contrato ativo ou contrato selecionado.
    """
    try:
        partes = urlsplit(str(url or "").strip())
        parametros = parse_qs(partes.query, keep_blank_values=False)
    except Exception:
        return False

    for chave in ("q", "id_contrato", "status", "cidade", "segmento", "contrato_ativo"):
        valores = parametros.get(chave) or []
        if any(_valor_query_contratos_preenchido(valor) for valor in valores):
            return True

    return False


def _resolver_return_to_clientes():
    candidatos = [
        request.args.get("return_to"),
        request.form.get("return_to"),
        session.get("clientes_lista_return_to"),
    ]

    for candidato in candidatos:
        url = str(candidato or "").strip()
        if not url:
            continue

        
        if url.startswith("/paineis/clientes"):
            return url

    return url_for("Paineis.clientes_lista", page=1)












def _resolver_return_to_contratos():
    """
    Eu resolvo a URL de retorno da lista de contratos preservando filtros.

    Aceito somente URLs internas da lista:
    /paineis/contratos
    /paineis/contratos?q=...&status=...
    """
    candidatos = [
        request.args.get("return_to"),
        request.form.get("return_to"),
        session.get("contratos_lista_return_to"),
    ]

    for candidato in candidatos:
        url = str(candidato or "").strip()

        if not url:
            continue

        if url == "/paineis/contratos" or url.startswith("/paineis/contratos?"):
            session["contratos_lista_return_to"] = url
            return url

    return url_for("Paineis.contratos_lista")



def _cache_get_seguro_paineis(chave, padrao=None):
    """Eu leio cache sem deixar falha de backend derrubar a tela."""
    try:
        valor = cache.get(chave)
        return padrao if valor is None else valor
    except Exception:
        return padrao


def _cache_set_seguro_paineis(chave, valor, timeout_segundos: int = 300):
    """Eu salvo cache de forma tolerante; se o cache falhar, a tela continua normal."""
    try:
        cache.set(chave, valor, timeout=int(timeout_segundos or 300))
    except Exception:
        pass












