@paineis_bp.app_context_processor
def injetar_acl_menu_paineis():
    """Eu injeto helpers do menu de Painéis nos templates.

    Regras importantes:
    - Vendedor vê a carteira própria pelo menu do usuário, não pelo submenu Ativos.
    - A URL é resolvida pelo vínculo DimUsuarios -> Vendedores -> FatoCarteiraVendedor.
    - Se não existir carteira vinculada, o item Minha Carteira simplesmente não aparece.
    """
    usuario_logado_eh_vendedor = False
    id_minha_carteira = 0
    minha_carteira_url = None
    home_usuario_url = None

    try:
        id_empresa_proprietaria = obter_id_empresa_proprietaria_usuario()
        if id_empresa_proprietaria == 1:
            home_usuario_url = url_for("euro.lista_produtos")
        else:
            # IDEmpresaProprietaria = 3 e demais empresas continuam na lista de painéis.
            home_usuario_url = url_for("Paineis.lista_paineis")
    except Exception:
        home_usuario_url = url_for("Paineis.lista_paineis")

    try:
        usuario_logado_eh_vendedor = bool(
            getattr(current_user, "is_authenticated", False)
            and _usuario_logado_eh_perfil_vendedor()
        )
    except Exception:
        usuario_logado_eh_vendedor = False

    if usuario_logado_eh_vendedor:
        try:
            id_minha_carteira = _resolver_id_fato_carteira_vendedor_logado()
            if id_minha_carteira > 0:
                minha_carteira_url = url_for(
                    "Paineis.carteira_detalhe",
                    id_fato_carteira_vendedor=id_minha_carteira,
                )
        except Exception:
            id_minha_carteira = 0
            minha_carteira_url = None

    return {
        "pode_acessar_menu_paineis": pode_acessar_menu_paineis,
        "usuario_logado_eh_vendedor_paineis": usuario_logado_eh_vendedor,
        "id_minha_carteira_vendedor": id_minha_carteira,
        "minha_carteira_url": minha_carteira_url,
        "home_usuario_url": home_usuario_url,
    }



def exige_admin_ou_usuarios_gerenciar(view_func):
    @wraps(view_func)
    def wrapper(*args, **kwargs):
        if not current_user.is_authenticated:
            return abort(401)

        pode = (
            current_user.has_permission("ADMIN_TUDO") or
            current_user.has_permission("USUARIOS_GERENCIAR")
        )
        if not pode:
            return abort(403)

        return view_func(*args, **kwargs)
    return wrapper









_TRANSIENT_SQLSTATE = ("08S01",)           
_TRANSIENT_MSG = ("10054", "10060", "timeout", "communication link failure", "reset by peer")

def _is_disconnect_error(exc: OperationalError) -> bool:
    s = str(getattr(exc, "orig", exc)).lower()
    return any(code.lower() in s for code in _TRANSIENT_SQLSTATE) or any(m in s for m in _TRANSIENT_MSG)

def _cleanup_session_and_pool(db):
    try:
        db.session.rollback()
    except Exception:
        pass
    try:
        db.session.close()
    except Exception:
        pass
    
    try:
        db.engine.dispose()
    except Exception:
        pass


def retry_get_view(db, attempts: int = 6, base_delay: float = 0.2, max_delay: float = 1.5):

    def _decorator(fn):
        @wraps(fn)
        def _wrapped(*args, **kwargs):
            if request.method != "GET":
                return fn(*args, **kwargs)

            last_exc = None
            for i in range(attempts):
                try:
                    return fn(*args, **kwargs)
                except OperationalError as e:
                    if not _is_disconnect_error(e):
                        raise
                    last_exc = e
                    _cleanup_session_and_pool(db)
                  
                    sleep_s = min(max_delay, base_delay * (2 ** i)) + random.uniform(0, 0.15)
                    time.sleep(sleep_s)
                except Exception:
  
                    raise
     
            raise last_exc
        return _wrapped
    return _decorator






def _obter_status_contratos_empresa(id_empresa_proprietaria: int | None):
    mapa_padrao = {
        1: "Em Digitação",
        2: "Pendente Geração",
        3: "Documento Gerado",
        4: "Pendente Envio",
        5: "Enviado Assinatura",
        6: "Em Assinatura",
        7: "Ativo",
        8: "Concluido",
        9: "Cancelado",
        10: "ERRO",
        31: "Reprovado",
    }

    try:
        id_empresa = int(id_empresa_proprietaria or 0)
    except Exception:
        id_empresa = 0

    if id_empresa <= 0:
        return [
            {
                "IDDimStatusContratos": id_status,
                "Status": nome,
                "CorHex": _cor_hex_status_contrato_padrao_paineis(id_status),
            }
            for id_status, nome in mapa_padrao.items()
        ]

    sql = text("""
        SELECT
             [IDDimStatusContratos]
            ,[Status]
            ,[CorHex]
        FROM [Integracao].[Silver].[DimStatusContratos]
        WHERE [IDEmpresaProprietaria] = :id_empresa_proprietaria
          AND (
                [IDDimStatusContratos] BETWEEN 1 AND 10
                OR [IDDimStatusContratos] = 31
              )
        ORDER BY [IDDimStatusContratos] ASC
    """)

    rows = db.session.execute(
        sql,
        {"id_empresa_proprietaria": id_empresa},
    ).mappings().all()

    if not rows:
        return [
            {
                "IDDimStatusContratos": id_status,
                "Status": nome,
                "CorHex": _cor_hex_status_contrato_padrao_paineis(id_status),
            }
            for id_status, nome in mapa_padrao.items()
        ]

    retorno = []
    ids_existentes = set()

    for row in rows:
        id_status = int(row.get("IDDimStatusContratos") or 0)
        if id_status <= 0:
            continue

        ids_existentes.add(id_status)
        retorno.append(
            {
                "IDDimStatusContratos": id_status,
                "Status": (row.get("Status") or mapa_padrao.get(id_status) or f"Status {id_status}").strip(),
                "CorHex": _normalizar_hex_css(
                    row.get("CorHex"),
                    _cor_hex_status_contrato_padrao_paineis(id_status) or "#94A3B8",
                ),
            }
        )

    for id_status, nome in mapa_padrao.items():
        if id_status not in ids_existentes:
            retorno.append(
                {
                    "IDDimStatusContratos": id_status,
                    "Status": nome,
                    "CorHex": _cor_hex_status_contrato_padrao_paineis(id_status),
                }
            )

    retorno.sort(key=lambda x: int(x.get("IDDimStatusContratos") or 0))
    return retorno


def _montar_diagrama_status_contrato(
    id_empresa_proprietaria: int | None,
    id_status_atual: int | None,
    nome_status_atual: str | None = None,
):
    status_rows = _obter_status_contratos_empresa(id_empresa_proprietaria)
    mapa_status = {
        int(row.get("IDDimStatusContratos") or 0): (row.get("Status") or "").strip()
        for row in status_rows
        if int(row.get("IDDimStatusContratos") or 0) > 0
    }
    mapa_cor = {
        int(row.get("IDDimStatusContratos") or 0): (
            _normalizar_hex_css(row.get("CorHex"), "")
            or _cor_hex_status_contrato_padrao_paineis(row.get("IDDimStatusContratos"))
        )
        for row in status_rows
        if int(row.get("IDDimStatusContratos") or 0) > 0
    }

    try:
        id_status_corrente = int(id_status_atual or 0)
    except Exception:
        id_status_corrente = 0

    nome_status_corrente = (nome_status_atual or mapa_status.get(id_status_corrente) or "").strip()
    cor_status_corrente = mapa_cor.get(id_status_corrente) or _cor_hex_status_contrato_padrao_paineis(id_status_corrente)

    etapas_principais = []
    for id_status in range(1, 8):
        nome = mapa_status.get(id_status) or f"Status {id_status}"
        concluido = False
        atual = False

        if id_status_corrente in range(1, 8):
            concluido = id_status < id_status_corrente
            atual = id_status == id_status_corrente
        elif id_status_corrente == 8:
            concluido = True

        etapas_principais.append(
            {
                "id": id_status,
                "nome": nome,
                "cor_hex": mapa_cor.get(id_status) or _cor_hex_status_contrato_padrao_paineis(id_status),
                "concluido": concluido,
                "atual": atual,
                "pendente": (not concluido) and (not atual),
                "mostra_d4sign": 2 <= id_status <= 6,
                "logo_d4sign_url": None,
            }
        )

    terminal_atual = None
    if id_status_corrente in (8, 9, 10, 31):
        terminal_atual = {
            "id": id_status_corrente,
            "nome": mapa_status.get(id_status_corrente) or nome_status_corrente or f"Status {id_status_corrente}",
            "cor_hex": mapa_cor.get(id_status_corrente) or _cor_hex_status_contrato_padrao_paineis(id_status_corrente),
            "classe": "sucesso" if id_status_corrente == 8 else "erro",
            "icone": "✓" if id_status_corrente == 8 else "✖" if id_status_corrente in (9, 31) else "!",
        }

    return {
        "status_atual_id": id_status_corrente if id_status_corrente > 0 else None,
        "status_atual_nome": nome_status_corrente or (mapa_status.get(id_status_corrente) if id_status_corrente > 0 else None),
        "status_atual_cor": cor_status_corrente,
        "etapas": etapas_principais,
        "terminal_atual": terminal_atual,
    }



@paineis_bp.route("/ocupacao/novo", methods=["GET", "POST"])
@login_required
@limiter.limit("25 per minute", methods=["POST"])
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def cadastrar_ocupacao():

    LOOPS_PERMITIDOS = ["1MIN", "2MIN"]


    clientes = (
        db.session.query(DimClientes)
        .order_by(
            case((DimClientes.NomeFantasia == None, 1), else_=0),
            DimClientes.NomeFantasia.asc(),
            case((DimClientes.RazaoSocial == None, 1), else_=0),
            DimClientes.RazaoSocial.asc(),
        )
        .all()
    )

    vendedores = (
        db.session.query(Vendedores)
        .order_by(
            case((Vendedores.NomeVendedor == None, 1), else_=0),
            Vendedores.NomeVendedor.asc(),
        )
        .all()
    )

    rows_cp = (
        db.session.query(DimFacesPaineis.CodPonto)
        .filter(DimFacesPaineis.CodPonto != None)
        .group_by(DimFacesPaineis.CodPonto)
        .order_by(DimFacesPaineis.CodPonto.asc())
        .all()
    )

    codpontos = []
    for (cp,) in rows_cp:
        if cp is None:
            continue
        try:
            codpontos.append(int(cp))
        except:
            continue

    rows_faces = (
        db.session.query(DimFacesPaineis.CodPonto, DimFacesPaineis.CodFace)
        .filter(
            DimFacesPaineis.CodPonto != None,
            DimFacesPaineis.CodFace != None,
            DimFacesPaineis.CodFace != "",
        )
        .group_by(DimFacesPaineis.CodPonto, DimFacesPaineis.CodFace)
        .all()
    )

    faces_por_ponto: dict[int, list[str]] = {}
    for cp, cf in rows_faces:
        try:
            cp_int = int(cp)
        except:
            continue
        if not cf:
            continue
        faces_por_ponto.setdefault(cp_int, []).append(str(cf))

    for cp_int in list(faces_por_ponto.keys()):
        faces_por_ponto[cp_int] = sorted(set(faces_por_ponto[cp_int]))


    form = CadastroContratoManualForm()

  
    form.cliente_id.choices = [
        (
            int(c.IDCliente),
            f"{(c.NomeFantasia or c.RazaoSocial or 'Cliente sem nome').strip()} {(('— ' + (c.CNPJ or '').strip()) if (c.CNPJ or '').strip() else '')}".strip()
        )
        for c in clientes
    ]
    form.vendedor_id.choices = [
        (int(v.IDVendedor), (v.NomeVendedor or "Vendedor sem nome").strip())
        for v in vendedores
    ]
    form.cod_ponto.choices = [(int(cp), str(cp)) for cp in codpontos]
    form.loop_tipo.choices = [(lp, lp) for lp in LOOPS_PERMITIDOS]

   
    default_cod_ponto = 118
    default_cod_face = "118AD"

    cod_ponto_selecionado = None
    if form.cod_ponto.data:
        try:
            cod_ponto_selecionado = int(form.cod_ponto.data)
        except:
            cod_ponto_selecionado = None

    if cod_ponto_selecionado is None:
        cod_ponto_selecionado = (
            default_cod_ponto if default_cod_ponto in codpontos else (codpontos[0] if codpontos else None)
        )

    faces_lista = faces_por_ponto.get(cod_ponto_selecionado, []) if cod_ponto_selecionado else []
    form.cod_face.choices = [(cf, cf) for cf in faces_lista]



    if request.method == "GET":
        hoje = datetime.now().date()

        if cod_ponto_selecionado is not None:
            form.cod_ponto.data = cod_ponto_selecionado

        if faces_lista:
            form.cod_face.data = default_cod_face if default_cod_face in faces_lista else faces_lista[0]

        form.loop_tipo.data = "2MIN" if "2MIN" in LOOPS_PERMITIDOS else LOOPS_PERMITIDOS[0]

        if vendedores:
            form.vendedor_id.data = int(vendedores[0].IDVendedor)

     
        form.origem.data = "MANUAL"
        form.tipo_documento.data = "MANUAL"
        form.data_lancamento.data = hoje

      
        form.data_inicio_previsto.data = hoje
        form.data_termino_previsto.data = hoje
        form.cota.data = 1
        form.permuta.data = "0"

        return render_template(
            "euromidia/ocupacao_form.html",
            form=form,
            clientes=clientes,
            vendedores=vendedores,
            codpontos=codpontos,
            faces_por_ponto=faces_por_ponto,
            loops=LOOPS_PERMITIDOS,
        )



    if not form.validate_on_submit():
        erros = []
        for campo, msgs in form.errors.items():
            for msg in msgs:
                erros.append(f"{campo}: {msg}")
        flash("Form inválido: " + " | ".join(erros), "danger")
        return redirect(url_for("Paineis.cadastrar_ocupacao"))

    try:
     
        cliente_id = int(form.cliente_id.data)
        vendedor_id = int(form.vendedor_id.data)

        numero_contrato = (form.numero_contrato.data or "").strip() or None
        numero_previa = (form.numero_previa.data or "").strip() or None
        data_lancamento = form.data_lancamento.data
        cidade_exibicao = (form.cidade_exibicao.data or "").strip() or None
        origem = (form.origem.data or "MANUAL").strip()
        tipo_documento = (form.tipo_documento.data or "MANUAL").strip()

  
        item_1 = {
            "cod_ponto": int(form.cod_ponto.data),
            "cod_face": (form.cod_face.data or "").strip(),
            "data_inicio": form.data_inicio_previsto.data,
            "data_fim": form.data_termino_previsto.data,
            "loop": (form.loop_tipo.data or "").strip(),
            "cota": int(form.cota.data or 1),
            "qtd_parcelas": form.quantidade_parcelas.data,
            "bruto_mensal": form.faturamento_bruto_mensal.data,
            "liquido_mensal": form.faturamento_liquido_mensal.data,
            "permuta_flag": 1 if (form.permuta.data or "0") == "1" else 0,
            "valor_permuta": form.valor_permuta.data,
        }

   
        extras_cod_ponto = request.form.getlist("itens_cod_ponto[]")
        extras_cod_face = request.form.getlist("itens_cod_face[]")
        extras_data_inicio = request.form.getlist("itens_data_inicio[]")
        extras_data_fim = request.form.getlist("itens_data_fim[]")
        extras_loop = request.form.getlist("itens_loop[]")

        extras_cota = request.form.getlist("itens_cota[]")
        extras_parcelas = request.form.getlist("itens_quantidade_parcelas[]")
        extras_bruto = request.form.getlist("itens_faturamento_bruto_mensal[]")
        extras_liquido = request.form.getlist("itens_faturamento_liquido_mensal[]")
        extras_permuta = request.form.getlist("itens_permuta[]")
        extras_valor_permuta = request.form.getlist("itens_valor_permuta[]")

      
        itens = [item_1]

      
        n = len(extras_cod_ponto)
        if not (len(extras_cod_face) == n == len(extras_data_inicio) == len(extras_data_fim) == len(extras_loop)):
            raise ValueError("Itens adicionais inconsistentes (listas de campos com tamanhos diferentes).")

        def _to_int(v, padrao=None):
            s = (v or "").strip()
            if not s:
                return padrao
            return int(s)

        def _to_date(v):
            s = (v or "").strip()
            if not s:
                return None
            return datetime.strptime(s, "%Y-%m-%d").date()

        def _to_decimal_str(v):
    
            s = (v or "").strip()
            return s if s else None

        for i in range(n):
            cp = _to_int(extras_cod_ponto[i])
            cf = (extras_cod_face[i] or "").strip()
            di = _to_date(extras_data_inicio[i])
            df = _to_date(extras_data_fim[i])
            lp = (extras_loop[i] or "").strip()

            if not cp:
                raise ValueError(f"Item adicional #{i+2}: informe o CodPonto.")
            if not cf:
                raise ValueError(f"Item adicional #{i+2}: informe o CodFace.")
            if not di or not df:
                raise ValueError(f"Item adicional #{i+2}: informe Data Início e Data Fim.")
            if df < di:
                raise ValueError(f"Item adicional #{i+2}: Data Fim não pode ser menor que Data Início.")

            cota_i = _to_int(extras_cota[i] if i < len(extras_cota) else "", 1) or 1
            parcelas_i = _to_int(extras_parcelas[i] if i < len(extras_parcelas) else "", None)
            bruto_i = _to_decimal_str(extras_bruto[i] if i < len(extras_bruto) else "")
            liquido_i = _to_decimal_str(extras_liquido[i] if i < len(extras_liquido) else "")
            permuta_i = 1 if (extras_permuta[i] if i < len(extras_permuta) else "0") == "1" else 0
            valor_permuta_i = _to_decimal_str(extras_valor_permuta[i] if i < len(extras_valor_permuta) else "")

            itens.append(
                {
                    "cod_ponto": cp,
                    "cod_face": cf,
                    "data_inicio": di,
                    "data_fim": df,
                    "loop": lp,
                    "cota": cota_i,
                    "qtd_parcelas": parcelas_i,
                    "bruto_mensal": bruto_i,
                    "liquido_mensal": liquido_i,
                    "permuta_flag": permuta_i,
                    "valor_permuta": valor_permuta_i,
                }
            )

    
        if not numero_previa:
          
            numero_previa = f"MANUAL-{itens[0]['cod_ponto']}-{itens[0]['cod_face']}-{datetime.now().strftime('%Y%m%d%H%M%S')}"

     
   
        cliente = db.session.query(DimClientes).filter(DimClientes.IDCliente == cliente_id).first()
        if not cliente:
            raise ValueError("Cliente inválido (não encontrado).")

        vendedor_obj = db.session.query(Vendedores).filter(Vendedores.IDVendedor == vendedor_id).first()
        if not vendedor_obj:
            raise ValueError("Vendedor inválido (não encontrado).")

        marca_exibida = (
            (getattr(cliente, "NomeFantasia", None) or "").strip()
            or (getattr(cliente, "RazaoSocial", None) or "").strip()
            or "Cliente sem nome"
        )
        razao_social = (getattr(cliente, "RazaoSocial", None) or "").strip() or None
        cnpj = (getattr(cliente, "CNPJ", None) or "").strip() or None
        cpf = (getattr(cliente, "CPF", None) or "").strip() or None
        nome_vendedor = (getattr(vendedor_obj, "NomeVendedor", None) or "").strip() or "Vendedor"

 
        sql_insert_contrato = text("""
            INSERT INTO [Integracao].[Silver].[FatoControleContratos] (
                DataAtualizacao,
                IDEmpresaProprietaria,
                NumeroContrato,
                NumeroPrevia,
                DataLancamento,
                CidadeExibicao,
                Origem,
                TipoDocumento,
                RazaoSocial,
                CNPJ,
                CPF,
                MarcaExibida,
                IDDimClientesEuromidia,
                QtdeCodFace,
                QtdeCodPonto,
                TotalBrutoContrato,
                TotalLiquidoContratoAGBRCTACORDO,
                TotalLiquidoContratoAGBRVENDGERCOOR,
                TotalValorMensalAgencia,
                TotalValorBureauMensal,
                TotalValorAcordoMensal,
                TotalOutrasComissoes,
                TotalFaturamentoLiquidoMensal,
                TotalFaturamentoLiquidoMensalFinal,
                TotalValorVendedor,
                ValorVendedorTotal,
                TotalValorCoordenador,
                ValorCoordenadorTotal,
                ValorGerenciaTotal,
                DimVendedor
            )
            OUTPUT INSERTED.IDFatoControleContratosEuromidia
            VALUES (
                GETDATE(),
                NULL,
                :NumeroContrato,
                :NumeroPrevia,
                :DataLancamento,
                :CidadeExibicao,
                :Origem,
                :TipoDocumento,
                :RazaoSocial,
                :CNPJ,
                :CPF,
                :MarcaExibida,
                :IDDimClientesEuromidia,
                :QtdeCodFace,
                :QtdeCodPonto,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                :DimVendedor
            );
        """)

        id_fato_contrato = db.session.execute(
            sql_insert_contrato,
            {
                "NumeroContrato": numero_contrato,
                "NumeroPrevia": numero_previa,
                "DataLancamento": data_lancamento,
                "CidadeExibicao": cidade_exibicao,
                "Origem": origem,
                "TipoDocumento": tipo_documento,
                "RazaoSocial": razao_social,
                "CNPJ": cnpj,
                "CPF": cpf,
                "MarcaExibida": marca_exibida,
                "IDDimClientesEuromidia": cliente_id,
                "QtdeCodFace": int(len(itens)),
                "QtdeCodPonto": int(len(itens)),
                "DimVendedor": nome_vendedor,
            },
        ).scalar_one()

 
        sql_insert_item = text("""
            INSERT INTO [Integracao].[Silver].[FatoControleContratosItens] (
                DataAtualizacao,
                NumeroContrato,
                NumeroPrevia,
                DataLancamento,
                DataAssinaturaRenovacao,
                DataInicioPrevisto,
                DataTerminoPrevisto,
                DataCancelamento,
                CidadeExibicao,
                Tipo,
                Origem,
                TipoDocumento,
                RazaoSocial,
                CNPJ,
                CPF,
                MarcaExibida,
                Vendedor,
                SDR,
                InicioRenovacao,
                AtivoCancelamento,
                Cota,
                CodPonto,
                CodFace,
                TempoExibicaoDias,
                QuantidadeParcelas,
                FaturamentoBrutoMensal,
                ValorPermuta,
                FaturamentoLiquidoPermuta,
                TotalBrutoContrato,
                TotalLiquidoContratoAGBRCTACORDO,
                TotalLiquidoContratoAGBRVENDGERCOOR,
                ValorMensalAgencia,
                ValorBureauMensal,
                ValorAcordoMensal,
                OutrasComissoes,
                FaturamentoLiquidoMensal,
                FaturamentoLiquidoMensalFinal,
                ValorVendedor,
                ValorVendedorTotal,
                ValorCoordenador,
                ValorCoordenadorTotal,
                ValorGerencia,
                ValorGerenciaTotal,
                Permuta,
                PercentualAgencia,
                PercentualBureau,
                PercentualCartaAcordo,
                PercentualComissaoVendedor,
                ComissaoCoordenacao,
                PercentualComissaoGerencia,
                IDFatoControleContratosEuromidia,
                IDVendedor
            )
            VALUES (
                GETDATE(),
                :NumeroContrato,
                :NumeroPrevia,
                :DataLancamento,
                NULL,
                :DataInicioPrevisto,
                :DataTerminoPrevisto,
                NULL,
                :CidadeExibicao,
                :Tipo,
                :Origem,
                :TipoDocumento,
                :RazaoSocial,
                :CNPJ,
                :CPF,
                :MarcaExibida,
                :Vendedor,
                NULL,
                NULL,
                NULL,
                :Cota,
                :CodPonto,
                :CodFace,
                NULL,
                :QuantidadeParcelas,
                :FaturamentoBrutoMensal,
                :ValorPermuta,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                :FaturamentoLiquidoMensal,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                :Permuta,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                NULL,
                :IDFatoControleContratosEuromidia,
                :IDVendedor
            );
        """)

      
        for idx, it in enumerate(itens, start=1):
            cod_ponto = int(it["cod_ponto"])
            cod_face = (it["cod_face"] or "").strip()
            data_inicio = it["data_inicio"]
            data_fim = it["data_fim"]
            loop = (it["loop"] or "").strip()

       
            info_face = (
                db.session.query(
                    func.coalesce(DimFacesPaineis.Tipo, DimPaineisEuromidia.Tipo).label("TipoPainel"),
                    DimFacesPaineis.IDDimPaineisEuromidia.label("IDDimPaineisEuromidia"),
                )
                .outerjoin(
                    DimPaineisEuromidia,
                    DimPaineisEuromidia.IDDimPaineisEuromidia == DimFacesPaineis.IDDimPaineisEuromidia,
                )
                .filter(
                    DimFacesPaineis.CodPonto == cod_ponto,
                    DimFacesPaineis.CodFace == cod_face,
                )
                .first()
            )
            if not info_face:
                raise ValueError(f"Item #{idx}: CodFace inválido para o CodPonto selecionado.")

            tipo_painel_face = (info_face.TipoPainel or "").strip().upper()
            eh_digital = (tipo_painel_face == "PAINEL DIGITAL")

            if eh_digital:
                if loop not in LOOPS_PERMITIDOS:
                    raise ValueError(f"Item #{idx}: Loop inválido. Use: {', '.join(LOOPS_PERMITIDOS)}.")
            else:
                loop = "2MIN"

            db.session.execute(
                sql_insert_item,
                {
                    "NumeroContrato": numero_contrato,
                    "NumeroPrevia": numero_previa,
                    "DataLancamento": data_lancamento,
                    "DataInicioPrevisto": data_inicio,
                    "DataTerminoPrevisto": data_fim,
                    "CidadeExibicao": cidade_exibicao,
                    "Tipo": loop, 
                    "Origem": origem,
                    "TipoDocumento": tipo_documento,
                    "RazaoSocial": razao_social,
                    "CNPJ": cnpj,
                    "CPF": cpf,
                    "MarcaExibida": marca_exibida,
                    "Vendedor": nome_vendedor,
                    "Cota": int(it.get("cota") or 1),
                    "CodPonto": cod_ponto,
                    "CodFace": cod_face,
                    "QuantidadeParcelas": it.get("qtd_parcelas"),
                    "FaturamentoBrutoMensal": it.get("bruto_mensal"),
                    "FaturamentoLiquidoMensal": it.get("liquido_mensal"),
                    "Permuta": int(it.get("permuta_flag") or 0),
                    "ValorPermuta": it.get("valor_permuta"),
                    "IDFatoControleContratosEuromidia": int(id_fato_contrato),
                    "IDVendedor": vendedor_id,
                },
            )

        db.session.commit()
        flash(f"Contrato MANUAL cadastrado com sucesso. IDFatoControleContratosEuromidia={id_fato_contrato}", "success")
        return redirect(url_for("Paineis.cadastrar_ocupacao"))

    except Exception as e:
        db.session.rollback()
        flash(str(e), "danger")
        return redirect(url_for("Paineis.cadastrar_ocupacao"))




@paineis_bp.route("/api/pontos", methods=["GET"])
@limiter.limit("120 per minute", methods=["GET"])
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def api_pontos():
    q = (request.args.get("q") or "").strip()

    sql = text("""
        SELECT TOP (100)
            p.CodPonto,
            TipoPainel = MAX(NULLIF(LTRIM(RTRIM(COALESCE(p.Tipo, ''))), ''))
        FROM [Integracao].[Silver].[DimPaineisEuromidia] p
        WHERE
            p.CodPonto IS NOT NULL
            AND (
                :q = ''
                OR CAST(p.CodPonto AS varchar(30)) LIKE :q_like
            )
        GROUP BY p.CodPonto
        ORDER BY p.CodPonto ASC
    """)

    rows = db.session.execute(
        sql,
        {
            "q": q,
            "q_like": f"{q}%"
        }
    ).mappings().all()

    itens = []

    for row in rows:
        cod_ponto = row["CodPonto"]
        if cod_ponto is None:
            continue

        tipo_painel = _normalizar_texto_checkin(row["TipoPainel"]) or "Sem tipo"

        try:
            cod_ponto_int = int(cod_ponto)
        except Exception:
            continue

        itens.append({
            "cod_ponto": cod_ponto_int,
            "tipo_painel": tipo_painel,
            "texto": f"{cod_ponto_int} | {tipo_painel}",
        })

    return jsonify({"items": itens})


@paineis_bp.route("/api/pontos/<int:codponto>/faces", methods=["GET"])
@login_required
@limiter.limit("120 per minute", methods=["GET"])
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def api_faces_do_ponto(codponto: int):
    sql = text("""
        SELECT TOP (200)
            f.CodFace,
            TipoFace = MAX(
                NULLIF(
                    LTRIM(RTRIM(COALESCE(f.Tipo, p.Tipo, ''))),
                    ''
                )
            )
        FROM [Integracao].[Silver].[DimFacesPaineis] f
        LEFT JOIN [Integracao].[Silver].[DimPaineisEuromidia] p
            ON p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia
        WHERE
            f.CodPonto = :codponto
            AND NULLIF(LTRIM(RTRIM(COALESCE(f.CodFace, ''))), '') IS NOT NULL
        GROUP BY f.CodFace
        ORDER BY f.CodFace ASC
    """)

    rows = db.session.execute(
        sql,
        {"codponto": codponto}
    ).mappings().all()

    itens = []

    for row in rows:
        cod_face = _normalizar_texto_checkin(row["CodFace"])
        if not cod_face:
            continue

        tipo_face = _normalizar_texto_checkin(row["TipoFace"]) or "Sem tipo"

        itens.append({
            "cod_face": cod_face,
            "tipo_face": tipo_face,
            "texto": f"{cod_face} | {tipo_face}",
        })

    return jsonify({
        "codponto": codponto,
        "items": itens
    })


@paineis_bp.route("/api/lista-paineis/sugestoes", methods=["GET"])
@login_required
@limiter.limit("180 per minute", methods=["GET"])
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def api_sugestoes_lista_paineis():
    """
    Eu alimento o combobox da lista de painéis.

    A sugestão mostra CodFace, endereço, bairro, cidade, tipo e formato.
    Ao selecionar uma opção no frontend, o campo q mantém os CodFaces já digitados
    e substitui apenas o trecho atual da busca pelo CodFace escolhido.
    """
    q_original = (request.args.get("q") or "").strip()
    ponto_ativo = (request.args.get("ponto_ativo") or "1").strip().lower()

    """Eu trato busca múltipla separada por vírgula e pesquiso o último trecho digitado no combobox."""
    partes_busca = [parte.strip() for parte in re.split(r"[,;\n]+", q_original) if parte.strip()]
    q = partes_busca[-1] if partes_busca else q_original

    if len(q) < 1:
        return jsonify({"items": []})

    q_limpo = q[:80]
    q_like = f"%{q_limpo.upper()}%"
    q_prefix = f"{q_limpo.upper()}%"

    somente_digitos = "".join([c for c in q_limpo if c.isdigit()])
    tem_busca_cnpj = 1 if len(somente_digitos) >= 8 else 0
    cnpj_like = f"%{somente_digitos}%" if tem_busca_cnpj else ""

    filtrar_ativo = 1 if ponto_ativo in ("0", "1") else 0
    ativo_int = 1 if ponto_ativo == "1" else 0

    sql = text("""
        WITH ultimo_painel AS (
            SELECT
                base.CodPonto,
                base.TipoNorm,
                base.Tipo,
                base.Logradouro,
                base.Bairro,
                base.Cidade,
                base.UF,
                base.FormatoLxA,
                base.BitAtivo
            FROM (
                SELECT
                    p.CodPonto,
                    TipoNorm = UPPER(LTRIM(RTRIM(COALESCE(p.Tipo, '')))),
                    p.Tipo,
                    p.Logradouro,
                    p.Bairro,
                    p.Cidade,
                    p.UF,
                    p.FormatoLxA,
                    p.BitAtivo,
                    rn = ROW_NUMBER() OVER (
                        PARTITION BY p.CodPonto, UPPER(LTRIM(RTRIM(COALESCE(p.Tipo, ''))))
                        ORDER BY p.DataAtualizacao DESC, p.IDDimPaineisEuromidia DESC
                    )
                FROM [Integracao].[Silver].[DimPaineisEuromidia] AS p
                WHERE p.CodPonto IS NOT NULL
            ) AS base
            WHERE base.rn = 1
        )
        SELECT TOP (30)
            CodFace = LTRIM(RTRIM(COALESCE(f.CodFace, ''))),
            CodPonto = f.CodPonto,
            Tipo = NULLIF(LTRIM(RTRIM(COALESCE(f.Tipo, up.Tipo, ''))), ''),
            Endereco = NULLIF(LTRIM(RTRIM(COALESCE(up.Logradouro, ''))), ''),
            Bairro = NULLIF(LTRIM(RTRIM(COALESCE(up.Bairro, ''))), ''),
            Cidade = NULLIF(LTRIM(RTRIM(COALESCE(up.Cidade, ''))), ''),
            UF = NULLIF(LTRIM(RTRIM(COALESCE(up.UF, ''))), ''),
            Formato = NULLIF(LTRIM(RTRIM(COALESCE(up.FormatoLxA, ''))), '')
        FROM [Integracao].[Silver].[DimFacesPaineis] AS f
        INNER JOIN ultimo_painel AS up
            ON up.CodPonto = f.CodPonto
           AND up.TipoNorm = UPPER(LTRIM(RTRIM(COALESCE(f.Tipo, ''))))
        WHERE
            NULLIF(LTRIM(RTRIM(COALESCE(f.CodFace, ''))), '') IS NOT NULL
            AND (:filtrar_ativo = 0 OR CONVERT(int, COALESCE(up.BitAtivo, 0)) = :ativo_int)
            AND (
                UPPER(LTRIM(RTRIM(COALESCE(f.CodFace, '')))) LIKE :q_like
                OR CAST(f.CodPonto AS varchar(30)) LIKE :q_like
                OR UPPER(LTRIM(RTRIM(COALESCE(up.Logradouro, '')))) LIKE :q_like
                OR UPPER(LTRIM(RTRIM(COALESCE(up.Bairro, '')))) LIKE :q_like
                OR UPPER(LTRIM(RTRIM(COALESCE(up.Cidade, '')))) LIKE :q_like
                OR UPPER(LTRIM(RTRIM(COALESCE(f.Tipo, up.Tipo, '')))) LIKE :q_like
                OR UPPER(LTRIM(RTRIM(COALESCE(up.FormatoLxA, '')))) LIKE :q_like
                OR (
                    :tem_busca_cnpj = 1
                    AND EXISTS (
                        SELECT 1
                        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] AS it
                        WHERE
                            it.CodFace = f.CodFace
                            AND (it.CodPonto = f.CodPonto OR it.CodPonto IS NULL)
                            AND REPLACE(REPLACE(REPLACE(COALESCE(it.CNPJ, ''), '.', ''), '/', ''), '-', '') LIKE :cnpj_like
                    )
                )
            )
        ORDER BY
            CASE
                WHEN UPPER(LTRIM(RTRIM(COALESCE(f.CodFace, '')))) LIKE :q_prefix THEN 0
                WHEN CAST(f.CodPonto AS varchar(30)) LIKE :q_prefix THEN 1
                WHEN UPPER(LTRIM(RTRIM(COALESCE(up.Cidade, '')))) LIKE :q_prefix THEN 2
                WHEN UPPER(LTRIM(RTRIM(COALESCE(up.Bairro, '')))) LIKE :q_prefix THEN 3
                ELSE 9
            END,
            up.Cidade ASC,
            f.CodFace ASC
    """)

    rows = db.session.execute(
        sql,
        {
            "q_like": q_like,
            "q_prefix": q_prefix,
            "tem_busca_cnpj": tem_busca_cnpj,
            "cnpj_like": cnpj_like,
            "filtrar_ativo": filtrar_ativo,
            "ativo_int": ativo_int,
        },
    ).mappings().all()

    itens = []
    vistos = set()

    for row in rows:
        cod_face = (row.get("CodFace") or "").strip()
        if not cod_face:
            continue

        cod_ponto = row.get("CodPonto")
        chave = (str(cod_ponto or "").strip(), cod_face.upper())
        if chave in vistos:
            continue
        vistos.add(chave)

        tipo = (row.get("Tipo") or "").strip()
        endereco = (row.get("Endereco") or "").strip()
        bairro = (row.get("Bairro") or "").strip()
        cidade = (row.get("Cidade") or "").strip()
        uf = (row.get("UF") or "").strip()
        formato = (row.get("Formato") or "").strip()

        cidade_uf = cidade
        if cidade and uf:
            cidade_uf = f"{cidade}/{uf}"
        elif uf:
            cidade_uf = uf

        partes_texto = [cod_face]
        if endereco:
            partes_texto.append(endereco)
        if bairro:
            partes_texto.append(bairro)
        if cidade_uf:
            partes_texto.append(cidade_uf)
        if tipo:
            partes_texto.append(tipo)
        if formato:
            partes_texto.append(formato)

        itens.append(
            {
                "cod_face": cod_face,
                "cod_ponto": cod_ponto,
                "tipo": tipo or "Sem tipo",
                "endereco": endereco,
                "bairro": bairro,
                "cidade": cidade,
                "uf": uf,
                "cidade_uf": cidade_uf,
                "formato": formato,
                "texto": " | ".join(partes_texto),
            }
        )

    return jsonify({"items": itens})




CAPACIDADE_DIGITAL_FIXA = 16

ID_PERFIL_VENDEDOR_PADRAO = 3
ID_PERFIL_ADMIN_PADRAO = 1
ID_PERFIL_CONTROLE_PADRAO = 4
ID_PERFIL_COORDENADOR_PADRAO = 5


def _normalizar_nome_perfil_paineis(valor) -> str:
    texto = str(valor or "").strip().lower()
    if not texto:
        return ""
    try:
        texto = unicodedata.normalize("NFKD", texto).encode("ascii", "ignore").decode("ascii")
    except Exception:
        pass
    return texto.strip()


def _usuario_logado_eh_perfil_admin() -> bool:
    """Eu identifico Admin real pelo ID 1 ou pelo nome do perfil."""
    try:
        if int(getattr(current_user, "IDDimPerfilUsuario", 0) or 0) == ID_PERFIL_ADMIN_PADRAO:
            return True
    except Exception:
        pass

    try:
        perfil = getattr(current_user, "perfil", None)
        candidatos = [
            getattr(current_user, "NomePerfil", None),
            getattr(current_user, "Perfil", None),
            getattr(current_user, "DescricaoPerfil", None),
            getattr(perfil, "NomePerfil", None) if perfil is not None else None,
            getattr(perfil, "Descricao", None) if perfil is not None else None,
        ]
        return any(
            _normalizar_nome_perfil_paineis(valor) in {
                "admin",
                "administrador",
                "administrador geral",
                "administrador do sistema",
                "super admin",
                "superadmin",
            }
            for valor in candidatos
        )
    except Exception:
        return False


def _usuario_logado_eh_perfil_coordenador() -> bool:
    """Eu identifico Coordenador pelo ID 5 e por fallback pelo nome do perfil."""
    try:
        if int(getattr(current_user, "IDDimPerfilUsuario", 0) or 0) == ID_PERFIL_COORDENADOR_PADRAO:
            return True
    except Exception:
        pass

    try:
        perfil = getattr(current_user, "perfil", None)
        candidatos = [
            getattr(current_user, "NomePerfil", None),
            getattr(current_user, "Perfil", None),
            getattr(current_user, "DescricaoPerfil", None),
            getattr(perfil, "NomePerfil", None) if perfil is not None else None,
            getattr(perfil, "Descricao", None) if perfil is not None else None,
        ]
        return any(_normalizar_nome_perfil_paineis(valor) == "coordenador" for valor in candidatos)
    except Exception:
        return False


def _usuario_logado_eh_perfil_controle() -> bool:
    """Eu identifico Controle pelo ID 4 e por fallback pelo nome do perfil."""
    try:
        if int(getattr(current_user, "IDDimPerfilUsuario", 0) or 0) == ID_PERFIL_CONTROLE_PADRAO:
            return True
    except Exception:
        pass

    try:
        perfil = getattr(current_user, "perfil", None)
        candidatos = [
            getattr(current_user, "NomePerfil", None),
            getattr(current_user, "Perfil", None),
            getattr(current_user, "DescricaoPerfil", None),
            getattr(perfil, "NomePerfil", None) if perfil is not None else None,
            getattr(perfil, "Descricao", None) if perfil is not None else None,
        ]
        return any(_normalizar_nome_perfil_paineis(valor) == "controle" for valor in candidatos)
    except Exception:
        return False


def _usuario_logado_tem_acesso_operacional_total_paineis() -> bool:
    """Admin e Coordenador enxergam os filtros e ações operacionais completas."""
    return _usuario_logado_eh_perfil_admin() or _usuario_logado_eh_perfil_coordenador()


def _usuario_logado_eh_perfil_vendedor() -> bool:
    """
    Retorna True quando o usuário logado pertence ao perfil Vendedor.

    Regra de negócio atual:
    - DimPerfilUsuario.IDDimPerfilUsuario = 3 representa o perfil Vendedor.

    Eu também faço fallback pelo nome do perfil para evitar falha caso
    o objeto current_user esteja com o relacionamento perfil carregado.
    """
    try:
        id_perfil = int(getattr(current_user, "IDDimPerfilUsuario", 0) or 0)
        if id_perfil == ID_PERFIL_VENDEDOR_PADRAO:
            return True
    except Exception:
        pass

    try:
        perfil = getattr(current_user, "perfil", None)
        candidatos = [
            getattr(current_user, "NomePerfil", None),
            getattr(current_user, "Perfil", None),
            getattr(current_user, "DescricaoPerfil", None),
            getattr(perfil, "NomePerfil", None) if perfil is not None else None,
            getattr(perfil, "Descricao", None) if perfil is not None else None,
        ]
        if any(_normalizar_nome_perfil_paineis(valor) == "vendedor" for valor in candidatos):
            return True
    except Exception:
        pass

    return False




def _id_usuario_logado_carteira() -> int:
    """Eu retorno o IDDimUsuarios do usuário logado para filtrar carteira com segurança."""
    try:
        return int(getattr(current_user, "IDDimUsuarios", 0) or 0)
    except Exception:
        return 0


def _usuario_logado_pode_ver_marca_reserva(id_usuario_criador) -> bool:
    """Aplica a regra de confidencialidade da marca exibida nas reservas da grade.

    A marca pode ser vista por ADMIN, COORDENADOR e CONTROLE ou pelo próprio
    usuário que criou a reserva. Identificador ausente ou inválido é tratado de
    forma restritiva: somente os três perfis operacionais continuam autorizados.
    """
    if (
        _usuario_logado_eh_perfil_admin()
        or _usuario_logado_eh_perfil_coordenador()
        or _usuario_logado_eh_perfil_controle()
    ):
        return True

    id_usuario_logado = _id_usuario_logado_carteira()

    try:
        id_criador = int(id_usuario_criador or 0)
    except Exception:
        id_criador = 0

    return bool(id_usuario_logado > 0 and id_criador > 0 and id_usuario_logado == id_criador)


def _resolver_id_vendedor_logado_carteira() -> int:
    """Eu encontro o IDVendedor vinculado ao usuário logado.

    A ligação usada é:
    - Integracao.Silver.DimUsuarios.IDDimUsuarios
    - Integracao.dbo.Vendedores.IDDimUsuarios

    Isso permite identificar a carteira própria do perfil Vendedor.
    """
    id_usuario = _id_usuario_logado_carteira()
    if id_usuario <= 0:
        return 0

    id_empresa = 0
    try:
        id_empresa = int(getattr(current_user, "IDEmpresaProprietaria", 0) or 0)
    except Exception:
        id_empresa = 0

    sql = text("""
        SELECT TOP (1)
            v.IDVendedor
        FROM [Integracao].[dbo].[Vendedores] v
        WHERE v.IDDimUsuarios = :id_usuario
          AND ISNULL(v.BitAtivo, 1) = 1
          AND (
                :id_empresa = 0
                OR ISNULL(v.IDEmpresaProprietaria, 0) = :id_empresa
              )
        ORDER BY
            CASE WHEN ISNULL(v.IDEmpresaProprietaria, 0) = :id_empresa THEN 0 ELSE 1 END,
            v.IDVendedor ASC;
    """)

    try:
        valor = db.session.execute(
            sql,
            {
                "id_usuario": id_usuario,
                "id_empresa": id_empresa,
            },
        ).scalar()
        return int(valor or 0)
    except Exception:
        return 0







def _converter_id_inteiro_seguro(valor, padrao: int = 0) -> int:
    """Eu converto IDs vindos do banco para inteiro sem quebrar a request."""
    try:
        if valor is None:
            return padrao
        return int(valor)
    except Exception:
        return padrao


def _usuario_logado_pode_gerenciar_ocupacao_por_id_vendedor(id_vendedor_ocupacao) -> bool:
    """Eu valido se o usuário logado pode alterar/cancelar a ocupação.

    Regra:
    - Admin pode gerenciar qualquer ocupação.
    - Coordenador pode gerenciar qualquer ocupação.
    - Vendedor só pode gerenciar quando a ocupação pertence ao próprio IDVendedor.
    - Outros perfis não recebem permissão operacional por esta regra.
    """
    if not getattr(current_user, "is_authenticated", False):
        return False

    if _usuario_logado_tem_acesso_operacional_total_paineis():
        return True

    if not _usuario_logado_eh_perfil_vendedor():
        return False

    id_vendedor_logado = _resolver_id_vendedor_logado_carteira()
    id_vendedor_ocupacao_int = _converter_id_inteiro_seguro(id_vendedor_ocupacao)

    return (
        id_vendedor_logado > 0
        and id_vendedor_ocupacao_int > 0
        and id_vendedor_logado == id_vendedor_ocupacao_int
    )


def _abortar_se_usuario_nao_pode_gerenciar_ocupacao(id_vendedor_ocupacao) -> None:
    """Eu bloqueio alteração/cancelamento de ocupação de outro vendedor."""
    if not _usuario_logado_pode_gerenciar_ocupacao_por_id_vendedor(id_vendedor_ocupacao):
        abort(403)


def _resolver_id_fato_carteira_vendedor_logado() -> int:
    """Eu encontro o IDFatoCarteiraVendedor da carteira própria do usuário logado.

    Fluxo usado:
    - usuário logado -> IDDimUsuarios;
    - IDDimUsuarios -> Integracao.dbo.Vendedores.IDDimUsuarios;
    - IDVendedor -> Integracao.Silver.FatoCarteiraVendedor.IDVendedor.

    Esse ID é o que monta a URL: /paineis/carteiras/<IDFatoCarteiraVendedor>.
    """
    if not _usuario_logado_eh_perfil_vendedor():
        return 0

    id_usuario = _id_usuario_logado_carteira()
    id_vendedor = _resolver_id_vendedor_logado_carteira()

    if id_usuario <= 0 and id_vendedor <= 0:
        return 0

    id_empresa = 0
    try:
        id_empresa = int(getattr(current_user, "IDEmpresaProprietaria", 0) or 0)
    except Exception:
        id_empresa = 0

    sql = text("""
        SELECT TOP (1)
            cv.IDFatoCarteiraVendedor
        FROM [Integracao].[Silver].[FatoCarteiraVendedor] cv
        INNER JOIN [Integracao].[dbo].[Vendedores] v
            ON v.IDVendedor = cv.IDVendedor
        WHERE ISNULL(v.BitAtivo, 1) = 1
          AND (
                 (:id_vendedor > 0 AND cv.IDVendedor = :id_vendedor)
              OR (:id_usuario > 0 AND v.IDDimUsuarios = :id_usuario)
          )
          AND (
                 :id_empresa = 0
              OR ISNULL(cv.IDEmpresaProprietaria, 0) = :id_empresa
              OR ISNULL(v.IDEmpresaProprietaria, 0) = :id_empresa
          )
        ORDER BY
            CASE WHEN :id_vendedor > 0 AND cv.IDVendedor = :id_vendedor THEN 0 ELSE 1 END,
            CASE WHEN :id_usuario > 0 AND v.IDDimUsuarios = :id_usuario THEN 0 ELSE 1 END,
            cv.IDFatoCarteiraVendedor ASC;
    """)

    try:
        valor = db.session.execute(
            sql,
            {
                "id_usuario": id_usuario,
                "id_vendedor": id_vendedor,
                "id_empresa": id_empresa,
            },
        ).scalar()
        return int(valor or 0)
    except Exception:
        return 0


def _carteira_eh_propria_para_vendedor(carteira_row, id_usuario_logado: int, id_vendedor_logado: int) -> bool:
    """Eu valido se a carteira acessada pertence ao vendedor logado.

    Aqui não libero carteira do Admin, porque a regra nova é: vendedor acessa
    somente "Minha Carteira".
    """
    if not carteira_row:
        return False

    try:
        id_vendedor_carteira = int(carteira_row.get("IDVendedor") or 0)
    except Exception:
        id_vendedor_carteira = 0

    try:
        id_usuario_vendedor = int(carteira_row.get("IDDimUsuariosVendedor") or 0)
    except Exception:
        id_usuario_vendedor = 0

    if id_vendedor_logado > 0 and id_vendedor_carteira == id_vendedor_logado:
        return True

    if id_usuario_logado > 0 and id_usuario_vendedor == id_usuario_logado:
        return True

    return False


def _normalizar_vendedor_para_comparacao(valor) -> str:
    """Normaliza nome de vendedor para comparação segura em regra de acesso."""
    try:
        texto = str(valor or "").strip().casefold()
        texto = unicodedata.normalize("NFKD", texto).encode("ascii", "ignore").decode("ascii")
        texto = re.sub(r"\s+", " ", texto).strip()
        return texto
    except Exception:
        return ""


def _resolver_vendedor_logado_info() -> dict:
    """Retorna o vendedor vinculado ao usuário logado pela tabela Integracao.dbo.Vendedores."""
    id_usuario = _id_usuario_logado_carteira()
    if id_usuario <= 0:
        return {"IDVendedor": 0, "NomeVendedor": ""}

    try:
        id_empresa = int(getattr(current_user, "IDEmpresaProprietaria", 0) or 0)
    except Exception:
        id_empresa = 0

    sql = text("""
        SELECT TOP (1)
             v.IDVendedor
            ,v.NomeVendedor
        FROM [Integracao].[dbo].[Vendedores] v WITH (NOLOCK)
        WHERE v.IDDimUsuarios = :id_usuario
          AND ISNULL(v.BitAtivo, 1) = 1
          AND (
                :id_empresa = 0
                OR ISNULL(v.IDEmpresaProprietaria, 0) = :id_empresa
              )
        ORDER BY
            CASE WHEN ISNULL(v.IDEmpresaProprietaria, 0) = :id_empresa THEN 0 ELSE 1 END,
            v.IDVendedor ASC;
    """)

    try:
        row = db.session.execute(
            sql,
            {
                "id_usuario": id_usuario,
                "id_empresa": id_empresa,
            },
        ).mappings().first()
    except Exception:
        row = None

    if not row:
        return {"IDVendedor": 0, "NomeVendedor": ""}

    try:
        id_vendedor = int(row.get("IDVendedor") or 0)
    except Exception:
        id_vendedor = 0

    return {
        "IDVendedor": id_vendedor,
        "NomeVendedor": str(row.get("NomeVendedor") or "").strip(),
    }


def _contrato_pertence_ao_vendedor_logado(
    id_fato_controle_contratos: int,
    id_vendedor_logado: int | None = None,
    nome_vendedor_logado: str | None = None,
) -> bool:
    """Valida se o contrato possui pelo menos um item vinculado ao vendedor logado."""
    try:
        id_contrato = int(id_fato_controle_contratos or 0)
    except Exception:
        id_contrato = 0

    if id_contrato <= 0:
        return False

    try:
        id_vendedor = int(id_vendedor_logado or 0)
    except Exception:
        id_vendedor = 0

    nome_vendedor_norm = _normalizar_vendedor_para_comparacao(nome_vendedor_logado)

    if id_vendedor <= 0 and not nome_vendedor_norm:
        return False

    sql = text("""
        SELECT
             ctr.Vendedor AS VendedorContrato
            ,i.IDVendedor
            ,i.Vendedor
        FROM [Integracao].[Silver].[FatoControleContratosEuromidia] ctr WITH (NOLOCK)
        LEFT JOIN [Integracao].[Silver].[FatoControleContratosItensEuromidia] i WITH (NOLOCK)
            ON i.IDFatoControleContratoEuromidia = ctr.IDFatoControleContratosEuromidia
        WHERE ctr.IDFatoControleContratosEuromidia = :id_contrato;
    """)

    try:
        rows = db.session.execute(sql, {"id_contrato": id_contrato}).mappings().all()
    except Exception:
        return False

    for row in rows or []:
        try:
            id_vendedor_item = int(row.get("IDVendedor") or 0)
        except Exception:
            id_vendedor_item = 0

        if id_vendedor > 0 and id_vendedor_item == id_vendedor:
            return True

        for campo_vendedor in ("Vendedor", "VendedorContrato"):
            nome_item_norm = _normalizar_vendedor_para_comparacao(row.get(campo_vendedor))
            if nome_vendedor_norm and nome_item_norm and nome_item_norm == nome_vendedor_norm:
                return True

    return False


def _carteira_eh_do_admin_ou_propria_para_vendedor(carteira_row, id_usuario_logado: int, id_vendedor_logado: int) -> bool:
    """Eu valido acesso direto à carteira quando o usuário logado é Vendedor.

    Regra aplicada:
    - permite a carteira do próprio vendedor;
    - permite a carteira do Admin.

    Para a carteira do Admin eu uso uma regra tolerante:
    - usuário vinculado ao vendedor com IDDimPerfilUsuario = 1;
    - ou nome do vendedor/usuário contendo ADMIN ou ADMINISTRADOR.
    """
    if not carteira_row:
        return False

    try:
        id_vendedor_carteira = int(carteira_row.get("IDVendedor") or 0)
    except Exception:
        id_vendedor_carteira = 0

    try:
        id_usuario_vendedor = int(carteira_row.get("IDDimUsuariosVendedor") or 0)
    except Exception:
        id_usuario_vendedor = 0

    if id_vendedor_logado > 0 and id_vendedor_carteira == id_vendedor_logado:
        return True

    if id_usuario_logado > 0 and id_usuario_vendedor == id_usuario_logado:
        return True

    try:
        id_perfil_vendedor_carteira = int(carteira_row.get("IDDimPerfilUsuarioVendedor") or 0)
    except Exception:
        id_perfil_vendedor_carteira = 0

    if id_perfil_vendedor_carteira == ID_PERFIL_ADMIN_PADRAO:
        return True

    nome_vendedor = str(carteira_row.get("NomeVendedor") or "").strip().upper()
    nome_usuario = str(carteira_row.get("NomeUsuarioVendedor") or "").strip().upper()

    return any(
        termo in nome_vendedor or termo in nome_usuario
        for termo in ("ADMIN", "ADMINISTRADOR")
    )

def _primeiro_ultimo_dia_mes(ano: int, mes: int):
    primeiro = date(ano, mes, 1)
    ultimo = date(ano, mes, calendar.monthrange(ano, mes)[1])
    return primeiro, ultimo


def _fim_efetivo_item(dt_fim_previsto, dt_cancelamento):
    df = dt_fim_previsto
    dc = dt_cancelamento

    if df is None and dc is None:
        return None
    if df is None:
        return dc
    if dc is None:
        return df
    return dc if dc < df else df


def _span_por_cota(cota) -> int:
    """Regra oficial: Cota 1080 = 2 slots; Cota 540 = 1 slot."""
    try:
        c = int(round(float(str(cota).strip().replace(',', '.'))))
    except Exception:
        c = None

    if c == 1080:
        return 2
    if c == 540:
        return 1

    return 1


def _calcular_ocupacao_e_conflitos_por_grupo(
    ocupacoes,
    tipo_por_face,
    tipo_por_idcadastro,
    capacidade_digital_por_cp,
    faces_por_cp_tipo,
    dt_ini,
    dt_fim,
):

    def _daterange(d0: date, d1: date):
        cur = d0
        while cur <= d1:
            yield cur
            cur += timedelta(days=1)


    out = {}


    spans_por_cp_por_dia = {}


    intervalos_por_face = {}


    faces_ocupadas_nao_digital = set()


    for cp, cf, cota, di, df, idcad in ocupacoes:
        if cp is None or di is None or df is None:
            continue

        
        cf_norm = (str(cf) or "").strip() if cf is not None else ""


        ini = max(di, dt_ini)
        fim = min(df, dt_fim)
        if fim < ini:
            continue

        tipo = ""
        if idcad not in (None, ""):
            try:
                tipo = (tipo_por_idcadastro.get(int(idcad)) or "").strip().upper()
            except:
                tipo = ""

        if not tipo and cf_norm:
            tipo = (tipo_por_face.get((cp, cf_norm)) or "").strip().upper()

      
        if not tipo:
            if (cp, "PAINEL DIGITAL") in faces_por_cp_tipo or int(capacidade_digital_por_cp.get(cp) or 0) > 0:
                tipo = "PAINEL DIGITAL"

        if not tipo:
            continue

        if tipo == "PAINEL DIGITAL":
            span = _span_por_cota(cota)
            spans_por_cp_por_dia.setdefault(cp, {})
            for d in _daterange(ini, fim):
                spans_por_cp_por_dia[cp][d] = spans_por_cp_por_dia[cp].get(d, 0) + span
        else:
        
            if not cf_norm:
                continue
            faces_ocupadas_nao_digital.add((cp, tipo, cf_norm))
            intervalos_por_face.setdefault((cp, tipo, cf_norm), []).append((ini, fim))


    for cp, por_dia in spans_por_cp_por_dia.items():
    
        capacidade_cadastro = int(capacidade_digital_por_cp.get(cp) or 0)

        pico_mes = 0
        tem_conflito = False

        for d, soma_span in por_dia.items():
            if soma_span > pico_mes:
                pico_mes = soma_span
            if capacidade_cadastro > 0 and soma_span > capacidade_cadastro:
                tem_conflito = True


        denominador = capacidade_cadastro
        if denominador <= 0:
            denominador = int(pico_mes) if pico_mes > 0 else 0
            tem_conflito = False

        key = (cp, "PAINEL DIGITAL")
        out[key] = {
            "ocupadas": int(pico_mes),
            "denominador": int(denominador),
            "conflitos": 1 if tem_conflito else 0,
        }

    ocupadas_por_grupo = {}
    for (cp, tipo, cf) in faces_ocupadas_nao_digital:
        ocupadas_por_grupo[(cp, tipo)] = ocupadas_por_grupo.get((cp, tipo), 0) + 1


    conflitos_por_grupo = {}
    for (cp, tipo, cf), intervalos in intervalos_por_face.items():
        if len(intervalos) <= 1:
            continue

        intervalos = sorted(intervalos, key=lambda x: (x[0], x[1]))
        fim_atual = intervalos[0][1]
        conflito = False

        for i in range(1, len(intervalos)):
            ini, fim = intervalos[i]
            if ini <= fim_atual:
                conflito = True
                break
            fim_atual = max(fim_atual, fim)

        if conflito:
            conflitos_por_grupo[(cp, tipo)] = conflitos_por_grupo.get((cp, tipo), 0) + 1


    for (cp, tipo), faces_set in faces_por_cp_tipo.items():
        if tipo == "PAINEL DIGITAL":
            continue
        out.setdefault((cp, tipo), {})
        out[(cp, tipo)]["ocupadas"] = int(ocupadas_por_grupo.get((cp, tipo), 0))
        out[(cp, tipo)]["denominador"] = int(len(faces_set))
        out[(cp, tipo)]["conflitos"] = int(conflitos_por_grupo.get((cp, tipo), 0))

    return out


def _intersecao_mes(di, df, dt_ini, dt_fim):
    """Retorna (dia_inicio, dia_fim) dentro do mês (1..last_day) ou (None,None) se não intersecta."""
    if di is None or df is None:
        return None, None
    if di > dt_fim or df < dt_ini:
        return None, None

    ini = di if di >= dt_ini else dt_ini
    fim = df if df <= dt_fim else dt_fim
    return ini.day, fim.day


def _marcar_conflitos_por_face(ocupacoes_por_face):
    """
    ocupacoes_por_face: dict { "118AD": [ {DataInicio, DataFim, ...}, ... ] }
    Retorna set faces_em_conflito e também marca cada item com 'BitConflito' (True/False) se overlap existir.
    """
    faces_em_conflito = set()

    for face, itens in ocupacoes_por_face.items():
        if not itens or len(itens) <= 1:
            for it in itens:
                it["BitConflito"] = False
            continue

        itens_sorted = sorted(itens, key=lambda x: (x["DataInicio"], x["DataFim"]))
        conflito = False
        fim_atual = itens_sorted[0]["DataFim"]

        for i in range(1, len(itens_sorted)):
            ini = itens_sorted[i]["DataInicio"]
            fim = itens_sorted[i]["DataFim"]
            if ini <= fim_atual:
                conflito = True
                break
            if fim > fim_atual:
                fim_atual = fim

        if conflito:
            faces_em_conflito.add(face)

        for it in itens:
            it["BitConflito"] = conflito

    return faces_em_conflito




@paineis_bp.route("/", methods=["GET"])
@login_required
@limiter.limit(LIMITE_GET_TELAS_NAVEGACAO, methods=["GET"])
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def lista_paineis():
    # A rota raiz de Painéis é a home histórica da aplicação.
    # Usuários da empresa 1 iniciam no Catálogo Produtos; usuários da empresa 3
    # (e empresas não mapeadas) permanecem na Lista de Painéis.
    if obter_id_empresa_proprietaria_usuario() == 1:
        return redirect(url_for("euro.lista_produtos"))

    def _parse_iso_date(s: str):
        try:
            if not s:
                return None
            return datetime.strptime(s.strip(), "%Y-%m-%d").date()
        except:
            return None

    def _somente_digitos(s: str) -> str:
        try:
            if not s:
                return ""
            return "".join([c for c in str(s) if c.isdigit()])
        except:
            return ""

    def _parse_float_ptbr(s: str):
        try:
            if s is None:
                return None
            s = str(s).strip()
            if not s:
                return None

            s = s.replace(".", "").replace(",", ".") if ("," in s and "." in s) else s.replace(",", ".")
            return float(s)
        except:
            return None

    def _calcular_periodo_rapido(periodo_rapido: str, hoje_ref: date):
        try:
            p = (periodo_rapido or "").strip().lower()
            if not p:
                return None, None

            if p in ("dia", "hoje"):
                return hoje_ref, hoje_ref

            if p == "semana":
                # Python considera segunda-feira como 0 em weekday(). Para a
                # regra da aplicação, a semana começa no domingo e termina no
                # sábado. O deslocamento abaixo transforma domingo em 0,
                # segunda em 1, ..., sábado em 6.
                dias_desde_domingo = (hoje_ref.weekday() + 1) % 7
                inicio = hoje_ref - timedelta(days=dias_desde_domingo)
                fim = inicio + timedelta(days=6)
                return inicio, fim

            if p == "mes":
                inicio = date(hoje_ref.year, hoje_ref.month, 1)
                fim = date(
                    hoje_ref.year,
                    hoje_ref.month,
                    calendar.monthrange(hoje_ref.year, hoje_ref.month)[1],
                )
                return inicio, fim

            if p == "ano":
                inicio = date(hoje_ref.year, 1, 1)
                fim = date(hoje_ref.year, 12, 31)
                return inicio, fim

            return None, None
        except:
            return None, None

    def _parse_lista_tokens_busca(raw: str):
        try:
            s = (raw or "").strip()
            if not s:
                return {"tipo": None, "codpontos": [], "cnpjs": [], "codfaces": [], "erro": ""}

            parts = []
            for chunk in s.replace(",", " ").split():
                c = (chunk or "").strip()
                if c:
                    parts.append(c)

            if not parts:
                return {"tipo": None, "codpontos": [], "cnpjs": [], "codfaces": [], "erro": ""}

            tipos_encontrados = set()
            codpontos = []
            cnpjs = []
            codfaces = []

            for p in parts:
                p_str = str(p).strip()
                p_digits = _somente_digitos(p_str)

                if p_digits and p_digits == p_str:
                    if len(p_digits) == 14:
                        tipos_encontrados.add("cnpj")
                        cnpjs.append(p_digits)
                    else:
                        tipos_encontrados.add("codponto")
                        try:
                            codpontos.append(int(p_digits))
                        except:
                            return {
                                "tipo": None,
                                "codpontos": [],
                                "cnpjs": [],
                                "codfaces": [],
                                "erro": f"Token inválido para CodPonto: '{p_str}'",
                            }
                else:
                    tipos_encontrados.add("codface")
                    codfaces.append(p_str)

            if len(tipos_encontrados) > 1:
                return {
                    "tipo": None,
                    "codpontos": [],
                    "cnpjs": [],
                    "codfaces": [],
                    "erro": "Busca inválida: você misturou tipos (CodPonto / CodFace / CNPJ). Use apenas um tipo por vez.",
                }

            t = next(iter(tipos_encontrados)) if tipos_encontrados else None

            def _dedup(seq):
                seen = set()
                out = []
                for x in seq:
                    if x in seen:
                        continue
                    seen.add(x)
                    out.append(x)
                return out

            codpontos = _dedup(codpontos)
            cnpjs = _dedup(cnpjs)
            codfaces = _dedup(codfaces)

            return {"tipo": t, "codpontos": codpontos, "cnpjs": cnpjs, "codfaces": codfaces, "erro": ""}
        except:
            return {"tipo": None, "codpontos": [], "cnpjs": [], "codfaces": [], "erro": "Erro ao processar a busca."}

    def _getlist_limpo(chave: str):
        try:
            vals = request.args.getlist(chave)
            out = []
            seen = set()
            for v in vals:
                vv = (v or "").strip()
                if not vv:
                    continue
                if vv in seen:
                    continue
                seen.add(vv)
                out.append(vv)
            return out
        except:
            return []


    def _getlist_args_expandido(chave: str):
        try:
            valores = []
            for bruto in request.args.getlist(chave):
                if bruto is None:
                    continue

                s_bruto = str(bruto).strip()
                if not s_bruto:
                    continue

                partes = [s_bruto]
                if "|" in s_bruto:
                    partes = s_bruto.split("|")
                elif ";" in s_bruto:
                    partes = s_bruto.split(";")
                elif "," in s_bruto:
                    partes = s_bruto.split(",")

                for parte in partes:
                    vv = (parte or "").strip()
                    if vv:
                        valores.append(vv)

            out = []
            seen = set()
            for v in valores:
                chave_seen = v.upper()
                if chave_seen in seen:
                    continue
                seen.add(chave_seen)
                out.append(v)

            return out
        except:
            return []

    def _get_faces_selecionadas():
        try:
            codfaces_raw = _getlist_args_expandido("selected_codface")
            codpontos_raw = _getlist_args_expandido("selected_codponto")

            pares = []
            codfaces = []
            codpontos = []

            seen_pares = set()
            seen_faces = set()
            seen_pontos = set()

            if codfaces_raw and codpontos_raw and len(codpontos_raw) == len(codfaces_raw):
                for cp_raw, cf_raw in zip(codpontos_raw, codfaces_raw):
                    try:
                        cp_int = int(str(cp_raw).strip())
                    except:
                        continue

                    cf_txt = (str(cf_raw) or "").strip()
                    if not cf_txt:
                        continue

                    chave_par = (cp_int, cf_txt.upper())
                    if chave_par in seen_pares:
                        continue
                    seen_pares.add(chave_par)

                    pares.append((cp_int, cf_txt))

                    if cp_int not in seen_pontos:
                        seen_pontos.add(cp_int)
                        codpontos.append(cp_int)

                    chave_face = cf_txt.upper()
                    if chave_face not in seen_faces:
                        seen_faces.add(chave_face)
                        codfaces.append(cf_txt)
            else:
                for cf_raw in codfaces_raw:
                    cf_txt = (str(cf_raw) or "").strip()
                    if not cf_txt:
                        continue

                    chave_face = cf_txt.upper()
                    if chave_face in seen_faces:
                        continue
                    seen_faces.add(chave_face)
                    codfaces.append(cf_txt)

            return {
                "pares": pares,
                "codfaces": codfaces,
                "codfaces_norm": [x.upper() for x in codfaces],
                "codpontos": codpontos,
            }
        except:
            return {
                "pares": [],
                "codfaces": [],
                "codfaces_norm": [],
                "codpontos": [],
            }

    def _aplicar_filtro_faces_dim(query, pares_faces, codfaces_norm):
        try:
            if not pares_faces and not codfaces_norm:
                return query

            codface_dim_norm = func.upper(func.ltrim(func.rtrim(func.coalesce(DimFacesPaineis.CodFace, ""))))

            if pares_faces:
                filtros = []
                for cp_sel, cf_sel in pares_faces:
                    filtros.append(
                        and_(
                            DimFacesPaineis.CodPonto == cp_sel,
                            codface_dim_norm == str(cf_sel).strip().upper(),
                        )
                    )

                if filtros:
                    return query.filter(or_(*filtros))
                return query

            return query.filter(codface_dim_norm.in_(codfaces_norm))
        except:
            return query

    def _aplicar_filtro_faces_itens(query, pares_faces, codfaces_norm):
        try:
            if not pares_faces and not codfaces_norm:
                return query

            codface_item_norm = func.upper(
                func.ltrim(func.rtrim(func.coalesce(FatoControleContratosItensEuromidia.CodFace, "")))
            )

            if pares_faces:
                filtros = []
                for cp_sel, cf_sel in pares_faces:
                    filtros.append(
                        and_(
                            FatoControleContratosItensEuromidia.CodPonto == cp_sel,
                            codface_item_norm == str(cf_sel).strip().upper(),
                        )
                    )

                if filtros:
                    return query.filter(or_(*filtros))
                return query

            return query.filter(codface_item_norm.in_(codfaces_norm))
        except:
            return query

    def _resolver_periodo_por_dim_calendario(
        ano: str,
        anomes: str,
        semana_iso: str,
        quinzena: str,
        bisemana: str,
        fim_de_semana: str,
        dia_semana_iso: str,
        trimestre: str,
        mes: str,
        dia: str,
    ):
        try:
            def _to_int(v: str):
                vv = (v or "").strip()
                if not vv:
                    return None
                if vv.isdigit():
                    return int(vv)
                return None

            ano_i = _to_int(ano)
            anomes_i = _to_int(anomes)
            semana_i = _to_int(semana_iso)
            quinzena_i = _to_int(quinzena)
            bisemana_i = _to_int(bisemana)
            dia_semana_i = _to_int(dia_semana_iso)
            trimestre_i = _to_int(trimestre)
            mes_i = _to_int(mes)
            dia_i = _to_int(dia)

            fim_semana_flag = (fim_de_semana or "").strip()
            if fim_semana_flag not in ("", "0", "1"):
                fim_semana_flag = ""

            if not any(
                [
                    ano_i is not None,
                    anomes_i is not None,
                    semana_i is not None,
                    quinzena_i is not None,
                    bisemana_i is not None,
                    dia_semana_i is not None,
                    trimestre_i is not None,
                    mes_i is not None,
                    dia_i is not None,
                    fim_semana_flag in ("0", "1"),
                ]
            ):
                return None, None

            qcal = db.session.query(
                func.min(DimCalendario.data).label("dt_ini"),
                func.max(DimCalendario.data).label("dt_fim"),
            )

            if ano_i is not None:
                qcal = qcal.filter(DimCalendario.ano == ano_i)

            if anomes_i is not None:
                qcal = qcal.filter(DimCalendario.ano_mes == anomes_i)

            if mes_i is not None:
                qcal = qcal.filter(DimCalendario.mes == mes_i)

            if dia_i is not None:
                qcal = qcal.filter(DimCalendario.dia == dia_i)

            if trimestre_i is not None:
                qcal = qcal.filter(DimCalendario.trimestre == trimestre_i)

            if semana_i is not None:
                qcal = qcal.filter(DimCalendario.semana_ano_iso == semana_i)

            if dia_semana_i is not None:
                qcal = qcal.filter(DimCalendario.dia_semana_iso == dia_semana_i)

            if quinzena_i is not None:
                qcal = qcal.filter(DimCalendario.quinzena == quinzena_i)

            if bisemana_i is not None:
                qcal = qcal.filter(DimCalendario.bi_semana_numero == bisemana_i)

            if fim_semana_flag in ("0", "1"):
                qcal = qcal.filter(DimCalendario.eh_fim_de_semana == (fim_semana_flag == "1"))

            row = qcal.first()
            if not row:
                return None, None

            dt_ini = getattr(row, "dt_ini", None)
            dt_fim = getattr(row, "dt_fim", None)

            if dt_ini and dt_fim and dt_ini > dt_fim:
                dt_ini, dt_fim = dt_fim, dt_ini

            return dt_ini, dt_fim
        except:
            return None, None

    def _coerce_to_date(v):
        try:
            if v is None:
                return None
            if isinstance(v, datetime):
                return v.date()
            if isinstance(v, date):
                return v
            s = str(v).strip()
            if not s:
                return None

            try:
                return datetime.strptime(s, "%Y-%m-%d").date()
            except:
                pass

            try:
                return datetime.strptime(s, "%d/%m/%Y").date()
            except:
                pass

            try:
                return datetime.fromisoformat(s).date()
            except:
                return None
        except:
            return None

    def _fim_efetivo_item(df_prev, dc=None):
        """
        Eu uso somente DataTerminoPrevisto na grade de ocupação.

        Regra correta da tela /paineis/<codponto>/grade:
        - DataInicioPrevisto define o início da ocupação.
        - DataTerminoPrevisto define o fim da ocupação.
        - DataCancelamento não entra no cálculo nem no desenho da barra, porque
          estava alongando/encurtando períodos e distorcendo a grade.
        """
        try:
            return _coerce_to_date(df_prev)
        except:
            return None

 
    def _slots_por_cota(cota, span_qtd=None):
        """
        Regra oficial de slot da grade digital:
        - COTA 1080 ocupa 2 slots.
        - COTA 540 ocupa 1 slot.

        Eu não uso _somente_digitos aqui porque valores vindos do SQL como
        "1080.00" viravam "108000" e derrubavam a cota para 1 slot errado.
        """
        try:
            try:
                if span_qtd not in (None, "", "null", "None"):
                    span_tmp = float(str(span_qtd).strip().replace(",", "."))
                    if span_tmp > 0:
                        return float(span_tmp)
            except Exception:
                pass

            if cota in (None, ""):
                return 1.0

            if isinstance(cota, Decimal):
                try:
                    c = int(cota)
                except Exception:
                    c = int(float(cota))
            elif isinstance(cota, (int, float)):
                try:
                    c = int(round(float(cota)))
                except Exception:
                    return 1.0
            else:
                s = str(cota or "").strip()
                if not s:
                    return 1.0

                s = s.replace("R$", "").replace(" ", "")

                if "," in s and "." in s:
                    s = s.replace(".", "").replace(",", ".")
                elif "," in s:
                    s = s.replace(",", ".")

                try:
                    c = int(Decimal(s))
                except Exception:
                    try:
                        c = int(round(float(s)))
                    except Exception:
                        return 1.0

            if c <= 0:
                return 1.0

            if c == 1080:
                return 2.0
            if c == 540:
                return 1.0

            return 1.0
        except Exception:
            return 1.0


    def _uso_no_periodo_por_intervalos(intervalos, dt_ini, dt_fim, denom_cap):
        try:
            if not intervalos or dt_ini is None or dt_fim is None:
                return 0.0, 0.0

            if dt_fim < dt_ini:
                dt_ini, dt_fim = dt_fim, dt_ini

            denom_cap = int(denom_cap or 0)
            denom_cap = max(1, denom_cap)

            eventos = []
            for di, df, slots in intervalos:
                if di is None or df is None:
                    continue

                di2 = di if di >= dt_ini else dt_ini
                df2 = df if df <= dt_fim else dt_fim

                if df2 < dt_ini or di2 > dt_fim:
                    continue
                if df2 < di2:
                    continue

                s = float(slots or 0.0)
                if s <= 0:
                    continue

                eventos.append((di2, +s))
                eventos.append((df2 + timedelta(days=1), -s))

            if not eventos:
                return 0.0, 0.0

            eventos.sort(key=lambda x: (x[0], 0 if x[1] < 0 else 1))

            atual = 0.0
            maximo = 0.0
            uso_slots_dias = 0.0

            cursor = dt_ini
            i = 0
            n = len(eventos)

            while i < n and eventos[i][0] < dt_ini:
                atual += float(eventos[i][1])
                if atual > maximo:
                    maximo = atual
                i += 1

            while cursor <= dt_fim:
                while i < n and eventos[i][0] == cursor:
                    atual += float(eventos[i][1])
                    if atual > maximo:
                        maximo = atual
                    i += 1

                proxima_data = dt_fim + timedelta(days=1)
                if i < n:
                    proxima_data = eventos[i][0]

                if proxima_data <= cursor:
                    cursor = cursor + timedelta(days=1)
                    continue

                fim_trecho_exclusivo = proxima_data
                if fim_trecho_exclusivo > (dt_fim + timedelta(days=1)):
                    fim_trecho_exclusivo = dt_fim + timedelta(days=1)

                dias_trecho = (fim_trecho_exclusivo - cursor).days
                if dias_trecho > 0:
                    ocupado = atual
                    if ocupado < 0:
                        ocupado = 0.0
                    if ocupado > float(denom_cap):
                        ocupado = float(denom_cap)

                    uso_slots_dias += float(ocupado) * float(dias_trecho)

                cursor = fim_trecho_exclusivo

            return float(uso_slots_dias), float(maximo)
        except:
            return 0.0, 0.0

    def _calcular_ocupacao_e_conflitos_por_face(
        ocupacoes,
        tipo_por_face,
        tipo_por_idcadastro,
        capacidade_digital_por_cp,
        dt_ini,
        dt_fim,
    ):
        try:
            por_face_tipo = {}

            for item_ocupacao in (ocupacoes or []):
                try:
                    cp_int, cf_norm, cota, di, df_ef, idcad = item_ocupacao[:6]
                    span_qtd_ocup = item_ocupacao[6] if len(item_ocupacao) > 6 else None
                except Exception:
                    continue

                if cp_int is None:
                    continue
                if not cf_norm:
                    continue

                di_dt = _coerce_to_date(di)
                df_dt = _coerce_to_date(df_ef)
                if di_dt is None or df_dt is None:
                    continue

                if dt_ini is not None and df_dt < dt_ini:
                    continue
                if dt_fim is not None and di_dt > dt_fim:
                    continue
                if df_dt < di_dt:
                    continue

                tp_up = tipo_por_face.get((cp_int, cf_norm))
                if (not tp_up) and (idcad not in (None, "")):
                    try:
                        tp_up = tipo_por_idcadastro.get(int(idcad))
                    except:
                        tp_up = None
                if not tp_up:
                    continue

                key = (cp_int, cf_norm, tp_up)

                """
                REGRA OFICIAL DE OCUPAÇÃO DA LISTA DE PAINÉIS

                A lista precisa usar a mesma lógica visual da grade do painel:
                - capacidade disponível = quantidade de dias do período × QuantidadeFaces;
                - ocupado = soma de slot-dia ocupado dentro do período;
                - para PAINEL DIGITAL, a ocupação deve respeitar o span da campanha;
                - COTA 1080 ocupa 2 slots por dia;
                - COTA 540 ocupa 1 slot por dia.

                Observação importante:
                - Em painel NÃO digital, a face física continua valendo 1 espaço por dia.
                - Em painel digital, o slot-dia precisa bater com a grade; caso contrário,
                  a lista mostra percentual menor que a grade, como no caso 215/480.
                """
                if tp_up == "PAINEL DIGITAL":
                    slots = float(_slots_por_cota(cota, span_qtd_ocup) or 1.0)
                else:
                    slots = 1.0

                por_face_tipo.setdefault(key, []).append((di_dt, df_dt, slots))

            out = {}

            if dt_ini is None or dt_fim is None:
                return out

            if dt_fim < dt_ini:
                dt_ini, dt_fim = dt_fim, dt_ini

            total_dias = int((dt_fim - dt_ini).days) + 1
            if total_dias <= 0:
                total_dias = 1

            for (cp_int, cf_norm, tp_up), intervalos in por_face_tipo.items():
                denom = 1
                if tp_up == "PAINEL DIGITAL":
                    denom = int(capacidade_digital_por_cp.get(cp_int) or 0) or int(CAPACIDADE_DIGITAL_FIXA)
                    denom = max(1, int(denom))

                uso_slots_dias, max_simult_sem_teto = _uso_no_periodo_por_intervalos(
                    intervalos=intervalos,
                    dt_ini=dt_ini,
                    dt_fim=dt_fim,
                    denom_cap=denom,
                )

                conflitos = 1 if (float(max_simult_sem_teto) > float(denom)) else 0

                uso_medio = float(uso_slots_dias) / float(total_dias)

                cap_total = float(denom) * float(total_dias)
                pct_uso = round((float(uso_slots_dias) / cap_total) * 100.0, 1) if cap_total > 0 else 0.0
                if pct_uso < 0:
                    pct_uso = 0.0
                if pct_uso > 100:
                    pct_uso = 100.0

                ocupadas_vis = int(round(uso_medio, 0))
                if ocupadas_vis < 0:
                    ocupadas_vis = 0
                if ocupadas_vis > denom:
                    ocupadas_vis = denom

                out[(cp_int, cf_norm, tp_up)] = {
                    "ocupadas": int(ocupadas_vis),
                    "denominador": int(denom),
                    "conflitos": int(conflitos),
                    "pct_uso": float(pct_uso),
                    "uso_medio": float(uso_medio),
                    "uso_slots_dias": float(uso_slots_dias),
                    "total_dias": int(total_dias),
                    "max_simult_sem_teto": float(max_simult_sem_teto),
                }

            return out
        except:
            return {}

    def _is_admin() -> bool:
        try:
            if getattr(current_user, "has_permission", None):
                if current_user.has_permission("ADMIN_TUDO"):
                    return True
                if current_user.has_permission("PAINEIS_VER_EXIBIDORA"):
                    return True
                if current_user.has_permission("ADMIN"):
                    return True

            perfil = getattr(current_user, "perfil", None)
            nome_perfil = (getattr(perfil, "NomePerfil", "") or "").strip().upper()

            if nome_perfil in ("ADMIN", "ADMINISTRADOR", "ADM", "ADMIN_TUDO"):
                return True

            return False
        except Exception:
            return False

