from sqlalchemy.orm import load_only, noload


@paineis_bp.get("/<int:codponto>/detalhe")
@login_required
@requer_permissao("PAINEIS_DETALHE_VER")
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def detalhe_painel(codponto: int):

    painel = (
        db.session.query(DimPaineisEuromidia)
        .options(
            noload("*"),
            load_only(
                DimPaineisEuromidia.IDDimPaineisEuromidia,
                DimPaineisEuromidia.DataAtualizacao,
                DimPaineisEuromidia.CodPonto,
                DimPaineisEuromidia.QuantidadeFaces,
                DimPaineisEuromidia.Tipo,
                DimPaineisEuromidia.Cidade,
                DimPaineisEuromidia.UF,
                DimPaineisEuromidia.Logradouro,
                DimPaineisEuromidia.Sentido,
                DimPaineisEuromidia.Bairro,
                DimPaineisEuromidia.Referencia,
                DimPaineisEuromidia.Numero,
                DimPaineisEuromidia.CEP,
                DimPaineisEuromidia.Latitude,
                DimPaineisEuromidia.Longitude,
                DimPaineisEuromidia.FormatoLxA,
                DimPaineisEuromidia.FormatoLonaAcabadaLxAm,
                DimPaineisEuromidia.AreaTotalm,
                DimPaineisEuromidia.BitIluminado,
                DimPaineisEuromidia.Restricoes,
                DimPaineisEuromidia.TipoSolo,
                DimPaineisEuromidia.DataInstalacao,
                DimPaineisEuromidia.DataRetirada,
                DimPaineisEuromidia.Exibidora,
                DimPaineisEuromidia.BitProprio,
                DimPaineisEuromidia.BitAtivo,
                DimPaineisEuromidia.BitAluguel,
                DimPaineisEuromidia.BitEnergia,
                DimPaineisEuromidia.BitInternet,
                DimPaineisEuromidia.IDProduto,
            ),
        )
        .filter(DimPaineisEuromidia.CodPonto == codponto)
        .first()
    )

    if not painel:
        abort(404, description=f"Painel CodPonto {codponto} não encontrado.")


    def _sim_nao(valor):
        return "Sim" if bool(valor) else "Não"

    def _texto(v, padrao="—"):
        if v is None:
            return padrao
        s = str(v).strip()
        return s if s else padrao

    def _to_date(v):
        if v is None:
            return None
        if isinstance(v, date) and not isinstance(v, datetime):
            return v
        if isinstance(v, datetime):
            return v.date()
        try:
            return v.date()
        except:
            return None

    def _parse_ddmmyyyy(s: str):
        """
        Espera "DD-MM-YYYY" ou "DD/MM/YYYY".
        Retorna date ou None.
        """
        if not s:
            return None
        s = (str(s) or "").strip()
        if not s:
            return None
        s = s.replace("/", "-")
        try:
            parts = s.split("-")
            if len(parts) != 3:
                return None
            dd = int(parts[0])
            mm = int(parts[1])
            yy = int(parts[2])
            return date(yy, mm, dd)
        except:
            return None

    def _primeiro_dia_ano(dt: date):
        return date(dt.year, 1, 1)

    def _meses_entre(dt_ini: date, dt_fim: date):
        if dt_ini is None or dt_fim is None:
            return []
        if dt_fim < dt_ini:
            return []

        y = dt_ini.year
        m = dt_ini.month
        y2 = dt_fim.year
        m2 = dt_fim.month

        out = []
        while (y < y2) or (y == y2 and m <= m2):
            out.append((y, m))
            m += 1
            if m > 12:
                m = 1
                y += 1
        return out

    def _add_months(dt: date, delta_meses: int):
        if dt is None:
            return None

        y = dt.year
        m = dt.month + int(delta_meses)

        while m > 12:
            m -= 12
            y += 1
        while m < 1:
            m += 12
            y -= 1

        if m == 12:
            prox = date(y + 1, 1, 1)
        else:
            prox = date(y, m + 1, 1)
        ultimo_dia = (prox - timedelta(days=1)).day

        dd = dt.day
        if dd > ultimo_dia:
            dd = ultimo_dia

        return date(y, m, dd)


    endereco_linha_1 = " ".join([
        _texto(painel.Logradouro, "").strip()
    ]).strip()

    if _texto(painel.Numero, "").strip():
        endereco_linha_1 = f"{endereco_linha_1} nº {_texto(painel.Numero, '').strip()}".strip()

    endereco_linha_2 = " • ".join([
        _texto(painel.Bairro),
        f"CEP {_texto(painel.CEP)}",
        _texto(painel.UF),
    ])


    hoje = date.today()

    dt_de_txt = (request.args.get("dt_de") or "").strip()
    dt_ate_txt = (request.args.get("dt_ate") or "").strip()

    dt_de = _parse_ddmmyyyy(dt_de_txt)
    dt_ate = _parse_ddmmyyyy(dt_ate_txt)


    if dt_de is None and dt_ate is None:
        dt_ate = hoje
        dt_ate_mes = date(dt_ate.year, dt_ate.month, 1)
        dt_de_mes = _add_months(dt_ate_mes, -11)
        dt_de = dt_de_mes
    else:
        if dt_ate is None:
            dt_ate = hoje

        if dt_de is None:
            dt_de = _primeiro_dia_ano(dt_ate)

    if dt_de > dt_ate:
        dt_de, dt_ate = dt_ate, dt_de


    sql_matriz = text("""
        SELECT
            CodPonto,
            Ano,
            Jan, Fev, Mar, Abr, Mai, Jun,
            Jul, Ago, [Set], [Out], Nov, Dez,
            NoAno,
            Acumulado
        FROM [Integracao].[Silver].[DimPontosHistoricoVendas]
        WHERE CodPonto = :codponto
        ORDER BY Ano DESC;
    """)

    rows_matriz = db.session.execute(sql_matriz, {"codponto": codponto}).fetchall()

    matriz_faturamento = []
    for r in rows_matriz:
        try:
            yy = int(r.Ano)
        except:
            continue

        def _v(x):
            try:
                return float(x or 0.0)
            except:
                return 0.0

        linha = {
            "Ano": yy,
            "Meses": {
                1: _v(r.Jan),
                2: _v(r.Fev),
                3: _v(r.Mar),
                4: _v(r.Abr),
                5: _v(r.Mai),
                6: _v(r.Jun),
                7: _v(r.Jul),
                8: _v(r.Ago),
                9: _v(getattr(r, "Set")),
                10: _v(getattr(r, "Out")),
                11: _v(r.Nov),
                12: _v(r.Dez),
            },
            "NoAno": _v(r.NoAno),
            "Acumulado": _v(r.Acumulado),
        }
        matriz_faturamento.append(linha)


    dt_de_mes = date(dt_de.year, dt_de.month, 1)
    dt_ate_mes = date(dt_ate.year, dt_ate.month, 1)

    sql_serie = text("""
        ;WITH Base AS (
            SELECT
                d.CodPonto,
                d.Ano,
                v.Mes,
                v.Valor,
                DATEFROMPARTS(d.Ano, v.Mes, 1) AS MesRef
            FROM [Integracao].[Silver].[DimPontosHistoricoVendas] d
            CROSS APPLY (VALUES
                (1, d.Jan),
                (2, d.Fev),
                (3, d.Mar),
                (4, d.Abr),
                (5, d.Mai),
                (6, d.Jun),
                (7, d.Jul),
                (8, d.Ago),
                (9, d.[Set]),
                (10, d.[Out]),
                (11, d.Nov),
                (12, d.Dez)
            ) v(Mes, Valor)
            WHERE d.CodPonto = :codponto
        )
        SELECT
            Ano,
            Mes,
            CAST(Valor AS decimal(19,2)) AS Valor
        FROM Base
        WHERE MesRef >= :dt_de_mes
          AND MesRef <= :dt_ate_mes
        ORDER BY Ano, Mes;
    """)

    rows_serie = db.session.execute(sql_serie, {
        "codponto": codponto,
        "dt_de_mes": dt_de_mes,
        "dt_ate_mes": dt_ate_mes,
    }).fetchall()

    serie_temporal = []
    for r in rows_serie:
        try:
            yy = int(r.Ano)
            mm = int(r.Mes)
            vv = float(r.Valor or 0.0)
        except:
            continue

        serie_temporal.append({
            "x": f"{yy:04d}-{mm:02d}",
            "y": vv,
        })


    return render_template(
        "euromidia/painel_detalhe.html",
        painel=painel,
        endereco_linha_1=_texto(endereco_linha_1),
        endereco_linha_2=_texto(endereco_linha_2),
        bit_ativo=bool(painel.BitAtivo),
        aluguel_txt=_sim_nao(painel.BitAluguel),
        energia_txt=_sim_nao(painel.BitEnergia),
        internet_txt=_sim_nao(painel.BitInternet),
        proprio_txt="Próprio" if bool(painel.BitProprio) else "Terceiro",

        faturamento_matriz=matriz_faturamento,
        faturamento_serie=serie_temporal,

        filtros_faturamento={
            "dt_de": dt_de.strftime("%d-%m-%Y") if dt_de else "",
            "dt_ate": dt_ate.strftime("%d-%m-%Y") if dt_ate else "",
        },
    )








def _limpar_email(email: str) -> str:
    """
    Eu normalizo o email antes de validar/salvar.

    O problema que gerava "Email inválido" era comum quando o email vinha
    com espaço invisível no final, principalmente o caractere Unicode NBSP
    (\u00A0), que visualmente parece um espaço normal.
    """
    if not email:
        return ""

    texto = str(email)

    try:
        texto = unicodedata.normalize("NFKC", texto)
    except Exception:
        pass

    for caractere_invisivel in ("\u00A0", "\u200B", "\u200C", "\u200D", "\ufeff"):
        texto = texto.replace(caractere_invisivel, "")

    texto = texto.strip()
    texto = re.sub(r"\s+", "", texto)

    return texto.lower()

def _parse_data_yyyy_mm_dd(txt: str):
    s = (txt or "").strip()
    if not s:
        return None
    try:
        return datetime.strptime(s, "%Y-%m-%d")
    except Exception:
        return None

def _senha_hash(senha_plana: str) -> str:
  
   
    return generate_password_hash(senha_plana, method="pbkdf2:sha256")



ID_PERFIL_ADMIN_PADRAO = 1
ID_EMPRESA_PROPRIETARIA_ADMIN_PADRAO = 3
OBS_PERMISSAO_ADMIN_TOTAL = "Acesso total liberado automaticamente para perfil administrador."


def _id_usuario_executor_atual():
    try:
        id_usuario = int(getattr(current_user, "IDDimUsuarios", 0) or 0)
        return id_usuario if id_usuario > 0 else None
    except Exception:
        return None


def _perfil_usuario_eh_admin(id_perfil_usuario: int) -> bool:
    try:
        id_perfil = int(id_perfil_usuario or 0)
    except Exception:
        id_perfil = 0

    if id_perfil == ID_PERFIL_ADMIN_PADRAO:
        return True

    perfil = (
        db.session.query(DimPerfilUsuario)
        .filter(DimPerfilUsuario.IDDimPerfilUsuario == id_perfil)
        .first()
    )

    nome_perfil = (getattr(perfil, "NomePerfil", "") or "").strip().upper()
    return nome_perfil in {"ADMIN", "ADMINISTRADOR", "ADM", "ADMIN_TUDO", "ADMIN EUROMIDIA"}


def _aplicar_acesso_total_usuario_admin(
    id_usuario: int,
    id_usuario_executor: int | None = None,
    id_empresa_proprietaria: int = ID_EMPRESA_PROPRIETARIA_ADMIN_PADRAO,
) -> int:
    agora = datetime.now()

    usuario_admin = (
        db.session.query(DimUsuarios)
        .filter(DimUsuarios.IDDimUsuarios == int(id_usuario))
        .first()
    )

    if not usuario_admin:
        raise ValueError("Usuário informado não existe na tabela DimUsuarios.")

    usuario_admin.IDDimPerfilUsuario = ID_PERFIL_ADMIN_PADRAO
    usuario_admin.BitAtivo = True
    usuario_admin.IDEmpresaProprietaria = int(id_empresa_proprietaria)
    usuario_admin.UpdateAt = agora

    permissoes_ativas = (
        db.session.query(DimPermissoes)
        .filter(DimPermissoes.BitAtivo == True)
        .order_by(DimPermissoes.IDDimPermissoes.asc())
        .all()
    )

    permissoes_usuario = (
        db.session.query(PermissoesUsuario)
        .filter(PermissoesUsuario.IDDimUsuarios == int(id_usuario))
        .all()
    )

    permissoes_usuario_por_id = {
        int(row.IDDimPermissoes): row
        for row in permissoes_usuario
        if row.IDDimPermissoes is not None
    }

    total_permissoes_aplicadas = 0

    for permissao in permissoes_ativas:
        id_permissao = int(permissao.IDDimPermissoes)
        row_existente = permissoes_usuario_por_id.get(id_permissao)

        if row_existente:
            row_existente.DataExpiracao = None
            row_existente.DataAtualizacao = agora
            row_existente.TipoAtribuicao = "CONCEDER"
            if not row_existente.CriadoPorIDDimUsuarios:
                row_existente.CriadoPorIDDimUsuarios = id_usuario_executor
            row_existente.Observacao = OBS_PERMISSAO_ADMIN_TOTAL
        else:
            db.session.add(
                PermissoesUsuario(
                    IDDimUsuarios=int(id_usuario),
                    IDDimPermissoes=id_permissao,
                    TipoAtribuicao="CONCEDER",
                    DataExpiracao=None,
                    DataCriacao=agora,
                    DataAtualizacao=agora,
                    CriadoPorIDDimUsuarios=id_usuario_executor,
                    Observacao=OBS_PERMISSAO_ADMIN_TOTAL,
                )
            )

        total_permissoes_aplicadas += 1

    return total_permissoes_aplicadas


def _remover_acesso_total_admin_automatico(id_usuario: int) -> int:
    removidas = (
        db.session.query(PermissoesUsuario)
        .filter(PermissoesUsuario.IDDimUsuarios == int(id_usuario))
        .filter(PermissoesUsuario.Observacao == OBS_PERMISSAO_ADMIN_TOTAL)
        .delete(synchronize_session=False)
    )

    return int(removidas or 0)




