def _month_iter(start_y: int, start_m: int, count: int):
    """'Gera YYYY-MM sequencial por count meses.'"""
    y = start_y
    m = start_m
    for _ in range(count):
        yield (y, m)
        m += 1
        if m > 12:
            m = 1
            y += 1


def _to_month_key(d: date) -> str:
    """'YYYY-MM'"""
    return f"{d.year:04d}-{d.month:02d}"


@paineis_bp.get("/checkout/disponibilidade")
@login_required
def checkout_disponibilidade():
    """
    'Retorna meses disponíveis (YYYY-MM) para DataInicio/DataFim,
     removendo meses que encostam em intervalos ocupados.'
    """
    codponto = request.args.get("codponto")
    codface = (request.args.get("codface") or "").strip()

    try:
        codponto = int(codponto)
    except:
        return jsonify({"ok": False, "erro": "codponto inválido"}), 400

    if codponto <= 0 or not codface:
        return jsonify({"ok": False, "erro": "codponto/codface inválidos"}), 400

 
    ocup = (
        db.session.query(FatoOcupacaoPaineisEuromidia.DataInicio, FatoOcupacaoPaineisEuromidia.DataFim)
        .filter(FatoOcupacaoPaineisEuromidia.CodPonto == codponto)
        .filter(FatoOcupacaoPaineisEuromidia.CodFace == codface)
        .all()
    )


    bloqueados = set()

    for di, df in ocup:
        if not di or not df:
            continue

  
        y = di.year
        m = di.month

        while True:
            key = f"{y:04d}-{m:02d}"
            bloqueados.add(key)

            if y == df.year and m == df.month:
                break

            m += 1
            if m > 12:
                m = 1
                y += 1

   
    hoje = date.today()
    candidatos = []
    for (y, m) in _month_iter(hoje.year, hoje.month, 24):
        key = f"{y:04d}-{m:02d}"
        if key not in bloqueados:
            candidatos.append(key)

    return jsonify({"ok": True, "meses": candidatos, "bloqueados": sorted(list(bloqueados))})






def _obter_lista_int_request(nome_campo: str) -> list[int]:
    """
    Eu leio parâmetros repetidos do tipo ?status=1&status=2
    e também aceito valor único separado por vírgula.
    """

    valores_brutos: list[str] = []
    valores_brutos.extend(request.args.getlist(nome_campo))

    valor_unico = (request.args.get(nome_campo) or "").strip()
    if valor_unico:
        valores_brutos.append(valor_unico)

    ids: list[int] = []
    vistos: set[int] = set()

    for valor_bruto in valores_brutos:
        for pedaco in str(valor_bruto).split(","):
            pedaco = pedaco.strip()
            if not pedaco:
                continue

            try:
                valor_int = int(pedaco)
            except ValueError:
                continue

            if valor_int <= 0 or valor_int in vistos:
                continue

            vistos.add(valor_int)
            ids.append(valor_int)

    return ids


def _texto_sem_mascara_documento(valor: str) -> str:
    """
    Eu removo caracteres comuns de máscara para permitir busca
    por CNPJ/CPF com ou sem pontuação.
    """
    return (
        (valor or "")
        .replace(".", "")
        .replace("/", "")
        .replace("-", "")
        .replace(" ", "")
        .strip()
    )


def _filtro_exists_cidade_exibicao_like(valor_like: str):
    """
    Eu monto um EXISTS correlacionado para buscar cidade do item
    sem explodir a consulta principal com join desnecessário.
    """
    return (
        db.session.query(
            FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia
        )
        .filter(
            FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia
            == FatoControleContratosEuromidia.IDFatoControleContratosEuromidia,
            FatoControleContratosItensEuromidia.CidadeExibicao.like(valor_like),
        )
        .exists()
    )





def _obter_lista_texto_request(chave: str) -> list[str]:
    """
    Eu leio parâmetros repetidos da query string e devolvo uma lista de textos únicos.

    Exemplos aceitos:
    ?cidade=Campinas&cidade=São Paulo
    ?segmento=Comércio|Serviços
    ?segmento=Comércio,Serviços
    """
    valores: list[str] = []

    for bruto in request.args.getlist(chave):
        if bruto is None:
            continue

        texto = str(bruto).strip()
        if not texto:
            continue

        partes = [texto]

        if "|" in texto:
            partes = texto.split("|")
        elif ";" in texto:
            partes = texto.split(";")
        elif "," in texto:
            partes = texto.split(",")

        for parte in partes:
            valor = str(parte or "").strip()
            if valor:
                valores.append(valor)

    retorno: list[str] = []
    vistos: set[str] = set()

    for valor in valores:
        chave_vista = valor.upper()

        if chave_vista in vistos:
            continue

        vistos.add(chave_vista)
        retorno.append(valor)

    return retorno








def _normalizar_hex_css(valor, padrao="#64748B"):
    """
    Eu valido a cor hexadecimal antes de mandar para o HTML.

    Isso evita CSS quebrado e também impede que um valor incorreto vindo do banco
    seja usado dentro do atributo style da etiqueta de segmento.
    """
    texto = str(valor or "").strip()

    if re.fullmatch(r"#[0-9A-Fa-f]{6}", texto) or re.fullmatch(r"#[0-9A-Fa-f]{3}", texto):
        return texto.upper()

    if re.fullmatch(r"[0-9A-Fa-f]{6}", texto) or re.fullmatch(r"[0-9A-Fa-f]{3}", texto):
        return f"#{texto.upper()}"

    return padrao


def _cor_texto_contraste_css(cor_fundo, padrao="#FFFFFF"):
    """
    Eu escolho automaticamente a cor do texto do badge com base na cor de fundo.

    A lógica evita status com fundo claro e texto branco ilegível, especialmente
    em cores como amarelo/laranja.
    """
    cor = _normalizar_hex_css(cor_fundo, "")

    if not cor:
        return padrao

    hex_limpo = cor.lstrip("#")

    if len(hex_limpo) == 3:
        hex_limpo = "".join(ch * 2 for ch in hex_limpo)

    try:
        r = int(hex_limpo[0:2], 16)
        g = int(hex_limpo[2:4], 16)
        b = int(hex_limpo[4:6], 16)
    except Exception:
        return padrao

    luminancia = ((r * 299) + (g * 587) + (b * 114)) / 1000

    if luminancia >= 150:
        return "#111827"

    return "#FFFFFF"


def _cor_hex_status_contrato_padrao_paineis(id_status: int | None) -> str | None:
    """Retorna a cor padrão do status do contrato quando o banco não tiver CorHex."""
    mapa = {
        1: "#6B7280",  # Em Digitação
        2: "#F59E0B",  # Pendente Geração
        3: "#2563EB",  # Documento Gerado
        4: "#9333EA",  # Pendente Envio
        5: "#0EA5E9",  # Enviado Assinatura
        6: "#06B6D4",  # Em Assinatura
        7: "#15803D",  # Ativo
        8: "#166534",  # Concluído
        9: "#7F1D1D",  # Cancelado
        10: "#DC2626", # ERRO
        31: "#B91C1C", # Reprovado
    }
    try:
        return mapa.get(int(id_status or 0))
    except Exception:
        return None


def _obter_mapa_status_contratos_com_cores(id_empresa_proprietaria=3):
    """
    Eu busco o cadastro oficial de status direto na tabela Silver.DimStatusContratos.

    Fiz assim para não depender de o model SQLAlchemy estar atualizado com a
    coluna CorHex; se a tabela já tem a coluna, a lista consegue pintar os badges.
    """
    try:
        id_empresa = int(id_empresa_proprietaria or 3)
    except Exception:
        id_empresa = 3

    rows = db.session.execute(
        text("""
            SELECT
                 [IDDimStatusContratos]
                ,[Status]
                ,[CorHex]
            FROM [Integracao].[Silver].[DimStatusContratos]
            WHERE [IDEmpresaProprietaria] = :id_empresa_proprietaria
        """),
        {"id_empresa_proprietaria": id_empresa},
    ).mappings().all()

    mapa = {}

    for row in rows:
        try:
            id_status = int(row.get("IDDimStatusContratos") or 0)
        except Exception:
            id_status = 0

        if id_status <= 0:
            continue

        cor = _normalizar_hex_css(row.get("CorHex"), "")

        mapa[id_status] = {
            "IDDimStatusContratos": id_status,
            "Status": (row.get("Status") or f"Status {id_status}").strip(),
            "CorHex": cor,
            "CorTexto": _cor_texto_contraste_css(cor, "#FFFFFF"),
        }

    return mapa










@paineis_bp.get("/contratos")
@login_required
def contratos_lista():
    tempo_inicio = time.perf_counter()

    limpar_filtros = request.args.get("limpar_filtros") == "1"
    tem_filtro_real_na_requisicao = (
        _valor_query_contratos_preenchido(request.args.get("q"))
        or _valor_query_contratos_preenchido(request.args.get("id_contrato"))
        or _valor_query_contratos_preenchido(request.args.get("contrato_ativo"))
        or any(_valor_query_contratos_preenchido(valor) for valor in request.args.getlist("status"))
        or any(_valor_query_contratos_preenchido(valor) for valor in request.args.getlist("cidade"))
        or any(_valor_query_contratos_preenchido(valor) for valor in request.args.getlist("segmento"))
    )

    if limpar_filtros:
        session.pop("contratos_lista_return_to", None)

    elif not tem_filtro_real_na_requisicao:
        url_lista_salva = str(session.get("contratos_lista_return_to") or "").strip()
        url_lista_atual_requisicao = _url_request_atual()

        if (
            url_lista_salva
            and url_lista_salva != url_lista_atual_requisicao
            and (
                url_lista_salva == "/paineis/contratos"
                or url_lista_salva.startswith("/paineis/contratos?")
            )
            and _url_contratos_tem_filtro_real(url_lista_salva)
        ):
            return redirect(url_lista_salva)

    q = (request.args.get("q") or "").strip()
    ids_status_selecionados = _obter_lista_int_request("status")
    cidades_selecionadas = _obter_lista_texto_request("cidade")
    segmentos_selecionados = _obter_lista_texto_request("segmento")

    try:
        id_contrato_selecionado = int(request.args.get("id_contrato") or 0)
    except ValueError:
        id_contrato_selecionado = 0

    if id_contrato_selecionado <= 0:
        id_contrato_selecionado = None

    contrato_ativo = (request.args.get("contrato_ativo") or "").strip()

    if contrato_ativo not in {"0", "1"}:
        contrato_ativo = ""

    contrato_ativo_opcoes = [
        {"valor": "1", "nome": "Ativos"},
        {"valor": "0", "nome": "Inativos"},
    ]

    mapa_contrato_ativo = {
        item["valor"]: item["nome"]
        for item in contrato_ativo_opcoes
    }

    contrato_ativo_nome = mapa_contrato_ativo.get(contrato_ativo, "")

    try:
        page = int(request.args.get("page") or 1)
    except ValueError:
        page = 1

    if page < 1:
        page = 1

    try:
        per_page = int(request.args.get("per_page") or 25)
    except ValueError:
        per_page = 25

    if per_page < 10:
        per_page = 10

    if per_page > 100:
        per_page = 100

    calcular_total = request.args.get("calcular_total") == "1"

    mapa_status_config = _obter_mapa_status_contratos_com_cores(3)

    """
    Eu coloco as opções dos filtros em cache porque elas são iguais para todos
    os acessos da lista e não precisam ser recalculadas em toda abertura da tela.

    O ponto mais pesado aqui era a opção de segmento, porque ela encosta na
    DimEmpresas, que tem milhões de linhas. Com cache, essa consulta deixa de
    rodar a cada GET de /paineis/contratos.
    """
    cache_timeout_filtros_contratos = 1800

    status_opcoes_cache = _cache_get_seguro_paineis(
        "paineis:contratos_lista:status_opcoes:v3"
    )

    if status_opcoes_cache is None:
        rows_status_usados = db.session.execute(
            text("""
                SELECT DISTINCT
                    [IDDimStatusContratos]
                FROM [Integracao].[Silver].[FatoControleContratosEuromidia] WITH (NOLOCK)
                WHERE [IDDimStatusContratos] IS NOT NULL
            """),
        ).mappings().all()

        ids_status_usados = {
            int(row.get("IDDimStatusContratos") or 0)
            for row in rows_status_usados
            if row.get("IDDimStatusContratos") is not None
        }

        status_opcoes_cache = [
            dict(dados_status)
            for id_status, dados_status in mapa_status_config.items()
            if id_status in ids_status_usados
        ]

        status_opcoes_cache.sort(key=lambda item: (item.get("Status") or "").lower())
        _cache_set_seguro_paineis(
            "paineis:contratos_lista:status_opcoes:v3",
            status_opcoes_cache,
            cache_timeout_filtros_contratos,
        )

    status_opcoes = [
        SimpleNamespace(**dados_status)
        for dados_status in (status_opcoes_cache or [])
    ]

    cidade_opcoes_cache = _cache_get_seguro_paineis(
        "paineis:contratos_lista:cidade_opcoes:v3"
    )

    if cidade_opcoes_cache is None:
        rows_cidades = db.session.execute(
            text("""
                SELECT
                    CidadeExibicao = LTRIM(RTRIM([CidadeExibicao]))
                FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] WITH (NOLOCK)
                WHERE NULLIF(LTRIM(RTRIM([CidadeExibicao])), '') IS NOT NULL
                GROUP BY LTRIM(RTRIM([CidadeExibicao]))
                ORDER BY LOWER(LTRIM(RTRIM([CidadeExibicao])))
            """),
        ).mappings().all()

        cidade_opcoes_cache = [
            {"CidadeExibicao": (row.get("CidadeExibicao") or "").strip()}
            for row in rows_cidades
            if (row.get("CidadeExibicao") or "").strip()
        ]

        _cache_set_seguro_paineis(
            "paineis:contratos_lista:cidade_opcoes:v3",
            cidade_opcoes_cache,
            cache_timeout_filtros_contratos,
        )

    cidade_opcoes = [
        SimpleNamespace(**linha)
        for linha in (cidade_opcoes_cache or [])
    ]

    segmento_opcoes_cache = _cache_get_seguro_paineis(
        "paineis:contratos_lista:segmento_opcoes:v4"
    )

    if segmento_opcoes_cache is None:
        rows_segmentos = db.session.execute(
            text("""
                SELECT
                    cn.[Classe] AS Classe,
                    MAX(cn.[Hex]) AS Hex
                FROM (
                    SELECT DISTINCT
                        ctr.[IDEmpresa]
                    FROM [Integracao].[Silver].[FatoControleContratosEuromidia] AS ctr WITH (NOLOCK)
                    WHERE ctr.[IDEmpresa] IS NOT NULL
                ) AS empresas_contratos
                INNER JOIN [Integracao].[Silver].[DimEmpresas] AS emp WITH (NOLOCK)
                    ON emp.[IDEmpresa] = empresas_contratos.[IDEmpresa]
                INNER JOIN [Integracao].[Silver].[DimCnaes] AS cn WITH (NOLOCK)
                    ON cn.[cnaepadrao] = emp.[CNAE]
                WHERE NULLIF(LTRIM(RTRIM(cn.[Classe])), '') IS NOT NULL
                GROUP BY
                    cn.[Classe]
                ORDER BY
                    LOWER(cn.[Classe])
            """),
        ).mappings().all()

        segmento_opcoes_cache = [
            {
                "Classe": (row.get("Classe") or "").strip(),
                "Hex": _normalizar_hex_css(row.get("Hex")),
            }
            for row in rows_segmentos
            if (row.get("Classe") or "").strip()
        ]

        _cache_set_seguro_paineis(
            "paineis:contratos_lista:segmento_opcoes:v4",
            segmento_opcoes_cache,
            cache_timeout_filtros_contratos,
        )

    segmento_opcoes = [
        SimpleNamespace(
            Classe=(linha.get("Classe") or "").strip(),
            Hex=_normalizar_hex_css(linha.get("Hex")),
        )
        for linha in (segmento_opcoes_cache or [])
        if (linha.get("Classe") or "").strip()
    ]

    mapa_status = {
        int(linha.IDDimStatusContratos): (linha.Status or "").strip()
        for linha in status_opcoes
    }

    mapa_cidades = {
        (linha.CidadeExibicao or "").strip(): (linha.CidadeExibicao or "").strip()
        for linha in cidade_opcoes
        if (linha.CidadeExibicao or "").strip()
    }

    mapa_segmentos = {
        (linha.Classe or "").strip(): (linha.Classe or "").strip()
        for linha in segmento_opcoes
        if (linha.Classe or "").strip()
    }

    nomes_status_selecionados = [
        mapa_status[id_status]
        for id_status in ids_status_selecionados
        if id_status in mapa_status
    ]

    nomes_cidades_selecionadas = [
        mapa_cidades[cidade]
        for cidade in cidades_selecionadas
        if cidade in mapa_cidades
    ]

    nomes_segmentos_selecionados = [
        mapa_segmentos[segmento]
        for segmento in segmentos_selecionados
        if segmento in mapa_segmentos
    ]

    q_exibicao = q
    id_para_exibir = id_contrato_selecionado

    if id_para_exibir is None and q.isdigit():
        try:
            id_para_exibir = int(q)
        except ValueError:
            id_para_exibir = None

    if id_para_exibir:
        contrato_q_exibicao = (
            db.session.query(
                FatoControleContratosEuromidia.IDFatoControleContratosEuromidia.label("IDContrato"),
                FatoControleContratosEuromidia.RazaoSocial.label("RazaoSocial"),
                FatoControleContratosEuromidia.MarcaExibida.label("MarcaExibida"),
                FatoControleContratosEuromidia.NumeroContrato.label("NumeroContrato"),
            )
            .filter(
                FatoControleContratosEuromidia.IDFatoControleContratosEuromidia == id_para_exibir
            )
            .first()
        )

        if contrato_q_exibicao:
            nome_principal = (
                contrato_q_exibicao.RazaoSocial
                or contrato_q_exibicao.MarcaExibida
                or contrato_q_exibicao.NumeroContrato
                or f"Contrato {contrato_q_exibicao.IDContrato}"
            )

            q_exibicao = f"{contrato_q_exibicao.IDContrato} • {nome_principal}"

    consulta_base_ids = db.session.query(
        FatoControleContratosEuromidia.IDFatoControleContratosEuromidia
    )

    if id_contrato_selecionado:
        consulta_base_ids = consulta_base_ids.filter(
            FatoControleContratosEuromidia.IDFatoControleContratosEuromidia
            == id_contrato_selecionado
        )

    else:
        if q:
            like_prefixo = f"{q}%"
            like_contendo = f"%{q}%"

            texto_sem_mascara = _texto_sem_mascara_documento(q)
            busca_documental = texto_sem_mascara.isdigit()

            filtro_cidade_busca = _filtro_exists_cidade_exibicao_like(like_contendo)

            filtro_segmento_busca = (
                db.session.query(DimEmpresas.IDEmpresa)
                .join(
                    DimCnaes,
                    DimCnaes.cnaepadrao == DimEmpresas.CNAE,
                )
                .filter(
                    DimEmpresas.IDEmpresa == FatoControleContratosEuromidia.IDEmpresa,
                    DimCnaes.Classe.like(like_contendo),
                )
                .exists()
            )

            if busca_documental:
                consulta_base_ids = consulta_base_ids.filter(
                    or_(
                        FatoControleContratosEuromidia.NumeroContrato.like(like_prefixo),
                        FatoControleContratosEuromidia.NumeroPrevia.like(like_prefixo),
                        FatoControleContratosEuromidia.CNPJ.like(like_prefixo),
                        FatoControleContratosEuromidia.CPF.like(like_prefixo),
                        FatoControleContratosEuromidia.IDFatoControleContratosEuromidia
                        == int(texto_sem_mascara),
                    )
                )

            else:
                consulta_base_ids = consulta_base_ids.filter(
                    or_(
                        FatoControleContratosEuromidia.NumeroContrato.like(like_prefixo),
                        FatoControleContratosEuromidia.NumeroPrevia.like(like_prefixo),
                        FatoControleContratosEuromidia.CNPJ.like(like_prefixo),
                        FatoControleContratosEuromidia.CPF.like(like_prefixo),
                        FatoControleContratosEuromidia.RazaoSocial.like(like_contendo),
                        FatoControleContratosEuromidia.MarcaExibida.like(like_contendo),
                        FatoControleContratosEuromidia.Vendedor.like(like_contendo),
                        FatoControleContratosEuromidia.Agencia.like(like_contendo),
                        FatoControleContratosEuromidia.Bureau.like(like_contendo),
                        FatoControleContratosEuromidia.Intermediario.like(like_contendo),
                        FatoControleContratosEuromidia.TipoDocumento.like(like_contendo),
                        FatoControleContratosEuromidia.Origem.like(like_contendo),
                        FatoControleContratosEuromidia.SDR.like(like_contendo),
                        filtro_cidade_busca,
                        filtro_segmento_busca,
                    )
                )

    if ids_status_selecionados:
        consulta_base_ids = consulta_base_ids.filter(
            FatoControleContratosEuromidia.IDDimStatusContratos.in_(
                ids_status_selecionados
            )
        )

    if cidades_selecionadas:
        filtro_cidade_selecionada = (
            db.session.query(
                FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia
            )
            .filter(
                FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia
                == FatoControleContratosEuromidia.IDFatoControleContratosEuromidia,
                FatoControleContratosItensEuromidia.CidadeExibicao.in_(
                    cidades_selecionadas
                ),
            )
            .exists()
        )

        consulta_base_ids = consulta_base_ids.filter(
            filtro_cidade_selecionada
        )

    if segmentos_selecionados:
        filtro_segmento_selecionado = (
            db.session.query(DimEmpresas.IDEmpresa)
            .join(
                DimCnaes,
                DimCnaes.cnaepadrao == DimEmpresas.CNAE,
            )
            .filter(
                DimEmpresas.IDEmpresa == FatoControleContratosEuromidia.IDEmpresa,
                DimCnaes.Classe.in_(segmentos_selecionados),
            )
            .exists()
        )

        consulta_base_ids = consulta_base_ids.filter(
            filtro_segmento_selecionado
        )

    if contrato_ativo in {"0", "1"}:
        consulta_base_ids = consulta_base_ids.filter(
            FatoControleContratosEuromidia.BitAtivo == int(contrato_ativo)
        )

    total = None
    total_pages = None
    tempo_count = 0.0

    if calcular_total:
        t_count0 = time.perf_counter()

        total = consulta_base_ids.order_by(None).count()
        total_pages = max(1, (total + per_page - 1) // per_page)

        if page > total_pages:
            page = total_pages

        tempo_count = time.perf_counter() - t_count0

    offset = (page - 1) * per_page

    t_ids0 = time.perf_counter()

    ordenacao_data_nula_por_ultimo = case(
        (
            FatoControleContratosEuromidia.DataLancamento.is_(None),
            1,
        ),
        else_=0,
    )

    ids_plus = [
        linha[0]
        for linha in (
            consulta_base_ids
            .order_by(
                ordenacao_data_nula_por_ultimo.asc(),
                desc(FatoControleContratosEuromidia.DataLancamento),
                desc(FatoControleContratosEuromidia.IDFatoControleContratosEuromidia),
            )
            .offset(offset)
            .limit(per_page + 1)
            .all()
        )
    ]

    tempo_ids = time.perf_counter() - t_ids0

    has_next = len(ids_plus) > per_page
    ids_pagina = ids_plus[:per_page]
    has_prev = page > 1

    contratos = []
    tempo_logo = 0.0
    tempo_detalhes = 0.0

    logo_empresa_url = ""
    logo_empresa_raw = ""

    if ids_pagina:
        t_logo0 = time.perf_counter()

        row_logo = db.session.execute(
            text(
                """
                SELECT TOP 1
                    Logo
                FROM [Integracao].[dbo].[EmpresaProprietaria]
                WHERE IDEmpresaProprietaria = 3
                """
            )
        ).mappings().first()

        logo_empresa_raw = (row_logo.get("Logo") if row_logo else "") or ""
        logo_empresa_raw = logo_empresa_raw.strip()

        if logo_empresa_raw:
            nome_arquivo_logo = os.path.basename(
                logo_empresa_raw.replace("\\", "/")
            )

            logo_empresa_url = url_for(
                "static",
                filename=f"LogoEmpresaProprietaria/{nome_arquivo_logo}",
            )

        tempo_logo = time.perf_counter() - t_logo0

        t_detalhes0 = time.perf_counter()

        subquery_cidades = (
            db.session.query(
                FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia.label("id_contrato"),
                func.min(
                    FatoControleContratosItensEuromidia.CidadeExibicao
                ).label("CidadeExibicao"),
            )
            .filter(
                FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia.in_(
                    ids_pagina
                )
            )
            .group_by(
                FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia
            )
            .subquery()
        )

        """
        Correção de performance:
        Antes a lista montava uma subquery de segmento agrupando a DimEmpresas
        inteira, mesmo quando a página exibia só 25 contratos. Como a DimEmpresas
        tem milhões de linhas, isso deixava /paineis/contratos lento.

        Agora a rota faz em duas etapas:
        1) busca somente os contratos da página;
        2) pega os segmentos apenas dos IDEmpresa presentes nessa página.

        Assim todas as informações continuam sendo exibidas, mas o backend para
        de fazer uma agregação desnecessária em milhões de empresas por request.
        """
        linhas_contratos = (
            db.session.query(
                FatoControleContratosEuromidia.IDFatoControleContratosEuromidia.label("IDContrato"),
                FatoControleContratosEuromidia.IDFatoControleContratosEuromidia.label("IDFatoControleContratosEuromidia"),
                FatoControleContratosEuromidia.IDEmpresa.label("IDEmpresa"),
                FatoControleContratosEuromidia.DataLancamento.label("DataLancamento"),
                FatoControleContratosEuromidia.RazaoSocial.label("RazaoSocial"),
                FatoControleContratosEuromidia.MarcaExibida.label("MarcaExibida"),
                FatoControleContratosEuromidia.IDDimStatusContratos.label("IDDimStatusContratos"),
                FatoControleContratosEuromidia.BitAtivo.label("BitAtivo"),
                subquery_cidades.c.CidadeExibicao.label("CidadeExibicao"),
            )
            .outerjoin(
                subquery_cidades,
                subquery_cidades.c.id_contrato
                == FatoControleContratosEuromidia.IDFatoControleContratosEuromidia,
            )
            .filter(
                FatoControleContratosEuromidia.IDFatoControleContratosEuromidia.in_(
                    ids_pagina
                )
            )
            .all()
        )

        ids_empresas_pagina = sorted(
            {
                int(getattr(linha, "IDEmpresa", 0) or 0)
                for linha in linhas_contratos
                if getattr(linha, "IDEmpresa", None) is not None
                and int(getattr(linha, "IDEmpresa", 0) or 0) > 0
            }
        )

        mapa_segmentos_pagina: dict[int, dict] = {}

        if ids_empresas_pagina:
            sql_segmentos_pagina = text("""
                SELECT
                    emp.[IDEmpresa] AS IDEmpresa,
                    MIN(cn.[Classe]) AS SegmentoContrato,
                    MAX(cn.[Hex]) AS SegmentoHex
                FROM [Integracao].[Silver].[DimEmpresas] AS emp WITH (NOLOCK)
                LEFT JOIN [Integracao].[Silver].[DimCnaes] AS cn WITH (NOLOCK)
                    ON cn.[cnaepadrao] = emp.[CNAE]
                WHERE
                    emp.[IDEmpresa] IN :ids_empresas_pagina
                GROUP BY
                    emp.[IDEmpresa]
            """).bindparams(bindparam("ids_empresas_pagina", expanding=True))

            rows_segmentos_pagina = db.session.execute(
                sql_segmentos_pagina,
                {"ids_empresas_pagina": ids_empresas_pagina},
            ).mappings().all()

            mapa_segmentos_pagina = {
                int(row.get("IDEmpresa") or 0): {
                    "SegmentoContrato": (row.get("SegmentoContrato") or "").strip(),
                    "SegmentoHex": _normalizar_hex_css(row.get("SegmentoHex")),
                }
                for row in rows_segmentos_pagina
                if int(row.get("IDEmpresa") or 0) > 0
            }

        mapa_preferencia_reserva: dict[int, int] = {}

        sql_preferencia_reserva = text("""
            SELECT
                ci.[IDFatoControleContratoEuromidia] AS IDFatoControleContratosEuromidia,
                MAX(
                    CASE
                        WHEN TRY_CONVERT(int, ci.[BitPreferencia]) = 1 THEN 1
                        ELSE 0
                    END
                ) AS BitPreferenciaReserva
            FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] AS ci
            WHERE
                ci.[IDFatoControleContratoEuromidia] IN :ids_pagina
                AND ISNULL(ci.[BitAtivo], 1) = 1
                AND TRY_CONVERT(int, ci.[BitPreferencia]) IN (0, 1)
            GROUP BY
                ci.[IDFatoControleContratoEuromidia]
        """).bindparams(bindparam("ids_pagina", expanding=True))

        rows_preferencia_reserva = db.session.execute(
            sql_preferencia_reserva,
            {"ids_pagina": ids_pagina},
        ).mappings().all()

        mapa_preferencia_reserva = {
            int(row["IDFatoControleContratosEuromidia"]): int(row["BitPreferenciaReserva"] or 0)
            for row in rows_preferencia_reserva
            if row.get("IDFatoControleContratosEuromidia") is not None
        }

        tempo_detalhes = time.perf_counter() - t_detalhes0

        mapa_contratos: dict[int, SimpleNamespace] = {}

        for linha in linhas_contratos:
            dados = dict(linha._mapping)
            dados["LogoEmpresaProprietaria"] = logo_empresa_raw
            dados["LogoEmpresaProprietariaUrl"] = logo_empresa_url

            try:
                id_empresa_contrato = int(dados.get("IDEmpresa") or 0)
            except Exception:
                id_empresa_contrato = 0

            dados_segmento = mapa_segmentos_pagina.get(id_empresa_contrato, {})
            dados["SegmentoContrato"] = (dados_segmento.get("SegmentoContrato") or "").strip()
            dados["SegmentoHex"] = _normalizar_hex_css(dados_segmento.get("SegmentoHex"))

            try:
                id_status_contrato = int(dados.get("IDDimStatusContratos") or 0)
            except Exception:
                id_status_contrato = 0

            dados_status = mapa_status_config.get(id_status_contrato, {})
            dados["StatusContrato"] = (dados_status.get("Status") or "").strip()
            dados["CorHexStatusContrato"] = dados_status.get("CorHex") or ""
            dados["CorTextoStatusContrato"] = dados_status.get("CorTexto") or "#FFFFFF"

            id_contrato_pref = int(dados["IDFatoControleContratosEuromidia"] or 0)

            if id_status_contrato in (8, 9, 10):
                bit_preferencia_reserva = 0
            else:
                bit_preferencia_reserva = int(mapa_preferencia_reserva.get(id_contrato_pref, 0) or 0)

            dados["BitPreferenciaReserva"] = bit_preferencia_reserva
            dados["PreferenciaReservaTexto"] = "Sim" if bit_preferencia_reserva == 1 else "Não"

            mapa_contratos[
                dados["IDFatoControleContratosEuromidia"]
            ] = SimpleNamespace(**dados)

        contratos = [
            mapa_contratos[id_contrato]
            for id_contrato in ids_pagina
            if id_contrato in mapa_contratos
        ]

    if total is None:
        inicio = 0 if len(contratos) == 0 else offset + 1
        fim = offset + len(contratos)
    else:
        inicio = 0 if total == 0 else offset + 1
        fim = min(offset + per_page, total)

    if total_pages is None:
        total_pages = page + 1 if has_next else page

    paginacao = {
        "page": page,
        "per_page": per_page,
        "total": total,
        "total_pages": total_pages,
        "inicio": inicio,
        "fim": fim,
        "has_next": has_next,
        "has_prev": has_prev,
        "calcular_total": calcular_total,
    }

    if limpar_filtros:
        url_lista_atual = url_for(
            "Paineis.contratos_lista",
            per_page=per_page,
            calcular_total=(1 if calcular_total else 0),
        )
    else:
        url_lista_atual = _url_request_atual()

    session["contratos_lista_return_to"] = url_lista_atual

    filtros = {
        "q": q,
        "q_exibicao": q_exibicao,
        "id_contrato": id_contrato_selecionado,
        "per_page": per_page,
        "status_ids": ids_status_selecionados,
        "status_nomes": nomes_status_selecionados,
        "cidades": cidades_selecionadas,
        "cidade_nomes": nomes_cidades_selecionadas,
        "segmentos": segmentos_selecionados,
        "segmento_nomes": nomes_segmentos_selecionados,
        "contrato_ativo": contrato_ativo,
        "contrato_ativo_nome": contrato_ativo_nome,
        "url_atual": url_lista_atual,
    }

    tempo_total = time.perf_counter() - tempo_inicio

    current_app.logger.warning(
        "contratos_lista | ordem=DataLancamento DESC, IDContrato DESC | q=%r | id_contrato=%s | status=%s | cidades=%s | segmentos=%s | "
        "contrato_ativo=%r | page=%s | per_page=%s | total=%s | count=%.3fs | ids=%.3fs | "
        "logo=%.3fs | detalhes=%.3fs | total_req=%.3fs",
        q,
        id_contrato_selecionado,
        ids_status_selecionados,
        cidades_selecionadas,
        segmentos_selecionados,
        contrato_ativo,
        page,
        per_page,
        total,
        tempo_count,
        tempo_ids,
        tempo_logo,
        tempo_detalhes,
        tempo_total,
    )

    return render_template(
        "euromidia/contratos_lista.html",
        contratos=contratos,
        paginacao=paginacao,
        filtros=filtros,
        status_opcoes=status_opcoes,
        cidade_opcoes=cidade_opcoes,
        segmento_opcoes=segmento_opcoes,
        contrato_ativo_opcoes=contrato_ativo_opcoes,
    )







@paineis_bp.get("/contratos/sugestoes-busca")
@login_required
def contratos_busca_sugestoes():
    termo = (request.args.get("q") or "").strip()
    mapa_status_config = _obter_mapa_status_contratos_com_cores(3)

    cidade_exibicao_subquery = (
        db.session.query(
            func.min(FatoControleContratosItensEuromidia.CidadeExibicao)
        )
        .filter(
            FatoControleContratosItensEuromidia.IDFatoControleContratoEuromidia
            == FatoControleContratosEuromidia.IDFatoControleContratosEuromidia
        )
        .correlate(FatoControleContratosEuromidia)
        .scalar_subquery()
    )

    segmento_contrato_subquery = (
        db.session.query(func.min(DimCnaes.Classe))
        .select_from(DimEmpresas)
        .outerjoin(DimCnaes, DimCnaes.cnaepadrao == DimEmpresas.CNAE)
        .filter(DimEmpresas.IDEmpresa == FatoControleContratosEuromidia.IDEmpresa)
        .correlate(FatoControleContratosEuromidia)
        .scalar_subquery()
    )

    segmento_hex_subquery = (
        db.session.query(func.max(DimCnaes.Hex))
        .select_from(DimEmpresas)
        .outerjoin(DimCnaes, DimCnaes.cnaepadrao == DimEmpresas.CNAE)
        .filter(DimEmpresas.IDEmpresa == FatoControleContratosEuromidia.IDEmpresa)
        .correlate(FatoControleContratosEuromidia)
        .scalar_subquery()
    )

    consulta = (
        db.session.query(
            FatoControleContratosEuromidia.IDFatoControleContratosEuromidia.label("IDContrato"),
            FatoControleContratosEuromidia.NumeroContrato.label("NumeroContrato"),
            FatoControleContratosEuromidia.NumeroPrevia.label("NumeroPrevia"),
            FatoControleContratosEuromidia.RazaoSocial.label("RazaoSocial"),
            FatoControleContratosEuromidia.MarcaExibida.label("MarcaExibida"),
            FatoControleContratosEuromidia.CNPJ.label("CNPJ"),
            FatoControleContratosEuromidia.CPF.label("CPF"),
            FatoControleContratosEuromidia.DataLancamento.label("DataLancamento"),
            FatoControleContratosEuromidia.IDDimStatusContratos.label("IDDimStatusContratos"),
            FatoControleContratosEuromidia.BitAtivo.label("BitAtivo"),
            cidade_exibicao_subquery.label("CidadeExibicao"),
            segmento_contrato_subquery.label("SegmentoContrato"),
            segmento_hex_subquery.label("SegmentoHex"),
        )
    )

    if termo:
        like_prefixo = f"{termo}%"
        like_contendo = f"%{termo}%"

        texto_sem_mascara = _texto_sem_mascara_documento(termo)
        busca_documental = texto_sem_mascara.isdigit()

        if busca_documental:
            consulta = consulta.filter(
                or_(
                    FatoControleContratosEuromidia.NumeroContrato.like(like_prefixo),
                    FatoControleContratosEuromidia.NumeroPrevia.like(like_prefixo),
                    FatoControleContratosEuromidia.CNPJ.like(like_prefixo),
                    FatoControleContratosEuromidia.CPF.like(like_prefixo),
                    func.cast(
                        FatoControleContratosEuromidia.IDFatoControleContratosEuromidia,
                        db.String,
                    ).like(like_prefixo),
                )
            )
        else:
            texto_busca_normalizado = unicodedata.normalize("NFKD", termo).encode("ascii", "ignore").decode("ascii").lower().strip()

            ids_status_busca = [
                id_status
                for id_status, dados_status in mapa_status_config.items()
                if texto_busca_normalizado
                and texto_busca_normalizado in unicodedata.normalize("NFKD", (dados_status.get("Status") or "")).encode("ascii", "ignore").decode("ascii").lower()
            ]

            filtro_segmento_busca = (
                db.session.query(DimEmpresas.IDEmpresa)
                .join(
                    DimCnaes,
                    DimCnaes.cnaepadrao == DimEmpresas.CNAE,
                )
                .filter(
                    DimEmpresas.IDEmpresa == FatoControleContratosEuromidia.IDEmpresa,
                    DimCnaes.Classe.like(like_contendo),
                )
                .exists()
            )

            filtros_busca = [
                FatoControleContratosEuromidia.NumeroContrato.like(like_prefixo),
                FatoControleContratosEuromidia.NumeroPrevia.like(like_prefixo),
                FatoControleContratosEuromidia.CNPJ.like(like_prefixo),
                FatoControleContratosEuromidia.CPF.like(like_prefixo),
                FatoControleContratosEuromidia.RazaoSocial.like(like_contendo),
                FatoControleContratosEuromidia.MarcaExibida.like(like_contendo),
                FatoControleContratosEuromidia.Vendedor.like(like_contendo),
                FatoControleContratosEuromidia.Agencia.like(like_contendo),
                FatoControleContratosEuromidia.Bureau.like(like_contendo),
                FatoControleContratosEuromidia.Intermediario.like(like_contendo),
                FatoControleContratosEuromidia.TipoDocumento.like(like_contendo),
                FatoControleContratosEuromidia.Origem.like(like_contendo),
                FatoControleContratosEuromidia.SDR.like(like_contendo),
                _filtro_exists_cidade_exibicao_like(like_contendo),
                filtro_segmento_busca,
            ]

            if ids_status_busca:
                filtros_busca.append(
                    FatoControleContratosEuromidia.IDDimStatusContratos.in_(ids_status_busca)
                )

            if texto_busca_normalizado in {"ativo", "ativos", "ativa", "ativas"}:
                filtros_busca.append(FatoControleContratosEuromidia.BitAtivo == 1)

            if texto_busca_normalizado in {"inativo", "inativos", "inativa", "inativas"}:
                filtros_busca.append(FatoControleContratosEuromidia.BitAtivo == 0)


            consulta = consulta.filter(or_(*filtros_busca))

    linhas = (
        consulta
        .order_by(
            desc(FatoControleContratosEuromidia.DataLancamento),
            desc(FatoControleContratosEuromidia.IDFatoControleContratosEuromidia),
        )
        .limit(15)
        .all()
    )

    ids_linhas = [int(linha.IDContrato) for linha in linhas if linha.IDContrato is not None]
    mapa_preferencia_reserva: dict[int, int] = {}

    if ids_linhas:
        sql_preferencia_reserva = text("""
            SELECT
                ci.[IDFatoControleContratoEuromidia] AS IDFatoControleContratosEuromidia,
                MAX(
                    CASE
                        WHEN TRY_CONVERT(int, ci.[BitPreferencia]) = 1 THEN 1
                        ELSE 0
                    END
                ) AS BitPreferenciaReserva
            FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] AS ci
            WHERE
                ci.[IDFatoControleContratoEuromidia] IN :ids_linhas
                AND ISNULL(ci.[BitAtivo], 1) = 1
                AND TRY_CONVERT(int, ci.[BitPreferencia]) IN (0, 1)
            GROUP BY
                ci.[IDFatoControleContratoEuromidia]
        """).bindparams(bindparam("ids_linhas", expanding=True))

        rows_preferencia_reserva = db.session.execute(
            sql_preferencia_reserva,
            {"ids_linhas": ids_linhas},
        ).mappings().all()

        mapa_preferencia_reserva = {
            int(row["IDFatoControleContratosEuromidia"]): int(row["BitPreferenciaReserva"] or 0)
            for row in rows_preferencia_reserva
            if row.get("IDFatoControleContratosEuromidia") is not None
        }

    itens: list[dict] = []

    for linha in linhas:
        id_contrato = int(linha.IDContrato)
        razao_social = (linha.RazaoSocial or "").strip()
        marca_exibida = (linha.MarcaExibida or "").strip()
        nome_principal = (
            razao_social
            or marca_exibida
            or (linha.NumeroContrato or "").strip()
            or f"Contrato {id_contrato}"
        )

        rotulo = f"#{id_contrato} • {nome_principal}"

        try:
            id_status_contrato = int(linha.IDDimStatusContratos or 0)
        except Exception:
            id_status_contrato = 0

        dados_status = mapa_status_config.get(id_status_contrato, {})
        status_nome = (dados_status.get("Status") or "—").strip() or "—"

        try:
            bit_ativo = int(linha.BitAtivo or 0)
        except Exception:
            bit_ativo = 0

        if id_status_contrato in (8, 9, 10):
            bit_preferencia_reserva = 0
        else:
            bit_preferencia_reserva = int(mapa_preferencia_reserva.get(id_contrato, 0) or 0)

        cidade = (linha.CidadeExibicao or "").strip() or "—"
        segmento = (linha.SegmentoContrato or "").strip() or "—"
        segmento_cor = _normalizar_hex_css(getattr(linha, "SegmentoHex", None)) or "#64748B"
        ativo_texto = "Ativo" if bit_ativo == 1 else "Inativo"
        preferencia_texto = "Sim" if bit_preferencia_reserva == 1 else "Não"

        subtitulos: list[str] = []
        if linha.NumeroContrato:
            subtitulos.append(f"Contrato: {linha.NumeroContrato}")
        if linha.NumeroPrevia:
            subtitulos.append(f"Prévia: {linha.NumeroPrevia}")
        if linha.CNPJ:
            subtitulos.append(f"CNPJ: {linha.CNPJ}")
        elif linha.CPF:
            subtitulos.append(f"CPF: {linha.CPF}")
        subtitulos.append(f"Ativo: {ativo_texto}")
        subtitulos.append(f"Status: {status_nome}")
        subtitulos.append(f"Cidade: {cidade}")
        subtitulos.append(f"Segmento: {segmento}")
        subtitulos.append(f"Preferência reserva: {preferencia_texto}")

        itens.append(
            {
                "id": id_contrato,
                "id_contrato": id_contrato,
                "rotulo": rotulo,
                "valor_busca": str(id_contrato),
                "subtitulo": " • ".join(subtitulos),
                "ativo": ativo_texto,
                "ativo_valor": bit_ativo,
                "status": status_nome,
                "status_cor": dados_status.get("CorHex") or "#E5E7EB",
                "status_cor_texto": dados_status.get("CorTexto") or "#111827",
                "cidade": cidade,
                "razao_social": razao_social or "—",
                "marca": marca_exibida or "—",
                "segmento": segmento,
                "segmento_cor": segmento_cor,
                "preferencia_reserva": preferencia_texto,
                "preferencia_reserva_valor": bit_preferencia_reserva,
            }
        )

    return jsonify({"itens": itens})






def _obter_status_contratos_empresa(id_empresa_proprietaria: int | None):
    mapa_padrao = {
        1: "Em Digitação",
        2: "Pendente Geração",
        3: "Documento Gerado",
        4: "Pendente Envio",
        5: "Enviado Assinatura",
        6: "Em Assinatura",
        7: "Ativo",
        8: "Concluido",
        9: "Cancelado",
        10: "ERRO",
        31: "Reprovado",
    }

    try:
        id_empresa = int(id_empresa_proprietaria or 0)
    except Exception:
        id_empresa = 0

    if id_empresa <= 0:
        return [
            {
                "IDDimStatusContratos": id_status,
                "Status": nome,
                "CorHex": _cor_hex_status_contrato_padrao_paineis(id_status),
            }
            for id_status, nome in mapa_padrao.items()
        ]

    sql = text("""
        SELECT
             [IDDimStatusContratos]
            ,[Status]
            ,[CorHex]
        FROM [Integracao].[Silver].[DimStatusContratos]
        WHERE [IDEmpresaProprietaria] = :id_empresa_proprietaria
          AND (
                [IDDimStatusContratos] BETWEEN 1 AND 10
                OR [IDDimStatusContratos] = 31
              )
        ORDER BY [IDDimStatusContratos] ASC
    """)

    rows = db.session.execute(
        sql,
        {"id_empresa_proprietaria": id_empresa},
    ).mappings().all()

    if not rows:
        return [
            {
                "IDDimStatusContratos": id_status,
                "Status": nome,
                "CorHex": _cor_hex_status_contrato_padrao_paineis(id_status),
            }
            for id_status, nome in mapa_padrao.items()
        ]

    retorno = []
    ids_existentes = set()

    for row in rows:
        id_status = int(row.get("IDDimStatusContratos") or 0)
        if id_status <= 0:
            continue

        ids_existentes.add(id_status)
        retorno.append(
            {
                "IDDimStatusContratos": id_status,
                "Status": (row.get("Status") or mapa_padrao.get(id_status) or f"Status {id_status}").strip(),
                "CorHex": _normalizar_hex_css(
                    row.get("CorHex"),
                    _cor_hex_status_contrato_padrao_paineis(id_status) or "#94A3B8",
                ),
            }
        )

    for id_status, nome in mapa_padrao.items():
        if id_status not in ids_existentes:
            retorno.append(
                {
                    "IDDimStatusContratos": id_status,
                    "Status": nome,
                    "CorHex": _cor_hex_status_contrato_padrao_paineis(id_status),
                }
            )

    retorno.sort(key=lambda x: int(x.get("IDDimStatusContratos") or 0))
    return retorno


def _montar_diagrama_status_contrato(
    id_empresa_proprietaria: int | None,
    id_status_atual: int | None,
    nome_status_atual: str | None = None,
):
    status_rows = _obter_status_contratos_empresa(id_empresa_proprietaria)

    mapa_status = {
        int(row.get("IDDimStatusContratos") or 0): (row.get("Status") or "").strip()
        for row in status_rows
        if int(row.get("IDDimStatusContratos") or 0) > 0
    }
    mapa_cor = {
        int(row.get("IDDimStatusContratos") or 0): (
            _normalizar_hex_css(row.get("CorHex"), "")
            or _cor_hex_status_contrato_padrao_paineis(row.get("IDDimStatusContratos"))
        )
        for row in status_rows
        if int(row.get("IDDimStatusContratos") or 0) > 0
    }

    try:
        id_status_corrente = int(id_status_atual or 0)
    except Exception:
        id_status_corrente = 0

    nome_status_corrente = (nome_status_atual or mapa_status.get(id_status_corrente) or "").strip()
    cor_status_corrente = mapa_cor.get(id_status_corrente) or _cor_hex_status_contrato_padrao_paineis(id_status_corrente)

    etapas_principais = []
    for id_status in range(1, 8):
        nome = mapa_status.get(id_status) or f"Status {id_status}"

        if id_status_corrente in range(1, 8):
            concluido = id_status < id_status_corrente
            atual = id_status == id_status_corrente
        elif id_status_corrente == 8:
            concluido = True
            atual = False
        else:
            concluido = False
            atual = False

        etapas_principais.append(
            {
                "id": id_status,
                "nome": nome,
                "cor_hex": mapa_cor.get(id_status) or _cor_hex_status_contrato_padrao_paineis(id_status),
                "concluido": concluido,
                "atual": atual,
                "pendente": (not concluido) and (not atual),
                "mostra_d4sign": 2 <= id_status <= 6,
                "logo_d4sign_url": url_for("static", filename="imagens/LogoSistemas/d4sign.jpg"),
            }
        )

    terminal_atual = None
    if id_status_corrente in (8, 9, 10, 31):
        terminal_atual = {
            "id": id_status_corrente,
            "nome": mapa_status.get(id_status_corrente) or nome_status_corrente or f"Status {id_status_corrente}",
            "cor_hex": mapa_cor.get(id_status_corrente) or _cor_hex_status_contrato_padrao_paineis(id_status_corrente),
            "classe": "sucesso" if id_status_corrente == 8 else "erro",
            "icone": "✓" if id_status_corrente == 8 else "✖" if id_status_corrente in (9, 31) else "!",
        }

    return {
        "status_atual_id": id_status_corrente,
        "status_atual_nome": nome_status_corrente or "Sem status definido",
        "status_atual_cor": cor_status_corrente,
        "etapas": etapas_principais,
        "terminal_atual": terminal_atual,
    }












from pprint import pformat

def _debug_dump_linhas(etapa: str, rows, limite: int = 100):
    """
    Eu imprimo linha por linha no terminal o retorno real da query.

    Uso isso para validar:
    1. se encontrou os itens do contrato;
    2. se encontrou vínculo na FatoContratoCardEuromidia;
    3. se encontrou histórico na FatoKanbanNegociacaoPreco.
    """
    try:
        linhas = [dict(row) for row in (rows or [])]

        _debug_contratos_detalhe(
            etapa,
            qtd_linhas=len(linhas),
            primeiras_linhas=linhas[:limite],
        )

        print("\n" + "=" * 140, flush=True)
        print(f"[CONTRATO_DETALHE_DEBUG_DUMP] etapa={etapa} | qtd_linhas={len(linhas)}", flush=True)

        for idx, linha in enumerate(linhas[:limite], start=1):
            print(f"\n[{idx}] {pformat(linha, width=220)}", flush=True)

        if len(linhas) > limite:
            print(f"\n... existem mais {len(linhas) - limite} linhas não impressas.", flush=True)

        print("=" * 140 + "\n", flush=True)

    except Exception:
        current_app.logger.exception(
            "Falha ao imprimir debug detalhado no contrato %s | etapa=%s",
            id_contrato,
            etapa,
        )























@paineis_bp.get("/api/contratos/<int:id_contrato>/detalhe-completo-status")
@login_required
@limiter.limit("180 per minute", methods=["GET"])
def api_contrato_detalhe_cache_status(id_contrato: int):
    """Eu informo para o front-end se o HTML completo do contrato já está pronto no Redis."""
    try:
        timeline_page = int(request.args.get("timeline_page") or "1")
    except Exception:
        timeline_page = 1
    timeline_page = max(1, timeline_page)

    try:
        id_usuario_cache = (
            getattr(current_user, "IDDimUsuarios", None)
            or (current_user.get_id() if hasattr(current_user, "get_id") else None)
            or "anonimo"
        )
    except Exception:
        id_usuario_cache = "anonimo"

    cache_key_html = (
        f"contratos_detalhe_html:v20260602_timeline8_v1:"
        f"usuario:{id_usuario_cache}:"
        f"contrato:{int(id_contrato)}:"
        f"modo:completo:"
        f"timeline:{timeline_page}"
    )

    try:
        html_cache = cache.get(cache_key_html)
    except Exception:
        html_cache = None

    return_to = request.args.get("return_to") or url_for("Paineis.contratos_lista")

    return jsonify({
        "ready": bool(html_cache),
        "id_contrato": int(id_contrato),
        "timeline_page": timeline_page,
        "url_completa": url_for(
            "Paineis.contratos_detalhe",
            id_contrato=int(id_contrato),
            return_to=return_to,
            modo_completo=1,
            timeline_page=timeline_page,
        ),
    })


def _so_digitos(v: str) -> str:
    if not v:
        return ""
    return (
        str(v)
        .replace(".", "")
        .replace("-", "")
        .replace("/", "")
        .replace(" ", "")
        .strip()
    )


def _paginacao_basica(page: int, per_page: int, total: int):
    """Cria objeto simples de paginação igual o padrão do seu template."""
    if per_page <= 0:
        per_page = 20

    total_pages = max((total + per_page - 1) // per_page, 1)
    page = max(min(page, total_pages), 1)

    inicio = (page - 1) * per_page + 1 if total > 0 else 0
    fim = min(page * per_page, total) if total > 0 else 0

    return {
        "page": page,
        "per_page": per_page,
        "total": total,
        "total_pages": total_pages,
        "inicio": inicio,
        "fim": fim,
        "has_prev": page > 1,
        "has_next": page < total_pages,
        "prev_page": page - 1 if page > 1 else 1,
        "next_page": page + 1 if page < total_pages else total_pages,
    }


