@paineis_bp.get("/preferencia-reservas")
@login_required
@limiter.limit(LIMITE_GET_TELAS_NAVEGACAO, methods=["GET"])
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def preferencia_reservas_lista():
    """
    Eu listo as preferências de reserva com filtros de período, busca e vendedor.

    Regras de acesso:
    - Admin e Coordenador enxergam todas as preferências ativas.
    - Vendedor enxerga somente as preferências ligadas ao seu IDVendedor.
    - Outros perfis não acessam esta tela.

    Regras de filtro:
    - q pesquisa contrato, prévia, razão social, marca, vendedor e CodFace.
    - dt_ini/dt_fim filtram por sobreposição do período reservado:
      DataInicioPrevisto <= dt_fim e DataTerminoPrevisto >= dt_ini.
    - vendedor é filtro múltiplo apenas para quem tem visão total.
    """
    usuario_eh_admin = _usuario_logado_eh_perfil_admin()
    usuario_eh_coordenador = _usuario_logado_eh_perfil_coordenador()
    usuario_eh_vendedor = _usuario_logado_eh_perfil_vendedor()
    usuario_tem_visao_total = usuario_eh_admin or usuario_eh_coordenador

    if not (usuario_tem_visao_total or usuario_eh_vendedor):
        abort(403, description="Perfil sem permissão para visualizar preferências de reserva.")

    def _parse_data_preferencia(valor):
        texto = str(valor or "").strip()
        if not texto:
            return None

        for formato in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
            try:
                return datetime.strptime(texto, formato).date()
            except Exception:
                continue

        return None

    def _normalizar_lista_int_preferencia(valores):
        resultado = []
        vistos = set()

        for valor in valores or []:
            texto = str(valor or "").strip()
            if not texto:
                continue

            try:
                numero = int(texto)
            except Exception:
                continue

            if numero <= 0 or numero in vistos:
                continue

            vistos.add(numero)
            resultado.append(numero)

        return resultado

    def _adicionar_filtro_in_preferencia(filtros_sql, params, coluna_sql, prefixo, valores):
        valores_validos = _normalizar_lista_int_preferencia(valores)
        if not valores_validos:
            return []

        placeholders = []
        for idx, valor in enumerate(valores_validos):
            chave = f"{prefixo}_{idx}"
            placeholders.append(f":{chave}")
            params[chave] = int(valor)

        filtros_sql.append(f"{coluna_sql} IN ({', '.join(placeholders)})")
        return valores_validos

    def _formatar_moeda_preferencia(valor):
        """Eu formato valor monetário em pt-BR sem depender de filtro externo do Jinja."""
        if valor is None:
            return "—"

        try:
            numero = float(valor)
        except Exception:
            return str(valor)

        return "R$ " + f"{numero:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")

    def _formatar_data_preferencia(valor, com_hora: bool = False):
        """Eu formato datas da tela em pt-BR e mantenho fallback seguro para strings."""
        if valor is None:
            return "—"

        if isinstance(valor, str):
            texto = valor.strip()
            if not texto:
                return "—"

            for formato in ("%Y-%m-%d %H:%M:%S.%f", "%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
                try:
                    valor = datetime.strptime(texto[:26], formato)
                    break
                except Exception:
                    continue
            else:
                return texto

        try:
            if com_hora:
                return valor.strftime("%d/%m/%Y %H:%M")
            return valor.strftime("%d/%m/%Y")
        except Exception:
            return str(valor)

    try:
        page = int((request.args.get("page") or "1").strip())
    except Exception:
        page = 1

    page = max(1, page)
    per_page = 10
    limite_resultados = 1000

    q = (request.args.get("q") or "").strip()[:160]
    dt_ini_raw = (request.args.get("dt_ini") or "").strip()
    dt_fim_raw = (request.args.get("dt_fim") or "").strip()

    data_inicio_filtro = _parse_data_preferencia(dt_ini_raw)
    data_fim_filtro = _parse_data_preferencia(dt_fim_raw)

    if data_inicio_filtro and data_fim_filtro and data_fim_filtro < data_inicio_filtro:
        data_inicio_filtro, data_fim_filtro = data_fim_filtro, data_inicio_filtro

    dt_ini = data_inicio_filtro.strftime("%Y-%m-%d") if data_inicio_filtro else ""
    dt_fim = data_fim_filtro.strftime("%Y-%m-%d") if data_fim_filtro else ""
    periodo_filtro_ativo = bool(dt_ini or dt_fim)
    ano_periodo = int((data_inicio_filtro or data_fim_filtro or date.today()).year)

    vendedores_ids_selecionados = (
        _normalizar_lista_int_preferencia(request.args.getlist("vendedor"))
        if usuario_tem_visao_total
        else []
    )

    id_vendedor_logado = 0
    filtros_sql = [
        "ISNULL(PR.BitAtivo, 0) = 1",
        "ISNULL(PRI.BitAtivo, 0) = 1",
    ]
    params = {}

    if usuario_eh_vendedor and not usuario_tem_visao_total:
        id_vendedor_logado = _resolver_id_vendedor_logado_carteira()

        if id_vendedor_logado <= 0:
            filtros_sql.append("1 = 0")
        else:
            filtros_sql.append("PR.IDVendedor = :id_vendedor_logado")
            params["id_vendedor_logado"] = id_vendedor_logado

    if q:
        filtros_sql.append("""
            (
                CAST(PR.IDFatoControleContratosEuromidia AS varchar(40)) LIKE :q_like
                OR ISNULL(CTR.NumeroContrato, '') COLLATE Latin1_General_CI_AI LIKE :q_like
                OR ISNULL(CTR.NumeroPrevia, '') COLLATE Latin1_General_CI_AI LIKE :q_like
                OR ISNULL(CTR.RazaoSocial, '') COLLATE Latin1_General_CI_AI LIKE :q_like
                OR ISNULL(PR.MarcaExibida, '') COLLATE Latin1_General_CI_AI LIKE :q_like
                OR ISNULL(V.NomeVendedor, '') COLLATE Latin1_General_CI_AI LIKE :q_like
                OR ISNULL(F.CodFace, '') COLLATE Latin1_General_CI_AI LIKE :q_like
            )
        """)
        params["q_like"] = f"%{q}%"

    if data_inicio_filtro is not None and data_fim_filtro is not None:
        filtros_sql.append("""
            PRI.DataInicioPrevisto IS NOT NULL
            AND PRI.DataTerminoPrevisto IS NOT NULL
            AND CAST(PRI.DataInicioPrevisto AS date) <= :data_fim_filtro
            AND CAST(PRI.DataTerminoPrevisto AS date) >= :data_inicio_filtro
        """)
        params["data_inicio_filtro"] = data_inicio_filtro
        params["data_fim_filtro"] = data_fim_filtro
    elif data_inicio_filtro is not None:
        filtros_sql.append("PRI.DataTerminoPrevisto IS NOT NULL AND CAST(PRI.DataTerminoPrevisto AS date) >= :data_inicio_filtro")
        params["data_inicio_filtro"] = data_inicio_filtro
    elif data_fim_filtro is not None:
        filtros_sql.append("PRI.DataInicioPrevisto IS NOT NULL AND CAST(PRI.DataInicioPrevisto AS date) <= :data_fim_filtro")
        params["data_fim_filtro"] = data_fim_filtro

    if usuario_tem_visao_total:
        _adicionar_filtro_in_preferencia(
            filtros_sql,
            params,
            "PR.IDVendedor",
            "vendedor_id",
            vendedores_ids_selecionados,
        )

    where_sql = " AND ".join(f"({filtro})" for filtro in filtros_sql)

    sql_from_where = f"""
        FROM [Integracao].[Silver].[FatoPreferenciaReserva] AS PR
        INNER JOIN [Integracao].[Silver].[FatoPreferenciaReservaItens] AS PRI
            ON PRI.IDFatoPreferenciaReserva = PR.IDFatoPreferenciaReserva
        LEFT JOIN [Integracao].[dbo].[Vendedores] AS V
            ON V.IDVendedor = PR.IDVendedor
        LEFT JOIN [Integracao].[Silver].[DimFacesPaineis] AS F
            ON F.IDDimFacesPaineis = PRI.IDDimFacesPaineis
        LEFT JOIN [Integracao].[Silver].[FatoControleContratosEuromidia] AS CTR
            ON CTR.IDFatoControleContratosEuromidia = PR.IDFatoControleContratosEuromidia
        WHERE {where_sql}
    """

    sql_total = text(f"""
        SELECT COUNT_BIG(1) AS Total
        {sql_from_where};
    """)

    total_bruto = int(db.session.execute(sql_total, params).scalar() or 0)
    total = min(total_bruto, limite_resultados)
    total_pages = max(int(math.ceil(total / per_page)), 1) if total > 0 else 1

    if page > total_pages:
        page = total_pages

    offset = (page - 1) * per_page

    sql_itens = text(f"""
        SELECT
             PR.IDFatoPreferenciaReserva
            ,PRI.IDFatoPreferenciaReservaItens
            ,PR.IDFatoControleContratosEuromidia
            ,PR.IDVendedor
            ,V.NomeVendedor
            ,CTR.NumeroContrato
            ,CTR.NumeroPrevia
            ,CTR.RazaoSocial
            ,PR.TotalLiquidoContrato
            ,PR.MarcaExibida
            ,F.CodFace
            ,PR.DataCriacao
            ,PRI.DataInicioPrevisto AS DataInicio
            ,PRI.DataTerminoPrevisto AS DataTermino
        {sql_from_where}
        ORDER BY
             PR.DataCriacao DESC
            ,PR.IDFatoPreferenciaReserva DESC
            ,PRI.IDFatoPreferenciaReservaItens DESC
        OFFSET :offset ROWS
        FETCH NEXT :per_page ROWS ONLY;
    """)

    params_itens = dict(params)
    params_itens.update({
        "offset": offset,
        "per_page": per_page,
    })

    rows = db.session.execute(sql_itens, params_itens).mappings().all()

    itens = []
    for row in rows:
        item = dict(row)
        id_contrato = item.get("IDFatoControleContratosEuromidia")
        numero_contrato = str(item.get("NumeroContrato") or "").strip()
        numero_previa = str(item.get("NumeroPrevia") or "").strip()

        if numero_contrato:
            item["NumeroContratoExibicao"] = numero_contrato
        elif numero_previa:
            item["NumeroContratoExibicao"] = numero_previa
        elif id_contrato:
            item["NumeroContratoExibicao"] = f"Contrato {id_contrato}"
        else:
            item["NumeroContratoExibicao"] = "Sem contrato"

        item["TotalLiquidoContratoFormatado"] = _formatar_moeda_preferencia(item.get("TotalLiquidoContrato"))
        item["DataCriacaoFormatada"] = _formatar_data_preferencia(item.get("DataCriacao"), com_hora=True)
        item["DataInicioFormatada"] = _formatar_data_preferencia(item.get("DataInicio"), com_hora=False)
        item["DataTerminoFormatada"] = _formatar_data_preferencia(item.get("DataTermino"), com_hora=False)
        itens.append(item)

    vendedor_opcoes = []
    if usuario_tem_visao_total:
        try:
            rows_vendedores = db.session.execute(text("""
                SELECT DISTINCT
                     PR.IDVendedor
                    ,V.NomeVendedor
                FROM [Integracao].[Silver].[FatoPreferenciaReserva] AS PR
                INNER JOIN [Integracao].[Silver].[FatoPreferenciaReservaItens] AS PRI
                    ON PRI.IDFatoPreferenciaReserva = PR.IDFatoPreferenciaReserva
                LEFT JOIN [Integracao].[dbo].[Vendedores] AS V
                    ON V.IDVendedor = PR.IDVendedor
                WHERE ISNULL(PR.BitAtivo, 0) = 1
                  AND ISNULL(PRI.BitAtivo, 0) = 1
                  AND PR.IDVendedor IS NOT NULL
                  AND NULLIF(LTRIM(RTRIM(V.NomeVendedor)), '') IS NOT NULL
                ORDER BY V.NomeVendedor ASC;
            """)).mappings().all()

            for row in rows_vendedores:
                try:
                    id_vendedor = int(row.get("IDVendedor") or 0)
                except Exception:
                    id_vendedor = 0

                nome_vendedor = str(row.get("NomeVendedor") or "").strip()
                if id_vendedor <= 0 or not nome_vendedor:
                    continue

                vendedor_opcoes.append({
                    "IDVendedor": id_vendedor,
                    "NomeVendedor": nome_vendedor,
                })
        except Exception:
            current_app.logger.exception("Falha ao carregar vendedores da tela de preferências de reserva.")
            vendedor_opcoes = []

    pagina_inicio = max(1, page - 3)
    pagina_fim = min(total_pages, page + 3)
    paginas_visiveis = list(range(pagina_inicio, pagina_fim + 1))

    paginacao = {
        "page": page,
        "per_page": per_page,
        "total": total,
        "total_bruto": total_bruto,
        "total_pages": total_pages,
        "inicio": (offset + 1) if total > 0 else 0,
        "fim": min(offset + per_page, total) if total > 0 else 0,
        "tem_anterior": page > 1,
        "tem_proxima": page < total_pages,
        "limite_resultados": limite_resultados,
        "paginas_visiveis": paginas_visiveis,
    }

    return render_template(
        "euromidia/preferencia_reservas_lista.html",
        itens=itens,
        paginacao=paginacao,
        q=q,
        dt_ini=dt_ini,
        dt_fim=dt_fim,
        ano_periodo=ano_periodo,
        periodo_filtro_ativo=periodo_filtro_ativo,
        vendedor_opcoes=vendedor_opcoes,
        vendedores_ids_selecionados=vendedores_ids_selecionados,
        usuario_logado_eh_perfil_vendedor=usuario_eh_vendedor,
        usuario_logado_eh_perfil_admin=usuario_eh_admin,
        usuario_logado_eh_perfil_coordenador=usuario_eh_coordenador,
        usuario_tem_visao_total_preferencia_reserva=usuario_tem_visao_total,
        id_vendedor_logado=id_vendedor_logado,
    )






@paineis_bp.route("/api/ocupacao/calendario", methods=["GET"])
@login_required
def api_ocupacao_calendario():

    cod_face = (request.args.get("cod_face") or request.args.get("codface") or "").strip()
    cod_ponto = (request.args.get("cod_ponto") or request.args.get("codponto") or "").strip()
    mes_ref = (request.args.get("mes_ref") or "").strip()
    cota_raw = (request.args.get("cota") or "").strip()
    meses = request.args.get("meses", 24)

    try:
        meses = int(meses)
    except Exception:
        meses = 24
    meses = max(1, min(meses, 36))

    if not cod_face:
        return jsonify({"ok": False, "erro": "cod_face obrigatório"}), 400

    def _primeiro_dia_mes(valor_mes_ref: str) -> date:
        valor = str(valor_mes_ref or "").strip()
        if re.match(r"^\d{4}-\d{2}$", valor):
            try:
                ano, mes = valor.split("-", 1)
                return date(int(ano), int(mes), 1)
            except Exception:
                pass
        hoje = date.today()
        return date(hoje.year, hoje.month, 1)

    def _adicionar_meses(data_base: date, qtd_meses: int) -> date:
        mes_total = (data_base.month - 1) + int(qtd_meses or 0)
        ano = data_base.year + (mes_total // 12)
        mes = (mes_total % 12) + 1
        return date(ano, mes, 1)

    data_inicio_cal = _primeiro_dia_mes(mes_ref)
    data_fim_exclusivo = _adicionar_meses(data_inicio_cal, meses)
    data_fim_cal = data_fim_exclusivo - timedelta(days=1)

    sql_meta = text("""
        DECLARE @CodFace varchar(100) = :cod_face;
        DECLARE @CodPonto int = TRY_CONVERT(int, NULLIF(:cod_ponto, ''));

        IF @CodPonto IS NULL
        BEGIN
            SELECT TOP (1)
                @CodPonto = f.CodPonto
            FROM [Integracao].[Silver].[DimFacesPaineis] f
            WHERE LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), f.CodFace), ''))) = @CodFace
              AND f.CodPonto IS NOT NULL
            ORDER BY f.IDDimFacesPaineis DESC;
        END;

        SELECT TOP (1)
            CodPonto = COALESCE(f.CodPonto, p.CodPonto, @CodPonto),
            TipoPainel = UPPER(LTRIM(RTRIM(COALESCE(NULLIF(CONVERT(varchar(100), f.Tipo), ''), NULLIF(CONVERT(varchar(100), p.Tipo), ''), '')))),
            BitAtivo = COALESCE(p.BitAtivo, 1),
            EhDigital = CASE
                WHEN UPPER(LTRIM(RTRIM(COALESCE(NULLIF(CONVERT(varchar(100), f.Tipo), ''), NULLIF(CONVERT(varchar(100), p.Tipo), ''), '')))) LIKE '%DIGITAL%' THEN 1
                ELSE 0
            END,
            CapacidadeSlots = CASE
                WHEN UPPER(LTRIM(RTRIM(COALESCE(NULLIF(CONVERT(varchar(100), f.Tipo), ''), NULLIF(CONVERT(varchar(100), p.Tipo), ''), '')))) LIKE '%DIGITAL%'
                    THEN COALESCE(NULLIF(TRY_CONVERT(int, p.QuantidadeFaces), 0), :capacidade_padrao)
                ELSE 1
            END
        FROM [Integracao].[Silver].[DimFacesPaineis] f
        OUTER APPLY (
            SELECT TOP (1)
                p.CodPonto,
                p.Tipo,
                p.QuantidadeFaces,
                p.BitAtivo,
                p.DataAtualizacao,
                p.IDDimPaineisEuromidia
            FROM [Integracao].[Silver].[DimPaineisEuromidia] p
            WHERE p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia
               OR p.CodPonto = f.CodPonto
               OR p.CodPonto = @CodPonto
            ORDER BY
                CASE WHEN p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia THEN 0 ELSE 1 END,
                p.DataAtualizacao DESC,
                p.IDDimPaineisEuromidia DESC
        ) p
        WHERE LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), f.CodFace), ''))) = @CodFace
          AND (@CodPonto IS NULL OR f.CodPonto = @CodPonto)
        ORDER BY f.IDDimFacesPaineis DESC;
    """)

    meta = db.session.execute(
        sql_meta,
        {
            "cod_face": cod_face,
            "cod_ponto": cod_ponto,
            "capacidade_padrao": int(CAPACIDADE_DIGITAL_FIXA or 16),
        },
    ).mappings().first()

    if not meta:
        return jsonify({"ok": False, "erro": "CodFace/CodPonto não encontrado para montar o calendário."}), 404

    try:
        cod_ponto_resolvido = int(meta.get("CodPonto")) if meta.get("CodPonto") is not None else None
    except Exception:
        cod_ponto_resolvido = None

    tipo_painel = str(meta.get("TipoPainel") or "").strip()
    bit_ativo = int(meta.get("BitAtivo") or 0)
    eh_digital = int(meta.get("EhDigital") or 0)
    try:
        capacidade_slots = int(meta.get("CapacidadeSlots") or 0)
    except Exception:
        capacidade_slots = 0

    if eh_digital == 1:
        capacidade_slots = max(1, min(capacidade_slots or int(CAPACIDADE_DIGITAL_FIXA or 16), 200))
    else:
        capacidade_slots = 1

    span_solicitado = _span_por_cota_reserva_grade(cota_raw, None) if eh_digital == 1 else 1
    span_solicitado = max(1, min(int(span_solicitado or 1), capacidade_slots))

    dias_calendario = _datas_inclusivas_reserva(data_inicio_cal, data_fim_cal)
    ocupado: dict[date, set[int]] = {dia: set() for dia in dias_calendario}

    def _blocos_possiveis(span: int):
        return range(0, max(0, capacidade_slots - int(span) + 1))

    def _bloco_livre_no_dia(dia: date, indice: int, span: int) -> bool:
        slots_ocupados = ocupado.setdefault(dia, set())
        for off in range(int(span)):
            if (int(indice) + off) in slots_ocupados:
                return False
        return True

    def _bloco_livre_em_todos_os_dias(dias, indice: int, span: int) -> bool:
        for dia in dias:
            if not _bloco_livre_no_dia(dia, indice, span):
                return False
        return True

    def _blocos_livres_do_dia(dia: date, span: int):
        return [idx for idx in _blocos_possiveis(span) if _bloco_livre_no_dia(dia, idx, span)]

    def _escolher_bloco(blocos, preferido=None):
        blocos = list(blocos or [])
        if not blocos:
            return None
        if preferido is None:
            return int(blocos[0])
        try:
            pref = int(preferido)
        except Exception:
            pref = None
        if pref is None:
            return int(blocos[0])
        return int(sorted(blocos, key=lambda idx: (abs(int(idx) - pref), int(idx)))[0])

    def _montar_plano_intervalo(di, df, span, loop_inicio=None, loop_fim=None, permitir_forcar=False):
        if isinstance(di, datetime):
            di = di.date()
        if isinstance(df, datetime):
            df = df.date()
        if di is None or df is None or df < di:
            return {"ok": True, "plano": {}, "conflito": False, "dia_sem_espaco": None}

        ini_clip = max(di, data_inicio_cal)
        fim_clip = min(df, data_fim_cal)
        if fim_clip < ini_clip:
            return {"ok": True, "plano": {}, "conflito": False, "dia_sem_espaco": None}

        dias = _datas_inclusivas_reserva(ini_clip, fim_clip)
        span_int = max(1, min(int(span or 1), capacidade_slots))

        idx_exp = _slot_indice_grade_reserva(loop_inicio, capacidade_slots)
        idx_fim_exp = _slot_indice_grade_reserva(loop_fim, capacidade_slots)
        if idx_exp is not None:
            if idx_fim_exp is not None:
                largura_exp = (idx_fim_exp - idx_exp) + 1
                if largura_exp != span_int:
                    idx_exp = None
            if idx_exp is not None and (idx_exp + span_int - 1) >= capacidade_slots:
                idx_exp = None

        if idx_exp is not None:
            plano_exp = {dia: idx_exp for dia in dias}
            if _bloco_livre_em_todos_os_dias(dias, idx_exp, span_int):
                return {"ok": True, "plano": plano_exp, "conflito": False, "dia_sem_espaco": None}
            # Tetris: LoopInicio/LoopFim gravado no banco é só preferência visual.
            # Se aquele bloco já estiver ocupado, tento encaixar em outro bloco livre
            # antes de marcar conflito. Conflito só é permitido quando não existe
            # nenhum encaixe real dentro do range.

        for idx in _blocos_possiveis(span_int):
            if _bloco_livre_em_todos_os_dias(dias, idx, span_int):
                return {"ok": True, "plano": {dia: idx for dia in dias}, "conflito": False, "dia_sem_espaco": None}

        plano = {}
        preferido = None
        conflito = False
        for dia in dias:
            livres = _blocos_livres_do_dia(dia, span_int)
            escolhido = _escolher_bloco(livres, preferido)
            if escolhido is None:
                if not permitir_forcar:
                    return {"ok": False, "plano": plano, "conflito": False, "dia_sem_espaco": dia}
                escolhido = _escolher_bloco(_blocos_possiveis(span_int), preferido)
                conflito = True
            plano[dia] = int(escolhido)
            preferido = int(escolhido)

        return {"ok": True, "plano": plano, "conflito": conflito, "dia_sem_espaco": None}

    def _marcar_plano(plano_por_dia, span: int):
        for dia, idx in (plano_por_dia or {}).items():
            if dia not in ocupado:
                continue
            slots_ocupados = ocupado.setdefault(dia, set())
            for off in range(int(span)):
                pos = int(idx) + off
                if 0 <= pos < capacidade_slots:
                    slots_ocupados.add(pos)

    if bit_ativo == 1:
        if eh_digital == 1:
            sql_existentes = text("""
                SELECT
                     Origem = CAST('CONTRATO' AS varchar(20))
                    ,IDItem = o.IDFatoOcupacaoPaineisEuromidia
                    ,DataInicio = TRY_CONVERT(date, o.DataInicio)
                    ,DataFim = TRY_CONVERT(date, o.DataFim)
                    ,Cota = o.Cota
                    ,SpanQtd = TRY_CONVERT(int, o.SpanQtd)
                    ,LoopInicio = LTRIM(RTRIM(COALESCE(CONVERT(varchar(30), o.LoopInicio), '')))
                    ,LoopFim = LTRIM(RTRIM(COALESCE(CONVERT(varchar(30), o.LoopFim), '')))
                    ,OrdemData = COALESCE(TRY_CONVERT(datetime2, o.CriadoEm), TRY_CONVERT(datetime2, o.DataAtualizacao), SYSUTCDATETIME())
                FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] o WITH (NOLOCK)
                WHERE TRY_CONVERT(int, o.CodPonto) = :cod_ponto
                  AND LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.CodFace), ''))) = :cod_face
                  AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Origem), ''))))
                        COLLATE Latin1_General_CI_AI = 'CONTRATO'
                  AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Status), ''))))
                        COLLATE Latin1_General_CI_AI NOT IN ('CANCELADO', 'CANCELADA')
                  AND o.CanceladoEm IS NULL
                  AND TRY_CONVERT(date, o.DataInicio) IS NOT NULL
                  AND TRY_CONVERT(date, o.DataFim) IS NOT NULL
                  AND TRY_CONVERT(date, o.DataInicio) <= :data_fim
                  AND TRY_CONVERT(date, o.DataFim) >= :data_inicio

                UNION ALL

                SELECT
                     Origem = CAST('RESERVA' AS varchar(20))
                    ,IDItem = o.IDFatoOcupacaoPaineisEuromidia
                    ,DataInicio = TRY_CONVERT(date, o.DataInicio)
                    ,DataFim = TRY_CONVERT(date, o.DataFim)
                    ,Cota = o.Cota
                    ,SpanQtd = TRY_CONVERT(int, o.SpanQtd)
                    ,LoopInicio = LTRIM(RTRIM(COALESCE(CONVERT(varchar(30), o.LoopInicio), '')))
                    ,LoopFim = LTRIM(RTRIM(COALESCE(CONVERT(varchar(30), o.LoopFim), '')))
                    ,OrdemData = COALESCE(TRY_CONVERT(datetime2, o.CriadoEm), TRY_CONVERT(datetime2, o.DataAtualizacao), SYSUTCDATETIME())
                FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] o WITH (NOLOCK)
                WHERE o.CodPonto = :cod_ponto
                  AND LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.CodFace), ''))) = :cod_face
                  AND o.CanceladoEm IS NULL
                  -- Contratos também vêm de FatoOcupacao, mas no bloco anterior com Origem=CONTRATO.
                  -- Aqui entram somente reservas ativas. A separação por Origem evita duplicidade
                  -- e mantém uma única unidade física por IDFatoOcupacaoPaineisEuromidia.
                  AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Origem), '')))) = 'RESERVA'
                  AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Status), '')))) = 'RESERVADO'
                  AND TRY_CONVERT(date, o.DataInicio) IS NOT NULL
                  AND TRY_CONVERT(date, o.DataFim) IS NOT NULL
                  AND TRY_CONVERT(date, o.DataInicio) <= :data_fim
                  AND TRY_CONVERT(date, o.DataFim) >= :data_inicio
                ORDER BY DataInicio ASC, DataFim ASC, OrdemData ASC, IDItem ASC;
            """)
            rows_existentes = db.session.execute(
                sql_existentes,
                {
                    "cod_ponto": int(cod_ponto_resolvido or 0),
                    "cod_face": cod_face,
                    "data_inicio": data_inicio_cal,
                    "data_fim": data_fim_cal,
                },
            ).mappings().all()

            for row in rows_existentes or []:
                span_existente = _span_por_cota_reserva_grade(row.get("Cota"), row.get("SpanQtd"))
                span_existente = max(1, min(int(span_existente or 1), capacidade_slots))
                plano_existente = _montar_plano_intervalo(
                    row.get("DataInicio"),
                    row.get("DataFim"),
                    span_existente,
                    row.get("LoopInicio"),
                    row.get("LoopFim"),
                    permitir_forcar=True,
                )
                _marcar_plano(plano_existente.get("plano") or {}, span_existente)
        else:
            sql_existentes = text("""
                SELECT
                    DataInicio = TRY_CONVERT(date, o.DataInicio),
                    DataFim = TRY_CONVERT(date, o.DataFim)
                FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] o WITH (NOLOCK)
                WHERE o.CodPonto = :cod_ponto
                  AND LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.CodFace), ''))) = :cod_face
                  AND o.CanceladoEm IS NULL
                  AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Status), '')))) IN ('ATIVO', 'RESERVADO')
                  AND TRY_CONVERT(date, o.DataInicio) <= :data_fim
                  AND TRY_CONVERT(date, o.DataFim) >= :data_inicio;
            """)
            rows_existentes = db.session.execute(
                sql_existentes,
                {
                    "cod_ponto": int(cod_ponto_resolvido or 0),
                    "cod_face": cod_face,
                    "data_inicio": data_inicio_cal,
                    "data_fim": data_fim_cal,
                },
            ).mappings().all()
            for row in rows_existentes or []:
                plano_existente = _montar_plano_intervalo(
                    row.get("DataInicio"),
                    row.get("DataFim"),
                    1,
                    None,
                    None,
                    permitir_forcar=True,
                )
                _marcar_plano(plano_existente.get("plano") or {}, 1)

    def _max_bloco_livre(slots_ocupados: set[int]) -> int:
        maior = 0
        atual = 0
        for idx in range(capacidade_slots):
            if idx in slots_ocupados:
                maior = max(maior, atual)
                atual = 0
            else:
                atual += 1
        return max(maior, atual)

    cal = {}
    for dia in dias_calendario:
        slots_ocupados_set = ocupado.get(dia, set())
        slots_ocupados = len(slots_ocupados_set)
        slots_disponiveis = max(0, capacidade_slots - slots_ocupados)
        max_bloco_livre = _max_bloco_livre(slots_ocupados_set)

        if bit_ativo == 0:
            dia_disponivel = 0
            status = "INDISPONIVEL"
            disp_cota = 0
        elif eh_digital == 0:
            dia_disponivel = 1 if slots_ocupados == 0 else 0
            status = "DISPONIVEL" if dia_disponivel else "OCUPADO"
            disp_cota = 1 if dia_disponivel else 0
        else:
            dia_disponivel = 1 if max_bloco_livre >= span_solicitado else 0
            disp_cota = span_solicitado if dia_disponivel else 0
            if slots_ocupados <= 0:
                status = "LIVRE"
            elif dia_disponivel:
                status = "PARCIAL"
            else:
                status = "CHEIO"

        pct = None
        if capacidade_slots > 0:
            pct = round(float(slots_ocupados) * 100.0 / float(capacidade_slots), 2)

        chave = dia.strftime("%Y-%m-%d")
        cal[chave] = {
            "status": status,
            "disp": int(slots_disponiveis),
            "disponiveis": int(slots_disponiveis),
            "disp_cota": int(disp_cota),
            "disponiveis_cota": int(disp_cota),
            "max_bloco_livre": int(max_bloco_livre),
            "span_necessario": int(span_solicitado),
            "cap": int(capacidade_slots),
            "ocup": int(slots_ocupados),
            "pct": pct,
            "dia_disponivel": int(dia_disponivel),
            "eh_digital": int(eh_digital),
            "codponto": int(cod_ponto_resolvido) if cod_ponto_resolvido is not None else None,
            "tipo": tipo_painel,
        }

    return jsonify({
        "ok": True,
        "cal": cal,
        "capacidade_total": int(capacidade_slots),
        "span_necessario": int(span_solicitado),
        "eh_digital": int(eh_digital),
        "codponto": int(cod_ponto_resolvido) if cod_ponto_resolvido is not None else None,
    })




@paineis_bp.route("/api/ocupacao/reserva/dados-modal", methods=["GET"])
@login_required
def api_ocupacao_reserva_dados_modal():

    cod_face = (request.args.get("cod_face") or request.args.get("codface") or "").strip()
    cod_ponto = (request.args.get("cod_ponto") or request.args.get("codponto") or "").strip()
    mes_ref = (request.args.get("mes_ref") or "").strip()
    cota = (request.args.get("cota") or "").strip()

    # A pesquisa de empresas é feita diretamente no SQL Server.
    # Isso evita depender de carregar toda a DimEmpresas no navegador.
    q_empresa = (
        request.args.get("q_empresa")
        or request.args.get("q_cliente")
        or ""
    ).strip()[:160]
    somente_empresas = (
        str(request.args.get("somente_empresas") or "").strip().lower()
        in {"1", "true", "sim", "yes"}
    )
    q_empresa_cnpj = re.sub(r"\D+", "", q_empresa)[:14]
    q_empresa_tem_letras = bool(re.search(r"[^\W\d_]", q_empresa, flags=re.UNICODE))

    dt_ini = (request.args.get("dt_ini") or "").strip()
    dt_fim = (request.args.get("dt_fim") or "").strip()

    def executar_primeiro_sql_que_funciona(lista_sql, params):
        for sql_txt in lista_sql:
            try:
                rows = db.session.execute(text(sql_txt), params).all()
                return [dict(r._mapping) for r in rows]
            except Exception:
                continue
        return []

    def formatar_prefixo_cnpj_reserva(digitos: str) -> str:
        """Formata também CNPJ parcial sem aplicar função na coluna do banco."""
        valor = re.sub(r"\D+", "", str(digitos or ""))[:14]
        if len(valor) <= 2:
            return valor
        if len(valor) <= 5:
            return f"{valor[:2]}.{valor[2:]}"
        if len(valor) <= 8:
            return f"{valor[:2]}.{valor[2:5]}.{valor[5:]}"
        if len(valor) <= 12:
            return f"{valor[:2]}.{valor[2:5]}.{valor[5:8]}/{valor[8:]}"
        return f"{valor[:2]}.{valor[2:5]}.{valor[5:8]}/{valor[8:12]}-{valor[12:]}"

    sql_colunas_empresas = """
        e.IDEmpresa,
        RazaoSocial = NULLIF(LTRIM(RTRIM(e.RazaoSocial)), ''),
        NomeFantasia = NULLIF(LTRIM(RTRIM(e.NomeFantasia)), ''),
        Nome = COALESCE(
            NULLIF(LTRIM(RTRIM(e.RazaoSocial)), ''),
            NULLIF(LTRIM(RTRIM(e.NomeFantasia)), ''),
            CONCAT('Empresa ', CONVERT(varchar(30), e.IDEmpresa))
        ),
        CNPJ = NULLIF(LTRIM(RTRIM(e.CNPJ)), '')
    """

    def executar_busca_empresas(sql_txt: str, parametros: dict) -> list[dict]:
        return [
            dict(row)
            for row in db.session.execute(text(sql_txt), parametros).mappings().all()
        ]

    # O termo compõe apenas a chave; o hash evita expor CNPJ/nome no backend
    # compartilhado de cache. Não há IDEmpresaProprietaria na consulta nem na chave.
    tipo_busca_empresa = (
        "cnpj"
        if q_empresa_cnpj and not q_empresa_tem_letras
        else ("nome" if q_empresa else "inicial")
    )
    cache_termo_empresa = q_empresa.casefold()
    cache_hash_empresa = hashlib.sha256(
        cache_termo_empresa.encode("utf-8", errors="ignore")
    ).hexdigest()
    cache_key_empresas = (
        f"reserva:busca_empresas:v4:{tipo_busca_empresa}:{cache_hash_empresa}"
    )
    empresas = _cache_get_seguro_paineis(cache_key_empresas, padrao=None)

    if empresas is None:
        if tipo_busca_empresa == "cnpj":
            # Comparação direta e prefixada: ao contrário do REPLACE/CAST anterior,
            # o SQL Server pode fazer seek em índice da coluna CNPJ. Aceito tanto
            # armazenamento puro (30908417000118) quanto mascarado.
            cnpj_mascarado = formatar_prefixo_cnpj_reserva(q_empresa_cnpj)
            busca_cnpj_completa = len(q_empresa_cnpj) == 14
            operador_cnpj = "=" if busca_cnpj_completa else "LIKE"
            sufixo_cnpj = "" if busca_cnpj_completa else "%"

            # Primeiro consulto o padrão sem máscara, que é o formato utilizado
            # atualmente pela DimEmpresas. Só faço a segunda consulta se for
            # necessário atender uma base legada que tenha pontuação.
            sql_empresas_cnpj = f"""
                SELECT TOP (50)
                    {sql_colunas_empresas}
                FROM [Integracao].[Silver].[DimEmpresas] AS e WITH (NOLOCK)
                WHERE e.IDEmpresa IS NOT NULL
                  AND e.CNPJ IS NOT NULL
                  AND e.CNPJ {operador_cnpj} CONVERT(varchar(33), :cnpj_busca)
                ORDER BY e.IDEmpresa ASC
                OPTION (RECOMPILE);
            """
            empresas = executar_busca_empresas(
                sql_empresas_cnpj,
                {"cnpj_busca": f"{q_empresa_cnpj}{sufixo_cnpj}"},
            )
            if not empresas and cnpj_mascarado != q_empresa_cnpj:
                empresas = executar_busca_empresas(
                    sql_empresas_cnpj,
                    {"cnpj_busca": f"{cnpj_mascarado}{sufixo_cnpj}"},
                )

        elif tipo_busca_empresa == "nome":
            params_empresas = {
                "nome_exato": q_empresa,
                "nome_prefixo": f"{q_empresa}%",
                "nome_contem": f"%{q_empresa}%",
            }
            sql_empresas_prefixo = f"""
                SELECT TOP (50)
                    {sql_colunas_empresas}
                FROM [Integracao].[Silver].[DimEmpresas] AS e WITH (NOLOCK)
                WHERE e.IDEmpresa IS NOT NULL
                  AND (
                        e.RazaoSocial LIKE :nome_prefixo COLLATE Latin1_General_CI_AI
                     OR e.NomeFantasia LIKE :nome_prefixo COLLATE Latin1_General_CI_AI
                  )
                ORDER BY
                    CASE
                        WHEN e.RazaoSocial = :nome_exato COLLATE Latin1_General_CI_AI THEN 0
                        WHEN e.NomeFantasia = :nome_exato COLLATE Latin1_General_CI_AI THEN 1
                        WHEN e.RazaoSocial LIKE :nome_prefixo COLLATE Latin1_General_CI_AI THEN 2
                        ELSE 3
                    END,
                    e.IDEmpresa ASC
                OPTION (RECOMPILE);
            """
            empresas = executar_busca_empresas(sql_empresas_prefixo, params_empresas)

            # Mantém a busca por palavra no meio do nome, mas só paga o custo do
            # "%termo%" quando a busca indexável por prefixo não encontrou nada.
            if not empresas:
                sql_empresas_contem = f"""
                    SELECT TOP (50)
                        {sql_colunas_empresas}
                    FROM [Integracao].[Silver].[DimEmpresas] AS e WITH (NOLOCK)
                    WHERE e.IDEmpresa IS NOT NULL
                      AND (
                            e.RazaoSocial LIKE :nome_contem COLLATE Latin1_General_CI_AI
                         OR e.NomeFantasia LIKE :nome_contem COLLATE Latin1_General_CI_AI
                      )
                    ORDER BY e.IDEmpresa ASC
                    OPTION (RECOMPILE);
                """
                empresas = executar_busca_empresas(
                    sql_empresas_contem,
                    params_empresas,
                )

        else:
            # Abertura do modal: uma amostra pequena e determinística, sem ordenar
            # milhões de empresas por razão social.
            sql_empresas_iniciais = f"""
                SELECT TOP (50)
                    {sql_colunas_empresas}
                FROM [Integracao].[Silver].[DimEmpresas] AS e WITH (NOLOCK)
                WHERE e.IDEmpresa IS NOT NULL
                ORDER BY e.IDEmpresa DESC;
            """
            empresas = executar_busca_empresas(sql_empresas_iniciais, {})

        _cache_set_seguro_paineis(
            cache_key_empresas,
            empresas,
            timeout_segundos=120,
        )

    # Nas pesquisas feitas enquanto o usuário digita, devolvo apenas empresas.
    # Assim a tela não recalcula ocupações, contratos e vendedores a cada tecla.
    if somente_empresas:
        return jsonify({
            "ok": True,
            "empresas": empresas,
            "clientes": empresas,
        })

    sql_ocupacoes = """
        SELECT
            IDFatoOcupacaoPaineisEuromidia,
            CodFace,
            Status,
            CONVERT(varchar(10), DataInicio, 23) AS DataInicio,
            CONVERT(varchar(10), DataFim, 23) AS DataFim,
            ISNULL(Cota,0) AS Cota,
            MarcaExibida,
            Vendedor
        FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
        WHERE CodFace = :cod_face
          AND (:cod_ponto IS NULL OR :cod_ponto = '' OR CodPonto = :cod_ponto)
          AND CanceladoEm IS NULL
          AND Status IN ('ATIVO','RESERVADO')
        ORDER BY DataInicio
    """
    ocupacoes = [
        dict(r._mapping)
        for r in db.session.execute(
            text(sql_ocupacoes),
            {"cod_face": cod_face, "cod_ponto": cod_ponto},
        )
    ]

    sqls_vendedores = [
        """
        SELECT DISTINCT
            IDVendedor,
            NomeVendedor
        FROM [Integracao].[dbo].[Vendedores]
        WHERE ISNULL(TRY_CONVERT(int, BitAtivo), 0) = 1
          AND NULLIF(LTRIM(RTRIM(COALESCE(NomeVendedor, ''))), '') IS NOT NULL
        ORDER BY NomeVendedor
        """
    ]
    vendedores = executar_primeiro_sql_que_funciona(sqls_vendedores, {})

    if not cod_face:
        return jsonify({
            "ok": True,
            "empresas": empresas,
            "clientes": empresas,
            "vendedores": vendedores,
            "contratos": [],
            "ocupacoes": [],
        })

    params_contratos = {
        "cod_ponto": cod_ponto,
        "dt_ini": dt_ini,
        "dt_fim": dt_fim,
        "mes_ref": mes_ref,
        "cota": cota
    }

 

    sqls_contratos = [
        # ✅ 1) PRIORIDADE: pelo ITENS (tem CodPonto) e JOIN no HEADER pra pegar RazaoSocial correta
        """
        SELECT DISTINCT
            IDContrato = COALESCE(i.IDFatoControleContratoEuromidia, h.IDFatoControleContratosEuromidia),
            IDFatoControleContratosEuromidia = COALESCE(i.IDFatoControleContratoEuromidia, h.IDFatoControleContratosEuromidia),
            NumeroContrato = NULLIF(LTRIM(RTRIM(CAST(COALESCE(h.NumeroContrato, i.NumeroContrato) AS varchar(50)))), ''),
            NumeroPrevia   = NULLIF(LTRIM(RTRIM(CAST(COALESCE(h.NumeroPrevia,   i.NumeroPrevia)   AS varchar(50)))), ''),
            RazaoSocial    = NULLIF(LTRIM(RTRIM(COALESCE(h.RazaoSocial, i.RazaoSocial))), ''),
            CNPJ           = NULLIF(LTRIM(RTRIM(CAST(COALESCE(h.CNPJ, i.CNPJ) AS varchar(30)))), ''),
            IDEmpresa      = COALESCE(h.IDEmpresa, i.IDEmpresa)
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        LEFT JOIN [Integracao].[Silver].[FatoControleContratosEuromidia] h
               ON h.IDFatoControleContratosEuromidia = i.IDFatoControleContratoEuromidia
        WHERE
            (NULLIF(:cod_ponto,'') IS NULL OR i.CodPonto = :cod_ponto)
        ORDER BY
            NULLIF(LTRIM(RTRIM(CAST(COALESCE(h.NumeroContrato, i.NumeroContrato) AS varchar(50)))), ''),
            NULLIF(LTRIM(RTRIM(CAST(COALESCE(h.NumeroPrevia,   i.NumeroPrevia)   AS varchar(50)))), '')
        """,

        # ✅ 2) fallback: header puro (SEM filtro por cod_ponto porque não existe CodPonto no header)
        """
        SELECT DISTINCT
            IDContrato = IDFatoControleContratosEuromidia,
            IDFatoControleContratosEuromidia,
            NumeroContrato = NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
            NumeroPrevia   = NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia   AS varchar(50)))), ''),
            RazaoSocial    = NULLIF(LTRIM(RTRIM(RazaoSocial)), ''),
            CNPJ           = NULLIF(LTRIM(RTRIM(CAST(CNPJ AS varchar(30)))), ''),
            IDEmpresa
        FROM [Integracao].[Silver].[FatoControleContratosEuromidia]
        ORDER BY
            NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
            NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia   AS varchar(50)))), '')
        """,

        # ✅ 3) fallback: itens puro (se por algum motivo o JOIN falhar)
        """
        SELECT DISTINCT
            IDContrato = IDFatoControleContratosItensEuromidia,
            CAST(NULL AS int) AS IDFatoControleContratosEuromidia,
            NumeroContrato = NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
            NumeroPrevia   = NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia   AS varchar(50)))), ''),
            RazaoSocial    = NULLIF(LTRIM(RTRIM(COALESCE(RazaoSocial,''))), ''),
            CNPJ           = NULLIF(LTRIM(RTRIM(CAST(CNPJ AS varchar(30)))), ''),
            IDEmpresa
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia]
        WHERE (NULLIF(:cod_ponto,'') IS NULL OR CodPonto = :cod_ponto)
        ORDER BY
            NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
            NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia   AS varchar(50)))), '')
        """,

        # ✅ 4) fallback: tabela antiga FatoControleContratos (se existir/for usada)
        """
        SELECT DISTINCT
            IDContrato,
            CAST(NULL AS int) AS IDFatoControleContratosEuromidia,
            NumeroContrato = NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
            NumeroPrevia   = NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia   AS varchar(50)))), ''),
            RazaoSocial    = NULLIF(LTRIM(RTRIM(COALESCE(RazaoSocial,''))), ''),
            CNPJ           = NULLIF(LTRIM(RTRIM(CAST(CNPJ AS varchar(30)))), ''),
            IDEmpresa
        FROM [Integracao].[Silver].[FatoControleContratos]
        WHERE (NULLIF(:cod_ponto,'') IS NULL OR CodPonto = :cod_ponto)
        ORDER BY
            NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
            NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia   AS varchar(50)))), '')
        """,
    ]

    contratos = executar_primeiro_sql_que_funciona(sqls_contratos, params_contratos)

    if not contratos:
        sql_contratos_fallback = """
            SELECT DISTINCT
                IDContrato = COALESCE(
                    NULLIF(LTRIM(RTRIM(CAST(IDFatoControleContratos AS varchar(50)))), ''),
                    NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
                    CONCAT('C:', CONVERT(varchar(10), MIN(DataInicio), 23), '|', CONVERT(varchar(10), MAX(DataFim), 23))
                ),
                IDFatoControleContratosEuromidia = IDFatoControleContratos,
                NumeroContrato = NULLIF(LTRIM(RTRIM(CAST(NumeroContrato AS varchar(50)))), ''),
                NumeroPrevia = NULLIF(LTRIM(RTRIM(CAST(NumeroPrevia AS varchar(50)))), ''),
                RazaoSocial = CAST('' AS varchar(200)),
                CNPJ = CAST('' AS varchar(30)),
                IDEmpresa = IDCliente
            FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
            WHERE CodFace = :cod_face
              AND (:cod_ponto IS NULL OR :cod_ponto = '' OR CodPonto = :cod_ponto)
              AND CanceladoEm IS NULL
              AND Status IN ('ATIVO','RESERVADO')
              AND (NumeroContrato IS NOT NULL OR NumeroPrevia IS NOT NULL OR IDFatoControleContratos IS NOT NULL)
            GROUP BY IDFatoControleContratos, NumeroContrato, NumeroPrevia, IDCliente
            ORDER BY NumeroContrato, NumeroPrevia
        """
        contratos = [dict(r._mapping) for r in db.session.execute(text(sql_contratos_fallback), {"cod_face": cod_face, "cod_ponto": cod_ponto})]

        for c in contratos:
            if not (str(c.get("IDContrato") or "").strip()):
                nc = str(c.get("NumeroContrato") or "").strip()
                np = str(c.get("NumeroPrevia") or "").strip()
                c["IDContrato"] = (nc + "-" + np).strip("-") or "sem-id"

    return jsonify({
        "ok": True,
        "empresas": empresas,
        "vendedores": vendedores,
        "contratos": contratos,
        "ocupacoes": ocupacoes,
    })





def _parse_data_reserva_yyyy_mm_dd(valor: str):
    """Eu converto data YYYY-MM-DD de reserva em date com validação simples."""
    texto = str(valor or "").strip()
    if not texto:
        return None

    try:
        return datetime.strptime(texto, "%Y-%m-%d").date()
    except Exception:
        return None


RESERVA_VALIDADE_HORAS_UTEIS = 48
RESERVA_CALENDARIO_UF_PADRAO = "SP"
RESERVA_CALENDARIO_MUNICIPIO_PADRAO = "VALINHOS"
RESERVA_FUSO_HORARIO_PADRAO = "America/Sao_Paulo"


def _config_calendario_reserva(nome: str, padrao=None):
    """Lê a configuração do calendário no Flask e, depois, no ambiente."""
    valor = None

    try:
        valor = current_app.config.get(nome)
    except Exception:
        valor = None

    if valor in (None, ""):
        try:
            valor = os.getenv(nome)
        except Exception:
            valor = None

    return padrao if valor in (None, "") else valor


def _agora_campinas_reserva() -> datetime:
    """
    Retorna o horário civil de Campinas/São Paulo sem depender do timezone
    configurado no servidor, no container ou no SQL Server.

    A tabela atual usa datetime2 (sem offset). Por isso, depois de converter o
    instante para America/Sao_Paulo, removo apenas a informação de timezone e
    preservo os valores locais que serão gravados em CriadoEm e ExpiraEm.
    """
    nome_fuso = str(
        _config_calendario_reserva(
            "RESERVA_FUSO_HORARIO",
            RESERVA_FUSO_HORARIO_PADRAO,
        )
        or RESERVA_FUSO_HORARIO_PADRAO
    ).strip()

    try:
        agora_local = datetime.now(ZoneInfo(nome_fuso))
    except Exception as exc:
        raise RuntimeError(
            f"Não foi possível carregar o fuso horário da reserva: {nome_fuso}"
        ) from exc

    return agora_local.replace(tzinfo=None, microsecond=0)


def _buscar_datas_feriados_reserva(data_inicial: date, data_final: date) -> set[date]:
    """
    Busca os dias que realmente interrompem a contagem da reserva.

    São considerados somente registros ativos, marcados como feriado e que não
    estejam liberados explicitamente por ConsiderarComoDiaUtil. O calendário
    corporativo usa feriados nacionais, do estado configurado e do município
    configurado. Assim, faces de cidades diferentes continuam com um único
    prazo comercial de bloqueio.
    """
    uf = str(
        _config_calendario_reserva(
            "RESERVA_CALENDARIO_FERIADOS_UF",
            RESERVA_CALENDARIO_UF_PADRAO,
        )
        or ""
    ).strip().upper()
    municipio = str(
        _config_calendario_reserva(
            "RESERVA_CALENDARIO_FERIADOS_MUNICIPIO",
            RESERVA_CALENDARIO_MUNICIPIO_PADRAO,
        )
        or ""
    ).strip().upper()

    codigo_ibge_raw = _config_calendario_reserva(
        "RESERVA_CALENDARIO_FERIADOS_CODIGO_IBGE",
        None,
    )
    try:
        codigo_ibge = int(codigo_ibge_raw) if codigo_ibge_raw not in (None, "") else 0
    except Exception:
        codigo_ibge = 0

    sql = text("""
        SELECT DISTINCT
            DataFeriado = TRY_CONVERT(date, f.DataFeriado)
        FROM [Integracao].[Silver].[FatoFeriados] AS f
        WHERE TRY_CONVERT(date, f.DataFeriado) BETWEEN :data_inicial AND :data_final
          AND ISNULL(TRY_CONVERT(int, f.Ativo), 0) = 1
          AND ISNULL(TRY_CONVERT(int, f.EhFeriado), 0) = 1
          AND ISNULL(TRY_CONVERT(int, f.ConsiderarComoDiaUtil), 0) = 0
          AND (
                -- Feriado nacional/federal declarado pelo tipo ou abrangência.
                UPPER(LTRIM(RTRIM(COALESCE(f.TipoFeriado, '')))) LIKE '%NACION%'
             OR UPPER(LTRIM(RTRIM(COALESCE(f.Abrangencia, '')))) LIKE '%NACION%'
             OR UPPER(LTRIM(RTRIM(COALESCE(f.TipoFeriado, '')))) LIKE '%FEDERAL%'
             OR UPPER(LTRIM(RTRIM(COALESCE(f.Abrangencia, '')))) LIKE '%FEDERAL%'

                -- Registro geral sem UF, município ou código IBGE.
             OR (
                    NULLIF(LTRIM(RTRIM(COALESCE(f.UF, ''))), '') IS NULL
                AND NULLIF(LTRIM(RTRIM(COALESCE(f.Municipio, ''))), '') IS NULL
                AND TRY_CONVERT(bigint, f.CodigoIBGE) IS NULL
                )

                -- Feriado estadual da UF do calendário corporativo.
             OR (
                    :uf <> ''
                AND UPPER(LTRIM(RTRIM(COALESCE(f.UF, '')))) = :uf
                AND (
                       UPPER(LTRIM(RTRIM(COALESCE(f.TipoFeriado, '')))) LIKE '%ESTAD%'
                    OR UPPER(LTRIM(RTRIM(COALESCE(f.Abrangencia, '')))) LIKE '%ESTAD%'
                    OR (
                           NULLIF(LTRIM(RTRIM(COALESCE(f.Municipio, ''))), '') IS NULL
                       AND TRY_CONVERT(bigint, f.CodigoIBGE) IS NULL
                       )
                    )
                )

                -- Feriado municipal identificado pelo código IBGE configurado.
             OR (
                    :codigo_ibge > 0
                AND TRY_CONVERT(bigint, f.CodigoIBGE) = :codigo_ibge
                )

                -- Feriado municipal identificado pelo nome do município.
             OR (
                    :municipio <> ''
                AND UPPER(LTRIM(RTRIM(COALESCE(f.Municipio, '')))) = :municipio
                AND (
                       :uf = ''
                    OR NULLIF(LTRIM(RTRIM(COALESCE(f.UF, ''))), '') IS NULL
                    OR UPPER(LTRIM(RTRIM(COALESCE(f.UF, '')))) = :uf
                    )
                )
          );
    """)

    rows = db.session.execute(sql, {
        "data_inicial": data_inicial,
        "data_final": data_final,
        "uf": uf,
        "municipio": municipio,
        "codigo_ibge": codigo_ibge,
    }).fetchall()

    datas = set()
    for row in rows:
        valor = row[0] if row else None
        if isinstance(valor, datetime):
            valor = valor.date()
        if isinstance(valor, date):
            datas.add(valor)

    return datas


def _somar_horas_uteis_calendario_reserva(
    data_base: datetime,
    horas_uteis: int,
    datas_feriados: set[date] | None = None,
) -> datetime:
    """
    Soma horas úteis de 24 horas, interrompendo totalmente a contagem em
    sábados, domingos e feriados.

    Não existe uma janela comercial de 8 horas neste processo: uma segunda-feira
    útil possui 24 horas contáveis. Essa é a regra que mantém 48 horas úteis como
    dois dias úteis no mesmo horário quando a criação ocorre em um dia útil.
    """
    if not isinstance(data_base, datetime):
        raise TypeError("data_base da reserva deve ser datetime")

    try:
        horas_restantes = int(horas_uteis or 0)
    except Exception as exc:
        raise ValueError("horas_uteis da reserva deve ser um número inteiro") from exc

    if horas_restantes < 0:
        raise ValueError("horas_uteis da reserva não pode ser negativo")
    if horas_restantes == 0:
        return data_base

    feriados = set(datas_feriados or set())
    restante = timedelta(hours=horas_restantes)
    atual = data_base

    # Limite defensivo: 370 dias é muito superior ao necessário para somar
    # 48 horas úteis e impede loop infinito se o calendário estiver corrompido.
    limite = data_base + timedelta(days=370)

    while restante > timedelta(0):
        if atual > limite:
            raise RuntimeError("Não foi possível calcular 48 horas úteis dentro de 370 dias")

        data_atual = atual.date()
        inicio_dia_seguinte = datetime.combine(
            data_atual + timedelta(days=1),
            datetime.min.time(),
        )

        if atual.weekday() >= 5 or data_atual in feriados:
            atual = inicio_dia_seguinte
            continue

        tempo_util_disponivel = inicio_dia_seguinte - atual
        if restante <= tempo_util_disponivel:
            return atual + restante

        restante -= tempo_util_disponivel
        atual = inicio_dia_seguinte

    return atual


def _calcular_expiracao_reserva_48_horas_uteis(data_base: datetime | None = None) -> tuple[datetime, datetime]:
    """
    Retorna (CriadoEm, ExpiraEm) no fuso de Campinas/São Paulo e usando a tabela
    de feriados. O mesmo par é reutilizado em todas as faces e segmentos do POST.
    """
    criado_em = data_base
    if criado_em is None:
        criado_em = _agora_campinas_reserva()

    if not isinstance(criado_em, datetime):
        raise RuntimeError("Não foi possível obter uma data válida para a reserva")

    data_final_consulta = criado_em.date() + timedelta(days=370)
    feriados = _buscar_datas_feriados_reserva(criado_em.date(), data_final_consulta)
    expira_em = _somar_horas_uteis_calendario_reserva(
        criado_em,
        RESERVA_VALIDADE_HORAS_UTEIS,
        feriados,
    )
    return criado_em, expira_em


def _montar_contexto_contador_horas_uteis_grade() -> dict:
    """
    Entrega ao JavaScript da grade o mesmo calendário usado para criar o
    ExpiraEm. A hora usa explicitamente America/Sao_Paulo para o contador não
    depender do relógio do servidor, do SQL Server ou do computador do usuário.

    Se o calendário não puder ser consultado, a grade recebe o indicador de
    indisponibilidade e não exibe um número de horas corridas como se fosse útil.
    """
    agora_campinas = None

    try:
        agora_campinas = _agora_campinas_reserva()
    except Exception:
        current_app.logger.exception(
            "RESERVA_GRADE | falha ao obter a hora de Campinas/São Paulo para o contador"
        )

    if not isinstance(agora_campinas, datetime):
        return {
            "agora_servidor_reserva_iso": "",
            "feriados_reserva_iso": [],
            "calendario_reserva_disponivel": False,
        }

    try:
        data_final_consulta = agora_campinas.date() + timedelta(days=370)
        datas_feriados = _buscar_datas_feriados_reserva(
            agora_campinas.date(),
            data_final_consulta,
        )

        return {
            "agora_servidor_reserva_iso": agora_campinas.strftime("%Y-%m-%dT%H:%M:%S"),
            "feriados_reserva_iso": sorted(
                data_feriado.strftime("%Y-%m-%d")
                for data_feriado in datas_feriados
            ),
            "calendario_reserva_disponivel": True,
        }
    except Exception:
        current_app.logger.exception(
            "RESERVA_GRADE | falha ao consultar FatoFeriados para o contador de horas úteis"
        )
        return {
            "agora_servidor_reserva_iso": agora_campinas.strftime("%Y-%m-%dT%H:%M:%S"),
            "feriados_reserva_iso": [],
            "calendario_reserva_disponivel": False,
        }




def _config_reserva_email_valor(nome_config: str, nome_env: str | None = None, padrao=None):
    """Lê configuração de e-mail priorizando current_app.config e depois variáveis de ambiente."""
    valor = None

    try:
        valor = current_app.config.get(nome_config)
    except Exception:
        valor = None

    if valor in (None, ""):
        try:
            valor = os.getenv(nome_env or nome_config)
        except Exception:
            valor = None

    if valor in (None, ""):
        return padrao

    return valor


def _email_reserva_tem_formato_minimo(email: str) -> bool:
    texto = str(email or "").strip()
    if not texto or len(texto) > 254:
        return False
    return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", texto))



def _email_reserva_normalizar_ids(ids_fato_ocupacao) -> list[int]:
    """Normaliza um ID ou uma lista de IDs de ocupação/reserva."""
    if ids_fato_ocupacao is None:
        return []

    if isinstance(ids_fato_ocupacao, (list, tuple, set)):
        fonte = list(ids_fato_ocupacao)
    else:
        fonte = [ids_fato_ocupacao]

    ids: list[int] = []
    vistos = set()
    for item in fonte:
        try:
            valor = int(item or 0)
        except Exception:
            valor = 0
        if valor > 0 and valor not in vistos:
            ids.append(valor)
            vistos.add(valor)

    return ids


def _email_reserva_texto_seguro(valor, padrao: str = "-") -> str:
    texto = str(valor or "").strip()
    return texto if texto else padrao


def _email_reserva_html(valor, padrao: str = "-") -> str:
    return str(html_escape(_email_reserva_texto_seguro(valor, padrao)))


def _email_reserva_formatar_data(valor, incluir_hora: bool = False, padrao: str = "-") -> str:
    if valor in (None, ""):
        return padrao

    dt = None

    if isinstance(valor, datetime):
        dt = valor
    elif isinstance(valor, date):
        dt = datetime(valor.year, valor.month, valor.day)
    else:
        texto = str(valor or "").strip()
        if not texto:
            return padrao

        tentativas = [
            "%Y-%m-%d %H:%M:%S.%f",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%dT%H:%M:%S.%f",
            "%Y-%m-%dT%H:%M:%S",
            "%Y-%m-%d",
            "%d/%m/%Y %H:%M:%S",
            "%d/%m/%Y %H:%M",
            "%d/%m/%Y",
        ]
        for fmt in tentativas:
            try:
                dt = datetime.strptime(texto[:26], fmt)
                break
            except Exception:
                pass

        if dt is None:
            try:
                dt = datetime.fromisoformat(texto.replace("Z", ""))
            except Exception:
                return texto

    if incluir_hora:
        return dt.strftime("%d/%m/%Y - %H:%M")
    return dt.strftime("%d/%m/%Y")


def _buscar_dados_email_confirmacao_reserva(ids_fato_ocupacao) -> dict:
    """
    Busca os dados reais gravados da reserva para montar o e-mail de confirmação.

    Regra principal:
    - o número exibido da reserva é o IDFatoOcupacaoPaineisEuromidia;
    - os dados comerciais vêm de Integracao.Silver.FatoOcupacaoPaineisEuromidia;
    - os dados de ponto/endereço vêm de DimFacesPaineis + DimPaineisEuromidia;
    - quando a reserva foi quebrada em vários segmentos, o e-mail lista todas as linhas criadas.

    Regra de destinatário:
    - primeiro tenta o usuário vinculado ao vendedor da reserva;
    - se não existir, tenta o usuário que criou a reserva;
    - se não houver e-mail válido, o envio é ignorado com log.
    """
    ids_ocupacao = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    if not ids_ocupacao:
        return {}

    sql = text("""
        SELECT
             IDReserva = o.IDFatoOcupacaoPaineisEuromidia
            ,IDDimUsuariosDestinatario = COALESCE(
                u_vendedor.IDDimUsuarios,
                u_criador.IDDimUsuarios,
                o.CriadoPorIDUsuario
             )
            ,IDDimUsuariosVendedor = u_vendedor.IDDimUsuarios
            ,IDDimUsuariosCriador = u_criador.IDDimUsuarios
            ,IDUsuarioCriacaoRaw = o.CriadoPorIDUsuario
            ,IDFatoControleContratosEuromidia = o.IDFatoControleContratos
            ,IDFatoControleContratosItensEuromidia = CONVERT(int, NULL)
            ,IDCliente = o.IDCliente
            ,IDVendedorReserva = o.IDVendedor
            ,EmailUsuario = COALESCE(
                NULLIF(LTRIM(RTRIM(u_vendedor.Email)), ''),
                NULLIF(LTRIM(RTRIM(u_criador.Email)), '')
             )
            ,NomeUsuario = COALESCE(
                NULLIF(LTRIM(RTRIM(u_vendedor.NomeUsuario)), ''),
                NULLIF(LTRIM(RTRIM(u_criador.NomeUsuario)), ''),
                NULLIF(LTRIM(RTRIM(o.Vendedor)), ''),
                NULLIF(LTRIM(RTRIM(v.NomeVendedor)), ''),
                'Usuário'
             )
            ,Vendedor = COALESCE(
                NULLIF(LTRIM(RTRIM(u_vendedor.NomeUsuario)), ''),
                NULLIF(LTRIM(RTRIM(u_criador.NomeUsuario)), ''),
                NULLIF(LTRIM(RTRIM(o.Vendedor)), ''),
                NULLIF(LTRIM(RTRIM(v.NomeVendedor)), ''),
                'Usuário'
             )
            ,NomeEmpresa = COALESCE(
                NULLIF(LTRIM(RTRIM(emp.RazaoSocial)), ''),
                NULLIF(LTRIM(RTRIM(emp.NomeFantasia)), ''),
                CONCAT('IDCliente ', CONVERT(varchar(20), o.IDCliente))
             )
            ,MarcaExibida = NULLIF(LTRIM(RTRIM(o.MarcaExibida)), '')
            ,CodPonto = NULLIF(LTRIM(RTRIM(CAST(o.CodPonto AS varchar(50)))), '')
            ,CodFace = COALESCE(
                NULLIF(LTRIM(RTRIM(CAST(face.CodFace AS varchar(50)))), ''),
                NULLIF(LTRIM(RTRIM(CAST(o.CodFace AS varchar(50)))), '')
             )
            ,Cota = NULLIF(LTRIM(RTRIM(CAST(o.Cota AS varchar(50)))), '')
            ,DataInicio = o.DataInicio
            ,DataFim = o.DataFim
            ,ExpiraEm = o.ExpiraEm
            ,CriadoEm = o.CriadoEm
            ,Face = NULLIF(LTRIM(RTRIM(CAST(face.Face AS varchar(50)))), '')
            ,Logradouro = NULLIF(LTRIM(RTRIM(painel.Logradouro)), '')
            ,Bairro = NULLIF(LTRIM(RTRIM(painel.Bairro)), '')
            ,Cidade = NULLIF(LTRIM(RTRIM(painel.Cidade)), '')
            ,UF = NULLIF(LTRIM(RTRIM(painel.UF)), '')
            ,ReferenciaPainel = NULLIF(LTRIM(RTRIM(painel.Referencia)), '')
        FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] AS o WITH (NOLOCK)
        OUTER APPLY (
            SELECT TOP (1)
                 f.IDDimFacesPaineis
                ,f.Face
                ,f.CodFace
                ,f.IDDimPaineisEuromidia
            FROM [Integracao].[Silver].[DimFacesPaineis] AS f WITH (NOLOCK)
            WHERE NULLIF(LTRIM(RTRIM(CAST(f.CodPonto AS varchar(50)))), '') = NULLIF(LTRIM(RTRIM(CAST(o.CodPonto AS varchar(50)))), '')
              AND (
                    NULLIF(LTRIM(RTRIM(CAST(f.CodFace AS varchar(50)))), '') = NULLIF(LTRIM(RTRIM(CAST(o.CodFace AS varchar(50)))), '')
                 OR NULLIF(LTRIM(RTRIM(CAST(f.Face    AS varchar(50)))), '') = NULLIF(LTRIM(RTRIM(CAST(o.CodFace AS varchar(50)))), '')
              )
            ORDER BY
                CASE
                    WHEN NULLIF(LTRIM(RTRIM(CAST(f.CodFace AS varchar(50)))), '') = NULLIF(LTRIM(RTRIM(CAST(o.CodFace AS varchar(50)))), '') THEN 0
                    ELSE 1
                END,
                f.IDDimFacesPaineis
        ) AS face
        OUTER APPLY (
            SELECT TOP (1)
                 p.IDDimPaineisEuromidia
                ,p.CodPonto
                ,p.Logradouro
                ,p.Bairro
                ,p.Cidade
                ,p.UF
                ,p.Referencia
                ,p.BitAtivo
            FROM [Integracao].[Silver].[DimPaineisEuromidia] AS p WITH (NOLOCK)
            WHERE (
                    face.IDDimPaineisEuromidia IS NOT NULL
                AND p.IDDimPaineisEuromidia = face.IDDimPaineisEuromidia
            )
               OR NULLIF(LTRIM(RTRIM(CAST(p.CodPonto AS varchar(50)))), '') = NULLIF(LTRIM(RTRIM(CAST(o.CodPonto AS varchar(50)))), '')
            ORDER BY
                CASE
                    WHEN face.IDDimPaineisEuromidia IS NOT NULL
                     AND p.IDDimPaineisEuromidia = face.IDDimPaineisEuromidia THEN 0
                    ELSE 1
                END,
                ISNULL(TRY_CONVERT(int, p.BitAtivo), 0) DESC,
                p.IDDimPaineisEuromidia
        ) AS painel
        LEFT JOIN [Integracao].[dbo].[Vendedores] AS v WITH (NOLOCK)
            ON v.IDVendedor = o.IDVendedor
        LEFT JOIN [Integracao].[Silver].[DimUsuarios] AS u_vendedor WITH (NOLOCK)
            ON u_vendedor.IDDimUsuarios = v.IDDimUsuarios
        LEFT JOIN [Integracao].[Silver].[DimUsuarios] AS u_criador WITH (NOLOCK)
            ON u_criador.IDDimUsuarios = o.CriadoPorIDUsuario
        LEFT JOIN [Integracao].[Silver].[DimEmpresas] AS emp WITH (NOLOCK)
            ON emp.IDEmpresa = o.IDCliente
        WHERE o.IDFatoOcupacaoPaineisEuromidia IN :ids_ocupacao
        ORDER BY
             o.IDFatoOcupacaoPaineisEuromidia
            ,o.DataInicio
            ,o.DataFim
            ,o.CodFace;
    """).bindparams(bindparam("ids_ocupacao", expanding=True))

    rows = db.session.execute(sql, {"ids_ocupacao": ids_ocupacao}).mappings().all()
    linhas = [dict(row or {}) for row in rows]
    if not linhas:
        return {}

    resultado = dict(linhas[0])
    resultado["LinhasReserva"] = linhas
    resultado["IDsConsulta"] = ids_ocupacao
    return resultado


RESERVA_EMAIL_COPIA_CONTRATOS = "contratos@euromidia.com.br"
RESERVA_NOTIFICACAO_ORIGEM = "RESERVA"
RESERVA_NOTIFICACAO_TIPO_EVENTO = "CONFIRMACAO DE RESERVA"
RESERVA_NOTIFICACAO_SISTEMA_ORIGEM = "PAINEIS EUROMIDIA"
RESERVA_NOTIFICACAO_MODULO_ORIGEM = "RESERVAS"
RESERVA_NOTIFICACAO_TIPO_REFERENCIA = "RESERVA"


def _registrar_fato_notificacao_email_reserva(
    *,
    dados: dict,
    ids_reserva,
    destinatario: str,
    destinatario_copia: str,
    assunto: str,
    corpo_html: str,
    corpo_texto: str,
    bit_enviado: bool,
    erro_envio: str | None = None,
) -> dict:
    """
    Registra o resultado do envio na Integracao.Silver.FatoNotificacoes.

    É gravada uma linha por ID de reserva. Dessa forma, um único e-mail agrupado
    continua vinculado individualmente a cada linha da
    FatoOcupacaoPaineisEuromidia por TipoReferencia + IDReferencia.

    A ChaveIdempotencia é determinística por reserva e evento. Se a mesma
    confirmação for processada novamente, o registro existente é atualizado
    em vez de gerar outra linha lógica para a mesma notificação.
    """
    ids_normalizados = _email_reserva_normalizar_ids(ids_reserva)
    if not ids_normalizados:
        return {"registrado": False, "motivo": "ids_reserva_invalidos"}

    try:
        id_usuario_destino = int(dados.get("IDDimUsuariosDestinatario") or 0) or None
    except Exception:
        id_usuario_destino = None

    data_email = datetime.now(ZoneInfo("America/Sao_Paulo")).replace(tzinfo=None)
    erro_envio_texto = str(erro_envio or "").strip()[:1000] or None
    bit_enviado_int = 1 if bit_enviado else 0

    sql_registrar = text("""
        SET NOCOUNT ON;

        IF EXISTS
        (
            SELECT 1
            FROM [Integracao].[Silver].[FatoNotificacoes] WITH (UPDLOCK, HOLDLOCK)
            WHERE ChaveIdempotencia = :chave_idempotencia
        )
        BEGIN
            UPDATE [Integracao].[Silver].[FatoNotificacoes]
               SET Origem = :origem,
                   TipoEvendo = :tipo_evento,
                   IDUsuarioDestino = :id_usuario_destino,
                   EmailDestino = :email_destino,
                   EmailCopia = :email_copia,
                   SistemaOrigem = :sistema_origem,
                   ModuloOrigem = :modulo_origem,
                   TipoReferencia = :tipo_referencia,
                   IDReferencia = :id_referencia,
                   Assunto = :assunto,
                   CorpoEmail = :corpo_email,
                   CorpoTexto = :corpo_texto,
                   PayloadJson = :payload_json,
                   BitEnviado = :bit_enviado,
                   DataEmail = :data_email
             WHERE ChaveIdempotencia = :chave_idempotencia;
        END
        ELSE
        BEGIN
            INSERT INTO [Integracao].[Silver].[FatoNotificacoes]
            (
                Origem,
                TipoEvendo,
                IDUsuarioDestino,
                EmailDestino,
                EmailCopia,
                ChaveIdempotencia,
                SistemaOrigem,
                ModuloOrigem,
                TipoReferencia,
                IDReferencia,
                Assunto,
                CorpoEmail,
                CorpoTexto,
                PayloadJson,
                BitEnviado,
                DataEmail
            )
            VALUES
            (
                :origem,
                :tipo_evento,
                :id_usuario_destino,
                :email_destino,
                :email_copia,
                :chave_idempotencia,
                :sistema_origem,
                :modulo_origem,
                :tipo_referencia,
                :id_referencia,
                :assunto,
                :corpo_email,
                :corpo_texto,
                :payload_json,
                :bit_enviado,
                :data_email
            );
        END;

        SELECT TOP (1)
            IDFatoNotificacoes
        FROM [Integracao].[Silver].[FatoNotificacoes] WITH (NOLOCK)
        WHERE ChaveIdempotencia = :chave_idempotencia
        ORDER BY IDFatoNotificacoes DESC;
    """)

    ids_fato_notificacoes = []

    try:
        for id_reserva in ids_normalizados:
            chave_idempotencia = (
                f"{RESERVA_NOTIFICACAO_SISTEMA_ORIGEM}|"
                f"{RESERVA_NOTIFICACAO_MODULO_ORIGEM}|"
                f"{RESERVA_NOTIFICACAO_TIPO_EVENTO}|{id_reserva}"
            )[:300]

            payload = {
                "Origem": RESERVA_NOTIFICACAO_ORIGEM,
                "TipoEvento": RESERVA_NOTIFICACAO_TIPO_EVENTO,
                "SistemaOrigem": RESERVA_NOTIFICACAO_SISTEMA_ORIGEM,
                "ModuloOrigem": RESERVA_NOTIFICACAO_MODULO_ORIGEM,
                "TipoReferencia": RESERVA_NOTIFICACAO_TIPO_REFERENCIA,
                "IDReferencia": id_reserva,
                "IDsReservaEmail": ids_normalizados,
                "IDUsuarioDestino": id_usuario_destino,
                "EmailDestino": destinatario,
                "EmailCopia": destinatario_copia,
                "BitEnviado": bool(bit_enviado),
                "ErroEnvio": erro_envio_texto,
                "DataEmail": data_email.isoformat(timespec="seconds"),
            }

            row = db.session.execute(
                sql_registrar,
                {
                    "origem": RESERVA_NOTIFICACAO_ORIGEM,
                    "tipo_evento": RESERVA_NOTIFICACAO_TIPO_EVENTO,
                    "id_usuario_destino": id_usuario_destino,
                    "email_destino": str(destinatario or "").strip() or None,
                    "email_copia": str(destinatario_copia or "").strip() or None,
                    "chave_idempotencia": chave_idempotencia,
                    "sistema_origem": RESERVA_NOTIFICACAO_SISTEMA_ORIGEM,
                    "modulo_origem": RESERVA_NOTIFICACAO_MODULO_ORIGEM,
                    "tipo_referencia": RESERVA_NOTIFICACAO_TIPO_REFERENCIA,
                    "id_referencia": int(id_reserva),
                    "assunto": str(assunto or "")[:1000],
                    "corpo_email": str(corpo_html or ""),
                    "corpo_texto": str(corpo_texto or ""),
                    "payload_json": json.dumps(
                        payload,
                        ensure_ascii=False,
                        separators=(",", ":"),
                        default=str,
                    ),
                    "bit_enviado": bit_enviado_int,
                    "data_email": data_email,
                },
            ).mappings().first()

            if row and row.get("IDFatoNotificacoes") is not None:
                ids_fato_notificacoes.append(int(row["IDFatoNotificacoes"]))

        db.session.commit()

        current_app.logger.info(
            "RESERVA_EMAIL_NOTIFICACAO | registro concluído | ids_reserva=%s | ids_notificacoes=%s | enviado=%s | destinatario=%s | copia=%s",
            ids_normalizados,
            ids_fato_notificacoes,
            bit_enviado_int,
            destinatario,
            destinatario_copia,
        )

        return {
            "registrado": True,
            "motivo": None,
            "ids_reserva": ids_normalizados,
            "ids_fato_notificacoes": ids_fato_notificacoes,
            "bit_enviado": bool(bit_enviado),
        }

    except Exception as exc:
        db.session.rollback()
        current_app.logger.exception(
            "RESERVA_EMAIL_NOTIFICACAO | falha ao registrar FatoNotificacoes | ids_reserva=%s | enviado=%s",
            ids_normalizados,
            bit_enviado_int,
        )
        return {
            "registrado": False,
            "motivo": str(exc)[:300],
            "ids_reserva": ids_normalizados,
            "bit_enviado": bool(bit_enviado),
        }


def _enviar_email_confirmacao_reserva_por_id(ids_fato_ocupacao) -> dict:
    """Envia confirmação da reserva por SMTP usando as variáveis do .env já existentes."""
    ids_ocupacao = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    dados = _buscar_dados_email_confirmacao_reserva(ids_ocupacao)
    if not dados:
        return {"enviado": False, "motivo": "dados_reserva_nao_encontrados"}

    destinatario = str(dados.get("EmailUsuario") or "").strip()
    destinatario_copia = RESERVA_EMAIL_COPIA_CONTRATOS
    ids_log = ",".join(str(x) for x in ids_ocupacao) if ids_ocupacao else str(ids_fato_ocupacao or "")
    if not _email_reserva_tem_formato_minimo(destinatario):
        current_app.logger.warning(
            "RESERVA_EMAIL | e-mail do usuário não encontrado ou inválido | ids_reserva=%s",
            ids_log,
        )
        return {"enviado": False, "motivo": "email_destinatario_invalido"}

    # IMPORTANTE:
    # O projeto já usa dotenv/env_file. Portanto a configuração oficial aqui é
    # exatamente a que você informou no .env: SENHA_EMAIL, SMTP, porta e criptografia.
    smtp_host = str(
        _config_reserva_email_valor("SMTP", "SMTP", None)
        or "smtp.office365.com"
    ).strip()

    smtp_port_raw = (
        _config_reserva_email_valor("porta", "porta", None)
        or 587
    )

    criptografia = str(
        _config_reserva_email_valor("criptografia", "criptografia", None)
        or "STARTTLS"
    ).strip().upper()

    smtp_user = "notificacoes@euromidia.com.br"
    smtp_password = _config_reserva_email_valor("SENHA_EMAIL", "SENHA_EMAIL", None)
    remetente = smtp_user
    remetente_nome = "Euromídia"

    try:
        smtp_port = int(str(smtp_port_raw or "587").strip())
    except Exception:
        smtp_port = 587

    if not smtp_host or not smtp_user or not smtp_password or not remetente:
        current_app.logger.warning(
            "RESERVA_EMAIL | configuração SMTP incompleta. "
            "Verifique SENHA_EMAIL, SMTP, porta e criptografia no .env. "
            "smtp_host=%s | smtp_port=%s | criptografia=%s | smtp_user_configurado=%s | senha_configurada=%s",
            smtp_host or "VAZIO",
            smtp_port,
            criptografia or "VAZIO",
            "sim" if bool(smtp_user) else "nao",
            "sim" if bool(smtp_password) else "nao",
        )
        return {"enviado": False, "motivo": "smtp_config_incompleta"}

    linhas_reserva = dados.get("LinhasReserva") or [dados]
    linhas_email = []
    for linha in linhas_reserva:
        linha_dict = dict(linha or {})
        expira_em = linha_dict.get("ExpiraEm")
        if not expira_em:
            current_app.logger.error(
                "RESERVA_EMAIL | ExpiraEm não foi gravado; o e-mail não recalculará um prazo divergente | id_reserva=%s",
                linha_dict.get("IDReserva"),
            )
        linha_dict["FimBloqueioFormatado"] = _email_reserva_formatar_data(expira_em, incluir_hora=True)
        linha_dict["DataInicioFormatada"] = _email_reserva_formatar_data(linha_dict.get("DataInicio"), incluir_hora=False)
        linha_dict["DataFimFormatada"] = _email_reserva_formatar_data(linha_dict.get("DataFim"), incluir_hora=False)
        linhas_email.append(linha_dict)

    ids_reserva = []
    vistos_reserva = set()
    for linha in linhas_email:
        valor = _email_reserva_texto_seguro(linha.get("IDReserva"), "")
        if valor and valor not in vistos_reserva:
            ids_reserva.append(valor)
            vistos_reserva.add(valor)

    ids_reserva_texto = ", ".join(ids_reserva) if ids_reserva else ids_log
    ids_reserva_assunto = "/".join(ids_reserva) if ids_reserva else ids_log.replace(",", "/")
    nome_usuario = str(dados.get("NomeUsuario") or "Usuário").strip() or "Usuário"
    vendedor_assunto = str(dados.get("Vendedor") or nome_usuario or "Usuário").strip() or "Usuário"

    if len(ids_reserva) > 1:
        frase_abertura = f"Olá, {nome_usuario}, suas reservas números {ids_reserva_texto} foram confirmadas."
    else:
        frase_abertura = f"Olá, {nome_usuario}, sua reserva número {ids_reserva_texto} foi confirmada."

    assunto = f'{vendedor_assunto} - Reserva {ids_reserva_assunto} realizada com sucesso'[:180]

    cabecalhos_texto = [
        "NÚMERO DA RESERVA",
        "VENDEDOR",
        "CÓDIGO FACE",
        "COTA",
        "DATA INÍCIO CAMPANHA",
        "DATA FIM CAMPANHA",
        "MARCA",
        "FIM DO BLOQUEIO",
    ]

    linhas_texto = ["\t".join(cabecalhos_texto)]
    for linha in linhas_email:
        linhas_texto.append("\t".join([
            _email_reserva_texto_seguro(linha.get("IDReserva")),
            _email_reserva_texto_seguro(linha.get("Vendedor")),
            _email_reserva_texto_seguro(linha.get("CodFace")),
            _email_reserva_texto_seguro(linha.get("Cota")),
            _email_reserva_texto_seguro(linha.get("DataInicioFormatada")),
            _email_reserva_texto_seguro(linha.get("DataFimFormatada")),
            _email_reserva_texto_seguro(linha.get("MarcaExibida")),
            _email_reserva_texto_seguro(linha.get("FimBloqueioFormatado")),
        ]))

    corpo = (
        f"{frase_abertura}\n\n"
        "Confira os detalhes:\n\n"
        + "\n".join(linhas_texto)
        + "\n\nAvisos Importantes:\n\n"
        "Esta Reserva será expirada automaticamente dentro do prazo limite.\n"
        "A Venda só será efetivada e aprovada após o envio dos documentos oficiais.\n"
    )

    logo_cid = "euromidia_logo"
    # ATENÇÃO:
    # Pelo docker-compose, o Flask NÃO enxerga diretamente o caminho do host:
    # /home/euromidia/projetos/pipelines/FlaskApp/app/static/imagens/logoeuro.png
    # O volume está montado assim:
    # ./FlaskApp/app/static:/app/app/static
    # Portanto, dentro do container flask-app, o caminho correto do logo é:
    # /app/app/static/imagens/logoeuro.png
    logo_path = "/app/app/static/imagens/logoeuro.png"
    logo_bytes = None
    logo_subtype = "png"
    logo_path_usado = None

    candidatos_logo = []
    for candidato in (
        os.getenv("EMAIL_RESERVA_LOGO_PATH"),
        "/app/app/static/imagens/logoeuro.png",
        str(Path(current_app.root_path) / "static" / "imagens" / "logoeuro.png"),
        str(Path(current_app.static_folder or "") / "imagens" / "logoeuro.png"),
        "/home/euromidia/projetos/pipelines/FlaskApp/app/static/imagens/logoeuro.png",
        "/home/guilherme_correa/PythonJobs/pipelines/FlaskApp/app/static/imagens/logoeuro.png",
    ):
        candidato = str(candidato or "").strip()
        if candidato and candidato not in candidatos_logo:
            candidatos_logo.append(candidato)

    for candidato in candidatos_logo:
        try:
            logo_path_obj = Path(candidato)
            if logo_path_obj.is_file():
                logo_bytes = logo_path_obj.read_bytes()
                logo_path_usado = candidato
                mime_type, _ = mimetypes.guess_type(str(logo_path_obj))
                if mime_type and "/" in mime_type:
                    logo_subtype = mime_type.split("/", 1)[1].lower() or "png"
                break
        except Exception:
            current_app.logger.exception(
                "RESERVA_EMAIL | falha ao tentar carregar logo | caminho=%s",
                candidato,
            )

    logo_url_publica = ""
    try:
        logo_url_publica = url_for(
            "static",
            filename="imagens/logoeuro.png",
            _external=True,
        )
    except Exception:
        logo_url_publica = "/static/imagens/logoeuro.png"

    if logo_bytes:
        current_app.logger.info(
            "RESERVA_EMAIL | logo Euromidia carregado inline | caminho=%s | bytes=%s",
            logo_path_usado,
            len(logo_bytes),
        )
        logo_html = (
            f'<img src="cid:{logo_cid}" alt="Euromídia Comunicação" '
            'width="190" style="display:block;width:190px;max-width:190px;height:auto;border:0;outline:none;text-decoration:none;margin-left:auto;">'
        )
    else:
        # Não volto mais para o texto "EUROMÍDIA COMUNICAÇÃO". Se o arquivo não existir
        # dentro do container, tento carregar a imagem pela URL pública do static.
        current_app.logger.warning(
            "RESERVA_EMAIL | logo Euromidia não encontrado nos caminhos=%s | usando url=%s",
            candidatos_logo,
            logo_url_publica,
        )
        logo_html = (
            f'<img src="{html_escape(logo_url_publica)}" alt="Euromídia Comunicação" '
            'width="190" style="display:block;width:190px;max-width:190px;height:auto;border:0;outline:none;text-decoration:none;margin-left:auto;">'
        )

    linhas_html = []
    for idx, linha in enumerate(linhas_email):
        bg = "#FFFFFF" if idx % 2 == 0 else "#FAFBFF"
        linhas_html.append(f"""
            <tr style="background:{bg};">
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;font-weight:700;color:#1D2433;white-space:nowrap;">{_email_reserva_html(linha.get('IDReserva'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;color:#1D2433;white-space:nowrap;">{_email_reserva_html(linha.get('Vendedor'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;font-weight:700;color:#1D2433;white-space:nowrap;">{_email_reserva_html(linha.get('CodFace'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;color:#1D2433;text-align:center;white-space:nowrap;">{_email_reserva_html(linha.get('Cota'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;color:#1D2433;text-align:center;white-space:nowrap;">{_email_reserva_html(linha.get('DataInicioFormatada'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;color:#1D2433;text-align:center;white-space:nowrap;">{_email_reserva_html(linha.get('DataFimFormatada'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;color:#1D2433;white-space:nowrap;">{_email_reserva_html(linha.get('MarcaExibida'))}</td>
                <td style="padding:14px 12px;border-bottom:1px solid #E8ECF5;font-size:12px;line-height:1.35;color:#CF1F2E;font-weight:800;text-align:center;white-space:nowrap;">{_email_reserva_html(linha.get('FimBloqueioFormatado'))}</td>
            </tr>
        """)

    corpo_html = f"""
    <!doctype html>
    <html lang="pt-BR">
    <head>
        <meta charset="utf-8">
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <title>{_email_reserva_html(assunto)}</title>
    </head>
    <body style="margin:0;padding:0;background:#F2F4F8;font-family:Arial,Helvetica,sans-serif;color:#1D2433;">
        <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;background:#F2F4F8;border-collapse:collapse;margin:0;padding:0;">
            <tr>
                <td align="center" style="padding:28px 14px;">
                    <table role="presentation" cellpadding="0" cellspacing="0" width="860" style="width:860px;max-width:860px;background:#FFFFFF;border-collapse:separate;border-spacing:0;border:1px solid #E6EAF2;box-shadow:0 10px 28px rgba(10,22,70,0.10);">
                        <tr>
                            <td style="height:12px;background:#FFD000;border-radius:14px 14px 0 0;font-size:0;line-height:0;">&nbsp;</td>
                        </tr>
                        <tr>
                            <td style="background:#0B0C8F;padding:30px 42px 28px 42px;">
                                <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;border-collapse:collapse;">
                                    <tr>
                                        <td align="left" valign="middle" style="width:62%;">
                                            <div style="font-size:30px;line-height:1.05;color:#FFFFFF;font-weight:900;letter-spacing:-0.7px;">Reserva Confirmada</div>
                                            <div style="font-size:12px;line-height:1.4;color:#FFFFFF;font-weight:700;margin-top:6px;opacity:.95;">Bloqueio Registrado com Validade de 48h úteis.</div>
                                        </td>
                                        <td align="right" valign="middle" style="width:38%;">
                                            {logo_html}
                                        </td>
                                    </tr>
                                </table>
                            </td>
                        </tr>

                        <tr>
                            <td style="padding:26px 36px 0 36px;">
                                <p style="font-size:14px;line-height:1.6;margin:0 0 20px 0;color:#1D2433;">
                                    {_email_reserva_html(frase_abertura, '')}
                                </p>
                                <p style="font-size:12px;line-height:1.6;margin:0;color:#4F5B6B;">
                                    Confira os detalhes da reserva abaixo:
                                </p>
                            </td>
                        </tr>

                        <tr>
                            <td style="padding:18px 36px 22px 36px;">
                                <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;border-collapse:separate;border-spacing:0;border:1px solid #E7EBF3;border-radius:12px;overflow:hidden;font-size:12px;">
                                    <thead>
                                        <tr style="background:#4B4BDB;color:#FFFFFF;">
                                            <th style="padding:12px 10px;text-align:left;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Número da Reserva</th>
                                            <th style="padding:12px 10px;text-align:left;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Vendedor</th>
                                            <th style="padding:12px 10px;text-align:left;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Código Face</th>
                                            <th style="padding:12px 10px;text-align:center;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Cota</th>
                                            <th style="padding:12px 10px;text-align:center;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Data Início Campanha</th>
                                            <th style="padding:12px 10px;text-align:center;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Data Fim Campanha</th>
                                            <th style="padding:12px 10px;text-align:left;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Marca</th>
                                            <th style="padding:12px 10px;text-align:center;font-size:10px;line-height:1.2;letter-spacing:.2px;text-transform:uppercase;font-weight:800;white-space:nowrap;">Fim do Bloqueio</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {''.join(linhas_html)}
                                    </tbody>
                                </table>
                            </td>
                        </tr>

                        <tr>
                            <td style="padding:0 36px 24px 36px;">
                                <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;border-collapse:separate;border-spacing:0;background:#FFF1F3;border-radius:10px;overflow:hidden;">
                                    <tr>
                                        <td style="width:6px;background:#E0202D;font-size:0;line-height:0;">&nbsp;</td>
                                        <td style="padding:17px 18px 16px 18px;">
                                            <div style="font-size:14px;font-weight:900;color:#991B1B;margin-bottom:8px;">Avisos importantes</div>
                                            <div style="font-size:12px;line-height:1.65;color:#7F1D1D;">
                                                Esta Reserva será expirada automaticamente dentro do prazo limite.<br>
                                                A Venda só será efetivada e aprovada após o envio dos documentos oficiais.
                                            </div>
                                        </td>
                                    </tr>
                                </table>
                            </td>
                        </tr>

                        <tr>
                            <td style="padding:0 0 0 0;">
                                <table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="width:100%;border-collapse:collapse;background:#F8FAFE;border-top:1px solid #E5E9F1;">
                                    <tr>
                                        <td style="padding:18px 36px;color:#647084;font-size:11px;line-height:1.5;">
                                            Mensagem automática do sistema de reservas Euromídia. Não responda este e-mail.
                                        </td>
                                    </tr>
                                </table>
                            </td>
                        </tr>
                    </table>
                </td>
            </tr>
        </table>
    </body>
    </html>
    """

    msg = EmailMessage()
    msg["Subject"] = assunto
    msg["From"] = f"{remetente_nome} <{remetente}>"
    msg["To"] = destinatario
    msg["Cc"] = destinatario_copia
    msg.set_content(corpo)
    msg.add_alternative(corpo_html, subtype="html")

    if logo_bytes:
        try:
            html_part = msg.get_payload()[-1]
            html_part.add_related(
                logo_bytes,
                maintype="image",
                subtype=logo_subtype,
                cid=f"<{logo_cid}>",
                filename="logoeuro.png",
            )
        except Exception:
            current_app.logger.exception(
                "RESERVA_EMAIL | falha ao anexar logo inline no e-mail | caminho=%s",
                logo_path,
            )

    try:
        current_app.logger.info(
            "RESERVA_EMAIL | tentando enviar confirmação | ids_reserva=%s | destinatario=%s | copia=%s | smtp_host=%s | smtp_port=%s | criptografia=%s",
            ids_log,
            destinatario,
            destinatario_copia,
            smtp_host,
            smtp_port,
            criptografia,
        )

        if criptografia in {"SSL", "TLS", "SMTPS"}:
            with smtplib.SMTP_SSL(smtp_host, smtp_port, timeout=20) as smtp:
                smtp.login(smtp_user, smtp_password)
                smtp.send_message(
                    msg,
                    from_addr=remetente,
                    to_addrs=[destinatario, destinatario_copia],
                )
        else:
            with smtplib.SMTP(smtp_host, smtp_port, timeout=20) as smtp:
                smtp.ehlo()
                if criptografia in {"STARTTLS", "START_TLS", "TLS_STARTTLS"}:
                    smtp.starttls()
                    smtp.ehlo()
                smtp.login(smtp_user, smtp_password)
                smtp.send_message(
                    msg,
                    from_addr=remetente,
                    to_addrs=[destinatario, destinatario_copia],
                )

        current_app.logger.info(
            "RESERVA_EMAIL | confirmação enviada | ids_reserva=%s | destinatario=%s | copia=%s",
            ids_log,
            destinatario,
            destinatario_copia,
        )
        registro_notificacao = _registrar_fato_notificacao_email_reserva(
            dados=dados,
            ids_reserva=ids_ocupacao,
            destinatario=destinatario,
            destinatario_copia=destinatario_copia,
            assunto=assunto,
            corpo_html=corpo_html,
            corpo_texto=corpo,
            bit_enviado=True,
        )
        return {
            "enviado": True,
            "motivo": None,
            "destinatario": destinatario,
            "copia": destinatario_copia,
            "registro_notificacao": registro_notificacao,
        }

    except Exception as exc:
        motivo_erro = str(exc)[:300]
        current_app.logger.exception(
            "RESERVA_EMAIL | falha ao enviar confirmação | ids_reserva=%s | destinatario=%s | copia=%s",
            ids_log,
            destinatario,
            destinatario_copia,
        )
        registro_notificacao = _registrar_fato_notificacao_email_reserva(
            dados=dados,
            ids_reserva=ids_ocupacao,
            destinatario=destinatario,
            destinatario_copia=destinatario_copia,
            assunto=assunto,
            corpo_html=corpo_html,
            corpo_texto=corpo,
            bit_enviado=False,
            erro_envio=motivo_erro,
        )
        return {
            "enviado": False,
            "motivo": motivo_erro,
            "destinatario": destinatario,
            "copia": destinatario_copia,
            "registro_notificacao": registro_notificacao,
        }




RESERVA_NOTIFICACAO_MARKER = "__EUROMIDIA_RESERVA_CONFIRMADA_JSON__"


def _notificacao_reserva_int_ou_none(valor):
    try:
        if valor is None or str(valor).strip() == "":
            return None
        valor_int = int(valor)
        return valor_int if valor_int > 0 else None
    except Exception:
        return None


def _notificacao_reserva_montar_payload(dados: dict) -> dict:
    """
    Monta o payload estruturado da notificação de reserva confirmada.

    A notificação usa a mesma base de dados do e-mail, mas guarda um JSON no final
    do TextoMensagem para a tela /admin/mensagens renderizar uma tabela segura,
    sem depender de HTML vindo do banco.
    """
    linhas_reserva = dados.get("LinhasReserva") or [dados]
    linhas_payload = []

    ids_reserva = []
    vistos_reserva = set()

    for linha in linhas_reserva:
        linha_dict = dict(linha or {})

        expira_em = linha_dict.get("ExpiraEm")
        if not expira_em:
            current_app.logger.error(
                "RESERVA_NOTIFICACAO | ExpiraEm não foi gravado; a notificação não recalculará um prazo divergente | id_reserva=%s",
                linha_dict.get("IDReserva"),
            )

        id_reserva_texto = _email_reserva_texto_seguro(linha_dict.get("IDReserva"), "")
        if id_reserva_texto and id_reserva_texto not in vistos_reserva:
            ids_reserva.append(id_reserva_texto)
            vistos_reserva.add(id_reserva_texto)

        linhas_payload.append({
            "numero_reserva": _email_reserva_texto_seguro(linha_dict.get("IDReserva")),
            "vendedor": _email_reserva_texto_seguro(linha_dict.get("Vendedor")),
            "cod_face": _email_reserva_texto_seguro(linha_dict.get("CodFace")),
            "cota": _email_reserva_texto_seguro(linha_dict.get("Cota")),
            "data_inicio": _email_reserva_formatar_data(linha_dict.get("DataInicio"), incluir_hora=False),
            "data_fim": _email_reserva_formatar_data(linha_dict.get("DataFim"), incluir_hora=False),
            "marca": _email_reserva_texto_seguro(linha_dict.get("MarcaExibida")),
            "fim_bloqueio": _email_reserva_formatar_data(expira_em, incluir_hora=True),
            "cod_ponto": _email_reserva_texto_seguro(linha_dict.get("CodPonto")),
            "referencia_painel": _email_reserva_texto_seguro(linha_dict.get("ReferenciaPainel")),
            "cidade": _email_reserva_texto_seguro(linha_dict.get("Cidade")),
            "uf": _email_reserva_texto_seguro(linha_dict.get("UF")),
        })

    ids_reserva_texto = ", ".join(ids_reserva) if ids_reserva else ", ".join(str(x) for x in (dados.get("IDsConsulta") or []))
    ids_reserva_assunto = "/".join(ids_reserva) if ids_reserva else ids_reserva_texto.replace(", ", "/")
    nome_usuario = str(dados.get("NomeUsuario") or "Usuário").strip() or "Usuário"
    vendedor_assunto = str(dados.get("Vendedor") or nome_usuario or "Usuário").strip() or "Usuário"

    if len(ids_reserva) > 1:
        frase_abertura = f"Olá, {nome_usuario}, suas reservas números {ids_reserva_texto} foram confirmadas."
    else:
        frase_abertura = f"Olá, {nome_usuario}, sua reserva número {ids_reserva_texto} foi confirmada."

    titulo = f"{vendedor_assunto} - Reserva {ids_reserva_assunto} realizada com sucesso"[:180]
    resumo = f"Reserva confirmada: {ids_reserva_texto}. Confira as CodFaces e o fim do bloqueio."

    payload = {
        "tipo_payload": "reserva_confirmada",
        "versao": 1,
        "ids_reserva": ids_reserva,
        "ids_chave": "|".join(ids_reserva),
        "titulo_visual": "Reserva Confirmada",
        "subtitulo_visual": "Bloqueio registrado com validade de 48h úteis.",
        "frase_abertura": frase_abertura,
        "resumo": resumo,
        "linhas": linhas_payload,
        "avisos": [
            "Esta Reserva será expirada automaticamente dentro do prazo limite.",
            "A Venda só será efetivada e aprovada após o envio dos documentos oficiais.",
        ],
    }

    texto_humano = (
        f"{frase_abertura}\n\n"
        "Confira os detalhes da reserva na tabela da mensagem.\n\n"
        "Avisos importantes:\n"
        "Esta Reserva será expirada automaticamente dentro do prazo limite.\n"
        "A Venda só será efetivada e aprovada após o envio dos documentos oficiais."
    )

    texto_banco = (
        texto_humano
        + "\n\n"
        + RESERVA_NOTIFICACAO_MARKER
        + "\n"
        + json.dumps(payload, ensure_ascii=False, separators=(",", ":"))
    )

    return {
        "titulo": titulo,
        "resumo": resumo,
        "texto": texto_banco,
        "payload": payload,
        "ids_reserva_texto": ids_reserva_texto,
    }



def _notificacao_reserva_ids_destinatarios(dados: dict) -> list[int]:
    """
    Resolve todos os usuários que precisam receber a mensagem interna da reserva.

    A falha mais comum aqui é gravar a mensagem só para o usuário vinculado ao
    vendedor e deixar de fora o usuário que realmente criou a reserva. Por isso
    eu envio para os dois quando forem IDs diferentes:
    - usuário vinculado ao vendedor;
    - usuário criador da reserva;
    - usuário logado no request, quando houver contexto de request.
    """
    candidatos = []

    def adicionar(valor):
        valor_int = _notificacao_reserva_int_ou_none(valor)
        if valor_int and valor_int not in candidatos:
            candidatos.append(valor_int)

    adicionar(dados.get("IDDimUsuariosDestinatario"))
    adicionar(dados.get("IDDimUsuariosVendedor"))
    adicionar(dados.get("IDDimUsuariosCriador"))
    adicionar(dados.get("IDUsuarioCriacaoRaw"))

    for linha in dados.get("LinhasReserva") or []:
        linha_dict = dict(linha or {})
        adicionar(linha_dict.get("IDDimUsuariosDestinatario"))
        adicionar(linha_dict.get("IDDimUsuariosVendedor"))
        adicionar(linha_dict.get("IDDimUsuariosCriador"))
        adicionar(linha_dict.get("IDUsuarioCriacaoRaw"))

    try:
        adicionar(getattr(current_user, "IDDimUsuarios", None))
        adicionar(getattr(current_user, "id", None))
    except Exception:
        pass

    return candidatos


def _notificacao_reserva_resolver_tipo_mensagem_id():
    """
    Resolve o IDDimTipoMensagem usado na FatoMensagemUsuario.

    Não crio tipo novo aqui para não depender de permissão/DDL/DML em dimensão.
    Se existir um tipo específico de reserva, uso ele. Se não existir, uso o
    primeiro tipo ativo encontrado, mantendo compatibilidade com a tela atual.
    """
    row = db.session.execute(
        text("""
            SELECT TOP (1)
                IDDimTipoMensagem
            FROM [Integracao].[Silver].[DimTipoMensagem] WITH (NOLOCK)
            WHERE UPPER(LTRIM(RTRIM(NomeTipoMensagem))) IN (
                N'RESERVA CONFIRMADA',
                N'RESERVA',
                N'RESERVA DE OCUPACAO',
                N'RESERVA DE OCUPAÇÃO',
                N'CONFIRMACAO DE RESERVA',
                N'CONFIRMAÇÃO DE RESERVA'
            )
            ORDER BY
                CASE UPPER(LTRIM(RTRIM(NomeTipoMensagem)))
                    WHEN N'RESERVA CONFIRMADA' THEN 0
                    WHEN N'CONFIRMAÇÃO DE RESERVA' THEN 1
                    WHEN N'CONFIRMACAO DE RESERVA' THEN 2
                    WHEN N'RESERVA' THEN 3
                    ELSE 4
                END,
                IDDimTipoMensagem;
        """)
    ).mappings().first()

    id_tipo = _notificacao_reserva_int_ou_none(row.get("IDDimTipoMensagem") if row else None)
    if id_tipo:
        return id_tipo

    row = db.session.execute(
        text("""
            SELECT TOP (1)
                IDDimTipoMensagem
            FROM [Integracao].[Silver].[DimTipoMensagem] WITH (NOLOCK)
            ORDER BY IDDimTipoMensagem;
        """)
    ).mappings().first()

    return _notificacao_reserva_int_ou_none(row.get("IDDimTipoMensagem") if row else None)


def _registrar_notificacao_confirmacao_reserva_por_id(ids_fato_ocupacao) -> dict:
    """
    Cria a mensagem interna em Integracao.Silver.FatoMensagemUsuario.

    Ajuste importante:
    - não uso mais INSERT multi-statement com @@ROWCOUNT, porque em SQL Server +
      SQLAlchemy/pyodbc isso pode falhar/rollbackar silenciosamente dependendo
      do driver;
    - faço SELECT do tipo, SELECT de duplicidade e INSERT separados na mesma
      transação;
    - envio para vendedor e criador da reserva, evitando o caso do e-mail sair,
      mas a tela /admin/mensagens do usuário logado não receber a mensagem.
    """
    ids_ocupacao = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    if not ids_ocupacao:
        return {"registrada": False, "motivo": "ids_reserva_invalidos"}

    dados = _buscar_dados_email_confirmacao_reserva(ids_ocupacao)
    if not dados:
        return {"registrada": False, "motivo": "dados_reserva_nao_encontrados"}

    ids_destinatarios = _notificacao_reserva_ids_destinatarios(dados)
    if not ids_destinatarios:
        current_app.logger.warning(
            "RESERVA_NOTIFICACAO | nenhum destinatário identificado | ids_reserva=%s",
            ids_ocupacao,
        )
        return {"registrada": False, "motivo": "destinatario_nao_identificado"}

    pacote = _notificacao_reserva_montar_payload(dados)
    linhas = (pacote.get("payload") or {}).get("linhas") or []

    link_destino = ""
    primeiro = linhas[0] if linhas else {}
    cod_ponto = str(primeiro.get("cod_ponto") or dados.get("CodPonto") or "").strip()
    if cod_ponto:
        link_destino = f"/paineis/ocupacao?codponto={cod_ponto}"

    try:
        id_tipo_reserva = _notificacao_reserva_resolver_tipo_mensagem_id()
        if not id_tipo_reserva:
            db.session.rollback()
            current_app.logger.warning(
                "RESERVA_NOTIFICACAO | IDDimTipoMensagem não encontrado | ids_reserva=%s",
                ids_ocupacao,
            )
            return {"registrada": False, "motivo": "tipo_mensagem_nao_encontrado"}

        ids_mensagens_inseridas = []
        ids_ja_existentes = []

        sql_buscar_existente = text("""
            SELECT TOP (1)
                IDFatoMensagemUsuario
            FROM [Integracao].[Silver].[FatoMensagemUsuario] WITH (UPDLOCK, HOLDLOCK)
            WHERE IDDimUsuariosDestinatario = :id_usuario_destinatario
              AND ISNULL(BitAtivo, 1) = 1
              AND ISNULL(TituloMensagem, '') = :titulo
            ORDER BY IDFatoMensagemUsuario DESC;
        """)

        sql_inserir = text("""
            INSERT INTO [Integracao].[Silver].[FatoMensagemUsuario]
            (
                IDDimUsuariosDestinatario,
                IDDimTipoMensagem,
                TituloMensagem,
                TextoMensagem,
                LinkDestino,
                BitLida,
                DataLeitura,
                BitAtivo,
                DataCriacao,
                DataAtualizacao
            )
            VALUES
            (
                :id_usuario_destinatario,
                :id_tipo_mensagem,
                :titulo,
                :texto_mensagem,
                NULLIF(LTRIM(RTRIM(:link_destino)), ''),
                0,
                NULL,
                1,
                SYSDATETIME(),
                SYSDATETIME()
            );
        """)

        for id_usuario_destinatario in ids_destinatarios:
            row_existente = db.session.execute(
                sql_buscar_existente,
                {
                    "id_usuario_destinatario": int(id_usuario_destinatario),
                    "titulo": pacote["titulo"],
                },
            ).mappings().first()

            id_existente = _notificacao_reserva_int_ou_none(
                row_existente.get("IDFatoMensagemUsuario") if row_existente else None
            )
            if id_existente:
                ids_ja_existentes.append(id_existente)
                continue

            db.session.execute(
                sql_inserir,
                {
                    "id_usuario_destinatario": int(id_usuario_destinatario),
                    "id_tipo_mensagem": int(id_tipo_reserva),
                    "titulo": pacote["titulo"],
                    "texto_mensagem": pacote["texto"],
                    "link_destino": link_destino,
                },
            )

            row_inserido = db.session.execute(
                text("""
                    SELECT TOP (1)
                        IDFatoMensagemUsuario
                    FROM [Integracao].[Silver].[FatoMensagemUsuario] WITH (NOLOCK)
                    WHERE IDDimUsuariosDestinatario = :id_usuario_destinatario
                      AND ISNULL(BitAtivo, 1) = 1
                      AND ISNULL(TituloMensagem, '') = :titulo
                    ORDER BY IDFatoMensagemUsuario DESC;
                """),
                {
                    "id_usuario_destinatario": int(id_usuario_destinatario),
                    "titulo": pacote["titulo"],
                },
            ).mappings().first()

            id_inserido = _notificacao_reserva_int_ou_none(
                row_inserido.get("IDFatoMensagemUsuario") if row_inserido else None
            )
            ids_mensagens_inseridas.append(id_inserido or int(id_usuario_destinatario))

        db.session.commit()

        if ids_mensagens_inseridas and callable(emitir_nova_mensagem_usuario):
            for id_usuario_destinatario in ids_destinatarios:
                try:
                    emitir_nova_mensagem_usuario(int(id_usuario_destinatario))
                except Exception:
                    current_app.logger.exception(
                        "RESERVA_NOTIFICACAO | falha ao emitir socket | id_usuario=%s | ids_reserva=%s",
                        id_usuario_destinatario,
                        ids_ocupacao,
                    )

        current_app.logger.info(
            "RESERVA_NOTIFICACAO | concluída | ids_reserva=%s | destinatarios=%s | inseridas=%s | existentes=%s",
            ids_ocupacao,
            ids_destinatarios,
            ids_mensagens_inseridas,
            ids_ja_existentes,
        )

        return {
            "registrada": bool(ids_mensagens_inseridas),
            "motivo": None if ids_mensagens_inseridas else "mensagem_ja_existente",
            "ids_usuarios": ids_destinatarios,
            "ids_mensagens_inseridas": ids_mensagens_inseridas,
            "ids_mensagens_existentes": ids_ja_existentes,
            "linhas_inseridas": len(ids_mensagens_inseridas),
        }

    except Exception as exc:
        db.session.rollback()
        current_app.logger.exception(
            "RESERVA_NOTIFICACAO | falha ao registrar mensagem interna | ids_reserva=%s | destinatarios=%s",
            ids_ocupacao,
            ids_destinatarios,
        )
        return {"registrada": False, "motivo": str(exc)[:300], "ids_usuarios": ids_destinatarios}


def _registrar_notificacao_confirmacao_reserva_ocupacao_agrupada(ids_fato_ocupacao) -> dict:
    """
    Registra a notificação agrupada da tela /paineis/reserva-ocupacao.

    Usa a mesma regra do e-mail: só a chamada que contém o maior ID do grupo
    grava a mensagem. Assim, várias CodFaces do mesmo cliente viram uma única
    notificação com todas as faces na tabela.
    """
    ids_atuais = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    if not ids_atuais:
        return {"registrada": False, "motivo": "ids_reserva_invalidos"}

    ids_grupo = _buscar_ids_grupo_email_reserva_ocupacao(ids_atuais, janela_segundos=120)
    if not ids_grupo:
        return {"registrada": False, "motivo": "grupo_reserva_vazio"}

    maior_id_atual = max(ids_atuais)
    maior_id_grupo = max(ids_grupo)

    if maior_id_atual != maior_id_grupo:
        current_app.logger.info(
            "RESERVA_NOTIFICACAO | registro agrupado ignorado nesta chamada; outra CodFace do mesmo cliente registrará a mensagem | ids_atuais=%s | ids_grupo=%s | maior_id_grupo=%s",
            ids_atuais,
            ids_grupo,
            maior_id_grupo,
        )
        return {
            "registrada": False,
            "motivo": "agrupada_em_outra_notificacao_reserva_ocupacao",
            "ids_grupo": ids_grupo,
        }

    return _registrar_notificacao_confirmacao_reserva_por_id(ids_grupo)



def _slot_indice_grade_reserva(valor, capacidade_slots: int) -> int | None:
    """Converte SPAN01/1/01 em índice 0-based da grade digital."""
    try:
        capacidade = int(capacidade_slots or 0)
    except Exception:
        capacidade = 0

    if capacidade <= 0:
        return None

    texto = str(valor or "").strip().upper()
    if not texto:
        return None

    m = re.search(r"(\d+)", texto)
    if not m:
        return None

    try:
        numero = int(m.group(1))
    except Exception:
        return None

    indice = numero - 1
    if 0 <= indice < capacidade:
        return indice

    return None


def _slot_label_grade_reserva(indice: int) -> str:
    """Retorna o nome visual do slot digital no padrão SPAN01."""
    try:
        return f"SPAN{int(indice) + 1:02d}"
    except Exception:
        return "SPAN01"


def _slot_numero_grade_reserva(valor, capacidade_slots: int) -> int | None:
    """
    Converte SPAN01/1/01 para o número inteiro gravável no banco.

    Importante:
    - A grade trabalha internamente com índice 0-based.
    - As colunas LoopInicio/LoopFim da tabela de ocupação são inteiras no SQL Server.
    - Portanto SPAN14 precisa ser gravado como 14, e não como texto 'SPAN14'.
    """
    idx = _slot_indice_grade_reserva(valor, capacidade_slots)
    if idx is None:
        return None
    return int(idx) + 1


def _datas_inclusivas_reserva(data_inicio: date, data_fim: date):
    """Gera todas as datas de um range inclusivo sem deslocar nenhuma data."""
    dias = []
    atual = data_inicio
    while atual <= data_fim:
        dias.append(atual)
        atual = atual + timedelta(days=1)
    return dias


def _span_por_cota_reserva_grade(cota, span_qtd=None) -> int:
    """
    Traduz cota em quantidade de slots adjacentes.

    Regras usadas na grade digital:
    - Cota 1080 ocupa 2 slots adjacentes.
    - Cota 540 ocupa 1 slot.
    - SpanQtd do banco tem prioridade quando vier preenchido.
    """
    try:
        if span_qtd not in (None, "", "null", "None"):
            span_tmp = int(float(str(span_qtd).strip().replace(",", ".")))
            if span_tmp > 0:
                return span_tmp
    except Exception:
        pass

    def _cota_para_int(valor):
        if valor in (None, "", "null", "None"):
            return 0
        if isinstance(valor, Decimal):
            try:
                return int(valor)
            except Exception:
                return int(float(valor))
        if isinstance(valor, (int, float)):
            try:
                return int(round(float(valor)))
            except Exception:
                return 0
        texto_original = str(valor or "").strip()
        texto = texto_original.replace("R$", "").replace(" ", "")
        if not texto:
            return 0
        if "," in texto and "." in texto:
            texto = texto.replace(".", "").replace(",", ".")
        elif "," in texto:
            texto = texto.replace(",", ".")
        try:
            return int(Decimal(texto))
        except Exception:
            try:
                return int(round(float(texto)))
            except Exception:
                match = re.search(r"\d+(?:[\.,]\d+)?", texto_original)
                if not match:
                    return 0
                try:
                    return int(round(float(match.group(0).replace(",", "."))))
                except Exception:
                    return 0

    cota_int = _cota_para_int(cota)

    if cota_int == 1080:
        return 2
    if cota_int == 540:
        return 1

    return 1


def _calcular_plano_encaixe_range_reserva_digital(
    cod_ponto: int,
    cod_face: str,
    data_inicio_obj: date,
    data_fim_obj: date,
    span_necessario: int,
    capacidade_slots: int,
):
    """
    Simula a grade digital dentro do range solicitado.

    Regra crítica:
    - A ocupação nunca sai do range de datas solicitado.
    - Uma reserva de 100 dias precisa encontrar 100 dias de espaço dentro do próprio range.
    - Primeiro tento um bloco contínuo/linha reta.
    - Se não existir linha reta, encaixo dia a dia nos pedaços livres do próprio dia.
    - Para SpanQtd=2, cada dia precisa ter 2 slots adjacentes; não aceito slots separados.
    """
    try:
        capacidade = int(capacidade_slots or CAPACIDADE_DIGITAL_FIXA or 16)
    except Exception:
        capacidade = int(CAPACIDADE_DIGITAL_FIXA or 16)

    capacidade = max(1, min(capacidade, 200))

    try:
        span_novo = int(span_necessario or 1)
    except Exception:
        span_novo = 1

    span_novo = max(1, min(span_novo, capacidade))

    if data_inicio_obj is None or data_fim_obj is None or data_fim_obj < data_inicio_obj:
        return {
            "ok": False,
            "erro": "Range de datas inválido para simular encaixe.",
            "dia_sem_espaco": None,
            "segmentos": [],
        }

    dias_range = _datas_inclusivas_reserva(data_inicio_obj, data_fim_obj)
    ocupado = {dia: set() for dia in dias_range}

    def _blocos_possiveis(span):
        return list(range(0, capacidade - int(span) + 1))

    def _bloco_livre_no_dia(dia, indice, span):
        slots_ocupados = ocupado.setdefault(dia, set())
        for off in range(int(span)):
            if (int(indice) + off) in slots_ocupados:
                return False
        return True

    def _bloco_livre_em_todos_os_dias(dias, indice, span):
        for dia in dias:
            if not _bloco_livre_no_dia(dia, indice, span):
                return False
        return True

    def _blocos_livres_do_dia(dia, span):
        return [idx for idx in _blocos_possiveis(span) if _bloco_livre_no_dia(dia, idx, span)]

    def _escolher_bloco(blocos, preferido=None):
        blocos = list(blocos or [])
        if not blocos:
            return None
        if preferido is None:
            return blocos[0]
        try:
            pref = int(preferido)
        except Exception:
            pref = None
        if pref is None:
            return blocos[0]
        return sorted(blocos, key=lambda idx: (abs(int(idx) - pref), int(idx)))[0]

    def _plano_para_segmentos(plano_por_dia, span):
        segmentos = []
        if not plano_por_dia:
            return segmentos

        dias_ordenados = sorted(plano_por_dia.keys())
        seg_ini = dias_ordenados[0]
        seg_fim = dias_ordenados[0]
        idx_atual = int(plano_por_dia[seg_ini])

        for dia in dias_ordenados[1:]:
            idx_dia = int(plano_por_dia[dia])
            if idx_dia == idx_atual and dia == (seg_fim + timedelta(days=1)):
                seg_fim = dia
                continue

            segmentos.append({
                "data_inicio": seg_ini,
                "data_fim": seg_fim,
                "slot_inicio": int(idx_atual) + 1,
                "slot_fim": int(idx_atual) + int(span),
                "slot_inicio_label": _slot_label_grade_reserva(idx_atual),
                "slot_fim_label": _slot_label_grade_reserva(idx_atual + int(span) - 1),
                "slot_inicio_indice": idx_atual,
                "span_qtd": int(span),
            })
            seg_ini = dia
            seg_fim = dia
            idx_atual = idx_dia

        segmentos.append({
            "data_inicio": seg_ini,
            "data_fim": seg_fim,
            "slot_inicio": int(idx_atual) + 1,
            "slot_fim": int(idx_atual) + int(span),
            "slot_inicio_label": _slot_label_grade_reserva(idx_atual),
            "slot_fim_label": _slot_label_grade_reserva(idx_atual + int(span) - 1),
            "slot_inicio_indice": idx_atual,
            "span_qtd": int(span),
        })
        return segmentos

    def _marcar_plano(plano_por_dia, span):
        for dia, idx in (plano_por_dia or {}).items():
            slots_ocupados = ocupado.setdefault(dia, set())
            for off in range(int(span)):
                slots_ocupados.add(int(idx) + off)

    def _montar_plano_intervalo(di, df, span, loop_inicio=None, loop_fim=None, permitir_forcar=False):
        if di is None or df is None or df < di:
            return {"ok": True, "plano": {}, "conflito": False, "dia_sem_espaco": None}

        ini_clip = max(di, data_inicio_obj)
        fim_clip = min(df, data_fim_obj)
        if fim_clip < ini_clip:
            return {"ok": True, "plano": {}, "conflito": False, "dia_sem_espaco": None}

        dias = _datas_inclusivas_reserva(ini_clip, fim_clip)
        span_int = max(1, min(int(span or 1), capacidade))

        idx_exp = _slot_indice_grade_reserva(loop_inicio, capacidade)
        idx_fim_exp = _slot_indice_grade_reserva(loop_fim, capacidade)
        if idx_exp is not None:
            if idx_fim_exp is not None:
                largura_exp = (idx_fim_exp - idx_exp) + 1
                if largura_exp != span_int:
                    idx_exp = None
            if idx_exp is not None and (idx_exp + span_int - 1) >= capacidade:
                idx_exp = None

        if idx_exp is not None:
            plano_exp = {dia: idx_exp for dia in dias}
            if _bloco_livre_em_todos_os_dias(dias, idx_exp, span_int):
                return {"ok": True, "plano": plano_exp, "conflito": False, "dia_sem_espaco": None}
            # Tetris: LoopInicio/LoopFim gravado no banco é só preferência visual.
            # Se aquele bloco já estiver ocupado, tento encaixar em outro bloco livre
            # antes de marcar conflito. Conflito só é permitido quando não existe
            # nenhum encaixe real dentro do range.

        for idx in _blocos_possiveis(span_int):
            if _bloco_livre_em_todos_os_dias(dias, idx, span_int):
                return {
                    "ok": True,
                    "plano": {dia: idx for dia in dias},
                    "conflito": False,
                    "dia_sem_espaco": None,
                }

        plano = {}
        preferido = None
        conflito = False

        for dia in dias:
            livres = _blocos_livres_do_dia(dia, span_int)
            escolhido = _escolher_bloco(livres, preferido)

            if escolhido is None:
                if not permitir_forcar:
                    return {
                        "ok": False,
                        "plano": plano,
                        "conflito": False,
                        "dia_sem_espaco": dia,
                    }
                escolhido = _escolher_bloco(_blocos_possiveis(span_int), preferido)
                conflito = True

            plano[dia] = int(escolhido)
            preferido = int(escolhido)

        return {"ok": True, "plano": plano, "conflito": conflito, "dia_sem_espaco": None}

    sql_existentes = text("""
        SELECT
             Origem = CAST('CONTRATO' AS varchar(20))
            ,IDItem = i.IDFatoControleContratosItensEuromidia
            ,DataInicio = TRY_CONVERT(date, i.DataInicioPrevisto)
            ,DataFim = COALESCE(
                TRY_CONVERT(date, i.DataCancelamento),
                TRY_CONVERT(date, i.DataTerminoPrevisto)
             )
            ,Cota = i.Cota
            ,SpanQtd = CAST(NULL AS int)
            ,LoopInicio = CAST(NULL AS varchar(30))
            ,LoopFim = CAST(NULL AS varchar(30))
            ,OrdemData = COALESCE(TRY_CONVERT(datetime2, i.DataAtualizacao), SYSUTCDATETIME())
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i WITH (UPDLOCK, HOLDLOCK)
        WHERE i.CodPonto = :cod_ponto
          AND LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), i.CodFace), ''))) = :cod_face
          AND i.DataInicioPrevisto IS NOT NULL
          AND i.DataTerminoPrevisto IS NOT NULL
          AND i.AtivoCancelamento = 'A'
          AND ISNULL(TRY_CONVERT(int, i.BitAtivo), 1) = 1
          AND TRY_CONVERT(date, i.DataInicioPrevisto) <= :data_fim
          AND COALESCE(TRY_CONVERT(date, i.DataCancelamento), TRY_CONVERT(date, i.DataTerminoPrevisto)) >= :data_inicio

        UNION ALL

        SELECT
             Origem = CAST('RESERVA' AS varchar(20))
            ,IDItem = o.IDFatoOcupacaoPaineisEuromidia
            ,DataInicio = TRY_CONVERT(date, o.DataInicio)
            ,DataFim = TRY_CONVERT(date, o.DataFim)
            ,Cota = o.Cota
            ,SpanQtd = TRY_CONVERT(int, o.SpanQtd)
            ,LoopInicio = LTRIM(RTRIM(COALESCE(CONVERT(varchar(30), o.LoopInicio), '')))
            ,LoopFim = LTRIM(RTRIM(COALESCE(CONVERT(varchar(30), o.LoopFim), '')))
            ,OrdemData = COALESCE(TRY_CONVERT(datetime2, o.CriadoEm), TRY_CONVERT(datetime2, o.DataAtualizacao), SYSUTCDATETIME())
        FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] o WITH (UPDLOCK, HOLDLOCK)
        WHERE o.CodPonto = :cod_ponto
          AND LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.CodFace), ''))) = :cod_face
          AND o.CanceladoEm IS NULL
          -- Não conto aqui ocupações de CONTRATO/LOCAÇÃO gravadas em FatoOcupacao,
          -- porque contratos já entram pelo FatoControleContratosItensEuromidia acima.
          -- Contar os dois duplicava a ocupação, gerava conflito falso e fazia a cota 1080
          -- parecer sem espaço mesmo com slots livres na grade.
          AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Origem), '')))) = 'RESERVA'
          AND UPPER(LTRIM(RTRIM(COALESCE(CONVERT(varchar(100), o.Status), '')))) = 'RESERVADO'
          AND TRY_CONVERT(date, o.DataInicio) IS NOT NULL
          AND TRY_CONVERT(date, o.DataFim) IS NOT NULL
          AND TRY_CONVERT(date, o.DataInicio) <= :data_fim
          AND TRY_CONVERT(date, o.DataFim) >= :data_inicio
        ORDER BY DataInicio ASC, DataFim ASC, OrdemData ASC, IDItem ASC;
    """)

    rows_existentes = db.session.execute(
        sql_existentes,
        {
            "cod_ponto": int(cod_ponto),
            "cod_face": str(cod_face or "").strip(),
            "data_inicio": data_inicio_obj,
            "data_fim": data_fim_obj,
        },
    ).mappings().all()

    conflitos_existentes = 0

    for row in rows_existentes or []:
        di = row.get("DataInicio")
        df = row.get("DataFim")
        if isinstance(di, datetime):
            di = di.date()
        if isinstance(df, datetime):
            df = df.date()
        if di is None or df is None or df < di:
            continue

        span_existente = _span_por_cota_reserva_grade(row.get("Cota"), row.get("SpanQtd"))
        span_existente = max(1, min(int(span_existente or 1), capacidade))

        plano_existente = _montar_plano_intervalo(
            di,
            df,
            span_existente,
            row.get("LoopInicio"),
            row.get("LoopFim"),
            permitir_forcar=True,
        )

        if plano_existente.get("conflito"):
            conflitos_existentes += 1

        _marcar_plano(plano_existente.get("plano") or {}, span_existente)

    plano_novo = _montar_plano_intervalo(
        data_inicio_obj,
        data_fim_obj,
        span_novo,
        None,
        None,
        permitir_forcar=False,
    )

    if not plano_novo.get("ok"):
        dia_sem_espaco = plano_novo.get("dia_sem_espaco")
        return {
            "ok": False,
            "erro": (
                "Não há espaço suficiente dentro do range selecionado. "
                "A reserva não foi gravada porque pelo menos uma data do período "
                "não possui bloco livre de slots adjacentes para essa cota."
            ),
            "dia_sem_espaco": dia_sem_espaco,
            "segmentos": _plano_para_segmentos(plano_novo.get("plano") or {}, span_novo),
            "conflitos_existentes": conflitos_existentes,
        }

    segmentos = _plano_para_segmentos(plano_novo.get("plano") or {}, span_novo)

    return {
        "ok": True,
        "erro": None,
        "dia_sem_espaco": None,
        "segmentos": segmentos,
        "modo": "reto" if len(segmentos) <= 1 else "fragmentado",
        "conflitos_existentes": conflitos_existentes,
    }

def _request_origem_tela_reserva_ocupacao(payload: dict | None = None) -> bool:
    """
    Identifica a tela /paineis/reserva-ocupacao.

    Essa tela pode disparar uma requisição por CodFace. Por isso o e-mail dela
    precisa passar por agrupamento/debounce no backend, em vez de ser enviado
    imediatamente a cada POST.
    """
    payload = payload or {}

    def _tem_reserva_ocupacao(valor) -> bool:
        texto = str(valor or "").strip().lower()
        return bool(texto and "reserva-ocupacao" in texto)

    try:
        for chave in (
            "origem_tela",
            "tela_origem",
            "source",
            "origem",
            "pagina_origem",
            "referer",
            "referrer",
        ):
            if _tem_reserva_ocupacao(payload.get(chave)):
                return True
    except Exception:
        pass

    try:
        for header in (
            request.headers.get("Referer"),
            request.headers.get("Referrer"),
            request.headers.get("X-Origem-Tela"),
            request.headers.get("X-Source-Page"),
            request.referrer,
        ):
            if _tem_reserva_ocupacao(header):
                return True
    except Exception:
        pass

    return False


def _normalizar_token_operacao_reserva(valor) -> str:
    """
    Normaliza o identificador idempotente enviado pelo template.

    O token não substitui o ID da reserva. Ele serve somente para reconhecer
    uma repetição da mesma requisição quando o banco confirmou o COMMIT, mas a
    resposta HTTP foi perdida pelo navegador/proxy.
    """
    token = str(valor or "").strip()
    if not token:
        return ""

    if len(token) < 16 or len(token) > 100:
        raise ValueError("token_operacao inválido.")

    if re.fullmatch(r"[A-Za-z0-9_-]+", token) is None:
        raise ValueError("token_operacao contém caracteres inválidos.")

    return token


def _buscar_reservas_por_token_operacao(token_operacao: str, criado_por) -> list[dict]:
    """
    Busca uma reserva já confirmada para a mesma tentativa de salvamento.

    A consulta exige o mesmo usuário criador e o marcador completo do token.
    Assim, uma repetição da requisição retorna a reserva existente em vez de
    criar outra ocupação.
    """
    token = _normalizar_token_operacao_reserva(token_operacao)
    if not token:
        return []

    marcador = f"Token Operacao: {token}"
    rows = db.session.execute(
        text("""
            SELECT
                 IDFatoOcupacaoPaineisEuromidia
                ,CodFace
                ,CodPonto
                ,DataInicio
                ,DataFim
            FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
            WHERE UPPER(LTRIM(RTRIM(COALESCE(Origem, '')))) = 'RESERVA'
              AND UPPER(LTRIM(RTRIM(COALESCE(Status, '')))) = 'RESERVADO'
              AND CanceladoEm IS NULL
              AND ISNULL(CriadoPorIDUsuario, -1) = ISNULL(:criado_por, -1)
              AND CHARINDEX(:marcador, COALESCE(TextoOriginal, '')) > 0
            ORDER BY IDFatoOcupacaoPaineisEuromidia ASC;
        """),
        {
            "criado_por": criado_por,
            "marcador": marcador,
        },
    ).mappings().all()

    return [dict(row) for row in rows]


def _resposta_reserva_idempotente(rows_existentes: list[dict], token_operacao: str):
    """Monta a mesma confirmação de sucesso para uma requisição repetida."""
    ids = []
    ids_por_codface = {}
    cod_faces = []

    for row in rows_existentes or []:
        try:
            id_reserva = int(row.get("IDFatoOcupacaoPaineisEuromidia"))
        except Exception:
            continue

        cod_face = str(row.get("CodFace") or "").strip()
        ids.append(id_reserva)
        if cod_face:
            ids_por_codface.setdefault(cod_face, []).append(id_reserva)
            if cod_face not in cod_faces:
                cod_faces.append(cod_face)

    if not ids:
        return None

    return jsonify({
        "ok": True,
        "confirmado": True,
        "requisicao_idempotente": True,
        "token_operacao": token_operacao,
        "id_fato_ocupacao_paineis_euromidia": ids[0],
        "ids_fato_ocupacao_paineis_euromidia": ids,
        "ids_por_codface": ids_por_codface,
        "cod_faces": cod_faces,
        "qtd_codfaces": len(cod_faces),
    })


def _buscar_ids_grupo_email_reserva_ocupacao(ids_fato_ocupacao, janela_segundos: int = 120) -> list[int]:
    """
    Busca reservas recém-criadas pela tela /paineis/reserva-ocupacao para o mesmo Cliente.

    A regra pedida é: se for a mesma empresa/cliente, a tabela do e-mail deve
    juntar as CodFaces e sair apenas um e-mail. Como o front dessa tela pode
    chamar o endpoint uma vez para cada CodFace, o agrupamento aqui usa:
    - mesmo IDCliente;
    - mesmo usuário que criou;
    - mesmo vendedor;
    - reservas criadas dentro de uma janela curta.
    """
    ids_base = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    if not ids_base:
        return []

    try:
        janela_int = int(janela_segundos or 120)
    except Exception:
        janela_int = 120
    janela_int = max(15, min(janela_int, 600))

    sql = text("""
        ;WITH base AS (
            SELECT TOP (1)
                 IDBase = o.IDFatoOcupacaoPaineisEuromidia
                ,CriadoEmBase = COALESCE(o.CriadoEm, o.DataAtualizacao, SYSDATETIME())
                ,IDClienteBase = o.IDCliente
                ,IDVendedorBase = o.IDVendedor
                ,CriadoPorBase = o.CriadoPorIDUsuario
                ,ExpiraEmBase = o.ExpiraEm
            FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] AS o WITH (NOLOCK)
            WHERE o.IDFatoOcupacaoPaineisEuromidia IN :ids_base
            ORDER BY
                COALESCE(o.CriadoEm, o.DataAtualizacao, SYSDATETIME()) DESC,
                o.IDFatoOcupacaoPaineisEuromidia DESC
        )
        SELECT
            o.IDFatoOcupacaoPaineisEuromidia
        FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] AS o WITH (NOLOCK)
        CROSS JOIN base AS b
        WHERE ISNULL(LTRIM(RTRIM(o.Origem)), '') = 'RESERVA'
          AND ISNULL(LTRIM(RTRIM(o.Status)), '') = 'RESERVADO'
          AND o.CanceladoEm IS NULL
          AND ISNULL(o.IDCliente, -1) = ISNULL(b.IDClienteBase, -1)
          AND ISNULL(o.IDVendedor, -1) = ISNULL(b.IDVendedorBase, -1)
          AND ISNULL(o.CriadoPorIDUsuario, -1) = ISNULL(b.CriadoPorBase, -1)
          AND ABS(DATEDIFF(SECOND, COALESCE(b.CriadoEmBase, SYSDATETIME()), COALESCE(o.CriadoEm, o.DataAtualizacao, SYSDATETIME()))) <= :janela_segundos
          AND (
                o.IDFatoOcupacaoPaineisEuromidia IN :ids_base_expiracao
             OR (
                    b.ExpiraEmBase IS NOT NULL
                AND o.ExpiraEm IS NOT NULL
                AND ABS(DATEDIFF(SECOND, b.ExpiraEmBase, o.ExpiraEm)) <= :janela_segundos
                )
          )
        ORDER BY
            o.IDFatoOcupacaoPaineisEuromidia ASC;
    """).bindparams(
        bindparam("ids_base", expanding=True),
        bindparam("ids_base_expiracao", expanding=True),
    )

    rows = db.session.execute(sql, {
        "ids_base": ids_base,
        "ids_base_expiracao": ids_base,
        "janela_segundos": janela_int,
    }).fetchall()

    ids = []
    vistos = set()
    for row in rows:
        try:
            valor = int(row[0])
        except Exception:
            continue
        if valor <= 0 or valor in vistos:
            continue
        vistos.add(valor)
        ids.append(valor)

    return ids or ids_base


def _enviar_email_confirmacao_reserva_ocupacao_agrupado(ids_fato_ocupacao) -> dict:
    """
    Envia o e-mail agrupado da tela /paineis/reserva-ocupacao.

    Para impedir dois e-mails quando o front fez um POST por CodFace, só o POST
    que contém o maior ID do grupo fica autorizado a enviar. Os demais apenas
    retornam como agrupados em outro envio.
    """
    ids_atuais = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    if not ids_atuais:
        return {"enviado": False, "motivo": "ids_reserva_invalidos"}

    ids_grupo = _buscar_ids_grupo_email_reserva_ocupacao(ids_atuais, janela_segundos=120)
    if not ids_grupo:
        return {"enviado": False, "motivo": "grupo_reserva_vazio"}

    maior_id_atual = max(ids_atuais)
    maior_id_grupo = max(ids_grupo)

    if maior_id_atual != maior_id_grupo:
        current_app.logger.info(
            "RESERVA_EMAIL | envio agrupado ignorado nesta chamada; outra CodFace do mesmo cliente enviará o e-mail | ids_atuais=%s | ids_grupo=%s | maior_id_grupo=%s",
            ids_atuais,
            ids_grupo,
            maior_id_grupo,
        )
        return {
            "enviado": False,
            "motivo": "agrupado_em_outro_email_reserva_ocupacao",
            "ids_grupo": ids_grupo,
        }

    current_app.logger.info(
        "RESERVA_EMAIL | enviando e-mail único agrupado da tela reserva-ocupacao | ids_grupo=%s",
        ids_grupo,
    )
    return _enviar_email_confirmacao_reserva_por_id(ids_grupo)


def _agendar_email_confirmacao_reserva_ocupacao(ids_fato_ocupacao, atraso_segundos: float = 8.0) -> dict:
    """
    Agenda o e-mail da tela /paineis/reserva-ocupacao com pequeno debounce.

    O retorno HTTP não fica preso esperando o usuário finalizar todas as faces.
    Depois do atraso, o worker consulta o banco e envia só pelo maior ID do grupo.
    """
    ids_agendados = _email_reserva_normalizar_ids(ids_fato_ocupacao)
    if not ids_agendados:
        return {"enviado": False, "motivo": "ids_reserva_invalidos"}

    try:
        atraso = float(atraso_segundos or 8.0)
    except Exception:
        atraso = 8.0
    atraso = max(3.0, min(atraso, 30.0))

    app = current_app._get_current_object()

    def _worker_email_reserva_ocupacao():
        try:
            time.sleep(atraso)
            with app.app_context():
                try:
                    _enviar_email_confirmacao_reserva_ocupacao_agrupado(ids_agendados)
                    _registrar_notificacao_confirmacao_reserva_ocupacao_agrupada(ids_agendados)
                finally:
                    try:
                        db.session.remove()
                    except Exception:
                        pass
        except Exception:
            try:
                with app.app_context():
                    current_app.logger.exception(
                        "RESERVA_EMAIL | falha no worker de agrupamento reserva-ocupacao | ids=%s",
                        ids_agendados,
                    )
            except Exception:
                pass

    try:
        t = threading.Thread(
            target=_worker_email_reserva_ocupacao,
            name=f"reserva-ocupacao-email-{max(ids_agendados)}",
            daemon=True,
        )
        t.start()
        current_app.logger.info(
            "RESERVA_EMAIL | e-mail da tela reserva-ocupacao agendado para agrupamento | ids=%s | atraso=%ss",
            ids_agendados,
            atraso,
        )
        return {
            "enviado": False,
            "motivo": "agendado_agrupamento_reserva_ocupacao",
            "ids_agendados": ids_agendados,
            "atraso_segundos": atraso,
        }
    except Exception as exc:
        current_app.logger.exception(
            "RESERVA_EMAIL | não consegui agendar agrupamento; tentando envio síncrono agrupado | ids=%s",
            ids_agendados,
        )
        retorno = _enviar_email_confirmacao_reserva_ocupacao_agrupado(ids_agendados)
        try:
            retorno["notificacao"] = _registrar_notificacao_confirmacao_reserva_ocupacao_agrupada(ids_agendados)
        except Exception:
            current_app.logger.exception(
                "RESERVA_NOTIFICACAO | falha no fallback síncrono de agrupamento | ids=%s",
                ids_agendados,
            )
        if not retorno.get("enviado") and not retorno.get("motivo"):
            retorno["motivo"] = str(exc)[:300]
        return retorno



@paineis_bp.route("/api/ocupacao/reserva/criar", methods=["POST"])
@login_required
def api_ocupacao_reserva_criar():

    payload = request.get_json(silent=True)
    if not isinstance(payload, dict):
        payload = {}

    csrf_token = (
        request.headers.get("X-CSRFToken")
        or request.headers.get("X-CSRF-Token")
        or payload.get("csrf_token")
        or request.form.get("csrf_token")
        or request.form.get("csrf")
    )

    try:
        validate_csrf(csrf_token)
    except Exception:
        return jsonify({"ok": False, "erro": "CSRF inválido/ausente"}), 400

    cod_ponto = (payload.get("cod_ponto") or request.form.get("cod_ponto") or "").strip()
    origem_tela_reserva_ocupacao = _request_origem_tela_reserva_ocupacao(payload)

    token_operacao_raw = payload.get("token_operacao")
    if token_operacao_raw is None:
        token_operacao_raw = request.form.get("token_operacao")

    try:
        token_operacao = _normalizar_token_operacao_reserva(token_operacao_raw)
    except ValueError as exc:
        return jsonify({"ok": False, "erro": str(exc)}), 400

    def _normalizar_codfaces_payload_reserva():
        """
        Eu aceito uma ou várias CodFaces no mesmo POST.

        Compatibilidade:
        - telas antigas continuam enviando cod_face único;
        - a tela /paineis/reserva-ocupacao pode enviar cod_faces/codfaces/faces como lista,
          string separada por vírgula/ponto-e-vírgula, ou lista de objetos com CodFace/cod_face.
        """
        codfaces = []
        vistos = set()

        def _adicionar(valor):
            if valor in (None, "", [], (), {}):
                return

            if isinstance(valor, dict):
                valor = (
                    valor.get("cod_face")
                    or valor.get("codface")
                    or valor.get("CodFace")
                    or valor.get("face")
                    or valor.get("Face")
                )

            if isinstance(valor, (list, tuple, set)):
                for item in valor:
                    _adicionar(item)
                return

            texto = str(valor or "").strip()
            if not texto:
                return

            for parte in texto.replace(";", ",").split(","):
                cod = str(parte or "").strip()
                if not cod:
                    continue
                chave = cod.upper()
                if chave in vistos:
                    continue
                vistos.add(chave)
                codfaces.append(cod)

        for nome in ("cod_faces", "codfaces", "faces", "cod_face", "codface"):
            if nome in payload:
                _adicionar(payload.get(nome))

            try:
                for valor_form in request.form.getlist(nome):
                    _adicionar(valor_form)
            except Exception:
                pass

            try:
                _adicionar(request.form.get(nome))
            except Exception:
                pass

        return codfaces

    cod_faces_reserva = _normalizar_codfaces_payload_reserva()
    cod_face = cod_faces_reserva[0] if cod_faces_reserva else ""

    cota_raw = payload.get("cota")
    if cota_raw is None:
        cota_raw = request.form.get("cota")

    data_inicio = (payload.get("data_inicio") or request.form.get("data_inicio") or "").strip()
    data_fim    = (payload.get("data_fim")    or request.form.get("data_fim")    or "").strip()

    id_cliente_raw = payload.get("id_cliente")
    if id_cliente_raw is None:
        id_cliente_raw = request.form.get("id_cliente")

    cnpj_cliente = re.sub(
        r"\D+",
        "",
        str(payload.get("cnpj_cliente") or request.form.get("cnpj_cliente") or ""),
    )

    id_vendedor_raw = payload.get("id_vendedor")
    if id_vendedor_raw is None:
        id_vendedor_raw = request.form.get("id_vendedor")

    vendedor_nome_raw = (payload.get("vendedor") or request.form.get("vendedor") or "").strip()

    id_fato_controle_raw = payload.get("id_fato_controle_contratos")
    if id_fato_controle_raw is None:
        id_fato_controle_raw = request.form.get("id_fato_controle_contratos")

    numero_contrato = (payload.get("numero_contrato") or request.form.get("numero_contrato") or "").strip()
    numero_previa   = (payload.get("numero_previa")   or request.form.get("numero_previa")   or "").strip()

    dias_raw = payload.get("dias")
    if dias_raw is None:
        dias_raw = request.form.get("dias")

  
    marca_exibida = (payload.get("marca_exibida") or request.form.get("marca_exibida") or "").strip()

    empresas_relacionadas_raw = payload.get("empresas_relacionadas")
    if empresas_relacionadas_raw is None:
        empresas_relacionadas_raw = request.form.get("empresas_relacionadas")

    if not cod_ponto:
        return jsonify({"ok": False, "erro": "cod_ponto obrigatório"}), 400
    if not cod_faces_reserva:
        return jsonify({"ok": False, "erro": "cod_face obrigatório"}), 400
    if not data_inicio or not data_fim:
        return jsonify({"ok": False, "erro": "data_inicio e data_fim obrigatórios"}), 400

    data_inicio_obj = _parse_data_reserva_yyyy_mm_dd(data_inicio)
    data_fim_obj = _parse_data_reserva_yyyy_mm_dd(data_fim)
    data_minima_reserva = date.today()

    if data_inicio_obj is None or data_fim_obj is None:
        return jsonify({"ok": False, "erro": "Datas inválidas. Use o formato AAAA-MM-DD."}), 400

    if data_inicio_obj < data_minima_reserva or data_fim_obj < data_minima_reserva:
        return jsonify({"ok": False, "erro": f"Não é permitido criar reserva com data anterior a {data_minima_reserva.strftime('%Y-%m-%d')}."}), 400

    if data_fim_obj < data_inicio_obj:
        return jsonify({"ok": False, "erro": "Data fim não pode ser menor que data início."}), 400

  
    if not marca_exibida:
        return jsonify({"ok": False, "erro": "marca_exibida obrigatória"}), 400
    if len(marca_exibida) > 200:
        return jsonify({"ok": False, "erro": "marca_exibida excede 200 caracteres"}), 400

    try:
        cod_ponto_int = int(cod_ponto)
    except Exception:
        return jsonify({"ok": False, "erro": "cod_ponto inválido"}), 400

    cota_int = None
    cota_invalida = False
    try:
        if cota_raw not in ("", None, "null", "None"):
            cota_txt = str(cota_raw).strip()
            match_cota = re.search(r"\d+(?:[\.,]\d+)?", cota_txt)
            if match_cota:
                cota_int = int(round(float(match_cota.group(0).replace(",", "."))))
            else:
                cota_invalida = True
    except Exception:
        cota_int = None
        cota_invalida = True

    id_cliente_int = None
    try:
        if id_cliente_raw not in ("", None, "null", "None"):
            id_cliente_int = int(id_cliente_raw)
    except Exception:
        return jsonify({"ok": False, "erro": "id_cliente inválido"}), 400

    id_vendedor_int = None
    try:
        if id_vendedor_raw not in ("", None, "null", "None"):
            id_vendedor_int = int(id_vendedor_raw)
    except Exception:
        return jsonify({"ok": False, "erro": "id_vendedor inválido"}), 400

    id_fato_controle_int = None
    try:
        if id_fato_controle_raw not in ("", None, "null", "None"):
            id_fato_controle_int = int(id_fato_controle_raw)
    except Exception:
        return jsonify({"ok": False, "erro": "id_fato_controle_contratos inválido"}), 400

    sql_painel = text("""
        SELECT TOP 1
            IDPainelEuromidia = COALESCE(f.IDDimPaineisEuromidia, p.IDDimPaineisEuromidia),
            TipoPainel = UPPER(LTRIM(RTRIM(COALESCE(NULLIF(f.Tipo, ''), p.Tipo, '')))),
            EhDigital = CASE
                WHEN UPPER(LTRIM(RTRIM(COALESCE(NULLIF(f.Tipo, ''), p.Tipo, '')))) LIKE '%DIGITAL%' THEN 1
                ELSE 0
            END
        FROM [Integracao].[Silver].[DimFacesPaineis] f
        OUTER APPLY (
            SELECT TOP (1)
                p.IDDimPaineisEuromidia,
                p.Tipo,
                p.DataAtualizacao
            FROM [Integracao].[Silver].[DimPaineisEuromidia] p
            WHERE p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia
               OR p.CodPonto = f.CodPonto
            ORDER BY
                CASE WHEN p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia THEN 0 ELSE 1 END,
                p.DataAtualizacao DESC,
                p.IDDimPaineisEuromidia DESC
        ) p
        WHERE f.CodFace = :cod_face
          AND f.CodPonto = :cod_ponto
        ORDER BY f.IDDimFacesPaineis DESC
    """)
    vendedor_nome = vendedor_nome_raw or None
    if id_vendedor_int is not None:
        sql_vend = text("""
            SELECT TOP 1 NomeVendedor
            FROM [Integracao].[dbo].[Vendedores]
            WHERE IDVendedor = :idv
              AND ISNULL(TRY_CONVERT(int, BitAtivo), 0) = 1
        """)
        nome_db = db.session.execute(sql_vend, {"idv": id_vendedor_int}).scalar()
        if nome_db:
            vendedor_nome = str(nome_db).strip() or vendedor_nome
        else:
            return jsonify({"ok": False, "erro": "Vendedor inválido ou inativo."}), 400

    if id_vendedor_int is None and vendedor_nome:
        sql_vend_id = text("""
            SELECT TOP 1 IDVendedor
            FROM [Integracao].[dbo].[Vendedores]
            WHERE NomeVendedor = :nome
              AND ISNULL(TRY_CONVERT(int, BitAtivo), 0) = 1
        """)
        id_db = db.session.execute(sql_vend_id, {"nome": vendedor_nome}).scalar()
        try:
            id_vendedor_int = int(id_db) if id_db is not None else None
        except Exception:
            id_vendedor_int = None

    # A empresa sempre é resolvida diretamente na DimEmpresas e sem filtro por
    # IDEmpresaProprietaria. As chaves são consultadas separadamente:
    #
    # 1. IDEmpresa usa igualdade direta e permite seek no índice/chave da tabela;
    # 2. CNPJ normalizado só é consultado como fallback quando o ID não existe.
    #
    # Não combinar as duas condições com OR. O OR junto dos REPLACE do CNPJ pode
    # obrigar o SQL Server a varrer toda a DimEmpresas mesmo quando IDEmpresa foi
    # informado, mantendo a tela presa em "Salvando reservas...".
    empresa_cliente = None

    if id_cliente_int is not None:
        sql_empresa_cliente_por_id = text("""
            SELECT TOP (1)
                e.IDEmpresa,
                CNPJ = NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(32)))), '')
            FROM [Integracao].[Silver].[DimEmpresas] AS e
            WHERE e.IDEmpresa = :id_empresa
        """)
        empresa_cliente = db.session.execute(
            sql_empresa_cliente_por_id,
            {"id_empresa": id_cliente_int},
        ).mappings().first()

    if empresa_cliente is None and cnpj_cliente:
        sql_empresa_cliente_por_cnpj = text("""
            SELECT TOP (1)
                e.IDEmpresa,
                CNPJ = NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(32)))), '')
            FROM [Integracao].[Silver].[DimEmpresas] AS e
            WHERE REPLACE(
                    REPLACE(
                        REPLACE(
                            REPLACE(
                                REPLACE(
                                    REPLACE(COALESCE(CAST(e.CNPJ AS varchar(32)), ''), '.', ''),
                                '/', ''),
                            '-', ''),
                        ' ', ''),
                    '(', ''),
                ')', '') = :cnpj
            ORDER BY e.IDEmpresa
        """)
        empresa_cliente = db.session.execute(
            sql_empresa_cliente_por_cnpj,
            {"cnpj": cnpj_cliente},
        ).mappings().first()

    if empresa_cliente is None:
        return jsonify({
            "ok": False,
            "erro": "Empresa não encontrada na DimEmpresas. Selecione novamente a empresa pelo nome ou CNPJ.",
        }), 400

    id_cliente_int = int(empresa_cliente["IDEmpresa"])
    cnpj_cliente = re.sub(r"\D+", "", str(empresa_cliente.get("CNPJ") or ""))

    def _normalizar_empresas_relacionadas_reserva(valor_bruto, marca_padrao: str):
        # Eu valido e normalizo as empresas relacionadas opcionais da reserva.
        if valor_bruto in (None, "", [], (), {}):
            return []

        if isinstance(valor_bruto, str):
            texto_bruto = valor_bruto.strip()
            if not texto_bruto:
                return []
            try:
                valor_bruto = json.loads(texto_bruto)
            except Exception:
                raise ValueError("empresas_relacionadas inválido. Envie uma lista JSON.")

        if not isinstance(valor_bruto, list):
            raise ValueError("empresas_relacionadas deve ser uma lista.")

        itens_normalizados = []
        ids_vistos = set()

        for idx, item in enumerate(valor_bruto, start=1):
            if not isinstance(item, dict):
                continue

            id_raw = item.get("id_empresa") or item.get("IDEmpresa") or item.get("id_cliente") or item.get("IDCliente")
            if id_raw in (None, "", "null", "None"):
                continue

            try:
                id_empresa = int(id_raw)
            except Exception:
                raise ValueError(f"Empresa relacionada #{idx}: id_empresa inválido.")

            if id_empresa <= 0:
                continue

            if id_empresa in ids_vistos:
                continue

            marca_relacionada = str(item.get("marca") or item.get("Marca") or "").strip()
            if not marca_relacionada:
                marca_relacionada = marca_padrao

            if len(marca_relacionada) > 200:
                raise ValueError(f"Empresa relacionada #{idx}: marca excede 200 caracteres.")

            ids_vistos.add(id_empresa)
            itens_normalizados.append({
                "id_empresa": id_empresa,
                "marca": marca_relacionada,
            })

        if not itens_normalizados:
            return []

        ids_sql = ",".join(str(int(item["id_empresa"])) for item in itens_normalizados)
        sql_empresas_relacionadas = text(f"""
            SELECT
                 IDEmpresa
                ,RazaoSocial = NULLIF(LTRIM(RTRIM(COALESCE(RazaoSocial, ''))), '')
                ,NomeFantasia = NULLIF(LTRIM(RTRIM(COALESCE(NomeFantasia, ''))), '')
                ,CNPJ = NULLIF(LTRIM(RTRIM(COALESCE(CAST(CNPJ AS varchar(30)), ''))), '')
            FROM [Integracao].[Silver].[DimEmpresas]
            WHERE IDEmpresa IN ({ids_sql})
        """)

        rows = db.session.execute(sql_empresas_relacionadas).mappings().all()
        empresas_por_id = {int(row.get("IDEmpresa") or 0): row for row in rows}

        retorno = []
        for item in itens_normalizados:
            id_empresa = int(item["id_empresa"])
            empresa = empresas_por_id.get(id_empresa)
            if not empresa:
                raise ValueError(f"Empresa relacionada IDEmpresa={id_empresa} não encontrada.")

            retorno.append({
                "id_empresa": id_empresa,
                "razao_social": (empresa.get("RazaoSocial") or empresa.get("NomeFantasia") or "").strip(),
                "nome_fantasia": (empresa.get("NomeFantasia") or "").strip(),
                "cnpj": (empresa.get("CNPJ") or "").strip(),
                "marca": item["marca"],
            })

        return retorno

    try:
        empresas_relacionadas = _normalizar_empresas_relacionadas_reserva(empresas_relacionadas_raw, marca_exibida)
    except ValueError as exc:
        return jsonify({"ok": False, "erro": str(exc)}), 400

    criado_por = _id_usuario_logado_carteira()

    # Idempotência da criação:
    #
    # O SQL Server mantém um application lock por token até o COMMIT/ROLLBACK.
    # Se o navegador repetir a mesma requisição porque perdeu a resposta HTTP,
    # a segunda chamada aguarda a primeira terminar e, em seguida, encontra a
    # reserva já gravada. Isso impede inserir uma segunda reserva para a mesma
    # tentativa.
    if token_operacao:
        recurso_lock = f"EUROMIDIA_RESERVA:{token_operacao}"
        try:
            resultado_lock = db.session.execute(
                text("""
                    SET NOCOUNT ON;

                    DECLARE @ResultadoLock int;

                    EXEC @ResultadoLock = sys.sp_getapplock
                         @Resource = :recurso_lock,
                         @LockMode = 'Exclusive',
                         @LockOwner = 'Transaction',
                         @LockTimeout = 20000;

                    SELECT @ResultadoLock AS ResultadoLock;
                """),
                {"recurso_lock": recurso_lock},
            ).scalar()

            try:
                resultado_lock_int = int(resultado_lock)
            except Exception:
                resultado_lock_int = -999

            if resultado_lock_int < 0:
                db.session.rollback()
                return jsonify({
                    "ok": False,
                    "erro": "A tentativa anterior ainda está sendo processada. Aguarde alguns segundos.",
                    "token_operacao": token_operacao,
                }), 503

            reservas_existentes_token = _buscar_reservas_por_token_operacao(
                token_operacao,
                criado_por,
            )
            resposta_idempotente = _resposta_reserva_idempotente(
                reservas_existentes_token,
                token_operacao,
            )
            if resposta_idempotente is not None:
                db.session.commit()
                return resposta_idempotente

        except Exception as exc:
            db.session.rollback()
            current_app.logger.exception(
                "RESERVA_IDEMPOTENCIA | falha ao adquirir/consultar token | token=%s",
                token_operacao,
            )
            return jsonify({
                "ok": False,
                "erro": f"Não foi possível validar a tentativa de salvamento: {exc}",
            }), 500

    # Regra única de validade da reserva:
    # - usa explicitamente o fuso de Campinas/São Paulo (America/Sao_Paulo);
    # - soma exatamente 48 horas em dias úteis de 24 horas;
    # - consulta Integracao.Silver.FatoFeriados;
    # - reutiliza o mesmo CriadoEm/ExpiraEm para todas as faces e segmentos.
    try:
        criado_em_reserva, expira_em_reserva = _calcular_expiracao_reserva_48_horas_uteis()
    except Exception as exc:
        db.session.rollback()
        current_app.logger.exception(
            "RESERVA_PRAZO | falha ao calcular 48 horas úteis pela FatoFeriados"
        )
        return jsonify({
            "ok": False,
            "erro": (
                "Não foi possível calcular as 48 horas úteis da reserva pela tabela "
                f"Integracao.Silver.FatoFeriados: {exc}"
            )[:500],
        }), 500

    def _montar_texto_original_reserva(
        id_usuario: int,
        empresas_relacionadas_normalizadas: list[dict],
        token_operacao_reserva: str = "",
    ) -> str:
        """Eu monto um TextoOriginal legível, sem gravar dict/JSON."""
        id_usuario_txt = str(id_usuario) if id_usuario else "não identificado"
        partes = [
            "Reserva Criada",
            f"ID Usuário: {id_usuario_txt}",
        ]

        if token_operacao_reserva:
            # O token fica no início para nunca ser removido pelo limite de
            # 1.000 caracteres quando existirem muitas empresas relacionadas.
            partes.append(f"Token Operacao: {token_operacao_reserva}")

        if not empresas_relacionadas_normalizadas:
            partes.append("Empresas Relacionadas: Não informado")
            return " - ".join(partes)[:1000]

        itens_empresas = []
        for empresa in empresas_relacionadas_normalizadas:
            id_empresa = int(empresa.get("id_empresa") or 0)
            nome_empresa = (
                str(empresa.get("razao_social") or "").strip()
                or str(empresa.get("nome_fantasia") or "").strip()
                or f"IDEmpresa {id_empresa}"
            )
            cnpj_empresa = str(empresa.get("cnpj") or "").strip()
            marca_relacionada = str(empresa.get("marca") or marca_exibida or "").strip()

            texto_empresa = f"Empresa relacionada: {nome_empresa}"
            if cnpj_empresa:
                texto_empresa += f" - CNPJ: {cnpj_empresa}"
            if marca_relacionada:
                texto_empresa += f" - Marca relacionada: {marca_relacionada}"

            itens_empresas.append(texto_empresa)

        partes.append("Empresas Relacionadas: " + "; ".join(itens_empresas))
        return " - ".join(partes)[:1000]

    texto_original_reserva = _montar_texto_original_reserva(
        criado_por,
        empresas_relacionadas,
        token_operacao,
    )


    sql_cap = text("""
        DECLARE @CodFace varchar(20) = :cod_face;
        DECLARE @CodPonto int = :cod_ponto;

        ;WITH Painel AS (
            SELECT TOP (1)
                p.CodPonto,
                TipoPainel = UPPER(LTRIM(RTRIM(p.Tipo))),
                QuantidadeFaces = NULLIF(p.QuantidadeFaces, 0),
                BitAtivo = COALESCE(p.BitAtivo, 1)
            FROM [Integracao].[Silver].[DimPaineisEuromidia] p
            WHERE p.CodPonto = @CodPonto
        )
        SELECT TOP 1
            CodPonto = (SELECT CodPonto FROM Painel),
            TipoPainel = COALESCE((SELECT TipoPainel FROM Painel), 'DESCONHECIDO'),
            BitAtivo   = (SELECT BitAtivo FROM Painel),
            EhDigital =
                CASE
                    WHEN COALESCE((SELECT TipoPainel FROM Painel),'') LIKE '%DIGITAL%' THEN 1
                    ELSE 0
                END,
            CapacidadeSlots =
                CASE
                    WHEN COALESCE((SELECT TipoPainel FROM Painel),'') LIKE '%DIGITAL%'
                    THEN COALESCE((SELECT QuantidadeFaces FROM Painel), 16)
                    ELSE 1
                END;
    """)

    faces_para_gravar = []
    total_segmentos_encaixe = 0

    for cod_face_item in cod_faces_reserva:
        cod_face_atual = str(cod_face_item or "").strip()
        if not cod_face_atual:
            continue

        painel_row_item = db.session.execute(
            sql_painel,
            {"cod_face": cod_face_atual, "cod_ponto": cod_ponto_int},
        ).mappings().first()

        if not painel_row_item:
            return jsonify({"ok": False, "erro": f"CodFace {cod_face_atual} não pertence ao CodPonto informado."}), 400

        try:
            id_painel_item = painel_row_item.get("IDPainelEuromidia")
            id_painel_item_int = int(id_painel_item) if id_painel_item is not None else None
        except Exception:
            id_painel_item_int = None

        cap_row = db.session.execute(
            sql_cap,
            {"cod_face": cod_face_atual, "cod_ponto": cod_ponto_int},
        ).mappings().first()

        if not cap_row:
            return jsonify({"ok": False, "erro": f"Não consegui resolver capacidade do painel para a CodFace {cod_face_atual}"}), 400

        bit_ativo = int(cap_row.get("BitAtivo") or 0)
        eh_digital = int(cap_row.get("EhDigital") or 0)
        capacidade_slots = int(cap_row.get("CapacidadeSlots") or 0)

        # A regra de digital vem do painel/capacidade, igual à grade. Se a face também vier como
        # digital, ela naturalmente cai nessa mesma validação.
        if bit_ativo == 0:
            return jsonify({"ok": False, "erro": f"Painel inativo (BitAtivo=0) para a CodFace {cod_face_atual}"}), 409

        if capacidade_slots <= 0:
            return jsonify({"ok": False, "erro": f"Capacidade inválida (<=0) para a CodFace {cod_face_atual}"}), 400

        if eh_digital == 1:
            if cota_invalida or cota_int not in (540, 1080):
                return jsonify({"ok": False, "erro": f"Para painel digital, informe uma cota válida: 540 ou 1080. CodFace {cod_face_atual}."}), 400
            cota_gravar = cota_int
        else:
            cota_gravar = None

        # Regra comercial oficial da ocupação digital:
        # Cota 1080 consome 2 slots; cota 540 consome 1 slot.
        # Em painel não digital, não gravamos SpanQtd nem Cota.
        slots_novo = 2 if eh_digital == 1 and cota_gravar == 1080 else 1
        spanqtd_novo = slots_novo if eh_digital == 1 else None

        plano_encaixe_reserva_item = {
            "ok": True,
            "modo": "nao_digital",
            "segmentos": [],
            "conflitos_existentes": 0,
        }

        if eh_digital == 0:
            sql_conflito = text("""
                SELECT TOP 1 1
                FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] WITH (UPDLOCK, HOLDLOCK)
                WHERE CodFace = :cod_face
                  AND CodPonto = :cod_ponto
                  AND CanceladoEm IS NULL
                  AND Status IN ('ATIVO','RESERVADO')
                  AND NOT (
                        TRY_CONVERT(date, :data_fim) < DataInicio
                     OR TRY_CONVERT(date, :data_inicio) > DataFim
                  )
            """)
            existe = db.session.execute(sql_conflito, {
                "cod_face": cod_face_atual,
                "cod_ponto": cod_ponto_int,
                "data_inicio": data_inicio,
                "data_fim": data_fim,
            }).scalar()

            if existe:
                return jsonify({
                    "ok": False,
                    "erro": f"Não há espaço livre nesse período para painel não digital. CodFace {cod_face_atual}. A reserva não foi gravada."
                }), 409

            segmentos_encaixe_item = [{
                "data_inicio": data_inicio_obj,
                "data_fim": data_fim_obj,
                "slot_inicio": None,
                "slot_fim": None,
                "span_qtd": None,
            }]
        else:
            plano_encaixe_reserva_item = _calcular_plano_encaixe_range_reserva_digital(
                cod_ponto=cod_ponto_int,
                cod_face=cod_face_atual,
                data_inicio_obj=data_inicio_obj,
                data_fim_obj=data_fim_obj,
                span_necessario=slots_novo,
                capacidade_slots=capacidade_slots,
            )

            if not plano_encaixe_reserva_item.get("ok"):
                dia_sem_espaco = plano_encaixe_reserva_item.get("dia_sem_espaco")
                dia_txt = dia_sem_espaco.strftime("%Y-%m-%d") if hasattr(dia_sem_espaco, "strftime") else None
                erro_msg = plano_encaixe_reserva_item.get("erro") or "Não há espaço suficiente na grade para esse range."
                if dia_txt:
                    erro_msg = f"{erro_msg} Dia sem encaixe: {dia_txt}."
                return jsonify({
                    "ok": False,
                    "erro": f"{erro_msg} CodFace {cod_face_atual}.",
                    "dia_sem_espaco": dia_txt,
                    "cod_face_sem_espaco": cod_face_atual,
                    "encaixe_modo": "sem_espaco",
                    "qtd_segmentos_simulados": len(plano_encaixe_reserva_item.get("segmentos") or []),
                }), 409

            segmentos_encaixe_item = plano_encaixe_reserva_item.get("segmentos") or []
            if not segmentos_encaixe_item:
                return jsonify({
                    "ok": False,
                    "erro": f"O simulador de encaixe não retornou segmentos para gravar a reserva digital. CodFace {cod_face_atual}."
                }), 409

        total_segmentos_encaixe += len(segmentos_encaixe_item)
        faces_para_gravar.append({
            "cod_face": cod_face_atual,
            "id_painel": id_painel_item_int,
            "eh_digital": eh_digital,
            "capacidade_slots": capacidade_slots,
            "cota": cota_gravar,
            "spanqtd_novo": spanqtd_novo,
            "plano_encaixe": plano_encaixe_reserva_item,
            "segmentos": segmentos_encaixe_item,
        })

    if not faces_para_gravar:
        return jsonify({"ok": False, "erro": "Nenhuma CodFace válida foi informada para criar reserva."}), 400

    reserva_ordem_prioridade_int = 1
    plano_encaixe_reserva = faces_para_gravar[0].get("plano_encaixe") or {
        "ok": True,
        "modo": "nao_digital",
        "segmentos": [],
        "conflitos_existentes": 0,
    }


    sql_insert = text("""
        SET NOCOUNT ON;

        DECLARE @ReservasInseridas TABLE (
            IDFatoOcupacaoPaineisEuromidia int NOT NULL
        );

        INSERT INTO [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] (
            DataAtualizacao,
            Referencia,
            CodPonto,
            CodFace,
            IDPainelEuromidia,
            Origem,
            Status,
            DataInicio,
            DataFim,
            LoopInicio,
            LoopFim,
            SpanQtd,
            Cota,
            MarcaExibida,
            Vendedor,
            IDVendedor,
            IDCliente,
            IDFatoControleContratos,
            NumeroContrato,
            NumeroPrevia,
            TextoOriginal,
            Observacao,
            Dias,
            ExpiraEm,
            CriadoEm,
            CriadoPorIDUsuario,
            ReservaOrdemPrioridade,
            TipoVinculoOrigem,
            BitEmpresasRelacionadas,
            TipoReserva
        )
        OUTPUT INSERTED.IDFatoOcupacaoPaineisEuromidia
        INTO @ReservasInseridas (IDFatoOcupacaoPaineisEuromidia)
        VALUES (
            :criado_em,
            CONVERT(varchar(64),
                HASHBYTES('SHA2_256',
                    CONCAT(
                        'RESERVA|',
                        COALESCE(CONVERT(varchar(30), :cod_ponto), ''), '|',
                        UPPER(LTRIM(RTRIM(COALESCE(:cod_face,'')))), '|',
                        COALESCE(CONVERT(varchar(10), TRY_CONVERT(date, :data_inicio), 23), ''), '|',
                        COALESCE(CONVERT(varchar(10), TRY_CONVERT(date, :data_fim), 23), ''), '|',
                        COALESCE(CONVERT(varchar(30), :spanqtd), ''), '|',
                        COALESCE(CONVERT(varchar(30), :cota), ''), '|',
                        COALESCE(CONVERT(varchar(30), :id_cliente), ''), '|',
                        COALESCE(CONVERT(varchar(30), :id_vendedor), ''), '|',
                        UPPER(LTRIM(RTRIM(COALESCE(:numero_contrato,'')))), '|',
                        UPPER(LTRIM(RTRIM(COALESCE(:numero_previa,''))))
                    )
                ), 2
            ),
            :cod_ponto,
            :cod_face,
            :id_painel,
            'RESERVA',
            'RESERVADO',
            TRY_CONVERT(date, :data_inicio),
            TRY_CONVERT(date, :data_fim),
            :loop_inicio,
            :loop_fim,
            :spanqtd,
            :cota,
            :marca_exibida,
            :vendedor_nome,
            :id_vendedor,
            :id_cliente,
            :id_fato_controle,
            NULLIF(LTRIM(RTRIM(:numero_contrato)), ''),
            NULLIF(LTRIM(RTRIM(:numero_previa)), ''),
            :texto_original,
            NULLIF(LTRIM(RTRIM(:observacao)), ''),
            :dias,
            :expira_em,
            :criado_em,
            :criado_por,
            :reserva_ordem_prioridade,
            :tipo_vinculo_origem,
            :bit_empresas_relacionadas,
            1
        );

        SELECT TOP (1)
            IDFatoOcupacaoPaineisEuromidia
        FROM @ReservasInseridas;
    """)

    try:
        ids_fato_ocupacao: list[int] = []
        ids_por_codface: dict[str, list[int]] = {}

        for face_gravacao in faces_para_gravar:
            cod_face_gravar = str(face_gravacao.get("cod_face") or "").strip()
            id_painel_gravar = face_gravacao.get("id_painel")
            eh_digital_gravar = int(face_gravacao.get("eh_digital") or 0)
            capacidade_slots_gravar = int(face_gravacao.get("capacidade_slots") or 0)
            cota_gravar = face_gravacao.get("cota")
            spanqtd_novo_gravar = face_gravacao.get("spanqtd_novo")
            segmentos_face = face_gravacao.get("segmentos") or []

            ids_por_codface.setdefault(cod_face_gravar, [])

            for idx_segmento, segmento in enumerate(segmentos_face, start=1):
                seg_ini = segmento.get("data_inicio") or data_inicio_obj
                seg_fim = segmento.get("data_fim") or data_fim_obj

                if isinstance(seg_ini, datetime):
                    seg_ini = seg_ini.date()
                if isinstance(seg_fim, datetime):
                    seg_fim = seg_fim.date()

                if seg_ini is None or seg_fim is None or seg_fim < seg_ini:
                    raise ValueError(f"Segmento de encaixe inválido na posição {idx_segmento} da CodFace {cod_face_gravar}.")

                dias_segmento_int = int((seg_fim - seg_ini).days + 1)
                loop_inicio_segmento = None
                loop_fim_segmento = None
                spanqtd_segmento = int(segmento.get("span_qtd") or spanqtd_novo_gravar or 1) if eh_digital_gravar == 1 else None

                if eh_digital_gravar == 1:
                    loop_inicio_segmento = _slot_numero_grade_reserva(segmento.get("slot_inicio"), capacidade_slots_gravar)
                    loop_fim_segmento = _slot_numero_grade_reserva(segmento.get("slot_fim"), capacidade_slots_gravar)

                    if loop_inicio_segmento is None or loop_fim_segmento is None:
                        raise ValueError(f"Segmento de encaixe sem LoopInicio/LoopFim numérico na posição {idx_segmento} da CodFace {cod_face_gravar}.")

                    if int(loop_fim_segmento) < int(loop_inicio_segmento):
                        raise ValueError(f"Segmento de encaixe com LoopFim menor que LoopInicio na posição {idx_segmento} da CodFace {cod_face_gravar}.")

                id_fato_ocupacao = db.session.execute(sql_insert, {
                    "cod_ponto": cod_ponto_int,
                    "cod_face": cod_face_gravar,
                    "id_painel": id_painel_gravar,
                    "data_inicio": seg_ini,
                    "data_fim": seg_fim,
                    "loop_inicio": loop_inicio_segmento,
                    "loop_fim": loop_fim_segmento,
                    "spanqtd": spanqtd_segmento,
                    "cota": cota_gravar,
                    "marca_exibida": marca_exibida,
                    "vendedor_nome": vendedor_nome,
                    "id_vendedor": id_vendedor_int,
                    "id_cliente": id_cliente_int,
                    "id_fato_controle": id_fato_controle_int,
                    "numero_contrato": numero_contrato,
                    "numero_previa": numero_previa,
                    "texto_original": texto_original_reserva,
                    "observacao": (payload.get("observacao") or request.form.get("observacao") or "").strip(),
                    "dias": dias_segmento_int,
                    "expira_em": expira_em_reserva,
                    "criado_em": criado_em_reserva,
                    "criado_por": criado_por,
                    "reserva_ordem_prioridade": reserva_ordem_prioridade_int,
                    "tipo_vinculo_origem": "Reserva",
                    "bit_empresas_relacionadas": 1 if empresas_relacionadas else 0
                }).scalar_one()

                id_fato_ocupacao_int_item = int(id_fato_ocupacao)
                ids_fato_ocupacao.append(id_fato_ocupacao_int_item)
                ids_por_codface[cod_face_gravar].append(id_fato_ocupacao_int_item)

        if not ids_fato_ocupacao:
            raise RuntimeError("Nenhuma linha de reserva foi inserida.")

        id_fato_ocupacao_int = int(ids_fato_ocupacao[0])

        if empresas_relacionadas:
            sql_insert_empresas_relacionadas = text("""
                INSERT INTO [Integracao].[Silver].[DimEmpresasRelacionadasContrato] (
                    IDFatoControleContratosEuromidia,
                    IDempresa,
                    IDFatoOcupacaoPaineisEuromidia,
                    Marca
                )
                VALUES (
                    :id_fato_controle_contratos,
                    :id_empresa,
                    :id_fato_ocupacao,
                    :marca
                )
            """)

            linhas_empresas_relacionadas = []
            for id_ocupacao_relacionada in ids_fato_ocupacao:
                for item in empresas_relacionadas:
                    linhas_empresas_relacionadas.append({
                        "id_fato_controle_contratos": id_fato_controle_int,
                        "id_empresa": int(item["id_empresa"]),
                        "id_fato_ocupacao": int(id_ocupacao_relacionada),
                        "marca": str(item.get("marca") or marca_exibida).strip()[:200],
                    })

            if linhas_empresas_relacionadas:
                db.session.execute(
                    sql_insert_empresas_relacionadas,
                    linhas_empresas_relacionadas,
                )

        db.session.commit()
    except Exception as exc:
        db.session.rollback()
        current_app.logger.exception("Erro ao inserir reserva de ocupação e empresas relacionadas.")
        return jsonify({"ok": False, "erro": f"Erro ao inserir reserva na tabela: {exc}"}), 500

    email_confirmacao_reserva = {"enviado": False, "motivo": "nao_tentado"}
    try:
        if origem_tela_reserva_ocupacao:
            email_confirmacao_reserva = _agendar_email_confirmacao_reserva_ocupacao(ids_fato_ocupacao)
        else:
            email_confirmacao_reserva = _enviar_email_confirmacao_reserva_por_id(ids_fato_ocupacao)
    except Exception as exc:
        current_app.logger.exception(
            "RESERVA_EMAIL | erro inesperado após salvar reserva | id_reserva=%s",
            id_fato_ocupacao_int,
        )
        email_confirmacao_reserva = {"enviado": False, "motivo": str(exc)[:300]}

    notificacao_confirmacao_reserva = {"registrada": False, "motivo": "nao_tentada"}
    try:
        if origem_tela_reserva_ocupacao:
            notificacao_confirmacao_reserva = (
                email_confirmacao_reserva.get("notificacao")
                or {"registrada": False, "motivo": "agendada_agrupamento_reserva_ocupacao"}
            )
        else:
            notificacao_confirmacao_reserva = _registrar_notificacao_confirmacao_reserva_por_id(ids_fato_ocupacao)
    except Exception as exc:
        current_app.logger.exception(
            "RESERVA_NOTIFICACAO | erro inesperado após salvar reserva | id_reserva=%s",
            id_fato_ocupacao_int,
        )
        notificacao_confirmacao_reserva = {"registrada": False, "motivo": str(exc)[:300]}

    return jsonify({
        "ok": True,
        "confirmado": True,
        "requisicao_idempotente": False,
        "token_operacao": token_operacao or None,
        "id_fato_ocupacao_paineis_euromidia": id_fato_ocupacao_int,
        "ids_fato_ocupacao_paineis_euromidia": ids_fato_ocupacao,
        "ids_por_codface": ids_por_codface,
        "cod_faces": [face.get("cod_face") for face in faces_para_gravar],
        "qtd_codfaces": len(faces_para_gravar),
        "bit_empresas_relacionadas": 1 if empresas_relacionadas else 0,
        "qtd_empresas_relacionadas": len(empresas_relacionadas),
        "encaixe_modo": "multi" if len(faces_para_gravar) > 1 else plano_encaixe_reserva.get("modo"),
        "qtd_segmentos_encaixe": total_segmentos_encaixe,
        "criado_em": criado_em_reserva.isoformat(sep=" "),
        "expira_em": expira_em_reserva.isoformat(sep=" "),
        "validade_horas_uteis": RESERVA_VALIDADE_HORAS_UTEIS,
        "email_confirmacao_enviado": bool(email_confirmacao_reserva.get("enviado")),
        "email_confirmacao_motivo": email_confirmacao_reserva.get("motivo"),
        "notificacao_confirmacao_registrada": bool(notificacao_confirmacao_reserva.get("registrada")),
        "notificacao_confirmacao_motivo": notificacao_confirmacao_reserva.get("motivo"),
    })









@paineis_bp.route("/ocupacao", methods=["GET"])
@login_required
@requer_item_menu_paineis("lista_ocupacao")
@limiter.limit("80 per minute", methods=["GET"])
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def lista_ocupacao():

    def _somente_digitos(s: str) -> str:
        try:
            if not s:
                return ""
            return "".join([c for c in str(s) if c.isdigit()])
        except:
            return ""

    def _lista_parametros_texto(nome: str):
        """Eu leio filtros multi-select vindos por query string repetida."""
        valores = []
        try:
            valores.extend(request.args.getlist(nome) or [])
        except Exception:
            pass

        # Compatibilidade com links antigos ou URLs montadas manualmente com vírgula.
        if not valores:
            bruto = (request.args.get(nome) or "").strip()
            if bruto:
                valores = bruto.split(",")

        saida = []
        vistos = set()
        for valor in valores:
            texto = str(valor or "").strip()
            if not texto:
                continue
            chave = texto.upper()
            if chave in vistos:
                continue
            vistos.add(chave)
            saida.append(texto)
        return saida

    def _lista_parametros_inteiros(nome: str):
        """Eu leio filtros multi-select de IDs, removendo vazio, duplicado e inválido."""
        saida = []
        vistos = set()
        for valor in _lista_parametros_texto(nome):
            try:
                numero = int(valor)
            except Exception:
                numero = 0
            if numero <= 0 or numero in vistos:
                continue
            vistos.add(numero)
            saida.append(numero)
        return saida

    def _bind_expanding(sql_text):
        """Eu ativo bindparam expansivo apenas para listas realmente usadas no SQL."""
        binds = []
        if ":status_lista" in sql_text:
            binds.append(bindparam("status_lista", expanding=True))
        if ":origem_lista" in sql_text:
            binds.append(bindparam("origem_lista", expanding=True))
        if ":vendedor_ids" in sql_text:
            binds.append(bindparam("vendedor_ids", expanding=True))
        consulta = text(sql_text)
        if binds:
            consulta = consulta.bindparams(*binds)
        return consulta

    def _montar_where_ocupacao(aplicar_status=True, aplicar_origem=True, aplicar_vendedor=True):
        filtros_sql_local = []
        params_local = {}

        filtros_sql_local.append("ftcp.CodFace <> '0' AND ftcp.CodFace IS NOT NULL")

        if aplicar_status and status_lista:
            filtros_sql_local.append("ftcp.Status IN :status_lista")
            params_local["status_lista"] = tuple(status_lista)

        if aplicar_origem and origem_lista:
            filtros_sql_local.append("ftcp.Origem IN :origem_lista")
            params_local["origem_lista"] = tuple(origem_lista)

        if aplicar_vendedor and vendedor_ids:
            filtros_sql_local.append("ftcp.IDVendedor IN :vendedor_ids")
            params_local["vendedor_ids"] = tuple(vendedor_ids)

        if q:
            filtros_sql_local.append("""
                (
                    ftcp.CodFace LIKE :q_like
                    OR emp.RazaoSocial LIKE :q_like
                    OR ftcp.MarcaExibida LIKE :q_like
                    OR ftcp.Vendedor LIKE :q_like
                    OR vend.NomeVendedor LIKE :q_like
                )
            """)
            params_local["q_like"] = f"%{q}%"

        where_sql_local = " AND ".join([f"({x})" for x in filtros_sql_local]) if filtros_sql_local else "1=1"
        return where_sql_local, params_local

    def _cte_dedupe_ocupacao(where_sql_local: str) -> str:
        return f"""
            ;WITH dedupe AS (
                SELECT
                    ftcp.IDFatoOcupacaoPaineisEuromidia,
                    ftcp.CodFace,
                    ftcp.Origem,
                    ftcp.Status,
                    ftcp.DataInicio,
                    ftcp.DataFim,
                    ftcp.MarcaExibida,
                    ftcp.Cota,
                    ftcp.IDVendedor,
                    ftcp.Vendedor,
                    vend.NomeVendedor,
                    ftcp.CriadoEm,
                    ftcp.DataAtualizacao,
                    emp.RazaoSocial,

                    ROW_NUMBER() OVER (
                        PARTITION BY
                            ISNULL(ftcp.CodFace,''),
                            ISNULL(ftcp.Origem,''),
                            ISNULL(ftcp.Status,''),
                            ISNULL(CAST(ftcp.DataInicio AS date),'1900-01-01'),
                            ISNULL(CAST(ftcp.DataFim AS date),'1900-01-01'),
                            ISNULL(ftcp.MarcaExibida,''),
                            ISNULL(CAST(ftcp.Cota AS varchar(50)),''),
                            ISNULL(CAST(ftcp.IDVendedor AS varchar(50)),''),
                            ISNULL(CAST(ftcp.CriadoEm AS datetime2),'1900-01-01')
                        ORDER BY
                            ISNULL(ftcp.DataAtualizacao, ftcp.CriadoEm) DESC,
                            ftcp.IDFatoOcupacaoPaineisEuromidia DESC
                    ) AS rn_key
                FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] AS ftcp
                LEFT JOIN [Integracao].[Silver].[DimEmpresas] AS emp
                    ON emp.IDEmpresa = ftcp.[IDCliente]
                LEFT JOIN [Integracao].[dbo].[Vendedores] AS vend
                    ON vend.IDVendedor = ftcp.IDVendedor
                WHERE {where_sql_local}
            )
        """

    q = (request.args.get("q") or "").strip()
    status_lista = _lista_parametros_texto("status")
    origem_lista = _lista_parametros_texto("origem")
    vendedor_ids = _lista_parametros_inteiros("vendedor")

    try:
        page = int(request.args.get("page") or "1")
    except:
        page = 1

    try:
        per_page = int(request.args.get("per_page") or "20")
    except:
        per_page = 20

    per_page = max(5, min(per_page, 100))
    page = max(1, page)

    usuario_eh_vendedor_restrito = bool(
        _usuario_logado_eh_perfil_vendedor()
        and not _usuario_logado_tem_acesso_operacional_total_paineis()
    )
    id_vendedor_logado_ocupacao = (
        _resolver_id_vendedor_logado_carteira()
        if usuario_eh_vendedor_restrito
        else 0
    )

    where_sql, params = _montar_where_ocupacao(
        aplicar_status=True,
        aplicar_origem=True,
        aplicar_vendedor=True,
    )

    sql_total = _bind_expanding(f"""
        {_cte_dedupe_ocupacao(where_sql)}
        SELECT COUNT(1) AS total
        FROM dedupe
        WHERE rn_key = 1
    """)

    row_total = db.session.execute(sql_total, params).fetchone()
    total = int(row_total[0] or 0) if row_total else 0

    total_pages = max(1, (total + per_page - 1) // per_page)
    if page > total_pages:
        page = total_pages

    inicio = (page - 1) * per_page + 1 if total > 0 else 0
    fim = min(page * per_page, total)

    start_rn = (page - 1) * per_page + 1
    end_rn = page * per_page

    params_page = dict(params)
    params_page.update({"start_rn": start_rn, "end_rn": end_rn})

    sql_rows = _bind_expanding(f"""
        {_cte_dedupe_ocupacao(where_sql)},
        filtrada AS (
            SELECT *
            FROM dedupe
            WHERE rn_key = 1
        ),
        ranked AS (
            SELECT
                *,
                ROW_NUMBER() OVER (
                    ORDER BY
                        ISNULL(CAST(CriadoEm AS datetime2), ISNULL(CAST(DataAtualizacao AS datetime2), CAST('1900-01-01' AS datetime2))) DESC,
                        IDFatoOcupacaoPaineisEuromidia DESC
                ) AS rn
            FROM filtrada
        )
        SELECT
            IDFatoOcupacaoPaineisEuromidia,
            CodFace,
            Origem,
            Status,
            DataInicio,
            DataFim,
            MarcaExibida,
            Cota,
            IDVendedor,
            Vendedor,
            NomeVendedor,
            CriadoEm,
            RazaoSocial
        FROM ranked
        WHERE rn BETWEEN :start_rn AND :end_rn
        ORDER BY rn
    """)

    rows = db.session.execute(sql_rows, params_page).fetchall()

    itens = []
    for r in rows:
        itens.append({
            "IDFatoOcupacaoPaineisEuromidia": int(r[0]) if r[0] is not None else None,
            "CodFace": (r[1] or "").strip(),
            "Origem": (r[2] or "").strip(),
            "Status": (r[3] or "").strip(),
            "DataInicio": r[4],
            "DataFim": r[5],
            "MarcaExibida": (r[6] or "").strip(),
            "Cota": r[7],
            "IDVendedor": _converter_id_inteiro_seguro(r[8]),
            "Vendedor": (r[9] or "").strip(),
            "NomeVendedor": (r[10] or "").strip(),
            "CriadoEm": r[11],
            "RazaoSocial": (r[12] or "").strip(),
            "PodeGerenciarOcupacao": _usuario_logado_pode_gerenciar_ocupacao_por_id_vendedor(r[8]),
        })

    where_status, params_status = _montar_where_ocupacao(
        aplicar_status=False,
        aplicar_origem=True,
        aplicar_vendedor=True,
    )
    sql_status = _bind_expanding(f"""
        {_cte_dedupe_ocupacao(where_status)}
        SELECT DISTINCT Status
        FROM dedupe
        WHERE rn_key = 1
          AND Status IS NOT NULL
          AND LTRIM(RTRIM(Status)) <> ''
        ORDER BY Status ASC
    """)
    status_opcoes = [str(x[0]).strip() for x in db.session.execute(sql_status, params_status).fetchall() if str(x[0] or "").strip()]

    where_origem, params_origem = _montar_where_ocupacao(
        aplicar_status=True,
        aplicar_origem=False,
        aplicar_vendedor=True,
    )
    sql_origem = _bind_expanding(f"""
        {_cte_dedupe_ocupacao(where_origem)}
        SELECT DISTINCT Origem
        FROM dedupe
        WHERE rn_key = 1
          AND Origem IS NOT NULL
          AND LTRIM(RTRIM(Origem)) <> ''
        ORDER BY Origem ASC
    """)
    origem_opcoes = [str(x[0]).strip() for x in db.session.execute(sql_origem, params_origem).fetchall() if str(x[0] or "").strip()]

    where_vendedor, params_vendedor = _montar_where_ocupacao(
        aplicar_status=True,
        aplicar_origem=True,
        aplicar_vendedor=False,
    )
    sql_vendedor = _bind_expanding(f"""
        {_cte_dedupe_ocupacao(where_vendedor)}
        SELECT DISTINCT
            IDVendedor,
            NomeVendedor = COALESCE(NULLIF(LTRIM(RTRIM(NomeVendedor)), ''), NULLIF(LTRIM(RTRIM(Vendedor)), ''))
        FROM dedupe
        WHERE rn_key = 1
          AND IDVendedor IS NOT NULL
          AND COALESCE(NULLIF(LTRIM(RTRIM(NomeVendedor)), ''), NULLIF(LTRIM(RTRIM(Vendedor)), '')) IS NOT NULL
        ORDER BY NomeVendedor ASC
    """)
    vendedor_opcoes = []
    for id_vendedor, nome_vendedor in db.session.execute(sql_vendedor, params_vendedor).fetchall():
        id_vendedor_int = _converter_id_inteiro_seguro(id_vendedor)
        nome_vendedor_txt = str(nome_vendedor or "").strip()
        if id_vendedor_int > 0 and nome_vendedor_txt:
            vendedor_opcoes.append({
                "IDVendedor": id_vendedor_int,
                "NomeVendedor": nome_vendedor_txt,
            })

    return render_template(
        "euromidia/ocupacao_lista.html",
        itens=itens,
        status_opcoes=status_opcoes,
        origem_opcoes=origem_opcoes,
        vendedor_opcoes=vendedor_opcoes,
        usuario_eh_vendedor_restrito=usuario_eh_vendedor_restrito,
        id_vendedor_logado_ocupacao=id_vendedor_logado_ocupacao,
        filtros={
            "q": q,
            "status": status_lista,
            "origem": origem_lista,
            "vendedor": vendedor_ids,
            "per_page": per_page,
        },
        paginacao={
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
            "inicio": inicio,
            "fim": fim,
        },
    )







