@paineis_bp.route("/ocupacao/<int:id_ocupacao>/cancelar", methods=["GET","POST"])
@login_required
@limiter.limit("40 per minute", methods=["POST"])
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def ocupacao_cancelar(id_ocupacao: int):
   
    sql_chk = text("""
        SELECT
            IDFatoOcupacaoPaineisEuromidia,
            CanceladoEm,
            Referencia,
            CodPonto,
            CodFace,
            DataInicio,
            DataFim,
            IDVendedor
        FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
        WHERE IDFatoOcupacaoPaineisEuromidia = :id
    """)
    r = db.session.execute(sql_chk, {"id": id_ocupacao}).fetchone()
    if not r:
        abort(404)

    referencia = r[2]
    cod_ponto = r[3]
    cod_face = r[4]
    data_inicio = r[5]
    data_fim = r[6]
    id_vendedor_ocupacao = r[7]

    _abortar_se_usuario_nao_pode_gerenciar_ocupacao(id_vendedor_ocupacao)

    ja_cancelado = r[1] is not None
    if ja_cancelado:
        flash("Esta ocupação já estava cancelada.", "warning")
        return redirect(url_for("Paineis.ocupacao_detalhe", id_ocupacao=id_ocupacao))

    motivo = (request.form.get("motivo_cancelamento") or "").strip()

    sql_cancel = text("""
        UPDATE [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
        SET
            Status = 'CANCELADO',
            CanceladoEm = GETDATE(),
            CanceladoPorIDUsuario = :id_usuario,
            Observacao = CASE
                WHEN :motivo IS NULL OR LTRIM(RTRIM(:motivo)) = '' THEN Observacao
                WHEN Observacao IS NULL OR LTRIM(RTRIM(Observacao)) = '' THEN :motivo
                ELSE CONCAT(Observacao, CHAR(10), '[CANCELAMENTO] ', :motivo)
            END,
            DataAtualizacao = GETDATE()
        WHERE IDFatoOcupacaoPaineisEuromidia = :id
    """)


    sql_upd_item = text("""
        DECLARE @Ref varchar(64) = :referencia;

        DECLARE @IDContrato int =
        (
            SELECT TOP 1 c.IDFatoControleContratosEuromidia
            FROM [Integracao].[Silver].[FatoControleContratosEuromidia] c
            WHERE c.Referencia = @Ref
            ORDER BY c.DataAtualizacao DESC
        );

        IF @IDContrato IS NULL
        BEGIN
            SELECT 0 AS LinhasAfetadas;
            RETURN;
        END

        UPDATE i
        SET
            i.Status = 'CANCELADO',
            i.DataCancelamento = CAST(GETDATE() AS date)
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        WHERE i.IDFatoControleContratoEuromidia = @IDContrato
          AND i.CodPonto = :cod_ponto
          AND LTRIM(RTRIM(COALESCE(i.CodFace,''))) = LTRIM(RTRIM(COALESCE(:cod_face,'')))
          AND i.DataInicioPrevisto = :data_inicio
          AND i.DataTerminoPrevisto = :data_fim;

        SELECT @@ROWCOUNT AS LinhasAfetadas;
    """)

    id_usuario = _id_usuario_logado_carteira()

    try:
        db.session.execute(sql_cancel, {
            "id": id_ocupacao,
            "id_usuario": id_usuario,
            "motivo": motivo if motivo else None
        })

       
        db.session.execute(sql_upd_item, {
            "referencia": str(referencia).strip() if referencia is not None else None,
            "cod_ponto": cod_ponto,
            "cod_face": cod_face,
            "data_inicio": data_inicio,
            "data_fim": data_fim
        })

        db.session.commit()
    except Exception:
        db.session.rollback()
        flash("Erro ao cancelar ocupação (ou ao cancelar item do contrato).", "danger")
        return redirect(url_for("Paineis.ocupacao_detalhe", id_ocupacao=id_ocupacao))

    flash("Ocupação cancelada com sucesso.", "success")
    return redirect(url_for("Paineis.lista_ocupacao"))





@paineis_bp.route("/ocupacao/<int:id_ocupacao>/status", methods=["POST", "GET"])
@login_required
@limiter.limit("120 per minute", methods=["POST"])
@retry_get_view(db, attempts=6, base_delay=0.2, max_delay=1.5)
def ocupacao_alterar_status(id_ocupacao: int):
    if request.method == "GET":
        return redirect(url_for("Paineis.ocupacao_detalhe", id_ocupacao=id_ocupacao))

    status_novo = (request.form.get("status_novo") or "").strip().upper()

    permitidos = {"CANCELADO", "RESERVADO", "ATIVO"}
    if status_novo not in permitidos:
        abort(400)

    id_usuario = None

    sql_chk = text("""
        SELECT
            oc.IDFatoOcupacaoPaineisEuromidia,
            LTRIM(RTRIM(ISNULL(oc.Status,'')))  AS StatusAtual,
            LTRIM(RTRIM(ISNULL(oc.Origem,'')))  AS OrigemAtual,
            oc.Referencia,
            oc.CodPonto,
            LTRIM(RTRIM(ISNULL(oc.CodFace,'')))   AS CodFace,
            oc.IDPainelEuromidia,
            oc.IDCliente,
            LTRIM(RTRIM(ISNULL(emp.RazaoSocial,''))) AS RazaoSocial,
            oc.MarcaExibida,
            oc.Vendedor,
            oc.IDVendedor,
            oc.NumeroContrato,
            oc.NumeroPrevia,
            oc.Cota,
            oc.DataInicio,
            oc.DataFim
        FROM [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia] AS oc
        LEFT JOIN [Integracao].[Silver].[DimEmpresas] AS emp
            ON emp.IDEmpresa = oc.IDCliente
        WHERE oc.IDFatoOcupacaoPaineisEuromidia = :id
    """)
    r = db.session.execute(sql_chk, {"id": id_ocupacao}).fetchone()
    if not r:
        abort(404)

    status_atual = (r[1] or "").strip().upper()

    referencia = (r[3] or "").strip()
    codponto = int(r[4]) if r[4] is not None else None
    codface = (r[5] or "").strip()
    id_painel = r[6]
    id_cliente = r[7]
    razao_social = (r[8] or "").strip()
    marca_exibida = (r[9] or "").strip() if r[9] else None
    vendedor = (r[10] or "").strip() if r[10] else None
    id_vendedor = r[11]
    _abortar_se_usuario_nao_pode_gerenciar_ocupacao(id_vendedor)

    numero_contrato = (r[12] or "").strip() if r[12] else None
    numero_previa = (r[13] or "").strip() if r[13] else None
    cota = r[14]
    data_inicio = r[15]
    data_fim = r[16]

    if not referencia or codponto is None or not codface or data_inicio is None or data_fim is None:
        abort(400)

    origem_forcada = None
    if status_novo == "ATIVO":
        origem_forcada = "CONTRATO"
    elif status_novo == "RESERVADO":
        origem_forcada = "RESERVA"

    sql_upd_ocup = text("""
        UPDATE [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
        SET
            Status = :status_novo,
            Origem = COALESCE(:origem_forcada, Origem),
            DataAtualizacao = GETDATE(),
            CanceladoEm = CASE
                WHEN :status_novo = 'CANCELADO' THEN ISNULL(CanceladoEm, GETDATE())
                ELSE NULL
            END,
            CanceladoPorIDUsuario = CASE
                WHEN :status_novo = 'CANCELADO' THEN :id_usuario
                ELSE NULL
            END
        WHERE IDFatoOcupacaoPaineisEuromidia = :id
    """)
    db.session.execute(sql_upd_ocup, {
        "id": id_ocupacao,
        "status_novo": status_novo,
        "origem_forcada": origem_forcada,
        "id_usuario": id_usuario
    })

    if status_novo == "ATIVO":

        sql_get_dimface = text("""
            SELECT TOP 1
                IDDimFacesPaineis
            FROM [Integracao].[Silver].[DimFacesPaineis]
            WHERE
                IDDimPaineisEuromidia = TRY_CONVERT(int, :id_painel)
                AND LTRIM(RTRIM(ISNULL(CodFace,''))) = LTRIM(RTRIM(:codface))
            ORDER BY IDDimFacesPaineis DESC
        """)
        id_dim_faces = db.session.execute(sql_get_dimface, {
            "id_painel": id_painel,
            "codface": codface
        }).scalar()

        if id_dim_faces is None:
            sql_get_dimface_fallback = text("""
                SELECT TOP 1
                    IDDimFacesPaineis
                FROM [Integracao].[Silver].[DimFacesPaineis]
                WHERE
                    CodPonto = :codponto
                    AND LTRIM(RTRIM(ISNULL(CodFace,''))) = LTRIM(RTRIM(:codface))
                ORDER BY IDDimFacesPaineis DESC
            """)
            id_dim_faces = db.session.execute(sql_get_dimface_fallback, {
                "codponto": codponto,
                "codface": codface
            }).scalar()

        try:
            id_dim_faces_int = int(id_dim_faces) if id_dim_faces is not None else None
        except Exception:
            id_dim_faces_int = None

        sql_get_header = text("""
            SELECT TOP 1 IDFatoControleContratosEuromidia
            FROM [Integracao].[Silver].[FatoControleContratosEuromidia]
            WHERE Referencia = :ref
            ORDER BY IDFatoControleContratosEuromidia DESC
        """)
        row_header = db.session.execute(sql_get_header, {"ref": referencia}).fetchone()

        if row_header:
            id_contrato = int(row_header[0])
        else:
            sql_ins_header = text("""
                INSERT INTO [Integracao].[Silver].[FatoControleContratosEuromidia] (
                    DataAtualizacao,
                    Referencia,
                    NumeroContrato,
                    NumeroPrevia,
                    DataLancamento,
                    RazaoSocial,
                    MarcaExibida,
                    Vendedor,
                    Origem,
                    IDEmpresa
                )
                OUTPUT INSERTED.IDFatoControleContratosEuromidia AS IDNovo
                VALUES (
                    GETDATE(),
                    :ref,
                    :numero_contrato,
                    :numero_previa,
                    CAST(GETDATE() AS date),
                    :razao_social,
                    :marca_exibida,
                    :vendedor,
                    'CONTRATO',
                    :id_empresa
                );
            """)
            row_new = db.session.execute(sql_ins_header, {
                "ref": referencia,
                "numero_contrato": numero_contrato,
                "numero_previa": numero_previa,
                "razao_social": razao_social if razao_social else None,
                "marca_exibida": marca_exibida,
                "vendedor": vendedor,
                "id_empresa": id_cliente
            }).fetchone()

            if not row_new or row_new[0] is None:
                db.session.rollback()
                abort(500)

            id_contrato = int(row_new[0])

        sql_get_item = text("""
            SELECT TOP 1 IDFatoControleContratosItensEuromidia
            FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia]
            WHERE
                Referencia = :ref
                AND ISNULL(CodPonto, -1) = :codponto
                AND LTRIM(RTRIM(ISNULL(CodFace,''))) = :codface
                AND DataInicioPrevisto = :dt_ini
                AND DataTerminoPrevisto = :dt_fim
            ORDER BY IDFatoControleContratosItensEuromidia DESC
        """)
        row_item = db.session.execute(sql_get_item, {
            "ref": referencia,
            "codponto": codponto,
            "codface": codface,
            "dt_ini": data_inicio,
            "dt_fim": data_fim
        }).fetchone()

        if row_item:

            id_item = int(row_item[0])
            sql_upd_item_ativo = text("""
                UPDATE [Integracao].[Silver].[FatoControleContratosItensEuromidia]
                SET
                    IDFatoControleContratoEuromidia = :id_contrato,
                    Status = 'ATIVO',
                    Origem = 'CONTRATO',
                    DataCancelamento = NULL,
                    AtivoCancelamento = NULL,
                    DataAtualizacao = GETDATE(),
                    IDPainelEuromidia = :id_painel,
                    IDDimFacesPaineis = :id_dim_faces
                WHERE IDFatoControleContratosItensEuromidia = :id_item
            """)
            db.session.execute(sql_upd_item_ativo, {
                "id_contrato": id_contrato,
                "id_item": id_item,
                "id_painel": id_painel,
                "id_dim_faces": id_dim_faces_int
            })
        else:

            sql_ins_item = text("""
                INSERT INTO [Integracao].[Silver].[FatoControleContratosItensEuromidia] (
                    IDFatoControleContratoEuromidia,
                    DataAtualizacao,
                    Referencia,
                    NumeroContrato,
                    NumeroPrevia,
                    CodPonto,
                    CodFace,
                    DataLancamento,
                    Cota,
                    Origem,
                    RazaoSocial,
                    MarcaExibida,
                    Vendedor,
                    IDVendedor,
                    IDPainelEuromidia,
                    IDDimFacesPaineis,
                    DataInicioPrevisto,
                    DataTerminoPrevisto,
                    Status
                )
                VALUES (
                    :id_contrato,
                    GETDATE(),
                    :ref,
                    :numero_contrato,
                    :numero_previa,
                    :codponto,
                    :codface,
                    CAST(GETDATE() AS date),
                    :cota,
                    'CONTRATO',
                    :razao_social,
                    :marca_exibida,
                    :vendedor,
                    :id_vendedor,
                    :id_painel,
                    :id_dim_faces,
                    :dt_ini,
                    :dt_fim,
                    'ATIVO'
                );
            """)
            db.session.execute(sql_ins_item, {
                "id_contrato": id_contrato,
                "ref": referencia,
                "numero_contrato": numero_contrato,
                "numero_previa": numero_previa,
                "codponto": codponto,
                "codface": codface,
                "cota": cota,
                "razao_social": razao_social if razao_social else None,
                "marca_exibida": marca_exibida,
                "vendedor": vendedor,
                "id_vendedor": id_vendedor,
                "id_painel": id_painel,
                "id_dim_faces": id_dim_faces_int,
                "dt_ini": data_inicio,
                "dt_fim": data_fim
            })

        sql_set_fk = text("""
            UPDATE [Integracao].[Silver].[FatoOcupacaoPaineisEuromidia]
            SET IDFatoControleContratos = :id_contrato
            WHERE IDFatoOcupacaoPaineisEuromidia = :id_ocup
        """)
        db.session.execute(sql_set_fk, {
            "id_contrato": id_contrato,
            "id_ocup": id_ocupacao
        })

    if status_novo == "CANCELADO":

        sql_get_header2 = text("""
            SELECT TOP 1 IDFatoControleContratosEuromidia
            FROM [Integracao].[Silver].[FatoControleContratosEuromidia]
            WHERE Referencia = :ref
            ORDER BY IDFatoControleContratosEuromidia DESC
        """)
        row_header2 = db.session.execute(sql_get_header2, {"ref": referencia}).fetchone()

        if row_header2:
            id_contrato2 = int(row_header2[0])

            sql_cancel_item = text("""
                UPDATE [Integracao].[Silver].[FatoControleContratosItensEuromidia]
                SET
                    Status = 'CANCELADO',
                    DataCancelamento = CAST(GETDATE() AS date),
                    AtivoCancelamento = 'S',
                    DataAtualizacao = GETDATE()
                WHERE
                    IDFatoControleContratoEuromidia = :id_contrato
                    AND ISNULL(CodPonto, -1) = :codponto
                    AND LTRIM(RTRIM(ISNULL(CodFace,''))) = :codface
                    AND DataInicioPrevisto = :dt_ini
                    AND DataTerminoPrevisto = :dt_fim
            """)
            db.session.execute(sql_cancel_item, {
                "id_contrato": id_contrato2,
                "codponto": codponto,
                "codface": codface,
                "dt_ini": data_inicio,
                "dt_fim": data_fim
            })

    db.session.commit()
    return redirect(url_for("Paineis.ocupacao_detalhe", id_ocupacao=id_ocupacao))




def _obter_base_url_publica_checkin() -> str:
    """
    Regra:
    1) se existir configuração explícita, uso ela;
    2) senão, monto automaticamente com o host da request;
    3) se o host vier sem porta, acrescento a porta pública do checkin.
    """
    base_url_cfg = str(current_app.config.get("CHECKIN_BASE_URL_PUBLICA") or "").strip()
    if base_url_cfg:
        return base_url_cfg.rstrip("/")

    porta_publica = str(
        current_app.config.get("CHECKIN_PORTA_PUBLICA")
        or current_app.config.get("SERVER_PORT_PUBLICA")
        or 5000
    ).strip()

    host_forwarded = str(request.headers.get("X-Forwarded-Host") or "").strip()
    host_padrao = str(request.headers.get("Host") or request.host or "").strip()
    host = host_forwarded or host_padrao

    protocolo = str(
        request.headers.get("X-Forwarded-Proto")
        or request.scheme
        or "http"
    ).strip().lower()

    if not host:
        return f"{protocolo}://127.0.0.1:{porta_publica}"

    host = re.sub(r"^https?://", "", host, flags=re.IGNORECASE).strip().rstrip("/")

    # Se o host não vier com porta, força a porta pública do checkin.
    if ":" not in host:
        host = f"{host}:{porta_publica}"

    return f"{protocolo}://{host}".rstrip("/")







def _localizar_arquivo_imagem(pasta: Path) -> Path:
    """Eu localizo a primeira imagem válida dentro de uma pasta.

    Aceito JPG, JPEG, PNG e WEBP porque o upload já permite WEBP e alguns fundos
    podem estar nesse formato.
    """
    pasta = Path(pasta)

    if not pasta.exists() or not pasta.is_dir():
        raise FileNotFoundError(f"Pasta de imagem não encontrada: {pasta}")

    extensoes = ("*.jpg", "*.jpeg", "*.png", "*.webp", "*.JPG", "*.JPEG", "*.PNG", "*.WEBP")

    arquivos = []
    for ext in extensoes:
        arquivos.extend(pasta.glob(ext))

    arquivos = [arq for arq in arquivos if arq.is_file()]

    if not arquivos:
        raise FileNotFoundError(f"Nenhuma imagem encontrada em: {pasta}")

    return sorted(arquivos, key=lambda arq: arq.name.lower())[0]
def _normalizar_texto_checkin(valor) -> str:
    try:
        return str(valor or "").strip()
    except Exception:
        return ""


def _somente_digitos(valor) -> str:
    return "".join(ch for ch in _normalizar_texto_checkin(valor) if ch.isdigit())


def _garantir_pasta(caminho: Path) -> None:
    caminho.mkdir(parents=True, exist_ok=True)





def _obter_pasta_base_checkin() -> Path:
    """Eu resolvo a pasta raiz real dos checkins.

    Regra correta do projeto:
    /home/guilherme_correa/PythonJobs/pipelines/FlaskApp/chekin/pontos

    Também trato o caso em que alguma configuração venha apontando para
    /chekin em vez de /chekin/pontos, porque isso muda completamente o caminho
    final e faz o sistema procurar /chekin/245 em vez de /chekin/pontos/245.
    """
    candidatos = [
        current_app.config.get("PASTA_BASE_CHECKIN"),
        current_app.config.get("CHECKIN_PASTA_BASE"),
        current_app.config.get("DIRETORIO_BASE_CHECKIN"),
        "/home/guilherme_correa/PythonJobs/pipelines/FlaskApp/chekin/pontos",
    ]

    for candidato in candidatos:
        texto = str(candidato or "").strip()
        if not texto:
            continue

        caminho = Path(texto).expanduser()
        nome_pasta = caminho.name.lower()

        if nome_pasta != "pontos" and (nome_pasta in {"chekin", "checkin"} or (caminho / "pontos").exists()):
            caminho = caminho / "pontos"

        return caminho

    raise RuntimeError("Não foi possível resolver a pasta base do checkin.")
def _normalizar_extensao_arquivo(nome_arquivo: str) -> str:
    """Eu extraio a extensão do arquivo e devolvo sempre em minúsculo."""
    nome_arquivo = str(nome_arquivo or "").strip()
    if "." not in nome_arquivo:
        return ".jpg"
    return "." + nome_arquivo.rsplit(".", 1)[1].lower()


def _obter_regras_upload_checkin() -> dict[str, object]:
    """Eu centralizo as regras de upload de imagem e vídeo com fallback seguro."""
    extensoes_imagem = {".jpg", ".jpeg", ".png", ".webp"}
    mimes_imagem = {"image/jpeg", "image/png", "image/webp"}
    extensoes_video = {".mp4"}
    mimes_video = {"video/mp4"}

    return {
        "extensoes_imagem": extensoes_imagem,
        "mimes_imagem": mimes_imagem,
        "extensoes_video": extensoes_video,
        "mimes_video": mimes_video,
        "tamanho_maximo_imagem_bytes": int(current_app.config.get("CHECKIN_TAMANHO_MAXIMO_IMAGEM_BYTES", 20 * 1024 * 1024)),
        "tamanho_maximo_video_bytes": int(current_app.config.get("CHECKIN_TAMANHO_MAXIMO_VIDEO_BYTES", 250 * 1024 * 1024)),
    }


def _obter_tamanho_arquivo_upload_checkin(arquivo) -> int:
    """Eu leio o tamanho do arquivo em bytes sem perder a posição original do stream."""
    try:
        posicao_atual = arquivo.stream.tell()
    except Exception:
        posicao_atual = 0

    try:
        arquivo.stream.seek(0, os.SEEK_END)
        tamanho_bytes = int(arquivo.stream.tell() or 0)
    finally:
        try:
            arquivo.stream.seek(posicao_atual)
        except Exception:
            arquivo.stream.seek(0)

    return tamanho_bytes


def _validar_e_classificar_arquivo_upload_checkin(
    *,
    arquivo,
    largura_maxima: int,
    altura_maxima: int,
) -> dict[str, object]:
    """Eu valido extensão, MIME, coerência e regras específicas de imagem ou vídeo."""
    regras = _obter_regras_upload_checkin()

    if arquivo is None:
        raise ValueError("Nenhum arquivo foi enviado.")

    nome_original = _normalizar_texto_checkin(getattr(arquivo, "filename", ""))
    if not nome_original:
        raise ValueError("O nome do arquivo está vazio.")

    extensao = _normalizar_extensao_arquivo(nome_original)
    mimetype = str(getattr(arquivo, "mimetype", "") or "").strip().lower()

    if not mimetype:
        raise ValueError("Não foi possível identificar o MIME type do arquivo.")

    eh_ext_imagem = extensao in regras["extensoes_imagem"]
    eh_mime_imagem = mimetype in regras["mimes_imagem"]
    eh_ext_video = extensao in regras["extensoes_video"]
    eh_mime_video = mimetype in regras["mimes_video"]

    if eh_ext_imagem and eh_mime_video:
        raise ValueError("Arquivo incoerente: a extensão é de imagem, mas o MIME type é de vídeo.")

    if eh_ext_video and eh_mime_imagem:
        raise ValueError("Arquivo incoerente: a extensão é de vídeo, mas o MIME type é de imagem.")

    if eh_ext_imagem and eh_mime_imagem:
        tipo_midia = "Imagem"
        id_dim_tipo_midia = 1
    elif eh_ext_video and eh_mime_video:
        tipo_midia = "Video"
        id_dim_tipo_midia = 2
    else:
        raise ValueError("Extensão e MIME type não são compatíveis com uma mídia permitida.")

    tamanho_bytes = _obter_tamanho_arquivo_upload_checkin(arquivo)

    if tipo_midia == "Imagem":
        if tamanho_bytes > int(regras["tamanho_maximo_imagem_bytes"]):
            raise ValueError("A imagem excede o tamanho máximo permitido.")

        arquivo.stream.seek(0)
        conteudo = arquivo.read()
        arquivo.stream.seek(0)

        try:
            imagem_validacao = Image.open(BytesIO(conteudo))
            imagem_validacao.verify()
            imagem_medicao = Image.open(BytesIO(conteudo))
            largura, altura = imagem_medicao.size
        except Exception as exc:
            raise ValueError("O arquivo enviado não é uma imagem válida.") from exc

        if largura > int(largura_maxima) or altura > int(altura_maxima):
            raise ValueError(
                f"Imagem maior que o permitido. Máximo: {int(largura_maxima)}x{int(altura_maxima)}px."
            )

        return {
            "id_dim_tipo_midia": id_dim_tipo_midia,
            "nome_midia": tipo_midia,
            "extensao": extensao,
            "mimetype": mimetype,
            "tamanho_bytes": tamanho_bytes,
            "largura": int(largura),
            "altura": int(altura),
            "eh_imagem": True,
            "eh_video": False,
        }

    if tamanho_bytes > int(regras["tamanho_maximo_video_bytes"]):
        raise ValueError("O vídeo excede o tamanho máximo permitido.")

    return {
        "id_dim_tipo_midia": id_dim_tipo_midia,
        "nome_midia": tipo_midia,
        "extensao": extensao,
        "mimetype": mimetype,
        "tamanho_bytes": tamanho_bytes,
        "largura": None,
        "altura": None,
        "eh_imagem": False,
        "eh_video": True,
    }


def _localizar_fundo_checkin(cod_ponto: str, cod_face: str) -> Path:
    """Eu localizo o fundo oficial do ponto/face.

    Regra principal do projeto: o fundo fica em:
    pontos/CodPonto/fundo

    Também mantenho fallback para pontos/CodPonto/CodFace/fundo para não quebrar
    cadastros antigos, mas a prioridade agora é a pasta fundo dentro do CodPonto.
    """
    pasta_base = _obter_pasta_base_checkin()
    cod_ponto_txt = _normalizar_segmento_pasta_checkin(cod_ponto)
    cod_face_txt = _normalizar_segmento_pasta_checkin(cod_face, forcar_maiusculo=True)

    pasta_ponto = _resolver_pasta_filha_checkin(pasta_base, cod_ponto_txt)
    if not pasta_ponto.exists() or not pasta_ponto.is_dir():
        raise FileNotFoundError(f"Pasta do ponto não encontrada: {pasta_ponto}")

    pasta_face = _resolver_pasta_filha_checkin(pasta_ponto, cod_face_txt)
    if not pasta_face.exists() or not pasta_face.is_dir():
        raise FileNotFoundError(f"Pasta da face não encontrada: {pasta_face}")

    candidatos_pasta_fundo = [
        _resolver_pasta_filha_checkin(pasta_ponto, "fundo"),
        _resolver_pasta_filha_checkin(pasta_face, "fundo"),
    ]

    pasta_fundo = next((p for p in candidatos_pasta_fundo if p.exists() and p.is_dir()), None)
    if pasta_fundo is None:
        caminhos_testados = " | ".join(str(p) for p in candidatos_pasta_fundo)
        raise FileNotFoundError(f"Pasta do fundo não encontrada. Caminhos testados: {caminhos_testados}")

    return _localizar_arquivo_imagem(pasta_fundo)
def _normalizar_segmento_pasta_checkin(valor, *, forcar_maiusculo: bool = False, valor_padrao: str = "0") -> str:
    """Eu normalizo cada segmento usado na pasta final do checkin para evitar variações e subpastas indevidas."""
    texto = _normalizar_texto_checkin(valor)
    if forcar_maiusculo:
        texto = texto.upper()

    if not texto:
        texto = str(valor_padrao)

    texto = texto.replace("..", "").replace("/", "").replace("\\", "")
    texto = texto.strip()

    if not texto:
        texto = str(valor_padrao)

    return texto



def _resolver_pasta_filha_checkin(pasta_pai: Path, nome_pasta: str, *, criar: bool = False) -> Path:
    """Eu resolvo uma subpasta direta sem criar duplicidade por diferença de maiúsculas/minúsculas.

    Exemplo: se o usuário manda 245AD, mas a pasta física estiver 245Ad, eu reutilizo
    a pasta existente em vez de criar outra. Em Linux isso importa porque o sistema de
    arquivos diferencia maiúsculas de minúsculas.
    """
    pasta_pai = Path(pasta_pai)
    nome_limpo = str(nome_pasta or "").strip().replace("..", "").replace("/", "").replace("\\", "")

    if not nome_limpo:
        nome_limpo = "0"

    caminho_direto = pasta_pai / nome_limpo

    if caminho_direto.exists():
        return caminho_direto

    if pasta_pai.exists() and pasta_pai.is_dir():
        nome_casefold = nome_limpo.casefold()
        try:
            for filho in pasta_pai.iterdir():
                if filho.is_dir() and filho.name.casefold() == nome_casefold:
                    return filho
        except Exception:
            pass

    if criar:
        _garantir_pasta(caminho_direto)

    return caminho_direto

def _montar_pasta_destino_final_checkin(
    *,
    cod_ponto: str | int,
    cod_face: str,
    id_fato_controle_contratos: int,
    id_fato_contrato_destinatario_externo: int,
) -> Path:
    """Eu monto a pasta final do upload dentro de pontos/CodPonto/CodFace/Contrato/Destinatario."""
    pasta_base = _obter_pasta_base_checkin()
    cod_ponto_txt = _normalizar_segmento_pasta_checkin(cod_ponto)
    cod_face_txt = _normalizar_segmento_pasta_checkin(cod_face, forcar_maiusculo=True)
    id_contrato_txt = _normalizar_segmento_pasta_checkin(int(id_fato_controle_contratos))
    id_destinatario_txt = _normalizar_segmento_pasta_checkin(int(id_fato_contrato_destinatario_externo or 0))

    pasta_ponto = _resolver_pasta_filha_checkin(pasta_base, cod_ponto_txt, criar=True)
    pasta_face = _resolver_pasta_filha_checkin(pasta_ponto, cod_face_txt, criar=True)

    pasta_destino = (
        pasta_face
        / id_contrato_txt
        / id_destinatario_txt
    )

    _garantir_pasta(pasta_destino)
    return pasta_destino
def _salvar_upload_original_checkin(
    *,
    pasta_destino: Path,
    id_fato_controle_contratos: int,
    id_fato_contrato_destinatario_externo: int,
    cod_face: str,
    data_checkin: date,
    arquivo=None,
    caminho_arquivo_origem: str | Path | None = None,
    nome_original_cliente: str | None = None,
) -> tuple[str, Path]:
    """
    Eu salvo a mídia importada dentro da pasta final do contrato e destinatário externo.

    Posso receber:
    - arquivo da request Flask
    - caminho temporário já salvo em disco
    """

    if arquivo is None and caminho_arquivo_origem is None:
        raise ValueError("Informe 'arquivo' ou 'caminho_arquivo_origem' para salvar o upload original.")

    caminho_origem = Path(str(caminho_arquivo_origem).strip()) if caminho_arquivo_origem else None

    nome_original = (
        _normalizar_texto_checkin(nome_original_cliente)
        or _normalizar_texto_checkin(getattr(arquivo, "filename", ""))
        or (caminho_origem.name if caminho_origem else "")
        or "arquivo"
    )

    nome_seguro = secure_filename(nome_original) if nome_original else ""
    extensao = Path(nome_seguro).suffix.lower()

    if not extensao and caminho_origem is not None:
        extensao = caminho_origem.suffix.lower()

    if not extensao:
        extensao = ".jpg"

    _garantir_pasta(pasta_destino)

    nome_base = (
        f"{cod_face}_{data_checkin.strftime('%Y%m%d')}_"
        f"{int(id_fato_controle_contratos)}_{int(id_fato_contrato_destinatario_externo)}_upload"
    )
    caminho_saida = pasta_destino / f"{nome_base}{extensao}"

    contador = 1
    while caminho_saida.exists():
        caminho_saida = pasta_destino / f"{nome_base}_{contador:02d}{extensao}"
        contador += 1

    if arquivo is not None:
        arquivo.stream.seek(0)
        arquivo.save(caminho_saida)
    else:
        if not caminho_origem or not caminho_origem.exists() or not caminho_origem.is_file():
            raise FileNotFoundError(f"Arquivo temporário não encontrado: {caminho_origem}")
        shutil.move(str(caminho_origem), str(caminho_saida))

    return nome_original, caminho_saida



def _obter_item_contrato_checkin(
    *,
    id_fato_controle_contratos: int,
    cod_ponto: str,
    cod_face: str,
) -> dict | None:
    """Eu localizo o item ativo exato do contrato selecionado para o checkin."""
    sql = text("""
        SELECT TOP (1)
            IDFatoControleContratosItensEuromidia = i.IDFatoControleContratosItensEuromidia,
            IDFatoControleContratoEuromidia = i.IDFatoControleContratoEuromidia,
            IDEmpresaAgencia = i.IDEmpresaAgencia,
            BitAtivo = CAST(ISNULL(i.BitAtivo, 1) AS bit)
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        WHERE
            i.IDFatoControleContratoEuromidia = :id_fato_controle_contratos
            AND i.CodPonto = :cod_ponto
            AND UPPER(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50))))) = UPPER(LTRIM(RTRIM(:cod_face)))
            AND ISNULL(i.BitAtivo, 1) = 1
        ORDER BY i.IDFatoControleContratosItensEuromidia DESC
    """)

    row = db.session.execute(
        sql,
        {
            "id_fato_controle_contratos": int(id_fato_controle_contratos),
            "cod_ponto": str(cod_ponto or "").strip(),
            "cod_face": str(cod_face or "").strip(),
        },
    ).mappings().first()

    return dict(row) if row else None






def _buscar_destinatarios_externos_do_item_checkin(
    *,
    id_fato_controle_contratos: int,
    id_fato_controle_contratos_item: int,
) -> list[dict]:
    """Eu devolvo apenas os destinatários externos ativos e coerentes com o cabeçalho e com o item do contrato."""

    sql = text("""
        SELECT
            de.IDFatoContratoDestinatarioExterno,
            de.IDEmpresaDestinatario,
            RazaoSocial = NULLIF(LTRIM(RTRIM(COALESCE(emp.RazaoSocial, emp.NomeFantasia, ''))), ''),
            NomeFantasia = NULLIF(LTRIM(RTRIM(COALESCE(emp.NomeFantasia, ''))), ''),
            CNPJ = NULLIF(LTRIM(RTRIM(CAST(emp.CNPJ AS varchar(30)))), '')
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        INNER JOIN [Integracao].[Silver].[FatoControleContratosEuromidia] c
            ON c.IDFatoControleContratosEuromidia = i.IDFatoControleContratoEuromidia
        INNER JOIN [Integracao].[Silver].[FatoContratoDestinatarioExternoItens] dei
            ON dei.IDFatoControleContratosItensEuromidia = i.IDFatoControleContratosItensEuromidia
        INNER JOIN [Integracao].[Silver].[FatoContratoDestinatarioExterno] de
            ON de.IDFatoContratoDestinatarioExterno = dei.IDFatoContratoDestinatarioExterno
        LEFT JOIN [Integracao].[Silver].[DimEmpresas] emp
            ON emp.IDEmpresa = de.IDEmpresaDestinatario
        WHERE
            i.IDFatoControleContratosItensEuromidia = :id_fato_controle_contratos_item
            AND i.IDFatoControleContratoEuromidia = :id_fato_controle_contratos
            AND de.IDFatoControleContratosEuromidia = c.IDFatoControleContratosEuromidia
            AND de.IDEmpresa = c.IDEmpresa
            AND ISNULL(i.BitAtivo, 1) = 1
            AND ISNULL(c.BitAtivo, 1) = 1
            AND ISNULL(de.BitAtivo, 1) = 1
            AND ISNULL(dei.BitAtivo, 1) = 1
            AND (
                (
                    i.IDEmpresaAgencia IS NOT NULL
                    AND de.IDEmpresaDestinatario = i.IDEmpresaAgencia
                )
                OR
                (
                    i.IDEmpresaAgencia IS NULL
                    AND de.IDEmpresaDestinatario = c.IDEmpresa
                )
            )
        ORDER BY
            NULLIF(LTRIM(RTRIM(COALESCE(emp.RazaoSocial, emp.NomeFantasia, ''))), ''),
            de.IDFatoContratoDestinatarioExterno
    """)

    rows = db.session.execute(
        sql,
        {
            "id_fato_controle_contratos": int(id_fato_controle_contratos),
            "id_fato_controle_contratos_item": int(id_fato_controle_contratos_item),
        },
    ).mappings().all()

    retorno = []

    for row in rows:
        nome = (
            _normalizar_texto_checkin(row.get("RazaoSocial"))
            or _normalizar_texto_checkin(row.get("NomeFantasia"))
            or "Sem nome"
        )
        cnpj = _normalizar_texto_checkin(row.get("CNPJ"))

        retorno.append(
            {
                "id_fato_contrato_destinatario_externo": int(row["IDFatoContratoDestinatarioExterno"]),
                "id_empresa_destinatario": int(row["IDEmpresaDestinatario"]),
                "razao_social": nome,
                "cnpj": cnpj,
                "texto": f"{nome}{(' | ' + cnpj) if cnpj else ''}",
            }
        )

    return retorno



def _resolver_destinatario_externo_upload_checkin(
    *,
    id_empresa_principal: int,
    id_fato_controle_contratos: int,
    cod_ponto: str,
    cod_face: str,
    id_empresa_destinatario_informado: int | None,
    id_fato_contrato_destinatario_externo_informado: int | None,
) -> dict[str, object]:
    """Eu resolvo e valido o destinatário externo ativo do item selecionado."""

    item = _obter_item_contrato_checkin(
        id_fato_controle_contratos=id_fato_controle_contratos,
        cod_ponto=cod_ponto,
        cod_face=cod_face,
    )

    if not item:
        raise ValueError("O item do contrato não foi encontrado para o ponto e a face informados.")

    id_item = int(item["IDFatoControleContratosItensEuromidia"])

    """A fonte de verdade agora é a tabela de vínculo, não o IDEmpresaAgencia do item."""
    destinatarios = _buscar_destinatarios_externos_do_item_checkin(
        id_fato_controle_contratos=id_fato_controle_contratos,
        id_fato_controle_contratos_item=id_item,
    )

    """Se não houver vínculo ativo nas tabelas novas, uso a empresa principal."""
    if not destinatarios:
        return {
            "tem_destinatario_externo": False,
            "id_fato_controle_contratos_item": id_item,
            "id_fato_contrato_destinatario_externo": 0,
            "id_empresa_destinatario": int(id_empresa_principal),
            "destinatario_texto": None,
            "destinatarios_disponiveis": [],
        }

    selecionado = None

    if id_fato_contrato_destinatario_externo_informado not in (None, 0):
        for item_dest in destinatarios:
            if int(item_dest["id_fato_contrato_destinatario_externo"]) == int(id_fato_contrato_destinatario_externo_informado):
                selecionado = item_dest
                break

        if not selecionado:
            raise ValueError("O destinatário externo informado não está ativo para o item selecionado.")

    elif id_empresa_destinatario_informado not in (None, 0):
        for item_dest in destinatarios:
            if int(item_dest["id_empresa_destinatario"]) == int(id_empresa_destinatario_informado):
                selecionado = item_dest
                break

        if not selecionado:
            raise ValueError("A empresa destinatária informada não está ativa para o item selecionado.")

    elif len(destinatarios) == 1:
        selecionado = destinatarios[0]

    else:
        raise ValueError("Selecione um destinatário externo válido para o item do contrato.")

    return {
        "tem_destinatario_externo": True,
        "id_fato_controle_contratos_item": id_item,
        "id_fato_contrato_destinatario_externo": int(selecionado["id_fato_contrato_destinatario_externo"]),
        "id_empresa_destinatario": int(selecionado["id_empresa_destinatario"]),
        "destinatario_texto": str(selecionado["texto"]),
        "destinatarios_disponiveis": destinatarios,
    }





def _processar_upload_checkin_por_caminho(
    *,
    id_empresa: int,
    id_empresa_destinatario: int | None = None,
    id_fato_controle_contratos: int,
    id_fato_controle_contratos_item: int | None = None,
    id_fato_contrato_destinatario_externo: int | None = None,
    id_dim_tipo_midia: int | None = None,
    nome_tipo_midia: str | None = None,
    mimetype_arquivo: str | None = None,
    extensao_arquivo: str | None = None,
    cod_ponto: str,
    cod_face: str,
    data_checkin_iso: str,
    caminho_arquivo_temporario: str,
    nome_original_cliente: str | None = None,
    cnpj_digitado: str | None = None,
    observacao: str | None = None,
    id_usuario_criacao: int | None = None,
) -> dict[str, object]:
    """Eu processo o checkin usando arquivo temporário já salvo e devolvo um payload serializável."""

    cod_ponto_txt = _somente_digitos(cod_ponto)
    cod_face_txt = _normalizar_texto_checkin(cod_face).upper()
    observacao_txt = _normalizar_texto_checkin(observacao) or None
    cnpj_txt = _somente_digitos(cnpj_digitado) or None

    if not cod_ponto_txt:
        raise ValueError("CodPonto não informado.")

    if not cod_face_txt:
        raise ValueError("CodFace não informado.")

    if not id_empresa:
        raise ValueError("Empresa não informada.")

    if not id_fato_controle_contratos:
        raise ValueError("Contrato não informado.")

    try:
        data_checkin = datetime.strptime(str(data_checkin_iso), "%Y-%m-%d").date()
    except Exception as exc:
        raise ValueError("Data de checkin inválida para processamento assíncrono.") from exc

    cod_ponto_int = int(cod_ponto_txt)
    id_empresa_principal_int = int(id_empresa)
    id_empresa_destinatario_int = int(id_empresa_destinatario or id_empresa_principal_int)
    id_fato_contrato_destinatario_externo_int = int(id_fato_contrato_destinatario_externo or 0)
    id_dim_tipo_midia_int = int(id_dim_tipo_midia or 1)
    nome_tipo_midia_txt = str(
        nome_tipo_midia or ("Video" if id_dim_tipo_midia_int == 2 else "Imagem")
    ).strip() or "Imagem"
    extensao_arquivo_txt = str(extensao_arquivo or "").strip().lower()

    try:
        pasta_face, caminho_imagem_painel, caminho_fundo = _buscar_paths_mockup(
            cod_ponto_int,
            cod_face_txt,
        )

        pasta_destino_final = _montar_pasta_destino_final_checkin(
            cod_ponto=cod_ponto_int,
            cod_face=cod_face_txt,
            id_fato_controle_contratos=int(id_fato_controle_contratos),
            id_fato_contrato_destinatario_externo=id_fato_contrato_destinatario_externo_int,
        )

        current_app.logger.info(
            "[CHECKIN] Pasta final resolvida | contrato=%s | ponto=%s | face=%s | destinatario=%s | pasta=%s",
            int(id_fato_controle_contratos),
            cod_ponto_int,
            cod_face_txt,
            id_fato_contrato_destinatario_externo_int,
            str(pasta_destino_final),
        )

        nome_original_cliente, caminho_midia_upload = _salvar_upload_original_checkin(
            pasta_destino=pasta_destino_final,
            id_fato_controle_contratos=int(id_fato_controle_contratos),
            id_fato_contrato_destinatario_externo=id_fato_contrato_destinatario_externo_int,
            cod_face=cod_face_txt,
            data_checkin=data_checkin,
            caminho_arquivo_origem=caminho_arquivo_temporario,
            nome_original_cliente=nome_original_cliente,
        )

        caminho_arquivo_resultado = caminho_midia_upload
        caminho_imagem_gerada = None

        if id_dim_tipo_midia_int == 1:
            nome_base_gerado = (
                f"{cod_face_txt}_{data_checkin.strftime('%Y%m%d')}_"
                f"{int(id_fato_controle_contratos)}_{id_fato_contrato_destinatario_externo_int}_gerado"
            )
            caminho_imagem_gerada = pasta_destino_final / f"{nome_base_gerado}.jpg"

            contador = 1
            while caminho_imagem_gerada.exists():
                caminho_imagem_gerada = (
                    pasta_destino_final / f"{nome_base_gerado}_{contador:02d}.jpg"
                )
                contador += 1

            _gerar_mockup_checkin(
                caminho_fundo=caminho_fundo,
                caminho_imagem_upload=caminho_midia_upload,
                caminho_saida=caminho_imagem_gerada,
            )
            caminho_arquivo_resultado = caminho_imagem_gerada

        razao_social = None
        sql_empresa = text("""
            SELECT TOP (1)
                CNPJ = NULLIF(LTRIM(RTRIM(CAST(CNPJ AS varchar(30)))), ''),
                RazaoSocial = NULLIF(LTRIM(RTRIM(CAST(COALESCE(RazaoSocial, NomeFantasia, '') AS nvarchar(200)))), '')
            FROM [Integracao].[Silver].[DimEmpresas]
            WHERE IDEmpresa = :id_empresa
        """)
        row_empresa = db.session.execute(
            sql_empresa,
            {"id_empresa": id_empresa_destinatario_int}
        ).mappings().first()

        if row_empresa:
            if not cnpj_txt:
                cnpj_txt = _somente_digitos(row_empresa["CNPJ"]) or None
            razao_social = _normalizar_texto_checkin(row_empresa["RazaoSocial"]) or None

        tipo_painel = None
        tipo_face = None

        try:
            row_face = (
                db.session.query(
                    func.coalesce(DimFacesPaineis.Tipo, DimPaineisEuromidia.Tipo).label("TipoPainel")
                )
                .outerjoin(
                    DimPaineisEuromidia,
                    DimPaineisEuromidia.IDDimPaineisEuromidia == DimFacesPaineis.IDDimPaineisEuromidia,
                )
                .filter(
                    DimFacesPaineis.CodPonto == cod_ponto_int,
                    DimFacesPaineis.CodFace == cod_face_txt,
                )
                .first()
            )
            if row_face:
                tipo_painel = _normalizar_texto_checkin(row_face[0]) or None
        except Exception:
            tipo_painel = None

        checkin = DimCheckinHistorico()
        checkin.DataAtualizacao = datetime.now()
        checkin.DataChekin = data_checkin
        checkin.IDEmpresa = id_empresa_destinatario_int
        checkin.CNPJ = cnpj_txt
        checkin.RazaoSocial = razao_social
        checkin.IDFatoControleContratosEuromidia = int(id_fato_controle_contratos)
        checkin.CodPonto = cod_ponto_int
        checkin.CodFace = cod_face_txt
        checkin.TipoPainel = tipo_painel
        checkin.TipoFace = tipo_face
        checkin.NomeArquivoOriginal = nome_original_cliente or None
        checkin.NomeArquivoSalvo = caminho_midia_upload.name
        checkin.CaminhoImagemPainel = str(caminho_imagem_painel)
        checkin.CaminhoImagemFundo = str(caminho_fundo) if id_dim_tipo_midia_int == 1 else None
        checkin.CaminhoImagemUpload = str(caminho_midia_upload)
        checkin.CaminhoImagemGerada = str(caminho_arquivo_resultado)
        checkin.UrlImagemUpload = None
        checkin.UrlImagemGerada = None
        checkin.BitChekin = False
        checkin.DataConfirmacao = None
        checkin.IDUsuarioCriacao = (
            int(id_usuario_criacao)
            if id_usuario_criacao not in (None, "", 0)
            else None
        )
        checkin.IDUsuarioConfirmacao = None
        checkin.Observacao = observacao_txt

        db.session.add(checkin)
        db.session.flush()

        id_checkin = int(checkin.IDDimCheckinHistorico)
        url_arquivo_resultado = f"/paineis/checkin/arquivo/{id_checkin}"

        checkin.UrlImagemGerada = url_arquivo_resultado
        db.session.flush()

        try:
            db.session.execute(
                text("""
                    UPDATE [Integracao].[Silver].[DimCheckinHistorico]
                    SET IDDimTipoMidia = :id_dim_tipo_midia
                    WHERE IDDimCheckinHistorico = :id_checkin
                """),
                {
                    "id_dim_tipo_midia": int(id_dim_tipo_midia_int),
                    "id_checkin": int(id_checkin),
                },
            )
        except Exception:
            current_app.logger.exception(
                "[CHECKIN] não foi possível atualizar IDDimTipoMidia via SQL."
            )

        db.session.commit()
        db.session.refresh(checkin)

        return {
            "ok": True,
            "status": "SUCCESS",
            "id_checkin": id_checkin,
            "url_arquivo_resultado": url_arquivo_resultado,
            "url_imagem_gerada": url_arquivo_resultado if id_dim_tipo_midia_int == 1 else None,
            "url_confirmacao": f"/paineis/checkin/{id_checkin}/confirmar",
            "nome_arquivo_original": checkin.NomeArquivoOriginal,
            "nome_arquivo_salvo": checkin.NomeArquivoSalvo,
            "cod_ponto": int(cod_ponto_int),
            "cod_face": str(cod_face_txt),
            "id_fato_controle_contratos": int(id_fato_controle_contratos),
            "id_fato_controle_contratos_item": (
                int(id_fato_controle_contratos_item)
                if id_fato_controle_contratos_item not in (None, "", 0)
                else None
            ),
            "id_fato_contrato_destinatario_externo": int(id_fato_contrato_destinatario_externo_int),
            "id_empresa": int(id_empresa_principal_int),
            "id_empresa_destinatario": int(id_empresa_destinatario_int),
            "razao_social": razao_social,
            "id_dim_tipo_midia": int(id_dim_tipo_midia_int),
            "tipo_midia": nome_tipo_midia_txt,
            "mimetype_arquivo": str(mimetype_arquivo or "").strip().lower(),
            "extensao_arquivo": extensao_arquivo_txt,
        }

    except Exception:
        db.session.rollback()
        raise





def _montar_mockup_checkin(
    *,
    caminho_fundo: Path,
    caminho_arte: Path,
    caminho_saida: Path,
) -> None:
    """Eu monto o mockup centralizando a arte sobre o fundo com redimensionamento proporcional."""
    fundo = Image.open(caminho_fundo).convert("RGBA")
    arte = Image.open(caminho_arte).convert("RGBA")

    largura_fundo, altura_fundo = fundo.size

    margem_lateral = int(largura_fundo * 0.08)
    margem_superior = int(altura_fundo * 0.08)

    largura_util = max(1, largura_fundo - (margem_lateral * 2))
    altura_util = max(1, altura_fundo - (margem_superior * 2))

    arte_ajustada = ImageOps.contain(arte, (largura_util, altura_util))

    posicao_x = int((largura_fundo - arte_ajustada.width) / 2)
    posicao_y = int((altura_fundo - arte_ajustada.height) / 2)

    composicao = fundo.copy()
    composicao.paste(arte_ajustada, (posicao_x, posicao_y), arte_ajustada)

    _garantir_pasta(caminho_saida.parent)
    composicao.convert("RGB").save(caminho_saida, quality=95)


def _buscar_razao_social_empresa(id_empresa: int | None) -> str:
    """Eu busco a razão social da empresa para gravar junto com o checkin."""
    if not id_empresa:
        return ""

    sql = text("""
        SELECT TOP (1)
            RazaoSocial = NULLIF(LTRIM(RTRIM(COALESCE(RazaoSocial, NomeFantasia, ''))), '')
        FROM [Integracao].[Silver].[DimEmpresas]
        WHERE IDEmpresa = :id_empresa
    """)

    row = db.session.execute(sql, {"id_empresa": id_empresa}).mappings().first()
    if not row:
        return ""

    return _normalizar_texto_checkin(row["RazaoSocial"])


def _processar_upload_checkin(
    *,
    id_empresa: int | None,
    id_empresa_destinatario: int | None = None,
    id_fato_controle_contratos: int,
    id_fato_controle_contratos_item: int | None = None,
    id_fato_contrato_destinatario_externo: int | None = None,
    id_dim_tipo_midia: int | None = None,
    nome_tipo_midia: str | None = None,
    mimetype_arquivo: str | None = None,
    extensao_arquivo: str | None = None,
    cod_ponto: str,
    cod_face: str,
    data_checkin: date,
    arquivo,
    cnpj_digitado: str | None = None,
    observacao: str | None = None,
):
    """Eu mantenho a versão síncrona delegando para o mesmo pipeline por caminho temporário."""
    if arquivo is None:
        raise ValueError("Arquivo não informado.")

    upload_temp = _salvar_upload_temporario_checkin(
        arquivo=arquivo,
        id_empresa=int(id_empresa or 0),
        id_fato_controle_contratos=int(id_fato_controle_contratos),
        cod_ponto=cod_ponto,
        cod_face=cod_face,
        data_checkin=data_checkin,
    )

    return _processar_upload_checkin_por_caminho(
        id_empresa=int(id_empresa or 0),
        id_empresa_destinatario=id_empresa_destinatario,
        id_fato_controle_contratos=int(id_fato_controle_contratos),
        id_fato_controle_contratos_item=id_fato_controle_contratos_item,
        id_fato_contrato_destinatario_externo=id_fato_contrato_destinatario_externo,
        id_dim_tipo_midia=id_dim_tipo_midia,
        nome_tipo_midia=nome_tipo_midia,
        mimetype_arquivo=mimetype_arquivo,
        extensao_arquivo=extensao_arquivo,
        cod_ponto=cod_ponto,
        cod_face=cod_face,
        data_checkin_iso=data_checkin.strftime("%Y-%m-%d"),
        caminho_arquivo_temporario=str(upload_temp["caminho_arquivo_temporario"]),
        nome_original_cliente=str(upload_temp["nome_original_cliente"]),
        cnpj_digitado=cnpj_digitado,
        observacao=observacao,
        id_usuario_criacao=_obter_id_usuario_logado_para_checkin(),
    )




@paineis_bp.route("/checkin/status/<string:task_id>", methods=["GET"])
@login_required
@requer_item_menu_paineis("checkin_novo")
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def checkin_status(task_id: str):
    """Eu devolvo o estado atual do processamento assíncrono do checkin."""

    resultado_async = AsyncResult(task_id, app=celery_app)
    estado = str(resultado_async.state or "PENDING").upper()

    if estado == "SUCCESS":
        resultado = dict(resultado_async.result or {})

        url_publica_relativa = str(resultado.get("url_publica_relativa") or "").strip()
        if url_publica_relativa and not str(resultado.get("url_publica") or "").strip():
            resultado["url_publica"] = f"{_obter_base_url_publica_checkin()}{url_publica_relativa}"

        return jsonify(
            {
                "ok": True,
                "status": estado,
                "resultado": resultado,
            }
        )

    if estado in {"FAILURE", "REVOKED"}:
        erro = str(resultado_async.result) if resultado_async.result else "Falha ao processar o checkin."
        return jsonify(
            {
                "ok": False,
                "status": estado,
                "erro": erro,
            }
        ), 500

    meta = resultado_async.info if isinstance(resultado_async.info, dict) else {}
    return jsonify(
        {
            "ok": True,
            "status": estado,
            "meta": meta,
        }
    ), 202









def _buscar_dados_select_checkin(id_empresa: int | None = None):
    sql_empresas = text("""
        SELECT
            TOP (500)
            e.IDEmpresa,
            CNPJ = NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(30)))), ''),
            RazaoSocial = NULLIF(LTRIM(RTRIM(COALESCE(e.RazaoSocial, e.NomeFantasia, ''))), ''),
            NomeFantasia = NULLIF(LTRIM(RTRIM(COALESCE(e.NomeFantasia, ''))), '')
        FROM [Integracao].[Silver].[DimEmpresas] e
        WHERE NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(30)))), '') IS NOT NULL
        ORDER BY
            NULLIF(LTRIM(RTRIM(COALESCE(e.RazaoSocial, e.NomeFantasia, ''))), ''),
            NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(30)))), '')
    """)

    sql_pontos = text("""
        SELECT
            TOP (1000)
            p.CodPonto,
            TipoPainel = NULLIF(LTRIM(RTRIM(COALESCE(p.Tipo, ''))), '')
        FROM [Integracao].[Silver].[DimPaineisEuromidia] p
        WHERE p.CodPonto IS NOT NULL
        ORDER BY p.CodPonto ASC
    """)

    sql_faces = text("""
        SELECT
            TOP (2000)
            f.IDDimFacesPaineis,
            f.CodPonto,
            f.CodFace,
            TipoFace = NULLIF(LTRIM(RTRIM(COALESCE(f.Tipo, ''))), ''),
            TipoPainel = NULLIF(LTRIM(RTRIM(COALESCE(p.Tipo, ''))), '')
        FROM [Integracao].[Silver].[DimFacesPaineis] f
        LEFT JOIN [Integracao].[Silver].[DimPaineisEuromidia] p
            ON p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia
        WHERE f.CodPonto IS NOT NULL
          AND NULLIF(LTRIM(RTRIM(COALESCE(f.CodFace, ''))), '') IS NOT NULL
        ORDER BY f.CodPonto ASC, f.CodFace ASC
    """)

    empresas_rows = db.session.execute(sql_empresas).mappings().all()
    pontos_rows = db.session.execute(sql_pontos).mappings().all()
    faces_rows = db.session.execute(sql_faces).mappings().all()

    empresas = []
    for row in empresas_rows:
        id_empresa_linha = row["IDEmpresa"]
        cnpj = _somente_digitos(row["CNPJ"])
        razao = _normalizar_texto_checkin(row["RazaoSocial"])
        nome_fantasia = _normalizar_texto_checkin(row["NomeFantasia"])

        nome_exibicao = razao or nome_fantasia or "Sem nome cadastrado"

        empresas.append({
            "IDEmpresa": id_empresa_linha,
            "CNPJ": cnpj,
            "RazaoSocial": razao,
            "NomeFantasia": nome_fantasia,
            "texto": f"{cnpj} | {nome_exibicao}",
        })

    pontos = []
    for row in pontos_rows:
        cod_ponto = row["CodPonto"]
        tipo_painel = _normalizar_texto_checkin(row["TipoPainel"]) or "Sem tipo"

        pontos.append({
            "CodPonto": cod_ponto,
            "TipoPainel": tipo_painel,
            "texto": f"{cod_ponto} | {tipo_painel}",
        })

    faces = []
    for row in faces_rows:
        cod_ponto = row["CodPonto"]
        cod_face = _normalizar_texto_checkin(row["CodFace"])
        tipo_face = _normalizar_texto_checkin(row["TipoFace"]) or _normalizar_texto_checkin(row["TipoPainel"]) or "Sem tipo"

        faces.append({
            "IDDimFacesPaineis": row["IDDimFacesPaineis"],
            "CodPonto": cod_ponto,
            "CodFace": cod_face,
            "TipoFace": tipo_face,
            "TipoPainel": _normalizar_texto_checkin(row["TipoPainel"]),
            "texto_face": f"{cod_face} | {tipo_face}",
        })

    return empresas, [], pontos, faces




@paineis_bp.route("/checkin/empresas/buscar", methods=["GET"])
@login_required
@requer_item_menu_paineis("checkin_novo")
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def checkin_empresas_buscar():
    q = _normalizar_texto_checkin(request.args.get("q"))
    q_digitos = _somente_digitos(q)

    if not q:
        return jsonify([])

    def formatar_cnpj(cnpj: str) -> str:
        cnpj = _somente_digitos(cnpj)
        if len(cnpj) != 14:
            return cnpj
        return f"{cnpj[0:2]}.{cnpj[2:5]}.{cnpj[5:8]}/{cnpj[8:12]}-{cnpj[12:14]}"

    retorno = []

    if q_digitos:
        q_cnpj_puro = q_digitos
        q_cnpj_mascarado = formatar_cnpj(q_digitos)

        parametros = {
            "q": q,
            "q_like": f"%{q}%",
            "q_cnpj_puro": q_cnpj_puro,
            "q_cnpj_mascarado": q_cnpj_mascarado,
            "q_cnpj_puro_prefixo": f"{q_cnpj_puro}%",
            "q_cnpj_mascarado_prefixo": f"{q_cnpj_mascarado}%",
        }

        sql = text("""
            SELECT TOP (20)
                e.IDEmpresa,
                CNPJ = NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(30)))), ''),
                RazaoSocial = NULLIF(LTRIM(RTRIM(COALESCE(e.RazaoSocial, ''))), ''),
                NomeFantasia = NULLIF(LTRIM(RTRIM(COALESCE(e.NomeFantasia, ''))), '')
            FROM [Integracao].[Silver].[DimEmpresas] e
            WHERE
                NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(30)))), '') IS NOT NULL
                AND
                (
                    CAST(e.CNPJ AS varchar(30)) = :q_cnpj_puro
                    OR CAST(e.CNPJ AS varchar(30)) = :q_cnpj_mascarado
                    OR CAST(e.CNPJ AS varchar(30)) LIKE :q_cnpj_puro_prefixo
                    OR CAST(e.CNPJ AS varchar(30)) LIKE :q_cnpj_mascarado_prefixo
                )
            ORDER BY
                CASE
                    WHEN CAST(e.CNPJ AS varchar(30)) = :q_cnpj_puro THEN 0
                    WHEN CAST(e.CNPJ AS varchar(30)) = :q_cnpj_mascarado THEN 1
                    WHEN CAST(e.CNPJ AS varchar(30)) LIKE :q_cnpj_puro_prefixo THEN 2
                    WHEN CAST(e.CNPJ AS varchar(30)) LIKE :q_cnpj_mascarado_prefixo THEN 3
                    ELSE 4
                END,
                RazaoSocial,
                NomeFantasia,
                CNPJ
        """)
    else:
        parametros = {
            "q": q,
            "q_like": f"%{q}%",
        }

        sql = text("""
            SELECT TOP (20)
                e.IDEmpresa,
                CNPJ = NULLIF(LTRIM(RTRIM(CAST(e.CNPJ AS varchar(30)))), ''),
                RazaoSocial = NULLIF(LTRIM(RTRIM(COALESCE(e.RazaoSocial, ''))), ''),
                NomeFantasia = NULLIF(LTRIM(RTRIM(COALESCE(e.NomeFantasia, ''))), '')
            FROM [Integracao].[Silver].[DimEmpresas] e
            WHERE
                (
                    COALESCE(e.RazaoSocial, '') LIKE :q_like
                    OR COALESCE(e.NomeFantasia, '') LIKE :q_like
                )
            ORDER BY
                CASE
                    WHEN COALESCE(e.RazaoSocial, '') = :q THEN 0
                    WHEN COALESCE(e.NomeFantasia, '') = :q THEN 1
                    ELSE 2
                END,
                RazaoSocial,
                NomeFantasia,
                CNPJ
        """)

    rows = db.session.execute(sql, parametros).mappings().all()

    for row in rows:
        id_empresa = row["IDEmpresa"]
        cnpj = _normalizar_texto_checkin(row["CNPJ"])
        cnpj_digitos = _somente_digitos(cnpj)
        razao = _normalizar_texto_checkin(row["RazaoSocial"])
        nome_fantasia = _normalizar_texto_checkin(row["NomeFantasia"])

        nome_exibicao = razao or nome_fantasia or "Sem nome cadastrado"

        retorno.append({
            "id": int(id_empresa),
            "cnpj": cnpj,
            "cnpj_digitos": cnpj_digitos,
            "razao_social": razao,
            "nome_fantasia": nome_fantasia,
            "texto": f"{cnpj} | {nome_exibicao}",
        })

    return jsonify(retorno)









def _salvar_upload_temporario_checkin(
    *,
    arquivo,
    id_empresa: int,
    id_fato_controle_contratos: int,
    cod_ponto: str,
    cod_face: str,
    data_checkin: date,
) -> dict[str, str | int]:
    """Eu salvo o upload bruto em pasta temporária e devolvo os metadados necessários para a fila."""

    nome_original = _normalizar_texto_checkin(getattr(arquivo, "filename", "")) or "arquivo"
    extensao = _normalizar_extensao_arquivo(nome_original)

    token_upload = uuid.uuid4().hex
    pasta_temp = (
        _obter_pasta_temp_checkin()
        / data_checkin.strftime("%Y%m%d")
        / str(int(id_empresa))
        / str(int(id_fato_controle_contratos))
    )
    _garantir_pasta(pasta_temp)

    nome_temporario = (
        f"checkin_{int(id_empresa)}_"
        f"{int(id_fato_controle_contratos)}_"
        f"{_somente_digitos(cod_ponto)}_"
        f"{_normalizar_texto_checkin(cod_face).upper()}_"
        f"{token_upload}{extensao}"
    )

    caminho_temporario = pasta_temp / nome_temporario

    arquivo.stream.seek(0)
    arquivo.save(caminho_temporario)

    return {
        "token_upload": token_upload,
        "nome_original_cliente": nome_original,
        "caminho_arquivo_temporario": str(caminho_temporario),
    }







def _obter_id_usuario_logado_para_checkin() -> int | None:
    candidatos = [
        getattr(current_user, "IDDimUsuarios", None),
        getattr(current_user, "id", None),
    ]

    for valor in candidatos:
        try:
            valor_int = int(valor)
            if valor_int > 0:
                return valor_int
        except Exception:
            pass

    if hasattr(current_user, "get_id"):
        try:
            valor_int = int(current_user.get_id())
            if valor_int > 0:
                return valor_int
        except Exception:
            pass

    return None


def _obter_id_empresa_proprietaria_logada_para_checkin() -> int | None:
    candidatos = [
        getattr(current_user, "IDEmpresaProprietaria", None),
        getattr(current_user, "id_empresa_proprietaria", None),
    ]

    for valor in candidatos:
        try:
            valor_int = int(valor)
            if valor_int > 0:
                return valor_int
        except Exception:
            pass

    return None




def _quebrar_nome_banco_schema_tabela_checkin(nome_tabela: str) -> tuple[str | None, str | None, str | None]:
    """Separo um nome de tabela no padrão banco.schema.tabela, schema.tabela ou tabela."""
    texto = str(nome_tabela or "").strip()
    if not texto:
        return None, None, None

    partes = [parte.strip().strip("[]").strip() for parte in texto.split(".") if str(parte).strip()]
    if not partes:
        return None, None, None

    if len(partes) == 3:
        banco_nome, schema_nome, tabela_nome = partes
        return (
            banco_nome or None,
            schema_nome or None,
            tabela_nome or None,
        )

    if len(partes) == 2:
        schema_nome, tabela_nome = partes
        return (
            None,
            schema_nome or None,
            tabela_nome or None,
        )

    if len(partes) == 1:
        return (
            None,
            None,
            partes[0] or None,
        )

    tabela_nome = partes[-1] if len(partes) >= 1 else None
    schema_nome = partes[-2] if len(partes) >= 2 else None
    banco_nome = ".".join(partes[:-2]) if len(partes) > 2 else None

    return (
        banco_nome or None,
        schema_nome or None,
        tabela_nome or None,
    )






def _coluna_existe(nome_tabela: str, nome_coluna: str) -> bool:
    banco_nome, schema_nome, tabela_nome = _quebrar_nome_banco_schema_tabela_checkin(nome_tabela)
    coluna_nome = str(nome_coluna or "").strip().strip("[]").strip()

    if not tabela_nome or not coluna_nome:
        return False

    if banco_nome:
        sql = text(f"""
            SELECT TOP (1)
                1
            FROM [{banco_nome}].sys.tables t
            INNER JOIN [{banco_nome}].sys.schemas s
                ON s.schema_id = t.schema_id
            INNER JOIN [{banco_nome}].sys.columns c
                ON c.object_id = t.object_id
            WHERE s.name = :schema_nome
              AND t.name = :tabela_nome
              AND c.name = :coluna_nome;
        """)
    else:
        sql = text("""
            SELECT TOP (1)
                1
            FROM sys.tables t
            INNER JOIN sys.schemas s
                ON s.schema_id = t.schema_id
            INNER JOIN sys.columns c
                ON c.object_id = t.object_id
            WHERE s.name = :schema_nome
              AND t.name = :tabela_nome
              AND c.name = :coluna_nome;
        """)

    resultado = db.session.execute(
        sql,
        {
            "schema_nome": schema_nome or "dbo",
            "tabela_nome": tabela_nome,
            "coluna_nome": coluna_nome,
        },
    ).scalar()

    return bool(resultado)










def _aplicar_tag_checkin_confirmado_no_card_se_precisar(
    *,
    id_card: int,
    id_tag: int,
    id_usuario: int | None,
    id_empresa_proprietaria: int | None = None,
) -> bool:
    if not id_card:
        raise RuntimeError("ID do card não informado para aplicar a tag do checkin.")

    if not id_tag:
        raise RuntimeError("ID da tag não informado para aplicar no card.")

    tabela = "[Kanban].[Silver].[FatoKanbanCardTag]"
    condicao_tag_ativa = _obter_condicao_sql_tag_ativa_checkin_confirmado()

    sql_tag_existente = text(f"""
        SELECT TOP (1)
            1 AS Existe
        FROM {tabela} ct
        WHERE
            ct.IDFatoKanbanCard = :id_card
            AND ct.IDDimKanbanTag = :id_tag
            AND {condicao_tag_ativa}
    """)

    tag_ja_existe = db.session.execute(
        sql_tag_existente,
        {
            "id_card": int(id_card),
            "id_tag": int(id_tag),
        },
    ).mappings().first()

    if tag_ja_existe:
        return False

    colunas = [
        "IDFatoKanbanCard",
        "IDDimKanbanTag",
        "AplicadoEm",
    ]
    valores = [
        ":id_card",
        ":id_tag",
        "GETDATE()",
    ]
    params = {
        "id_card": int(id_card),
        "id_tag": int(id_tag),
    }

    if _coluna_existe(tabela, "IDUsuario"):
        colunas.append("IDUsuario")
        valores.append(":id_usuario")
        params["id_usuario"] = int(id_usuario) if id_usuario not in (None, "", 0) else None
    elif _coluna_existe(tabela, "AplicadoPor"):
        colunas.append("AplicadoPor")
        valores.append(":id_usuario")
        params["id_usuario"] = int(id_usuario) if id_usuario not in (None, "", 0) else None

    if _coluna_existe(tabela, "IDEmpresaProprietaria"):
        colunas.append("IDEmpresaProprietaria")
        valores.append(":id_empresa_proprietaria")
        params["id_empresa_proprietaria"] = (
            int(id_empresa_proprietaria)
            if id_empresa_proprietaria not in (None, "", 0)
            else None
        )

    sql_insert = text(f"""
        INSERT INTO {tabela}
        ({", ".join(colunas)})
        VALUES
        ({", ".join(valores)})
    """)

    db.session.execute(sql_insert, params)
    return True







def _obter_card_vinculado_item_contrato_checkin(
    *,
    id_fato_controle_contratos: int,
    cod_ponto: str,
    cod_face: str,
) -> dict[str, int | None] | None:
    cod_ponto_txt = _somente_digitos(cod_ponto)
    cod_face_txt = _normalizar_texto_checkin(cod_face).upper()

    if not id_fato_controle_contratos:
        return None

    if not cod_ponto_txt:
        return None

    if not cod_face_txt:
        return None

    sql = text("""
        SELECT TOP (1)
            id_card = i.IDFatoKanbanCard,
            id_empresa_proprietaria = c.IDEmpresaProprietaria
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        LEFT JOIN [Kanban].[Silver].[FatoKanbanCard] c
            ON c.IDFatoKanbanCard = i.IDFatoKanbanCard
        WHERE
            i.IDFatoControleContratoEuromidia = :id_fato_controle_contratos
            AND i.IDFatoKanbanCard IS NOT NULL
            AND i.CodPonto = :cod_ponto
            AND UPPER(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50))))) = UPPER(LTRIM(RTRIM(:cod_face)))
        ORDER BY i.IDFatoControleContratosItensEuromidia DESC
    """)

    row = db.session.execute(
        sql,
        {
            "id_fato_controle_contratos": int(id_fato_controle_contratos),
            "cod_ponto": str(cod_ponto_txt).strip(),
            "cod_face": str(cod_face_txt).strip(),
        },
    ).mappings().first()

    if not row:
        return None

    id_card = row.get("id_card")
    if not id_card:
        return None

    id_empresa_proprietaria = row.get("id_empresa_proprietaria")

    return {
        "id_card": int(id_card),
        "id_empresa_proprietaria": int(id_empresa_proprietaria) if id_empresa_proprietaria not in (None, "", 0) else None,
    }










def _sincronizar_tag_checkin_confirmado_com_card(checkin: DimCheckinHistorico) -> dict[str, int | bool | None]:
    if not checkin:
        raise RuntimeError("Checkin não informado para sincronizar a tag do card.")

    id_contrato = int(getattr(checkin, "IDFatoControleContratosEuromidia", 0) or 0)
    cod_ponto = _somente_digitos(getattr(checkin, "CodPonto", None))
    cod_face = _normalizar_texto_checkin(getattr(checkin, "CodFace", None)).upper()

    if not id_contrato:
        raise RuntimeError("O checkin não possui contrato vinculado.")

    if not cod_ponto:
        raise RuntimeError("O checkin não possui CodPonto válido.")

    if not cod_face:
        raise RuntimeError("O checkin não possui CodFace válido.")

    card = _obter_card_vinculado_item_contrato_checkin(
        id_fato_controle_contratos=id_contrato,
        cod_ponto=cod_ponto,
        cod_face=cod_face,
    )

    if not card:
        return {
            "id_card": None,
            "id_tag": ID_TAG_CHECKIN_CONFIRMADO_KANBAN,
            "tag_aplicada": False,
            "card_encontrado": False,
        }

    id_card = int(card.get("id_card") or 0)
    if not id_card:
        return {
            "id_card": None,
            "id_tag": ID_TAG_CHECKIN_CONFIRMADO_KANBAN,
            "tag_aplicada": False,
            "card_encontrado": False,
        }

    id_usuario = _obter_id_usuario_logado_para_checkin()
    id_empresa_proprietaria = int(
        getattr(checkin, "IDEmpresaProprietaria", 0)
        or getattr(current_user, "IDEmpresaProprietaria", 0)
        or 0
    ) or None

    tag_aplicada = _aplicar_tag_checkin_confirmado_no_card_se_precisar(
        id_card=id_card,
        id_tag=ID_TAG_CHECKIN_CONFIRMADO_KANBAN,
        id_usuario=id_usuario,
        id_empresa_proprietaria=id_empresa_proprietaria,
    )

    return {
        "id_card": id_card,
        "id_tag": ID_TAG_CHECKIN_CONFIRMADO_KANBAN,
        "tag_aplicada": bool(tag_aplicada),
        "card_encontrado": True,
    }






def _buscar_paths_mockup(cod_ponto: int, cod_face: str) -> tuple[Path, Path | None, Path]:
    """Eu resolvo os caminhos necessários para gerar o mockup do checkin.

    Estrutura correta esperada:
    pontos/CodPonto/CodFace
    pontos/CodPonto/fundo

    O ponto importante: eu NÃO exijo mais uma imagem dentro de pontos/CodPonto/CodFace,
    porque o mockup usa a imagem importada pelo usuário + a imagem de fundo. Exigir uma
    imagem solta dentro da pasta da face fazia o upload falhar sem necessidade.
    """
    pasta_raiz = _obter_pasta_base_checkin()
    cod_ponto_txt = _normalizar_segmento_pasta_checkin(cod_ponto)
    cod_face_txt = _normalizar_segmento_pasta_checkin(cod_face, forcar_maiusculo=True)

    pasta_ponto = _resolver_pasta_filha_checkin(pasta_raiz, cod_ponto_txt)
    pasta_face = _resolver_pasta_filha_checkin(pasta_ponto, cod_face_txt)

    if not pasta_ponto.exists() or not pasta_ponto.is_dir():
        raise FileNotFoundError(f"Pasta do ponto não encontrada: {pasta_ponto}")

    if not pasta_face.exists() or not pasta_face.is_dir():
        raise FileNotFoundError(f"Pasta da face não encontrada: {pasta_face}")

    candidatos_pasta_fundo = [
        _resolver_pasta_filha_checkin(pasta_ponto, "fundo"),
        _resolver_pasta_filha_checkin(pasta_face, "fundo"),
    ]

    pasta_fundo = next((p for p in candidatos_pasta_fundo if p.exists() and p.is_dir()), None)

    if pasta_fundo is None:
        caminhos_testados = " | ".join(str(p) for p in candidatos_pasta_fundo)
        raise FileNotFoundError(f"Pasta do fundo não encontrada. Caminhos testados: {caminhos_testados}")

    caminho_fundo = _localizar_arquivo_imagem(pasta_fundo)

    return pasta_face, None, caminho_fundo
def _gerar_mockup_checkin(
    caminho_fundo: Path,
    caminho_imagem_upload: Path,
    caminho_saida: Path,
) -> None:
    """
    Eu gero o mockup final colocando a arte enviada em cima do fundo padrão.

    Lógica:
    - abro a imagem de fundo
    - abro a imagem enviada pelo usuário
    - ajusto a imagem exatamente na área útil definida
    - colo a imagem ajustada sobre o fundo
    - salvo o resultado final
    """

    fundo = Image.open(caminho_fundo).convert("RGB")
    imagem = Image.open(caminho_imagem_upload).convert("RGB")

    x1 = 430
    y1 = 35
    x2 = 1230
    y2 = 605

    largura_area = x2 - x1
    altura_area = y2 - y1

    imagem_ajustada = ImageOps.fit(
        imagem,
        (largura_area, altura_area),
        method=Image.Resampling.LANCZOS,
        centering=(0.5, 0.5),
    )

    fundo.paste(imagem_ajustada, (x1, y1))

    _garantir_pasta(caminho_saida.parent)
    fundo.save(caminho_saida, quality=95)










def _checkin_item_pertence_ao_contrato(
    *,
    id_fato_controle_contratos: int,
    cod_ponto: str,
    cod_face: str,
) -> bool:
    return _obter_item_contrato_checkin(
        id_fato_controle_contratos=id_fato_controle_contratos,
        cod_ponto=cod_ponto,
        cod_face=cod_face,
    ) is not None


def _obter_condicao_sql_tag_ativa_checkin_confirmado() -> str:
    tabela = "[Kanban].[Silver].[FatoKanbanCardTag]"

    if _coluna_existe(tabela, "RemovidoEm"):
        return "ct.RemovidoEm IS NULL"

    if _coluna_existe(tabela, "DataRemocao"):
        return "ct.DataRemocao IS NULL"

    return "1 = 1"












@paineis_bp.route("/checkin/contratos/<int:id_fato_controle_contratos>/pontos", methods=["GET"])
@login_required
@requer_item_menu_paineis("checkin_novo")
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def checkin_pontos_do_contrato(id_fato_controle_contratos: int):
    sql = text("""
        SELECT TOP (300)
            CodPonto = i.CodPonto,
            TipoPainel = MAX(
                NULLIF(
                    LTRIM(RTRIM(COALESCE(p.Tipo, ''))),
                    ''
                )
            )
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        LEFT JOIN [Integracao].[Silver].[DimPaineisEuromidia] p
            ON p.CodPonto = i.CodPonto
        WHERE
            i.IDFatoControleContratoEuromidia = :id_fato_controle_contratos
            AND i.CodPonto IS NOT NULL
        GROUP BY i.CodPonto
        ORDER BY i.CodPonto ASC
    """)

    rows = db.session.execute(
        sql,
        {"id_fato_controle_contratos": int(id_fato_controle_contratos)},
    ).mappings().all()

    itens = []
    for row in rows:
        cod_ponto = row["CodPonto"]
        if cod_ponto is None:
            continue

        tipo_painel = _normalizar_texto_checkin(row["TipoPainel"]) or "Sem tipo"

        itens.append(
            {
                "cod_ponto": int(cod_ponto),
                "tipo_painel": tipo_painel,
                "texto": f"{int(cod_ponto)} | {tipo_painel}",
            }
        )

    return jsonify({
        "id_fato_controle_contratos": int(id_fato_controle_contratos),
        "items": itens,
    })






@paineis_bp.route("/checkin/contratos/<int:id_fato_controle_contratos>/pontos/<int:codponto>/faces", methods=["GET"])
@login_required
@requer_item_menu_paineis("checkin_novo")
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def checkin_faces_do_contrato(id_fato_controle_contratos: int, codponto: int):
    sql = text("""
        SELECT TOP (300)
            CodFace = UPPER(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50))))),
            TipoFace = MAX(
                NULLIF(
                    LTRIM(RTRIM(COALESCE(f.Tipo, p.Tipo, ''))),
                    ''
                )
            )
        FROM [Integracao].[Silver].[FatoControleContratosItensEuromidia] i
        LEFT JOIN [Integracao].[Silver].[DimFacesPaineis] f
            ON f.CodPonto = i.CodPonto
            AND UPPER(LTRIM(RTRIM(CAST(f.CodFace AS varchar(50))))) = UPPER(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50)))))
        LEFT JOIN [Integracao].[Silver].[DimPaineisEuromidia] p
            ON p.IDDimPaineisEuromidia = f.IDDimPaineisEuromidia
            OR p.CodPonto = i.CodPonto
        WHERE
            i.IDFatoControleContratoEuromidia = :id_fato_controle_contratos
            AND i.CodPonto = :codponto
            AND NULLIF(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50)))), '') IS NOT NULL
        GROUP BY UPPER(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50)))))
        ORDER BY UPPER(LTRIM(RTRIM(CAST(i.CodFace AS varchar(50))))) ASC
    """)

    rows = db.session.execute(
        sql,
        {
            "id_fato_controle_contratos": int(id_fato_controle_contratos),
            "codponto": int(codponto),
        },
    ).mappings().all()

    itens = []
    for row in rows:
        cod_face = _normalizar_texto_checkin(row["CodFace"])
        if not cod_face:
            continue

        tipo_face = _normalizar_texto_checkin(row["TipoFace"]) or "Sem tipo"

        itens.append(
            {
                "cod_face": cod_face,
                "tipo_face": tipo_face,
                "texto": f"{cod_face} | {tipo_face}",
            }
        )

    return jsonify({
        "id_fato_controle_contratos": int(id_fato_controle_contratos),
        "codponto": int(codponto),
        "items": itens,
    })







@paineis_bp.route("/checkin/contratos/<int:id_fato_controle_contratos>/pontos/<int:codponto>/faces/<string:codface>/destinatarios", methods=["GET"])
@login_required
@requer_item_menu_paineis("checkin_novo")
@retry_get_view(db, attempts=2, base_delay=0.2, max_delay=0.8)
def checkin_destinatarios_externos_do_item(id_fato_controle_contratos: int, codponto: int, codface: str):
    item = _obter_item_contrato_checkin(
        id_fato_controle_contratos=int(id_fato_controle_contratos),
        cod_ponto=str(codponto),
        cod_face=str(codface),
    )

    if not item:
        return jsonify(
            {
                "ok": False,
                "id_fato_controle_contratos": int(id_fato_controle_contratos),
                "cod_ponto": int(codponto),
                "cod_face": str(codface).strip().upper(),
                "tem_destinatario_externo": False,
                "items": [],
                "msg": "Item do contrato não encontrado.",
            }
        ), 404

    id_item = int(item["IDFatoControleContratosItensEuromidia"])

    """Busca sempre pela tabela de vínculo, independentemente do IDEmpresaAgencia."""
